def ai_da_bi_vuot(page_id, conv_id, token, msgs_luc_soan):
    """Trong lúc AI soạn (~10-60s) đã có ai phía shop rep khách chưa? -> (True, ai) nếu có.

    Ca 13/09 (Saleem Hamza, Al Shifa Denture): sale Trúc Vân chat tay gửi 00:07:36, AI gửi đè
    00:07:37. AI chỉ kiểm "sale đã rep chưa" lúc BẮT ĐẦU soạn. Nên ngay trước khi bấm gửi, đọc
    lại hội thoại một lần (1 GET): số tin phía shop sau tin cuối của khách mà TĂNG so với lúc
    soạn thì nhường, không gửi. So bằng số đếm chứ không so "tin cuối là của page" để nhánh
    'xet' (Botcake đã rep từ trước khi soạn) vẫn gửi được.
    """
    moi, _, err = tin_cua_hoi_thoai(page_id, conv_id, token)
    if err or not moi:
        return False, None                      # đọc hỏng thì không chặn — đừng vì kiểm mà câm
    # KHÁCH NHẮN THÊM trong lúc AI soạn (ca Seeba 14/09: "How many gram" tới 7s trước khi AI gửi câu
    # soạn cho "2 pc") → không gửi câu đã cũ; lượt sau soạn MỘT câu trả lời cả hai tin.
    def _luc_khach(ds):
        return max((m["luc"] or "" for m in ds if m["boi"] == "khach"), default="")
    if _luc_khach(moi) > _luc_khach(msgs_luc_soan):
        _KHACH_NHAN_THEM.add(str(conv_id))
        return True, "khách"
    truoc, sau = _so_page_sau_khach(msgs_luc_soan), _so_page_sau_khach(moi)
    if sau > truoc:
        ai = next((m for m in reversed(moi) if m["boi"] in ("botcake", "nguoi")), {})
        return True, ("Botcake" if ai.get("boi") == "botcake" else f"sale {ai.get('ten') or '?'}")
    return False, None


# ─────────── Page KHÔNG có token page → chạy bằng TÀI KHOẢN Pancake (14/09/2026) ───────────
#
# Chủ shop chốt: AI trả lời được ở page tài khoản chỉ là Biên tập viên (không sinh được token page)
# mà không cần nâng quyền Facebook. Cách làm: trong danh sách page, page không token mang
# token giả TOKEN_USER; mọi hàm gọi API page thấy token này thì đi API nội bộ pancake.vn với
# PANCAKE_USER_TOKEN (đúng đường giao diện web). Đã đo 14/09 trên Mario Jewelry: đọc hội thoại,
# đọc tin (cần customer_id), gửi reply_inbox, mark_unread, ghi chú, settings.tags đều được.
TOKEN_USER = "__USER__"
WEB_API = "https://pancake.vn/api/v1"
_CUST = {}     # (pid, conv_id) -> customers[0].id — API nội bộ đọc tin bắt buộc có customer_id


def _la_user(token):
    return token == TOKEN_USER


def _tok_user():
    return env().get("PANCAKE_USER_TOKEN", "")


def _hoi_thoai_user(page_id, gio=None):
    """Danh sách hội thoại INBOX qua API nội bộ; lọc theo updated_at trong `gio` giờ nếu có."""
    res, err = _get(f"{WEB_API}/pages/{page_id}/conversations",
                    {"access_token": _tok_user(), "current_count": 0, "type": "INBOX", "mode": "OR"})
    if err or not res:
        return None, err or "API nội bộ không trả gì"
    convs = res.get("conversations") or []
    ten_the = _the_ten_page_user(page_id) if any(
        isinstance(t, int) for c in convs for t in (c.get("tags") or [])) else {}
    for c in convs:
        cu = ((c.get("customers") or [{}])[0] or {}).get("id")
        if cu:
            _CUST[(str(page_id), str(c.get("id")))] = cu
        # API nội bộ trả thẻ dạng SỐ ([-9, 3, 6, 44]) chứ không phải {id, text} như Public API →
        # the_noi_da_xong ném lỗi, cửa thẻ "Đã gửi" mù ở MỌI page chạy bằng tài khoản (14/09 ca
        # Sweetrose Torres, Mario Jewelry Kuwait: thẻ Đã gửi + đơn #14374 mà AI vẫn chat 10+ tin).
        # Đổi số ra {id, text} theo settings.tags của page.
        c["tags"] = [({"id": t, "text": ten_the.get(t)} if isinstance(t, int) else t)
                     for t in (c.get("tags") or [])]
    if gio:
        convs = [c for c in convs if _giay_tu(c.get("updated_at")) <= gio * 3600]
    return {"conversations": convs}, None


_THE_TEN_PAGE = {}    # pid -> ({id thẻ: tên}, lúc hỏi) — settings.tags qua API nội bộ


def _the_ten_page_user(page_id):
    cu = _THE_TEN_PAGE.get(str(page_id))
    if cu and time.time() - cu[1] < 600:
        return cu[0]
    res, err = _get(f"{WEB_API}/pages/{page_id}/settings", {"access_token": _tok_user()})
    tags = [] if (err or not res) else (res.get("tags") or (res.get("settings") or {}).get("tags") or [])
    bang = {t.get("id"): t.get("text") for t in tags if isinstance(t, dict)}
    if not bang and cu:
        return cu[0]                      # hỏi hỏng → dùng bảng cũ, đừng làm mù cửa thẻ
    if not bang:
        print(f"     ⚠️  không đọc được tên thẻ page {page_id}: {err} — cửa thẻ Đã gửi mù ở page này")
    _THE_TEN_PAGE[str(page_id)] = (bang, time.time())
    return bang


# ══ THẺ "AI CHAT" — SALE GẮN THÌ AI NGƯNG, GỠ THÌ AI CHAT LẠI (THE_AI_CHAT_2609) ══════════════════════════════════
# Chủ shop 26/09: *"khi sale gắn thẻ tag này là bạn ngưng chat, còn khi gỡ tag là bạn sẽ chat lại tư vấn như bình
# thường"*. Từ 20/09 AI KHÔNG nhường sale ("k nhường sale") → thẻ này là đường DUY NHẤT để sale giành lại một hội
# thoại. Đang mang thẻ: AI không đọc, không rep, không ghi chú, không đánh dấu chưa đọc — như thẻ "Đã gửi" nhưng KHÔNG
# có ngoại lệ 9b Mỹ/Úc. Daemon lên đơn (auto_len_don) KHÔNG xét thẻ này, vẫn lên đơn nháp như cũ. Gỡ thẻ: vòng dò xét
# lại hội thoại ngay (khách đang chờ thì AI rep theo luật thường). Thẻ do chuan_the.py (THEM) tạo sẵn trên mọi page
# còn gói, id theo current_tag_index. Tên khác: AI_THE_TAT="AI CHAT,Tên khác" trong .env (không cần restart).
# So tên bỏ hết khoảng trắng + chữ thường: "AI CHAT", "Ai Chat", "AICHAT " đều là một.
_THE_TAT_BANG = [None, 0.0]


def _chuan_the_tat(s):
    return re.sub(r"\s+", "", unicodedata.normalize("NFC", str(s or ""))).lower()


def _the_tat_ds():
    if _THE_TAT_BANG[0] is None or time.time() - _THE_TAT_BANG[1] > 60:
        ds = env().get("AI_THE_TAT") or os.environ.get("AI_THE_TAT") or "AI CHAT"
        _THE_TAT_BANG[0] = {_chuan_the_tat(x) for x in ds.split(",") if x.strip()}
        _THE_TAT_BANG[1] = time.time()
    return _THE_TAT_BANG[0]


def the_tat_ai(c):
    """Tên thẻ tắt AI ("AI CHAT") nếu hội thoại đang mang, không thì None. Nhận bản ghi DANH SÁCH hội thoại."""
    ds = _the_tat_ds()
    for t in ((c or {}).get("tags") or []):
        if isinstance(t, dict) and _chuan_the_tat(t.get("text")) in ds:
            return t.get("text")
    return None


def the_tat_ai_luc_gui(pid, conv_id, token):
    """Ngay trước khi gửi: sale vừa gắn thẻ AI CHAT trong lúc AI soạn (~10-30s)? Đọc DANH SÁCH (không mở hội thoại →
    không lật cờ đã xem). Đọc hỏng → None: không chặn, đừng vì kiểm mà câm."""
    try:
        return the_tat_ai(_hoi_thoai_trong_ds(pid, conv_id, token))
    except Exception:                                    # noqa: BLE001
        return None


def _customer_id_user(page_id, conv_id):
    k = (str(page_id), str(conv_id))
    if k not in _CUST:
        _hoi_thoai_user(page_id)
    return _CUST.get(k)


def gui_qua_user_bat():
    """Kênh gửi bằng TÀI KHOẢN Pancake (PANCAKE_USER_TOKEN) — bật mặc định từ 14/09/2026.

    Facebook chặn #2022 bám theo PAGE + kênh Public API (đổi tài khoản sinh token page vẫn
    chặn — đo 14/09: Kreain/Al Shifa nhận token mới vẫn #2022 ngay). Nhưng sale gửi từ giao
    diện Pancake vẫn được, vì giao diện đi đường khác: POST pancake.vn/api/v1/.../messages
    với access_token của TÀI KHOẢN. Tool đi cùng đường đó bằng tài khoản riêng của AI
    ("PHƯƠNG ANH LEADER 2"), tin hiện tên tài khoản như một sale. Dùng được cả ở page tài
    khoản chỉ là Biên tập viên (đọc/gửi hội thoại không cần Admin — chỉ sinh token page mới cần).
    Tắt: AI_GUI_QUA_USER=0.
    """
    return str(os.environ.get("AI_GUI_QUA_USER") or env().get("AI_GUI_QUA_USER") or "1") != "0"


def gui_tin_qua_user(page_id, conv_id, text):
    tok = env().get("PANCAKE_USER_TOKEN", "")
    if not tok:
        return False, "thiếu PANCAKE_USER_TOKEN"
    res, err = _post(f"https://pancake.vn/api/v1/pages/{page_id}/conversations/{conv_id}/messages",
                     {"access_token": tok}, {"action": "reply_inbox", "message": text})
    if err:
        return False, f"kênh tài khoản: {err}"
    if not (res or {}).get("success", True):
        return False, f"kênh tài khoản: {str(res)[:200]}"
    _LAN_GUI_CUOI[0] = time.time()
    _GUI_THEO_PAGE.setdefault(str(page_id), []).append(time.time())
    return True, None


_CHAN_VUA_GAP = set()   # page vừa bị #2022 ở kênh Public API trong lần gửi này (gui_tin đã né sang kênh tài khoản)


NHUONG_GUI = "NHƯỜNG:"   # gui_tin trả lỗi bắt đầu bằng chữ này = kiem_lai báo có người vừa nhắn, KHÔNG gửi


def gui_tin(page_id, conv_id, token, text, dry=True, sau_anh=False, kiem_lai=None, noi_tiep=False):
    """Gửi tin nhắn inbox cho khách. Tin đứng tên page (không truyền sender_id) — luật mục 9.

    Page bị Facebook chặn kênh Public API (#2022) → né sang kênh tài khoản (gui_tin_qua_user)
    ngay trong lần gửi này; page đã biết là bị chặn (_FB_CHAN) thì đi thẳng kênh tài khoản.
    """
    # LƯỚI CUỐI CHO SỐ WHATSAPP ĐÃ NGƯNG (20/09) — cửa này mọi tin đều qua, kể cả mẫu shop gửi
    # nguyên văn và bong bóng thứ 2-3 của bước kịch bản (những đường mà cổng ở tầng quyết định cố ý
    # không đụng vào chữ của shop). Bong bóng chỉ có mỗi số thì bỏ hẳn, coi như đã xong: nội dung duy
    # nhất của nó là thứ bị cấm gửi.
    if text and WA_SHOP.search(text):
        _sach_wa = cat_wa_shop(text)
        if not _sach_wa:
            log(f"   📵 tin toàn số WhatsApp đã ngưng — KHÔNG gửi: {text[:100]!r}")
            return True, None
        log(f"   📵 bỏ câu có số WhatsApp đã ngưng khỏi tin sắp gửi: {text[:100]!r}")
        text = _sach_wa
    # LƯỚI CUỐI CHO CHỮ NỘI BỘ (20/09) — bắt những đường không qua cổng ở tầng quyết định:
    # bong bóng thứ 2-3 của bước kịch bản, tin gửi lại sau lỗi, mẫu trả lời nhanh. Đo cùng ngày:
    # 0/8 bộ kịch bản của shop chứa chữ này, nên lưới này không đụng vào chữ shop viết.
    if text and lo_noi_bo(text):
        _sach_lo = cat_cau_lo_noi_bo(text)
        if not _sach_lo:
            log(f"   🕵️  tin lộ chữ nội bộ, gỡ không được — KHÔNG gửi: {text[:100]!r}")
            return True, None
        log(f"   🕵️  bỏ câu lộ chữ nội bộ khỏi tin sắp gửi: {text[:100]!r}")
        text = _sach_lo
    if dry:
        log(f"   [THỬ] sẽ gửi: {text[:120]!r}")
        return True, None
    # 17/09 tối — chủ shop chọn "20s theo page, bỏ trần": giãn AI_GIAN_CACH_GUI giây giữa hai tin
    # CÙNG PAGE, không còn tính chung cả nước. Bản cũ bắt mọi page xếp MỘT hàng 20s/tin, cả lượt
    # xử đứng đợi, khách nhắn sau phải chờ lượt trước gửi xong (Saudi lúc đông: 90% khách chờ tới
    # 5p41s). Đo 14→17/09: chỉ 3% tin gửi cách tin trước CÙNG page dưới 60s, nên giãn theo page
    # gần như không bắt ai đợi. Chung cả nước chỉ giữ AI_GIAN_CACH_CHUNG giây cho khỏi bắn dồn.
    # `sau_anh`: chữ đi ngay sau ảnh của CÙNG câu trả lời — ảnh + lời là một lượt, không đợi 20s.
    # 18/09: nhiều lượt xử chạy SONG SONG → hai luồng có thể cùng thấy "page rảnh" rồi cùng gửi. Nên GIỮ
    # CHỖ dưới khoá: mỗi lần gửi đặt trước một mốc giờ; lần sau cùng page phải sau mốc đó ≥ AI_GIAN_CACH_GUI,
    # mọi page ≥ AI_GIAN_CACH_CHUNG. Đợi thì đợi NGOÀI khoá.
    _p = str(page_id)
    with _KHOA_GUI:
        _bay_gio = time.time()
        _moc_page = max((_GUI_THEO_PAGE.get(_p) or [0.0])[-1], _HEN_GUI_PAGE.get(_p, 0.0))
        _luc_gui = max(_bay_gio,
                       # `noi_tiep`: tin thứ 2, 3… của CÙNG một bước kịch bản — page gửi liền nhau nên
                       # không đợi 20s; vẫn còn AI_GIAN_CACH_CHUNG (3s) nên các bong bóng cách nhau tự nhiên.
                       _bay_gio if (sau_anh or noi_tiep) else _moc_page + _so_env("AI_GIAN_CACH_GUI", 20),
                       max(_LAN_GUI_CUOI[0], _HEN_GUI_CHUNG[0]) + _so_env("AI_GIAN_CACH_CHUNG", 3))
        _HEN_GUI_PAGE[_p] = _luc_gui
        _HEN_GUI_CHUNG[0] = max(_HEN_GUI_CHUNG[0], _luc_gui)
    if _luc_gui > time.time():
        time.sleep(_luc_gui - time.time())   # giãn nhịp giữa hai lần gửi — luật 11/09
    # `kiem_lai()` (từ _phan_hoi) đọc lại hội thoại SAU khi đợi nhịp: trả "khách"/"sale …"/"Botcake" nếu
    # vừa có người nhắn → không gửi, nhả chỗ giữ nhịp, báo NHUONG_GUI để chỗ gọi nhường/hoãn.
    _vuot = kiem_lai() if kiem_lai else None
    if _vuot:
        with _KHOA_GUI:
            if _HEN_GUI_PAGE.get(_p) == _luc_gui:
                _HEN_GUI_PAGE[_p] = _moc_page
        return False, NHUONG_GUI + str(_vuot)
    ok, err = _gui_tin_ngay(page_id, conv_id, token, text)
    if not ok:
        with _KHOA_GUI:                      # gửi hỏng không giữ chỗ — lần thử lại #2022 khỏi đợi 20s
            if _HEN_GUI_PAGE.get(_p) == _luc_gui:
                _HEN_GUI_PAGE[_p] = _moc_page
    return ok, err


def _gui_tin_ngay(page_id, conv_id, token, text):
    """Phần gửi thật của gui_tin (sau khi đã giữ chỗ + đợi nhịp)."""
    if _la_user(token) or (str(page_id) in _FB_CHAN and gui_qua_user_bat()):
        return gui_tin_qua_user(page_id, conv_id, text)
    res, err = _post(f"{BASE_V1}/pages/{page_id}/conversations/{conv_id}/messages",
                     {"page_access_token": token},
                     {"action": "reply_inbox", "message": text})
    ok = res is not None and not err
    if ok:
        _LAN_GUI_CUOI[0] = time.time()
        _GUI_THEO_PAGE.setdefault(str(page_id), []).append(time.time())
    elif "#2022" in str(err) and gui_qua_user_bat():
        _CHAN_VUA_GAP.add(str(page_id))
        ok2, err2 = gui_tin_qua_user(page_id, conv_id, text)
        if ok2:
            log(f"   ↪ Public API bị chặn (#2022) → đã gửi bằng tài khoản Pancake")
            return True, None
        return False, f"{err} | {err2}"
    return ok, err


# ─────────── Dấu "AI SALE" NGOÀI danh sách hội thoại (chủ shop 12/09) ───────────
#
# Chủ shop muốn nhìn ngoài danh sách là biết AI đã rep, kiểu chữ [Botcake] mà Pancake in.
# Soi API 12/09: chữ đó KHÔNG nằm trong tin — tin Botcake chỉ là "✨ Your birth month…".
# Pancake tự in nhãn cho TÍCH HỢP CỦA NÓ: tin Botcake mang `app_id`+`flow_id` → "[Botcake]",
# tin POS mang `is_automated` → "[POS Reply]". Tin gửi qua Public API (dù đứng tên page hay
# tên một user qua `sender_id`) có `from` y hệt tin sale gõ tay → Pancake KHÔNG gắn nhãn, và
# endpoint gửi tin không có trường nào đặt nhãn (openapi: action/message/content_ids/filename/
# sender_id/reply_message_id). Nhét "[AI SALE]" vào câu thì KHÁCH ĐỌC THẤY — không được.
# Còn đúng một đường hiện ra ngoài mà khách không thấy: TAG hội thoại (chip cạnh "Bot",
# "Bot Delay" trong danh sách). Tag phải được tạo sẵn trên page — API công khai chỉ cho ĐỌC
# danh sách tag (POST /pages/<id>/tags trả 404), nên chủ shop tạo tag một lần trên Pancake.
TAG_AI = os.environ.get("AI_TAG_TEN", "AI SALE").strip()
_TAG_AI_ID = {}          # pid -> (id tag, lúc hỏi); id None = page chưa tạo tag này
_TAG_HOI_LAI = 900       # giây — page chưa có tag thì hỏi lại, chủ shop vừa tạo là nhận ngay
_TAG_DA_GAN = set()      # (pid, conv) đã gắn trong tiến trình này — khỏi gọi API lại
_TAG_DA_BAO = set()      # page đã kêu "chưa có tag" — kêu 1 lần thôi, khỏi rác log


def _tag_ai_id(pid, token):
    """Id tag tên TAG_AI trên page. Hỏi API một lần mỗi page mỗi tiến trình."""
    cu = _TAG_AI_ID.get(str(pid))
    if cu and (cu[0] is not None or time.time() - cu[1] < _TAG_HOI_LAI):
        return cu[0]
    tid = None
    if _la_user(token):
        res, err = _get(f"{WEB_API}/pages/{pid}/settings", {"access_token": _tok_user()})
        if res and not err:
            res = {"tags": (res.get("tags") or (res.get("settings") or {}).get("tags") or [])}
    else:
        res, err = qht.http_json("GET", f"{qht.BASE_PAGE_V1}/pages/{pid}/tags",
                                 {"page_access_token": token})
    if err:
        print(f"     ⚠️  không đọc được danh sách tag của page {pid}: {err}")
    else:
        for t in (res or {}).get("tags") or []:
            if qht.norm(t.get("text")) == qht.norm(TAG_AI) and t.get("id") is not None:
                tid = t["id"]
                break
        if tid is None and str(pid) not in _TAG_DA_BAO:
            _TAG_DA_BAO.add(str(pid))
            print(f"     🏷  page {pid} chưa có tag '{TAG_AI}' — tạo tag tên này trên Pancake "
                  f"thì AI tự gắn (hỏi lại mỗi {_TAG_HOI_LAI // 60} phút, không cần restart)")
    _TAG_AI_ID[str(pid)] = (tid, time.time())
    return tid


def gan_tag_ai(pid, conv_id, token, dry=True):
    """Gắn tag TAG_AI lên hội thoại. Chỉ hiện với người trong shop — khách KHÔNG thấy gì."""
    if not TAG_AI:
        return
    khoa = (str(pid), str(conv_id))
    if khoa in _TAG_DA_GAN:
        return
    tid = _tag_ai_id(pid, token)
    if tid is None:
        return
    if dry:
        log(f"   [THỬ] sẽ gắn tag '{TAG_AI}' (id {tid})")
        _TAG_DA_GAN.add(khoa)
        return
    if _la_user(token):
        res, err = _post(f"{WEB_API}/pages/{pid}/conversations/{conv_id}/toggle_tag",
                         {"access_token": _tok_user()}, {"tag_id": tid, "value": 1})
    else:
        res, err = _post(f"{BASE_V1}/pages/{pid}/conversations/{conv_id}/tags",
                         {"page_access_token": token}, {"action": "add", "tag_id": str(tid)})
    if err:
        print(f"     ⚠️  gắn tag '{TAG_AI}' hỏng: {err}")
    else:
        _TAG_DA_GAN.add(khoa)


def _hoi_thoai_trong_ds(page_id, conv_id, token):
    """Bản ghi MỘT hội thoại lấy từ danh sách (không mở hội thoại → không lật cờ đã xem). None = không thấy."""
    now = int(time.time())
    if _la_user(token):
        res, err = _hoi_thoai_user(page_id)
    else:
        res, err = qht.http_json("GET", f"{BASE_V2}/pages/{page_id}/conversations",
                                 {"page_access_token": token, "since": now - 3 * 86400,
                                  "until": now, "order_by": "updated_at"})
    if err or not res:
        return None
    return next((c for c in res.get("conversations") or [] if str(c.get("id")) == str(conv_id)), None)


# Giây chờ thêm giữa các lần canh SAU khi danh_dau_chua_doc đã thấy "chưa đọc" (~4s sau lúc gửi).
_CHO_ECHO_MUON = (6, 10)


def _canh_echo_muon(page_id, conv_id, token, luc_gui, nhan="", cho=None):
    """Echo MUỘN của tin AI vừa gửi lật hội thoại về "đã đọc" → đánh lại chưa đọc (20/09).

    Đo 19/09: 6 hội thoại "AI LEADER đã xem" đúng 6-7s sau lúc AI gửi qua tài khoản — SAU lần đọc lại cờ ở giây
    thứ 4 của danh_dau_chua_doc (lúc đó vẫn "chưa đọc", nên sổ ghi chua_doc=1 mà hội thoại vẫn trôi).
    Sale thật đã mở xem sau lúc AI gửi → để yên (luật 19/09: sale xem rồi thì không đánh).
    """
    moc = {"luc": time.strftime("%Y-%m-%dT%H:%M:%S", time.gmtime(luc_gui))}
    for cho_ in (cho or _CHO_ECHO_MUON):
        time.sleep(cho_)
        try:
            c = _hoi_thoai_trong_ds(page_id, conv_id, token)
            if not c or not c.get("seen"):
                continue
            ai_xem = _nguoi_that_da_xem(c, moc, page_id, conv_id)
            if ai_xem:
                return
            ok, loi = danh_dau_chua_doc(page_id, conv_id, token, dry=False, lan=2, cho=4)
            print(f"{nhan} ↩️  Pancake lật hội thoại về 'đã đọc' muộn ({time.time() - luc_gui:.0f}s sau lúc AI gửi/đánh dấu)"
                  f" — đánh lại chưa đọc {'✔' if ok else '✖ ' + str(loi)[:80]}", flush=True)
        except Exception as e:                           # noqa: BLE001 — canh hỏng không được giết luồng
            print(f"{nhan} ⚠️  canh echo muộn lỗi: {e!r}", flush=True)
            return


def _co_da_doc(page_id, conv_id, token):
    """Đọc lại cờ `seen` của MỘT hội thoại. Trả (True/False/None, lỗi).

    Pancake KHÔNG có endpoint lấy một hội thoại (`GET .../conversations/<id>` trả rỗng,
    thử cả v1 lẫn v2 ngày 2026-09-10), nên phải lấy cả danh sách rồi lọc ra.
    `None` nghĩa là KHÔNG BIẾT — chỗ gọi không được coi là đã đánh dấu xong.
    """
    now = int(time.time())
    if _la_user(token):
        res, err = _hoi_thoai_user(page_id)
    else:
        res, err = qht.http_json("GET", f"{BASE_V2}/pages/{page_id}/conversations",
                                 {"page_access_token": token, "since": now - 3 * 86400,
                                  "until": now, "order_by": "updated_at"})
    if err or not res:
        return None, err or "API không trả gì"
    for c in res.get("conversations") or []:
        if str(c.get("id")) == str(conv_id):
            return bool(c.get("seen")), None
    return None, "không thấy hội thoại trong danh sách 3 ngày"


def _f_chan_fb(mkey):
    return os.path.join(SCRIPT_DIR, "state", mkey, "page_bi_fb_chan.json")


def _nho_page_bi_chan(mkey, pid, ten_page, loi):
    try:
        d = json.load(open(_f_chan_fb(mkey), encoding="utf-8")) if os.path.exists(_f_chan_fb(mkey)) else {}
    except Exception:                                    # noqa: BLE001
        d = {}
    d[str(pid)] = {"ten": ten_page, "luc": int(time.time()), "loi": loi[:160]}
    json.dump(d, open(_f_chan_fb(mkey), "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    if gui_qua_user_bat():
        print(f"     ⛔ {ten_page}: Facebook chặn kênh Public API (#2022) — từ giờ gửi bằng tài khoản Pancake")
    else:
        print(f"     ⛔ {ten_page}: Facebook chặn gửi (#2022) — bỏ qua page này 1 giờ rồi thử lại")


def _f_anh_chan(mkey):
    return os.path.join(SCRIPT_DIR, "state", mkey, "page_anh_bi_chan.json")


# Mã Pancake trả khi đẩy ảnh sang Facebook hỏng — ảnh CHƯA tới khách (bắt được 20/09 sau khi
# vá quet_hoi_thoai.loi_api đọc thêm `message_code`; trước đó mọi ca chỉ ghi "không rõ lý do").
ANH_HONG_CHAP_CHON = "invalid_upload_fb_attachments_result"


def nho_page_anh_chan(mkey, pid, ten_page, loi):
    """Facebook từ chối ĐÍNH KÈM ở page này → nhớ 1 giờ để lượt sau khỏi hứa ảnh với khách.

    Đo 16/09 (Sweet Curve Co - Ksa, đang #2022): ảnh đầu đi lọt, các lần sau trả
    `invalid_upload_fb_attachments_result`. Biết trước thì prompt tắt mời gửi ảnh → model
    viết tin TƯ VẤN bình thường thay vì "here are the photos" rồi khách đợi hụt.
    """
    try:
        d = json.load(open(_f_anh_chan(mkey), encoding="utf-8")) if os.path.exists(_f_anh_chan(mkey)) else {}
    except Exception:                                    # noqa: BLE001
        d = {}
    # Khoá BAO LÂU tuỳ loại lỗi: `invalid_upload_fb_attachments_result` là chập chờn từng tin
    # (đo 20/09: 48/156 lượt gửi ảnh hỏng, tất cả đều mã này, mà cùng page vẫn gửi được lúc khác)
    # → khoá 10 phút, đủ để không bắn lặp ngay lượt sau. Lỗi khác (page bị chặn thật) giữ 1 giờ.
    phut = 10 if ANH_HONG_CHAP_CHON in str(loi) else 60
    d[str(pid)] = {"ten": ten_page, "luc": int(time.time()), "loi": str(loi)[:160], "phut": phut}
    json.dump(d, open(_f_anh_chan(mkey), "w", encoding="utf-8"), ensure_ascii=False, indent=1)


def page_anh_bi_chan(mkey, pid, gio=1):
    """True nếu page này vừa bị từ chối đính kèm trong `gio` giờ qua (1 giờ, như chặn chữ)."""
    if not mkey:
        return False
    try:
        d = json.load(open(_f_anh_chan(mkey), encoding="utf-8"))
    except Exception:                                    # noqa: BLE001
        return False
    r = d.get(str(pid))
    if not r:
        return False
    return time.time() - r.get("luc", 0) < (r.get("phut") or gio * 60) * 60


def anh_gui_duoc(mkey, pid):
    """Page này gửi được ảnh trong lượt này không? — dùng cho PROMPT, để model biết đường viết."""
    if not gui_anh_bat() or page_anh_bi_chan(mkey, pid):
        return False
    if str(pid) in _FB_CHAN and not (gui_qua_user_bat() and anh_qua_user_bat()):
        return False
    return True


def page_dang_bi_fb_chan(mkey, pid, gio=1):
    """True nếu page này bị Facebook chặn gửi trong `gio` giờ qua.

    Để 1 giờ chứ không 6: Facebook gỡ chặn lúc nào không báo, mà mỗi lần thử lại chỉ tốn
    một lượt model (~$0.004) + một lần gửi hỏng. Ca thật 10/09: Golden Soap House bị chặn
    06:42, tool im tới 12:42 trong khi sale vẫn gửi được qua giao diện Pancake — chủ shop
    hỏi "page này sao không rep". Chặn 6 giờ là tự tay tắt AI trên page đó nửa ngày.
    """
    try:
        d = json.load(open(_f_chan_fb(mkey), encoding="utf-8"))
    except Exception:                                    # noqa: BLE001
        return False
    r = d.get(str(pid))
    return bool(r) and time.time() - r.get("luc", 0) < gio * 3600


def danh_dau_chua_doc(page_id, conv_id, token, dry=True, lan=3, cho=4):
    """Treo hội thoại cho sale — mục 7. ĐÁNH RỒI PHẢI ĐỌC LẠI, KHÔNG TIN API.

    Đo tận tay 2026-09-10 trên 5 hội thoại AI vừa gửi tin thật: API `/unread` trả
    `{"success": true}` cả 5, nhưng đọc lại cờ `seen` thì 4/5 đã bị lật về **đã đọc**.
    Nguyên nhân: Pancake xử lý tin gửi đi BẤT ĐỒNG BỘ — cái "echo" của chính tin mình
    vừa gửi về tới vài giây sau và đặt lại `seen=true`, nuốt mất dấu chưa đọc.

    Hậu quả nếu tin API: chủ shop mở Pancake không thấy chấm đỏ, tin AI gửi cho khách
    trôi mất, không ai soát — đúng thứ luật mục 7 sinh ra để chặn.

    Nên: đánh dấu → đợi → ĐỌC LẠI cờ → còn "đã đọc" thì đánh lại, tối đa `lan` lượt.
    Chỉ trả True khi TẬN MẮT thấy cờ đã về chưa đọc.
    """
    if dry:
        log("   [THỬ] sẽ đánh dấu CHƯA ĐỌC (có đọc lại để xác nhận)")
        return True, None
    loi = None
    for i in range(lan):
        if _la_user(token):
            res, err = _post(f"{WEB_API}/pages/{page_id}/conversations/{conv_id}/mark_unread",
                             {"access_token": _tok_user()})
        else:
            res, err = _post(f"{BASE_V1}/pages/{page_id}/conversations/{conv_id}/unread",
                             {"page_access_token": token})
        if err or res is None:
            loi = err or "API không trả gì"
            time.sleep(cho)
            continue
        time.sleep(cho)          # chờ cái echo của tin vừa gửi đi qua rồi mới soi
        da_doc, err2 = _co_da_doc(page_id, conv_id, token)
        if da_doc is False:
            return True, None    # tận mắt thấy: đang chưa đọc
        loi = err2 or "Pancake lật lại thành ĐÃ ĐỌC"
    return False, f"{loi} (thử {lan} lượt)"


def ghi_chu(page_id, customer_id, token, text, dry=True):
    """Ghi chú nội bộ cho sale đọc — mục 7 bắt buộc kèm mỗi lần treo.

    Kiểm chứng tận mắt trên giao diện Pancake 2026-09-04: ghi chú gửi bằng API HIỆN đúng
    trong tab "Thông tin" của hội thoại, đứng tên **"Public API"**.
    `customer_id` chính là `customers[0].id` mà API tin nhắn trả về (đã đối chiếu: trùng
    `id` trong /page_customers, KHÁC `customer_id` ở đó — đừng nhầm hai trường này).
    Mẹo: phản hồi của lệnh POST trả về **cả danh sách ghi chú của khách kèm `id`** — muốn xoá
    thì lấy id từ đó rồi gọi DELETE cùng đường dẫn với body {"note_id": ...}.
    """
    if dry:
        log(f"   [THỬ] sẽ ghi chú: {text[:120]!r}")
        return True, None
    if not customer_id:
        return False, "thiếu page_customer_id"
    if _la_user(token):
        res, err = _post(f"{WEB_API}/pages/{page_id}/customers/{customer_id}/notes",
                         {"access_token": _tok_user()},
                         {"message": text, "images": "[]", "links": "[]"})
    else:
        res, err = _post(f"{BASE_V1}/pages/{page_id}/page_customers/{customer_id}/notes",
                         {"page_access_token": token}, {"message": text})
    return (res is not None and not err), err


def gan_tag(page_id, conv_id, token, tag_id, dry=True):
    """Gắn tag chốt đơn -> daemon auto_len_don.py sẽ tạo đơn. Tên tag: xem mục 11."""
    if dry:
        log(f"   [THỬ] sẽ gắn tag id={tag_id}")
        return True, None
    if _la_user(token):
        res, err = _post(f"{WEB_API}/pages/{page_id}/conversations/{conv_id}/toggle_tag",
                         {"access_token": _tok_user()}, {"tag_id": tag_id, "value": 1})
    else:
        res, err = _post(f"{BASE_V1}/pages/{page_id}/conversations/{conv_id}/tags",
                         {"page_access_token": token},
                         {"action": "add", "tag_id": str(tag_id)})
    return (res is not None and not err), err


# ─────────────── AI có vào cuộc không — mục 0b (bản 2026-09-03) ───────────────
#
# Botcake nay trả lời khách THEO TỪ KHOÁ, không chỉ chào hàng. AI chỉ vào cuộc khi
# Botcake IM hoặc TRẢ LỜI SAI. Bộ lọc Nhóm A/B của bản 28/8 đã BỎ.

CHAO = (r"^(hi+|hey+|hello+|hallo|helo|hola|yo|ola|salam|assalam|as-?salamu?\s*alaykum|"
        r"السلام\s*عليكم|مرحبا|اهلا|xin\s*chào|chào|good\s*(morning|evening|day|afternoon)|"
        r"kumusta|kamusta|你好|こんにちは|buna|buenas)\b")
NUT = r"^(get\s*started|bắt\s*đầu|start!?|menu|ok|okay|oo|yes|no|sure|👍|\?+|\.+)$"
# CÂU HỎI CHÍNH SÁCH TRƯỚC KHI MUA — khách chưa có đơn nào, chỉ muốn biết luật COD
# ("mở kiện xem hàng trước khi trả tiền được không"). Phải xét TRƯỚC DON_CU vì mấy câu này
# cũng chứa 'parcel'. Chủ shop bắt 2026-09-11, ca Mary Jane Dalaguit Eliguen (Minty Fresh
# Smile UAE): "Can I open the parcel before I pay?" → AI treo "chuyện đơn cũ" trong khi khách
# CHƯA có đơn nào. *"sao lại chuyện cũ?? bạn phải rep cái này chứ"*. Treo oan ở đây đắt gấp
# đôi: vừa mất câu trả lời, vừa chặn luôn bước lên đơn sớm (cờ `khong_tao` ở vòng chạy).
TRUOC_MUA = (r"((open|check|inspect|see|look\s*at|try)[^.?!]{0,30}(before|prior\s*to)[^.?!]{0,20}"
             r"(pay|paying|payment)|before\s+(i\s+)?pay(ing)?\b|"
             r"pay\s+(first|before)[^.?!]{0,20}(open|check|see)|"
             r"(pwede|puwede|maaari)[^.?!]{0,35}(buksan|tingnan|makita|check)|"
             r"bago\s+(ko\s+|ako\s+)?(bayaran|magbayad|bayad)|bayad\s+pagkatapos|"
             r"قبل\s*(ال)?دفع|قبل\s*ما\s*[أا]دفع|"
             r"(mở|kiểm\s*tra|xem)\s*(hàng|kiện|hộp|bưu\s*kiện)?\s*trước\s*khi\s*"
             r"(thanh\s*toán|trả\s*tiền))")

# Chuyện ĐƠN CŨ / giao hàng -> treo cho sale theo mục 7.4 (không phải việc của AI).
# 'parcel' vẫn đứng trần ở đây (đo 11/09: nới nó ra thì "Not parcel looks is that it's normal"
# — khách đang nói về kiện hàng đã giao — bị thả oan). Câu hỏi chính sách của khách MỚI đi qua
# cửa TRUOC_MUA ở trên, xét trước, nên không cần đụng vào danh sách này.
#
# ⚠️ REGEX NÀY CHỈ LÀ BỘ LỌC RẺ, KHÔNG PHẢI PHÁN QUYẾT (chủ shop 2026-09-14, ca Ajnick Datucali,
# Golden Soap House UAE): khách chưa mua gì hỏi "If ever I need to change area for delivery it's
# ok?" → "delivery it" khớp → treo "chuyện đơn cũ". *"sao lại là chuyện cũ, khách đã mua hàng ở
# page này đâu, vẫn phải rep trong TH này chứ"*. Đo 72h trước khi vá: 9 hội thoại bị đây treo thì
# 5 khách CHƯA có đơn nào trên POS ("can you deliver it", "deliver today? birthday gift", "paano
# bayad sa rider", ...). Nên ở vòng chạy, khớp DON_CU rồi còn phải TRA POS (`da_mua_o_page`):
# không có đơn → là câu hỏi TRƯỚC MUA, AI trả lời — KHÔNG có ngoại lệ theo chữ. Chủ shop nhắc
# lại lần 2 cùng ngày: *"khách này chưa từng mua hàng ở page này, nên được coi là khách mới,
# khách chỉ hỏi như vậy là bạn phải trả lời khách chứ sao lại treo cho sale"*. Bản đầu còn giữ
# nhóm "refund / not received…" treo dù không có đơn — đã bỏ theo ý chủ shop. Lưới đỡ còn lại là
# model: đọc ra khiếu nại thật thì nó vẫn được treo (mục 7, thấy trong sổ việc là `tra_loi_treo`).
DON_CU = (r"(delivery\s*(man|guy|boy)|deliver(ed|y)?\s*(it\b(?!')|na\b|already|yesterday|today)|"
          r"shipper|courier|rider|tracking|parcel|refund|return\s*(it|the|my)|"
          r"already\s*(paid|received|got)|not\s*(yet\s*)?(received|delivered|arrived)|"
          r"still\s*waiting|my\s*order|the\s*order\s*(i|was|is)|bring\s*change|"
          r"đơn\s*(của\s*)?(tôi|em|mình)|"
          r"chưa\s*nhận|đã\s*nhận|hoàn\s*tiền|trả\s*hàng|giao\s*rồi)")


def _chi_ky_hieu(t):
    """Chuỗi chỉ gồm emoji/dấu câu/khoảng trắng — coi như sticker."""
    return bool(t) and all(
        unicodedata.category(ch)[0] in "SPZC" or ch in "?!." for ch in t)


# "how. much" / "how.much" / "haw.mush" / "how,much" — dấu chen giữa làm mọi bộ dò giá mù (24/09, ca Mie Mie · Kreain Nature
# PH - Ksa: AI tả công dụng rồi hỏi "2-item hay 4-item" mà không báo giá). Sổ khách ~130 lần. Gộp về "how much".
# "who much" / "how's much" / "howb much" / "hi much po" — gõ nhầm how much (24/09, ca Tess Delijero · Kreain Nature PH
# in Uae: AI kể 2 gói không giá). "hi much" chỉ tính ở ĐẦU tin và đứng cuối / trước po|pls|?.
_HOW_GO_NHAM = re.compile(r"(?i)\b(?:who|how'?s|howb|whow)(?=\s*(?:much|mush|mach)\b)"
                          r"|^(\W*)hi(?=\s+much\s*(?:po\b|pls\b|please\b|\?|$))")
# HWO_CHAM_2609 (ca Mucaa Iluu: "Hwo.much", "Ok.hwo.much.") — tiền tố gõ sai lấy đúng bộ của _HOW_MUCH_GO_SAI.
_HOW_CHAM_MUCH = re.compile(r"(?i)\b(how|haw|hou|hw|hoe|huw|hiw|h(?:o[wuea]?[wo]?|a[wu]o?|u[wh]?|iw|ew|wo?|hw|or|pw|lw|sw))\s*[.,;:!?]+\s*"
                            r"(much|mush|mach|mahc|mch|muck|mich|mych|many|mutch|mouch)\b")


def lam_sach(t):
    # Chữ in đậm kiểu Unicode toán học (𝟖𝟗 𝐒𝐀𝐑) → chữ thường — mọi bộ dò đọc được (ca Noel 14/09).
    t = re.sub(r"<[^>]+>", " ", CG.bo_chu_toan(t))
    t = _HOW_CHAM_MUCH.sub(r"\1 \2", t)
    t = _HOW_GO_NHAM.sub(lambda m: (m.group(1) or "") + "how", t)
    return re.sub(r"\s+", " ", t).strip()


# Tên người gửi của CHÍNH AI: "Public API" (gửi bằng token page) + tên tài khoản Pancake của AI
# (gửi bằng tài khoản, từ 14/09). Cùng nguồn với hieu_suat.TEN_TAI_KHOAN_AI.
TEN_GUI_CUA_AI = {"Public API"} | {
    t.strip() for t in (os.environ.get("AI_TEN_TAI_KHOAN") or "AI LEADER,PHƯƠNG ANH LEADER 2").split(",")
    if t.strip()}


def nguoi_gui(m, page_id):
    """Tin này ai gửi: 'khach' | 'botcake' | 'ai' | 'nguoi' | 'hethong'.

    'ai' TÁCH khỏi 'nguoi' từ 2026-09-14 (ca Seeba Kbabu, Dubai Luxe Charm): khách gửi "2 pc"
    07:30:19 rồi "How many gram" 07:30:58; AI soạn cho "2 pc", gửi 07:31:05 bằng tài khoản
    "AI LEADER". Lượt sau AI thấy tin "AI LEADER" nằm SAU câu gram → tưởng "sale thật đã vào" →
    im; vòng dò nhanh cũng coi hội thoại là "sale vừa gửi" nên thôi đọc. Chủ shop: *"SAO CÂU THỨ
    2 BAO NHIÊU GRAM THÌ B LẠI K REP"*. Trả lời trùng đã có `dax` (mốc tin khách) chặn, không cần
    nhờ nhãn "nguoi" nữa.

    Đo thật 60 hội thoại UAE (2026-09-03): page gửi 619 tin — `from.admin_name` là
    'Botcake' 350 tin, tên nhân viên 76 tin, KHÔNG có admin_name 170 tin (tin hệ thống
    Facebook: '... đã trả lời một quảng cáo', 'Hi X! How can we help you?').
    Trường `is_automated` vô dụng: 619/619 đều false, kể cả tin Botcake.
    """
    f = m.get("from") or {}
    if str(f.get("id")) != str(page_id):
        return "khach"
    ten = (f.get("admin_name") or "").strip()
    if not ten:
        return "hethong"
    if ten.lower() == "botcake":
        return "botcake"
    return "ai" if ten in TEN_GUI_CUA_AI else "nguoi"


# Khách TỪ CHỐI / trì hoãn — đây là chỗ sale giỏi kiếm ra tiền, không phải "tin vô nghĩa".
# Anh · Tagalog · Ả Rập. Dùng kèm ngữ cảnh: page vừa hỏi/chốt mà khách đáp cụt lủn.
TU_CHOI = re.compile(
    r"\b(no|nope|not now|no need|don'?t need|dont need|no money|don'?t have money|dont have money"
    r"|no budget|too expensive|expensive|mahal|wala(ng)?\s*(pera|budget)?|hindi|ayaw|next time"
    r"|maybe later|later|not interested|busy|next month|after salary|sahod|wait"
    r"|salary|sweldo|suweldo|payday|pay\s*day|gaji|no cash|walang pera|end of (?:the )?month)\b"
    # 14/09 tối, ca Teresa ("Kaya lang 100 sar lang laman ng account" / "Kulang po pera ko eh") và Rena ("Sa
    # susunod nlng po cguro wla pa pong budget") — không chữ nào lọt bộ cũ nên AI đọc lại bảng giá.
    r"|\b(?:kulang|not enough|hindi sapat|di sapat|insufficient|budget|w(?:a)?la(?:ng)?\s+pa|sa susunod|susunod na"
    r"|only have|i only have|laman ng (?:account|wallet|bank|gcash)|lang laman)\b"
    # 14/09 tối, ca Bebe Garcia Vlogs ("Soon i order thank you") — lời HOÃN mua, AI tưởng đồng ý nên "Take your time".
    r"|\b(?:soon\s+(?:i\s+|i'?ll\s+|will\s+)?(?:order|buy|purchase)|(?:i'?ll|i\s+will|will)\s+(?:order|buy|purchase)"
    r"\s+(?:it\s+|this\s+)?(?:soon|later|next|tomorrow|another\s+time|some\s*time)|order\s+(?:it\s+)?(?:soon|later)"
    r"|let\s+me\s+think|i'?ll\s+think|think\s+about\s+it|not\s+yet(?!\s+(?:\w+\s+)?(?:receiv|deliver|arriv|recieve|recived|come|came|here))|maybe\s+(?:next|tomorrow|soon)"
    r"|i'?ll\s+(?:decide|consider)|mamaya|pag[- ]?isipan|isipin)\b"
    r"|\bلا\b|غالي|بعدين|مو الحين|ما ابغى|مافي فلوس|ما يكفي|ما عندي فلوس|مو كافي"
    # 19/09, ca Rinku Ray (Flat Jewelry UAE): khách Bangladesh "ওকে লাগবে না" (thôi không cần) — bộ cũ mù Bengali/Hindi/
    # Urdu. Chữ Bengali không dùng \b (dấu nguyên âm ◌া ◌ি không phải \w nên \b sau nó không bao giờ khớp).
    r"|লাগবে\s*না|নিবো\s*না|নেবো\s*না|নিব\s*না|নেব\s*না|চাই\s*না|দরকার\s*(?:নেই|নাই)|টাকা\s*(?:নাই|নেই)"
    r"|नहीं\s*चाहिए|नही\s*चाहिए|نہیں\s*چاہی[ےئ]|پیسے\s*نہیں"
    r"|\b(?:lagbe\s*na|nibo\s*na|chai\s+na|dorkar\s*nai|nah?in?\s*chahiye|nhi\s*chahiye|nahi\s*lena|paise?\s*nahi"
    r"|paisa\s*nahi)\b",
    re.I | re.U)


# Page vừa hỏi kiểu KẾT THÚC ("còn câu hỏi nào không?") — khách đáp "no, thank you" là chào
# tạm biệt lịch sự, KHÔNG phải từ chối mua. Ca 10/09 (برن منل مسي, Skin Renew): Botcake hỏi
# "Do you have any other questions?" → khách "no ....thank you" → AI nhảy vào chào combo kèm
# "ends at 11 PM" → khách "ill msg you po". Chủ shop: *"sao b tư vấn tiếp, khách mới từ chối
# lần đầu"*. Chỗ này phải IM; Botcake/sale follow-up sau, theo nhịp của page.
HOI_KET = re.compile(
    r"(any\s+(?:other|more)\s+questions?|anything\s+else|need\s+anything|other\s+concerns?"
    r"|may\s+(?:iba|tanong)\s+pa|còn\s+câu\s+hỏi|هل\s+لديك\s+(?:أي\s+)?أسئلة|استفسار\s+آخر)", re.I | re.U)
DAP_KET = re.compile(
    r"^\W*(no|nope|none|nothing|wala\s*na|wala|that'?s\s+all|ok(ay)?|thank\s*(?:s|you|u)|thanks?|salamat|شكرا|لا)"
    r"[\W\s]*(?:(?:thank\s*(?:s|you|u)|thanks?|salamat|po|dear|sis|ma'?am|sir|شكرا)[\W\s]*)*$", re.I | re.U)
HEN_SAU = re.compile(
    r"\b(i'?ll\s+(?:msg|message|text|contact|call|get\s+back)|will\s+(?:msg|message|text|contact|get\s+back)"
    r"|mag[- ]?message\s+(?:na\s+lang|ako)|let\s+you\s+know|بعدين\s+اكلمك|راح\s+اتواصل)\b", re.I | re.U)


# KHÁCH TỪ CHỐI SAU KHI ĐÃ BIẾT GIÁ — chủ shop 2026-09-14, ca Fe Borabo (Veloura Collection UAE):
# sale báo giá 3 lần ("149 AED 1 set / 239 AED 2 set"), khách từng nói "No thanks my be nextime",
# page hỏi "Do you wanna order 1 or 2 pcs dear?" → khách "Ok thanks". ai_co_vao_cuoc phán ĐÚNG
# "khách từ chối — phải thuyết phục", nhưng lý do đó KHÔNG vào prompt: goi_soan chỉ ghi "Botcake IM
# sau câu hỏi của khách — bạn phải trả lời" → model tưởng khách hỏi, bịa "Oo, BUY 1 TAKE 1 means 2
# sets…" rồi báo lại 239 AED + danh sách xin SĐT. *"khách đã biết giá ở trên rồi mà vẫn ok, thanks,
# tức là từ chối mua hàng, lúc này bạn phải thuyết phục khách, chứ sao lại báo giá lại vậy?"*
# Nhánh "đáp cụt" của ai_co_vao_cuoc gộp cả câu ĐỒNG Ý ("2 pcs", "yes") — nên phân loại từ chối
# phải xét riêng CHỮ của khách, không suy từ lý do.
# KHÁCH HỎI THANH TOÁN ≠ TỪ CHỐI (chủ shop 14/09 tối, ca Philip Gutib — Madam Mystic Fengshui Expert USA):
# "Money gram or palawan ano ipapadala ko naba kahit wala pa ang unit na ipadala mo sa akin madam" (gửi MoneyGram
# hay Palawan, dù chưa nhận hàng?) → TU_CHOI bắt "wala pa" (= chưa) → prompt "khách đang từ chối, không hỏi gì"
# → AI bê nguyên mẫu /Khokhantaichinh (kẹt tiền) 5 đoạn. *"khách chỉ đang hỏi nên thanh toán theo phương thức,
# b trả lời cái gì mà vừa lạc đề, vừa dài ngoằng vậy"*. Đo 4.341 tin khách (so_chi_phi, mọi nước): bản dưới bỏ
# 8 câu khỏi nhóm từ chối, cả 8 là câu hỏi thật ("Wait po my bayad po ba mdam", "no,how can this fit?"…);
# giữ "wala ako pera ngayon", "I'll wait, okay?" là từ chối.
PHUONG_THUC_TT = re.compile(
    r"\b(money\s*gram|moneygram|palawan|western\s*union|remitly|cebuana|m\s*lhuillier|lbc|venmo|zelle"
    r"|cash\s*app|cashapp|paypal|pay\s*pal|gcash|money\s*order|bank\s*(transfer|deposit)|wire\s*transfer)\b", re.I)
THIEU_TIEN = re.compile(
    r"\b(no\s+money|no\s+cash|no\s+budget|don'?t\s+have\s+(money|cash)|walang\s+pera"
    r"|wala\s*(pa\s*)?(ng\s+|pong\s+|po\s+)?(pera|budget|sweldo|sahod)|wala\w*\s+(\w+\s+){0,2}pera"
    r"|mahal|expensive|kulang|not\s+enough|salary|sweldo|sahod|payday)\b", re.I)
_TU_CHOI_YEU = re.compile(r"w(a)?la(ng)?(\s+pa)?|hindi|no|wait|later", re.I)
# Khách kêu KHÔNG ĐỌC / KHÔNG HIỂU tin page (ca Lucy JJ 14/09 tối: AI lỡ viết chữ Hindi, khách "Hindi ko naintidihan
# ang mga letra ito") — "hindi" ở đây là "không hiểu", tính là từ chối thì mất một lượt níu và treo sớm.
KHONG_HIEU = re.compile(
    r"\b(?:hindi|di|not|don'?t|dont|can'?t|cant|cannot|no)\s+(?:\w+\s+){0,2}"
    r"(?:\w*int[ie]{1,2}ndi\w*|\w*intidihan|understand|understood|read|nababasa|mabasa|basahin)\b"
    r"|\b(?:letra|letters|language|lengg?u?wahe)\b", re.I)
# Chào / cảm ơn kết thúc — SAU một lời từ chối là từ chối mềm, vẫn phải níu (ca Lucy JJ 14/09 tối:
# "Maraming Salamat Madam Mystic .Have a great day po .God bless us all." → AI im).
CHAO_TAM_BIET = re.compile(
    r"\b(have\s+a\s+(?:great|good|nice|blessed|wonderful)\s+(?:day|night|evening|weekend)|god\s+bless|take\s+care"
    r"|good\s*bye|bye|good\s*night|see\s+you|thank\s*(?:s|you|u)?|thanks?|salamat|ingat|pagpalain|شكرا|مع\s+السلامة)\b"
    r"|謝謝|多謝", re.I | re.U)
LUOT_NIU = 3          # chủ shop 15/09: níu TỐI ĐA 3 lần, khéo và tự nhiên (14/09 tối từng nâng lên 5); lượt 2 gửi feedback


def khach_hoi_thanh_toan(t):
    """Khách hỏi phương thức / cách trả tiền (MoneyGram? Venmo? kiểm hàng rồi mới trả?) — không kèm lời thiếu tiền."""
    t0 = lam_sach(t).strip().lower()
    return bool((PHUONG_THUC_TT.search(t0) or re.search(TRUOC_MUA, t0)) and not THIEU_TIEN.search(t0))


# KHÁCH HOÃN ĐỂ HỎI / CHO NGƯỜI NHÀ XEM — chủ shop 19/09, ca Arnaud Junio (Glamora Jewelry, Saudi): khách "i sent to my
# daughter if she likes it i will order" → TU_CHOI không có mẫu này → không vào nhánh níu → AI "No problem 😊 Take your
# time showing your daughter… just let me know". *"phải níu khách bằng giữ chương trình khuyến mãi chứ? hỏi khách có muốn
# tôi giữ khuyến mãi không, vì chương trình hết trong hôm nay"*. Cùng kiểu ca Yasso Chimali ("Take your time to ask your
# daughter"). Lời hoãn = từ chối mềm → níu + CAU_GIU_UU_DAI như "Soon i order".
_NGUOI_NHA = (r"(?:wife|husband|hubby|daughters?|sons?|kids?|children|mom|mother|mum|mommy|mama|dad|father|papa|daddy"
              r"|sisters?|brothers?|family|friends?|boss|partner|fianc[eé]e?|girlfriend|boyfriend|gf|bf|parents?|sis|bro"
              r"|aunt|auntie|tita|uncle|tito|niece|nephew|cousin|grand(?:ma|pa|mother|father)|lola|lolo|mister|misis"
              r"|employer|amo|madam|ma'?am)")
# "if she likes it i will order" / "if my husband agrees" / "I'll order when my husband comes" / "kung magustuhan niya" /
# "اذا عجبها" — điều kiện nằm ở người khác, kể cả khi câu có "I'll order".
NEU_NGUOI_THICH = re.compile(
    r"\b(?:if|f)\s+(?:she|he|they|my\s+" + _NGUOI_NHA + r")\s+(?:\w+\s+)?(?:likes?|liked|love[sd]?|agrees?|agreed"
    r"|approves?|approved|says?\s+(?:yes|ok)|wants?|is\s+ok|allows?|interested)\b"
    r"|\b(?:kung|pag|kapag|pagka)\s+(?:nagustuhan|magustuhan|gusto|pumayag)\s+(?:niya|nya|nila|ng\s+(?:asawa|anak|mister|misis))"
    r"|\b(?:i'?ll|i\s+will)\s+(?:order|buy)\s+(?:it\s+)?(?:when|once|after)\s+(?:he|she|they|my\s+" + _NGUOI_NHA + r")\b"
    r"|(?:اذا|إذا|لو)\s+(?:عجبها|عجبه|عجبهم|وافق|وافقت|وافقو)", re.I | re.U)
HOAN_HOI_NGUOI = re.compile(
    # "I'll ask/show my wife", "let me ask my husband first", "I need to consult my family"
    r"\b(?:i'?ll|i\s+will|let\s+me|lemme|i\s+(?:need|have|want|must)\s+to|i\s+must|i'?m\s+going\s+to|i\s+am\s+going\s+to|gonna"
    r"|i\s+(?:will\s+)?first|i)\s+(?:first\s+)?(?:ask|show|consult|check\s+with|discuss(?:\s+it)?\s+with|talk\s+(?:to|with)"
    r"|tell|inform)\s+(?:it\s+|this\s+|them\s+|her\s+|him\s+)?(?:to\s+|with\s+)?my\s+" + _NGUOI_NHA + r"\b"
    # "I sent it to my daughter" — đã gửi hình cho người nhà xem, chờ họ quyết
    r"|\bi\s+(?:already\s+|just\s+|have\s+)?(?:sent|showed|shown|forwarded|shared)\s+(?:it\s+|this\s+|them\s+|the\s+\w+\s+)?"
    r"(?:to\s+)?my\s+" + _NGUOI_NHA + r"\b"
    r"|\bask(?:ing)?\s+my\s+" + _NGUOI_NHA + r"\s+first\b"
    # "I waiting my friend f she interested…", "I will order am waiting for my boss to come"
    r"|\b(?:i|i'?m|am|i\s+am)\s+(?:still\s+)?waiting\s+(?:for\s+)?my\s+" + _NGUOI_NHA + r"\b"
    r"|\b(?:tanong(?:in)?|tanungin|itanong|tatanungin|sabihan|sabihin|ipakita|ipapakita|paalam|magpaalam|papaalam)\s+(?:ko\s+)?"
    r"(?:pa\s+)?(?:po\s+)?(?:muna\s+)?(?:po\s+)?(?:kay\s+|sa\s+)?(?:(?:aking|akong|ko|my)\s+)?(?:asawa|anak|mister|misis"
    r"|nanay|mama|tatay|papa|ate|kuya|pamilya|boss|amo|jowa|partner)"
    r"|(?<!\w)(?:ب|ا|أ)شاور(?!ما)|(?:ب|ا|أ)س(?:أ|ا)ل\s+(?:زوجي|زوجتي|اهلي|أهلي|بنتي|ولدي|امي|أمي|ابوي|أبوي|اخوي|أخوي|اختي|أختي)",
    re.I | re.U)
# Câu có mấy chữ này là chuyện GIAO HÀNG / thông tin nhận hàng ("I'll ask my husband for the address", "I will tell my
# husband to receive the parcel") — khách đang mua, không phải hoãn.
_HOAN_HOI_LOAI = re.compile(
    r"\b(?:address|location|pin|number|contact|phone|whatsapp|receive[ds]?|received|parcel|deliver\w*|pick\s*up|rider"
    r"|driver|courier|tracking|refund|return|pay|paid|payment|zelle|venmo|cancel\w*)\b|عنوان|رقم|موقع|استلام|توصيل|مندوب", re.I | re.U)
# Người kia ĐÃ ưng ("I showed my wife, she likes it") — không phải hoãn.
_DA_UNG = re.compile(r"\b(?:she|he|they)\s+(?:really\s+)?(?:likes?|liked|loves?|loved|wants?|agreed|approved)\b",
                     re.I)


def hoan_hoi_nguoi(t):
    """Khách hoãn để hỏi / cho người nhà xem trước khi mua ("if she likes it i will order")."""
    t = lam_sach(t).strip()
    if not t or _HOAN_HOI_LOAI.search(t):
        return False
    if NEU_NGUOI_THICH.search(t):
        return True
    return bool(HOAN_HOI_NGUOI.search(t) and not _DA_UNG.search(t) and not MUON_MUA.search(t))


_KHONG_DAP = re.compile(r"^\W*(?:no|nope|hindi|wala|not)\b", re.I)
# 26/09 (siết sau khi phiên REP SAI đo sổ thật): NƠI/GIỜ NHẬN CỤ THỂ — chữ chung chung (home, address, deliver, work, st, dr)
# KHÔNG đủ; "home/bahay/house" chỉ tính khi kèm lang/only/na lang/instead.
_NOI_NHAN_CU_THE = re.compile(
    r"\b(?:p\.?\s*o\.?\s*box|post\s*office|mail\s*box|office|opisina|apartment|apt\b|unit\s*\d|lobby|front\s*desk|reception"
    r"|(?:my|sa)\s+(?:sister|mother|mom|brother|friend|daughter|son|kapatid|nanay|anak|kaibigan|amo)(?:'s)?\s+(?:house|home|place|address|bahay)"
    r"|bahay\s+ni\b|sa\s+bahay\s+ng\b"
    r"|(?:home|bahay|house)\b[^.!?]{0,20}\b(?:lang|only|na\s+lang|instead)\b|(?:lang|only)\s+(?:sa\s+)?(?:home|bahay|house)\b"
    r"|(?:work\s*place|workplace|sa\s+work|sa\s+trabaho|at\s+(?:my\s+)?work)\b[^.!?]{0,20}\b(?:lang|only|na\s+lang|instead|address)\b"
    r"|(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday|weekdays?|weekends?|lunes|martes|miyerkules|huwebes|biyernes|sabado|linggo)"
    r"|\d{1,2}(?::\d{2})?\s*(?:am|pm)|morning|afternoon|evening|tonight|umaga|hapon|gabi)\b", re.I)
_DAU_TU_CHOI_HOAN = re.compile(
    r"\b(?:thank\w*|salamat|not\s+now|not\s+yet|for\s+now|muna|next\s+(?:time|month|week)|no\s+need|money|pera|cash|budget"
    r"|(?:not\s+(?:yet\s+)?|un)decided|(?:don'?t|do\s+not|dont|ayaw|hindi\s+ko|di\s+ko)\s+(?:want|like|need|kaya|gusto)|cancel\w*"
    r"|maybe|later|soon|wait\w*|busy|wala\s+pa|work\s+now|no\s+work|can'?t\s+afford|cannot\s+afford|afford|expensive|mahal|sorry"
    r"|i'?ll\s+pass|\bpass\b|no\s+(?:more|longer)|hindi\s+na|di\s+na|ayoko|ayaw)\b", re.I)
_HOI_NOI_GIAO = re.compile(
    r"\b(?:can|could|pwede|puwede|okay|ok|possible)\b[^?]{0,60}\b(?:deliver\w*|delivery|ihatid|dalhin|drop|leave|receive|tanggap\w*)\b"
    r"[^?]{0,40}\b(?:to|at|sa)\s+(?:your|the|inyong|iyong)?\s*(?:home|house|bahay|office|opisina|work|trabaho|p\.?o\.?\s*box|address)\b[^?]{0,30}\?"
    r"|\b(?:where|saan)\b[^?]{0,40}\b(?:deliver\w*|delivery|ihatid|receive|tanggap\w*)\b[^?]{0,40}\?"
    r"|\b(?:what|anong|when|kailan)\s+(?:time|oras|day|araw)\b[^?]{0,60}\?", re.I)
_HOI_KHONG_PHAI_NOI = re.compile(r"\b(?:reserve|reserba|book|order|promo|proceed|confirm\w*|kumpirma\w*|payment|bayad|magbayad)\b", re.I)


def _dap_noi_gio_nhan(t):
    """Câu khách mở đầu No/Hindi/Wala rồi nói NƠI/GIỜ nhận cụ thể, không dấu từ chối/hoãn → là câu trả lời, không phải từ chối."""
    m = _KHONG_DAP.match(t)
    if not m:
        return False
    con = t[m.end():]
    return bool(re.search(r"\w", con) and _NOI_NHAN_CU_THE.search(con) and not _DAU_TU_CHOI_HOAN.search(t)
                and not THIEU_TIEN.search(t) and not la_che_dat(t))


def _dap_cau_hoi_giao(msgs):
    """26/09 (ca Mina Arines · Madam Mystic USA 2): tin page ngay trước là CÂU HỎI về giao hàng/địa chỉ/giờ nhận ("Can you have
    the delivery to your home?") và khách đáp mở đầu bằng No/Hindi/Wala ("No, sa PO Box lang") → đang TRẢ LỜI câu hỏi, không phải
    từ chối mua. Bản cũ coi là từ chối → model bị ép níu + kèm 8 ảnh feedback."""
    ds = [m for m in (msgs or []) if lam_sach(m.get("text")).strip()]
    if len(ds) < 2 or ds[-1].get("boi") != "khach" or ds[-2].get("boi") not in ("nguoi", "ai", "botcake"):
        return False
    hoi, dap = lam_sach(ds[-2].get("text")), lam_sach(ds[-1].get("text")).strip()
    # siết 26/09: câu page phải là câu hỏi CÓ/KHÔNG về NƠI giao (không phải câu chốt "Shall I reserve… delivery date?");
    # khách "No" trơn (≤2 chữ) qua khi câu page đúng dạng; "No + chữ" phải là nơi/giờ nhận cụ thể.
    if not (_HOI_NOI_GIAO.search(hoi) and not _HOI_KHONG_PHAI_NOI.search(hoi)):
        return False
    m = _KHONG_DAP.match(dap)
    if not m or THIEU_TIEN.search(dap) or la_che_dat(dap) or _DAU_TU_CHOI_HOAN.search(dap):
        return False
    return len(re.findall(r"\w+", dap)) <= 2 or _dap_noi_gio_nhan(dap)


def khach_dang_tu_choi(t):
    """Câu khách là lời từ chối / lảng ("ok thanks", "no thanks", "maybe next time", "mahal"…)."""
    t = lam_sach(t).strip()
    if not t:
        return False
    # 26/09 (ca Mina Arines): "No, sa PO Box lang" / "Hindi, sa office ko na lang" = câu trả lời về NƠI/GIỜ nhận, không phải từ chối.
    if _dap_noi_gio_nhan(t):
        return False
    if HEN_SAU.search(t):
        return True               # "I'll message you" — hoãn mua (14/09 tối)
    if hoan_hoi_nguoi(t):
        return True               # "i sent to my daughter if she likes it i will order" — hoãn để hỏi người nhà (19/09)
    if DAP_KET.match(t) and re.search(r"thank|salamat|\bno\b|nope|شكرا|لا", t, re.I | re.U):
        return True               # "ok thanks" / "no thank you" — "ok" trơn thì có thể là đồng ý, không tính
    if not ((TU_CHOI.search(t) or la_che_dat(t))
            and not re.search(r"\b(\d+\s*(pcs?|sets?|pieces?)|yes|ok\s+\d)\b", t, re.I)):
        return False
    if PHUONG_THUC_TT.search(t) and not THIEU_TIEN.search(t):
        return False              # hỏi phương thức thanh toán (ca Philip 14/09)
    # Chữ từ chối duy nhất là "wala / wala pa / hindi / no / wait" trần, câu dài có từ hỏi → là câu HỎI.
    _ms = [m.group(0).strip() for m in TU_CHOI.finditer(t)]
    _hoi = (re.search(r"\b(ano|anong|paano|kailan|saan|sino|naba|na\s+ba|ba)\b", t, re.I)
            or (re.search(r"\b(what|which|how|where)\b", t, re.I) and "?" in t))
    if (_ms and all(_TU_CHOI_YEU.fullmatch(m) for m in _ms) and len(re.findall(r"\w+", t)) >= 6
            and _hoi and not THIEU_TIEN.search(t) and not la_che_dat(t)):
        return False
    if _ms and all(_TU_CHOI_YEU.fullmatch(m) for m in _ms) and KHONG_HIEU.search(t) \
            and not THIEU_TIEN.search(t) and not la_che_dat(t):
        return False              # "Hindi ko naintidihan…" — kêu không hiểu chữ (ca Lucy JJ 14/09)
    return True


# Chữ đệm được phép đứng quanh lời chào ("Maraming Salamat Madam Mystic .Have a great day po .God bless us all.").
_CHAO_DEM = re.compile(
    r"\b(po|opo|madam|madame|mam|maam|ma'?am|sir|dear|sis|miss|kuya|ate|bro|ok|okay|okey|oky|maraming|marami|many|much"
    r"|so|very|you|u|too|all|us|everyone|for|the|your|time|again|also|and|to|a|nga|sa|inyo|ninyo|ang|ng|na|lord|always|have|great|good|nice|happy|day|night|blessed)\b",
    re.I)


def _la_chao_sau_tu_choi(kh, j):
    """Tin khách kh[j] CHỈ là lời chào/cảm ơn kết thúc (bỏ chữ chào + chữ đệm còn ≤ 2 từ), đứng sau một lời từ chối
    THẬT (không tính "ok thanks" trơn) trong 3 tin khách trước đó.

    Đo so_chi_phi mọi nước 14/09: bản đầu (chỉ cần có chữ thanks/salamat) bắt 26 câu, phần lớn oan — "Thanks i received
    now my order", "Please arrange my shipment delivery ASAP thanks", tin "Thank you" trước đó bị tính là từ chối."""
    t = lam_sach(kh[j].get("text")).strip()
    if not t or not CHAO_TAM_BIET.search(t) or khach_dang_tu_choi(t) or "?" in t or len(t.split()) > 20 \
            or re.search(r"\d", t) or HOI_MUA.search(t) or MUON_MUA.search(t) \
            or re.search(r"\b(yes|yeah|opo|sure|receiv\w*|reciev\w*|arriv\w*|order\w*|deliver\w*|rider|cancel\w*|wait"
                         r"|aantay\w*|pray\w*|dasal|recover\w*)\b", t, re.I):
        return False
    if len(re.findall(r"[^\W\d_]+", _CHAO_DEM.sub(" ", CHAO_TAM_BIET.sub(" ", t)), re.U)) > 2:
        return False
    # Tin khách GẦN NHẤT trước đó (bỏ qua lời chào / "ok thanks" / kêu không hiểu chữ) phải là lời từ chối THẬT —
    # khách đã cho SĐT/địa chỉ hay hỏi chuyện khác sau lời từ chối thì "thank you" không còn là từ chối.
    for x in range(j - 1, max(-1, j - 4), -1):
        u = lam_sach(kh[x].get("text")).strip()
        if not u or DAP_KET.match(u) or (CHAO_TAM_BIET.search(u) and not khach_dang_tu_choi(u)) or KHONG_HIEU.search(u):
            continue
        return khach_dang_tu_choi(u)
    return False


def khach_chao_sau_tu_choi(msgs):
    """Tin khách CUỐI là lời chào/cảm ơn sau khi đã từ chối, page vừa níu (AI/Botcake — không phải sale thật, không
    phải câu 'còn câu hỏi nào không?') → trả câu đó; không thì None."""
    idx = [k for k, m in enumerate(msgs or []) if m.get("boi") == "khach" and lam_sach(m.get("text")).strip()]
    if not idx:
        return None
    i = idx[-1]
    truoc = next((m for m in reversed(msgs[:i]) if m.get("boi") != "khach" and m.get("boi") != "hethong"
                  and (m.get("text") or "").strip()), None)
    if not truoc or truoc.get("boi") not in ("ai", "botcake") or HOI_KET.search(lam_sach(truoc.get("text") or "")):
        return None
    kh = [msgs[k] for k in idx]
    return lam_sach(kh[-1]["text"])[:120] if _la_chao_sau_tu_choi(kh, len(kh) - 1) else None


def tien_page_da_noi(msgs):
    """Mọi con số tiền phía page (bot/sale/AI/hệ thống) đã nói trong hội thoại.

    Đổi tên 14/09: trùng tên với gia_page_da_bao (ca Aruna, trả (tập, câu)) → bản sau đè bản này,
    cửa từ chối nhận tuple → cả lượt văng TypeError. Hai hàm khác nghĩa, đừng gộp tên lại.
    """
    return {v for m in (msgs or []) if m.get("boi") != "khach" for v in CG.tien_trong(m.get("text"))}


# KHÁCH NÓI SẼ GỬI / MUỐN ĐƯA SỐ ĐIỆN THOẠI mà chưa có số — chủ shop 2026-09-14, ca Sallam Khan
# (Golden Buddha Blessings): khách gửi voice nhiều lần, sale xin "can u text dear", khách "Coming
# mobile number mobile" + 👍 → AI đang "tư vấn theo bước" nên chép bước /Câu4 xem chỉ tay bằng Tagalog.
# *"này khách nhắn gửi sdt điện thoại mà b rep gì vậy?"*. Luật "có SĐT là lên đơn" chỉ chạy khi số đã
# tới; câu HỨA gửi số phải được đáp bằng lời mời gửi số — kể cả đang giữa kịch bản tư vấn.
KHACH_HUA_SDT = re.compile(
    r"\b(?:coming|sending|send(?:ing)?|will\s+send|i'?ll\s+send|i\s+send|i\s+will\s+give|i'?ll\s+give|i\s+give"
    r"|giving|here'?s|here\s+is|this\s+is|this|that'?s|take)\s+(?:you\s+)?(?:my\s+)?"
    r"(?:mobile|phone|whatsapp|wa|contact|cell)?\s*(?:number|no\.|num)\b"
    r"|\bmy\s+(?:mobile|phone|whatsapp|contact|cell)\s*(?:number|no\.|num)?\s*$"
    r"|\bmobile\s+(?:number|no\.)\b|\bnumber\s+(?:do|le|lo|de|dunga|deta|bhejta|bhejunga)\b"
    r"|\b(?:ibigay|ipadala)\b[^.?!\\d]{0,20}\b(?:number|numero)\b", re.I)
# Câu khách XIN số của shop / nói về bưu tá / khiếu nại giao hàng không phải lời hứa đưa số của mình.
_HUA_SDT_LOAI = re.compile(
    r"\b(?:your|ur|you|u|me|postman|driver|rider|courier|delivery|deliver|j&t|refund|order|missed|shop|company"
    r"|not|don'?t|invalid|wrong|possible|can|could)\b", re.I)


def khach_hua_sdt(msgs):
    """Câu khách GẦN NHẤT HỨA / ĐƯA số của chính mình mà KHÔNG kèm con số → trả câu đó, không thì None.

    Đo 3.077 tin khách UAE (14/09) trước khi siết: bản đầu bắt 45 câu, phần lớn là khiếu nại giao hàng
    ("tell the delivery call me") hoặc khách XIN số shop ("give me your number") — nên chỉ nhận câu ngắn
    (≤ 10 từ), có dạng hứa/đưa số, không nhắc tới người khác hay đơn hàng.
    """
    kh = [m for m in (msgs or []) if m.get("boi") == "khach" and lam_sach(m.get("text")).strip()]
    if not kh:
        return None
    t = lam_sach(kh[-1]["text"])
    # Khách đã gửi số trong 5 tin gần đây thì "this is my number" là nói về số ĐÃ gửi — không xin lại.
    if any(len(re.sub(r"\D", "", lam_sach(m["text"]))) >= 7 for m in kh[-6:-1]):
        return None
    if (KHACH_HUA_SDT.search(t) and len(re.sub(r"\D", "", t)) < 7
            and len(t.split()) <= 10 and not _HUA_SDT_LOAI.search(t)):
        return t[:120]
    return None


# CÂU GIỮ ƯU ĐÃI — chủ shop đưa 14/09 tối, dùng khi khách từ chối / hoãn (ca Bebe Garcia Vlogs).
# Chủ shop 15/09: câu phải ngắn, tự nhiên. Chiều 15/09: ưu đãi hết trong HÔM NAY — không nói "11 PM" (khách nhắn lúc
# nửa đêm thì "tới 11 PM tối nay" là vô lý), và dù khuya vẫn đòi thông tin + chốt số lượng, không hẹn mai.
# KHÁCH ĐỢI LƯƠNG → GIỮ ƯU ĐÃI + GIAO NGÀY LƯƠNG + HẠN 11 GIỜ TỐI (chủ shop 25/09, ca Shiela Mae · Key Jewelry Saudi: "để tôi giữ ưu
# đãi cho bạn và giao hàng vào ngày bạn nhận lương, vì ưu đãi sẽ kết thúc lúc 11h tối nay. để tăng tính hối thúc khách hàng chốt đơn").
# Sau 22 giờ giờ địa phương → "chỉ trong hôm nay" (15/09: "tới 11 PM tối nay" lúc nửa đêm là vô lý). Page mà kịch bản KHÔNG có câu hạn
# chót thì cổng bia_khan_hiem vẫn bỏ phần hạn (không bịa), lời mời giữ ưu đãi còn nguyên.
_LECH_GIO_TT = {"uae": 4, "oman": 4, "saudi": 3, "kuwait": 3, "qatar": 3, "bahrain": 3, "taiwan": 8, "usa": -5, "japan": 9}
_GIU_UU_DAI_RX = re.compile(
    r"(?i)\b(?:reserve|keep|hold|secure|save|lock|i-?reserve|ireserba|i-?reserba|itabi|i-?hold|simpan|tahan)\b[^.!?\n]{0,60}"
    r"\b(?:promo\w*|offer|deal|discount|price|presyo|harga)\b|\b(?:promo\w*|offer)\b[^.!?\n]{0,40}\b(?:reserve|keep|hold|"
    r"i-?reserve|ireserba|itabi)\b|احجز|أحجز|احتفظ|أحتفظ|اثبت\s+لك|أثبت\s+لك|保留|預留|预留", re.U)


def cau_giu_uu_dai_luong(mkey=None):
    gio = time.gmtime(time.time() + 3600 * _LECH_GIO_TT.get(mkey, 3)).tm_hour
    han = "the promo ends at 11 PM tonight" if gio < 22 else "the promo is only valid today"
    return f"Let me reserve today's promo for you and deliver it on your payday — {han}. 😊"


CAU_GIU_UU_DAI = ("Shall I reserve today's promo for you? 😊 It's only valid today, and you can choose your delivery "
                  "date. ❤️")


def cau_giu_uu_dai(mkey=None):
    """CAU_GIU_UU_DAI theo giờ địa phương (chủ shop 25/09): trước 22 giờ "hết lúc 11 giờ tối nay", sau đó "chỉ hôm nay"."""
    gio = time.gmtime(time.time() + 3600 * _LECH_GIO_TT.get(mkey, 3)).tm_hour
    han = "It's only valid until 11 PM tonight" if gio < 22 else "It's only valid today"
    return f"Shall I reserve today's promo for you? 😊 {han}, and you can choose your delivery date. ❤️"
# Câu THẢ khách đi — cấm khi khách đang từ chối/hoãn.
THA_KHACH = re.compile(
    r"take\s+your\s+time|no\s+rush|whenever\s+you(?:'?re|\s+are)\s+ready|when(?:ever)?\s+you\s+(?:decide|are\s+free)"
    r"|just\s+(?:let\s+me\s+know|message\s+me|send\s+(?:me\s+)?your\s+details\s+(?:when|whenever))"
    r"|message\s+me\s+(?:back|anytime|when)|i'?ll\s+(?:be\s+)?(?:here|wait)|feel\s+free\s+to\s+(?:message|come\s+back)"
    r"|i'?ll\s+keep\s+the\s+promo|anytime\s+you\s+want", re.I)


# Bản CHẶT của THA_KHACH, dùng cho cổng áp mọi lượt (regex trên rộng hơn: nó bắt cả "just let me
# know <chọn gói>" — là lời mời chốt — nên chỉ hợp với cổng chỉ chạy lúc khách đang từ chối).
# Cố ý KHÔNG bắt: "no pressure", "no rush on payment / no rush, no risk" (đang giải thích COD).
# Đo 20/09 trên 8.362 tin AI đã gửi: bắt 101 tin (1,2%), soi tay không thấy ca nào bắt oan.
THA_CHAT = re.compile(
    r"\btake your time\b"
    r"|\bno rush\b(?![^.!?]{0,25}\b(?:payment|paying|pay|bayad|risk)\b)"
    r"|\b(?:when|whenever|once)\s+you(?:(?:'|\u2019)?re|\s+are)\s+ready\b"
    r"|\bi(?:'|\u2019)?ll be here\b|\bi(?:'|\u2019)?m here whenever\b"
    r"|\b(?:message|msg|text|pm|dm|contact)\s+me\s+(?:back|again|when|anytime|any time|once)\b"
    r"|\b(?:get|come)\s+back\s+to\s+me\b"
    r"|\blet me know\s+(?:when|once)\b"
    r"|\bmessage mo lang ako\b|\bi-?message mo lang ako\b|\bmag-?message ka lang\b"
    r"|\b(?:pag|kapag|kung)\s+ready na\s+(?:kayo|ka|po)\b|\bhintayin ko\b|\bisip[- ]isip\b"
    # ca Anthony Sebastian 23/09: bản Tagalog — "Kung sakaling magbago po ang isip ninyo, nandito lang po ako". Đo 16.608 tin
    # AI: "kung magbago isip" 26, "nandito lang ako/kami" 18 (bỏ "nandito po ako PARA tumulong"), "message nyo lang ako"
    # chỉ khi kèm lúc hẹn (pag / kapag / pagdating / pag-uwi…) — "i-PM mo lang ako dito — anong combo?" là mời chốt.
    # CỐ Ý KHÔNG BẮT "walang pressure" (4 tin, đều trong câu COD "walang risk, walang pressure" — như "no pressure").
    r"|\b(?:kung|kapag|pag)\s+(?:sakaling\s+)?(?:magbago|mabago|nagbago)\s+(?:po\s+)?(?:ang\s+)?(?:isip|desisyon)\b"
    r"|\b(?:nandito|andito|narito|nandiyan|andyan)\s+lang\s+(?:po\s+)?(?:ako|kami)\b(?!\s+(?:po\s+)?(?:para|upang)\b)"
    r"|\b(?:kapag|pag|kung|pagdating|pagbalik|pag-?uwi|anytime)\b[^.!?\n]{0,50}\b(?:i-?)?(?:message|mag-?message|chat|pm|text)\s+"
    r"(?:niyo|nyo|ninyo|mo)?\s*lang\s+(?:po\s+)?(?:ulit\s+)?(?:ako|kami)\b"
    r"|\b(?:i-?)?(?:message|chat|pm|text)\s+(?:niyo|nyo|ninyo|mo)?\s*lang\s+(?:po\s+)?(?:ako|kami)\b[^.!?\n]{0,40}"
    r"\b(?:kapag|pag|kung|anytime)\b"
    r"|\u062e\u0630 \u0648\u0642\u062a\u0643|\u0644\u0627 \u062a\u0633\u062a\u0639\u062c\u0644|\u0628\u0631\u0627\u062d\u062a\u0643"
    r"|\bsantai aja\b|\bkalau sudah siap\b|\bkabari saja\b",
    re.I | re.U)


# Cụm THẢ đứng làm mệnh đề phụ — gỡ riêng cụm là câu vẫn đủ nghĩa ("Just send the location on WhatsApp
# when you're ready" → "Just send the location on WhatsApp"). Cắt cả câu ở những ca này là mất luôn lời
# xin định vị / xin SĐT.
_CUM_PHU = re.compile(
    r"[,\s]*\b(?:when|whenever|once)\s+you(?:(?:'|\u2019)?re|\s+are)\s+ready\b"
    r"|[,\s]*\b(?:pag|kapag|kung)\s+ready na\s+(?:kayo|ka|po)\b", re.I | re.U)
# Câu có YÊU CẦU HÀNH ĐỘNG (xin SĐT/địa chỉ/ảnh/chọn gói) thì không được cắt bỏ cả câu.
_CAU_VIEC = re.compile(
    r"\?|\b(?:send|share|give|provide|reserve|book|order|choose|pick|confirm)\b"
    r"|\b(?:number|address|location|photo|picture|whatsapp|maps)\b"
    r"|\b(?:send|padala|ipadala|i-?send|piliin|mag-?order|sabihin|kailan)\b|\btell me\b|\bwhich day\b|\bwhen is\b|\u0623\u0631\u0633\u0644", re.I | re.U)


# Tin AI hay dùng emoji thay dấu chấm ("…thinking it over 😊 Shall I reserve…"): tách câu chỉ theo
# [.!?] thì cả đoạn thành MỘT câu, cắt máy bó tay và phải gọi model oan (ca Jhenjhen 20/09).
_NGAT_CAU = re.compile("(?<=[.!?])\\s+|(?<=[\U0001F300-\U0001FAFF\u2600-\u27BF\u2764])\\s+")


def _don_cau(t):
    """Dọn rác sau khi gỡ cụm: khoảng trắng kép, dấu phẩy mồ côi, chữ đầu câu viết hoa."""
    t = re.sub(r"\s{2,}", " ", t or "").strip()
    t = re.sub(r"\s+([,.!?])", r"\1", t)
    t = re.sub(r"([,\u2014-]\s*)+([.!?])", r"\2", t)
    t = re.sub(r"^[\s,\u2014-]+", "", t)
    t = re.sub(r"([.!?])\s*([,\u2014])\s*", r"\1 ", t)
    return t[:1].upper() + t[1:] if t else t


def cat_cau_tha_chat(t):
    """Bỏ cụm thả khách (bản chặt) mà giữ tối đa nội dung. Không làm sạch được thì trả None để gọi model.

    Hai bước: (1) gỡ cụm phụ ngay trong câu; (2) câu nào còn dính cụm thả mà KHÔNG mang yêu cầu hành động
    thì bỏ cả câu. Kết quả phải hết cụm thả, còn ≥ 40 ký tự và khác bản gốc.
    """
    goc = (t or "").strip()
    b1 = _don_cau(_CUM_PHU.sub("", goc))
    cau = re.split(_NGAT_CAU, b1)
    giu = []
    for c in cau:
        if THA_CHAT.search(c) and not _CAU_VIEC.search(c):
            continue                      # câu thuần thả khách → bỏ
        giu.append(c)
    kq = _don_cau(" ".join(giu))
    if len(kq) < 40 or kq == goc or THA_CHAT.search(kq):
        return None
    return kq


# ══ KIỂM HÀNG CHỈ KHI KHÁCH HỎI (chủ shop 2026-09-23) ═════════════════════════════════════════════════════════════
# *"khi nào khách hỏi có được xem hàng không thì mới cho kiểm hàng, còn nếu khách không nói tới thì đừng bao giờ nói
# chuyện được xem hàng trước khi nhận"*. Đo 23/09 trên 16.612 tin AI khác nhau đã gửi: ~1.300 tin (~8%) có câu "check it
# first before paying" / "i-check muna bago bayaran" / "تفتح الطرد قبل ما تدفع" — trong khi 24.046 câu khách khác nhau
# trong sổ chỉ ~80 câu HỎI / NHẮC chuyện đó. Nguồn: câu COD mẫu ở luật chung ("nhận hàng kiểm rồi mới trả") + 9 lời dặn
# trong code (níu, chê giá, nghi hàng giả 20/09 bắt buộc "ý kiểm hàng"…) → đã bỏ hết; cổng máy dưới đây gỡ phần còn lọt.
# Kèm theo là lời hứa bưu tá không làm: "the courier will wait while you inspect it", "pay only if you're happy".
# CỐ Ý KHÔNG BẮT: "pay only when it arrives" (COD trơn); "you can have it checked at any gold shop" không kèm "trước khi
# trả" — đó là khẳng định vàng thật, chủ shop thích AI nói vậy (đừng chặn).
_KH_VAT = (r"(?:it|them|this|that|everything|the\s+(?:\w+\s+){0,2}?(?:items?|products?|parcel|package|box|order|goods|gold"
           r"|jewel(?:le)?ry|necklaces?|rings?|bracelets?|earrings?|sets?|bottles?|lipsticks?|dentures?|quality|tea"
           r"|toothpaste|cream|rosary|wallet|soap)|your\s+(?:\w+\s+)?(?:items?|products?|parcel|package|order|set))")
KIEM_HANG_RA = re.compile(
    # "check/open/inspect … before paying / before you pay the courier"
    r"\b(?:open|check|inspect|see|look\s+at|examine|verify|test|try)(?:ed|ing|s)?\b[^.!?\n]{0,50}\b(?:before|prior\s+to)\s+"
    r"(?:you\s+|u\s+)?(?:pay|paying|payment|accept|receiv)"
    r"|\b(?:check|inspect|open|examine)(?:ed|ing|s)?\b[^.!?\n]{0,50}\bfirst\s+before\b"
    # "check it first", "check the gold when it arrives"
    r"|\b(?:check|inspect|open|examine|see|look\s+at)\s+" + _KH_VAT + r"\s+(?:first|upon\s+(?:arrival|delivery|receiving)"
    r"|on\s+arrival|when\s+(?:it|they)\s+(?:arrives?|comes?|is\s+delivered|are\s+delivered)|at\s+(?:your\s+)?(?:door|home))"
    # "receive it, check it, then pay" / "check the gold at any shop first, and pay"
    r"|\b(?:check|inspect|open|examine)(?:ed|ing|s)?\b[^.!?\n]{0,45}\b(?:then|and\s+then|and\s+only)\s+(?:you\s+)?(?:only\s+)?pay"
    r"|\b(?:check|inspect|open|examine|test|verify)(?:ed|ing|s)?\b[^.!?\n]{0,45}\b(?:first|muna)\b[^.!?\n]{0,20}"
    r"(?:\s*(?:and|then|saka|,)\s*)+(?:you\s+|ka\s+)?(?:only\s+)?(?:pay|mag-?bayad|magbabayad)"
    # "pay when you receive and check it", "once you've checked them", "check it with the courier first"
    r"|\b(?:receive|get)\s+(?:it\s+|them\s+)?and\s+(?:check|inspect|open|see)"
    r"|\bonce\s+you(?:'|’)?(?:ve|\s+have)\s+(?:checked|inspected|opened|seen)"
    r"|\bcheck\s+(?:it|them)\s+with\s+the\s+(?:courier|rider|driver)|\bcheck\s+(?:it|them)\s+in\s+person"
    r"|\b(?:check|inspect)\s+(?:it|them|the\s+\w+)\s+yourself|\byou(?:'|\u2019)?(?:ve|\s+have)\s+(?:checked|inspected|opened)\b"
    r"|\bafter\s+(?:you(?:'|\u2019)?(?:ve|\s+have)?\s+)?(?:check|inspect|open)(?:ed|ing)?\b"
    r"|\b(?:check|inspect)(?:ed|ing|s)?\b[^.!?\n]{0,40}\bwhen\s+(?:it|they)\s+(?:arrives?|comes?|is\s+delivered|are\s+delivered)"
    # hứa "không ưng thì khỏi trả" / "bưu tá đợi bạn kiểm"
    r"|\bpay\b[^.!?\n]{0,30}\bif\s+(?:you(?:'|’)?re\s+|you\s+are\s+)?(?:happy|satisfied|you\s+like\s+it)"
    r"|\bonly\s+if\s+(?:you(?:'|’)?re\s+|you\s+are\s+)?satisfied|\bwhen\s+everything\s+looks\s+good"
    r"|\b(?:courier|rider|driver)\s+(?:will\s+)?waits?\s+(?:while|for)\s+you"
    # Tagalog / Taglish
    r"|\b(?:i-?check|icheck|check|tingnan|tignan|makita|suriin|buksan|mabuksan|silipin|inspect)\b[^.!?\n]{0,50}"
    r"\bbago\s+(?:mo\s+|niyo\s+|nyo\s+|ninyo\s+|po\s+)?(?:mag)?(?:bayad|bayaran|magbayad|bumayad|bayar)\b"
    r"|\bbago\s+(?:(?:ka|kayo|mo|niyo|nyo|ninyo|po)\s+){0,2}(?:mag)?(?:bayad|bayar)\w*\b[^.!?\n]{0,50}"
    r"\b(?:buksan|i-?check|tingnan|tignan|suriin|susuriin|titingnan|titignan|ipa-?test|ipa-?check|makita)\b"
    r"|\b(?:cod|cash\s+on\s+delivery|pagdating|pag\s+dating)\b[^.!?\n]{0,40}\b(?:i-?check|icheck|check|tingnan|tignan"
    r"|titingnan|titignan|suriin|susuriin|buksan|makikita|mache-?check)\b[^.!?\n]{0,15}\bmuna\b"
    r"|\bi-?check\s+(?:mo|niyo|nyo|ninyo|po)\b[^.!?\n]{0,30}\b(?:saka|then|bago\s+(?:mo\s+|niyo\s+|nyo\s+|ninyo\s+|po\s+|ka\s+|kayo\s+)?(?:mag)?(?:bayad|bayaran|magbayad|bumayad|bayar|tanggapin))\b"
    r"|\b(?:i-?check|icheck|tingnan|tignan|suriin|buksan|inspect|check|makikita|mache-?check)\s+(?:niyo\s+|nyo\s+|mo\s+|ninyo\s+|po\s+)?muna\b"
    r"(?=[^.!?\n]{0,40}\b(?:bago\s+(?:mo\s+|niyo\s+|nyo\s+|ninyo\s+|po\s+|ka\s+|kayo\s+)?(?:mag)?(?:bayad|bayaran|magbayad|bumayad|bayar|tanggapin)|saka|pagdating|item|items|produkto|parcel|package|box|kahon|order|rider|courier|products?|gold|set|necklace|rings?|bracelet|soap|tea|lotion|cream|lipsticks?|quality|pcs?|piraso|certificate)\b)"
    r"|\b(?:titingnan|titignan|susuriin|bubuksan)\s+(?:niyo\s+|nyo\s+|mo\s+|ninyo\s+|po\s+)?muna\b"
    r"(?=[^.!?\n]{0,40}\b(?:bago\s+(?:mo\s+|niyo\s+|nyo\s+|ninyo\s+|po\s+|ka\s+|kayo\s+)?(?:mag)?(?:bayad|bayaran|magbayad|bumayad|bayar|tanggapin)|saka|pagdating|item|items|produkto|parcel|package|box|kahon|order|rider|courier|products?|gold|set|necklace|rings?|bracelet|soap|tea|lotion|cream|lipsticks?|quality|pcs?|piraso|certificate)\b)"
    r"|\bmunang\s+(?:buksan|i-?check|tingnan|suriin)|\bnatingnan\s+muna"
    r"|\b(?:buksan|i-?check|suriin)\s+(?:po\s+)?(?:ang\s+)?(?:parcel|package|box|kahon|item|produkto|order)"
    # Indonesia
    r"|\b(?:cek|periksa|buka|lihat)\b[^.!?\n]{0,40}\bsebelum\s+(?:bayar|membayar|dibayar)"
    # Ả Rập: "تفتح الطرد وتتأكد قبل ما تدفع", "تستلم، تفحصه، وبعدها تدفع", "تدفع بعد ما تفحص"
    r"|(?:تفتح|تفحص|تتأكد|تتاكد|تشوف|افتح|افحص|فحص|معاينة|تعاين)[^.!?\n]{0,50}قبل\s*(?:ما\s*)?(?:ال)?(?:دفع|تدفع)"
    r"|(?:تفتح|تفحص|تتأكد|تتاكد|تشوف|تعاين)\w*[^.!?\n]{0,50}(?:وبعدها|بعدها|وبعد\s*كذا|ثم|بعدين)\s*(?:ت)?دفع"
    r"|تدفع\w*[^.!?\n]{0,40}(?:بعد\s*ما\s*(?:تفحص|تتأكد|تتاكد|تشوف|تفتح)|إذا\s*عجبك)|(?:تفحص|فحص)\w*[^.!?\n]{0,20}عند\s+الاستلام"
    # Trung
    r"|驗貨|验货|開箱|开箱|先檢查|先检查|先看貨|先看货|檢查後再付|检查后再付",
    re.I | re.U)
# Khách HỎI / NHẮC chuyện mở-xem-kiểm hàng (rộng hơn TRUOC_MUA: "can I check it first?", "I will check before I pay",
# "U can inform also the courrier that i will check first") — có thì câu kiểm hàng được đi. Cố ý không nhận
# "tingnan ko muna" (= để tôi xem đã, lời hoãn) và "أشوف … قبل شوي" (= tôi thấy … lúc nãy).
KHACH_HOI_KIEM = re.compile(
    TRUOC_MUA +
    r"|\b(?:open|check|inspect|examine|unbox)\w*\b[^.?!\n]{0,30}\b(?:parcel|package|box|item|product|order|goods|gold|first"
    r"|upon|when\s+(?:it\s+)?arriv|when\s+(?:it\s+is\s+)?deliver)"
    r"|\b(?:can|could|may)\s+(?:i|we)\s+(?:see|check|open|inspect|look\s+at)\b[^.?!\n]{0,25}\b(?:first|before)\b"
    r"|\b(?:see|look\s+at)\b[^.?!\n]{0,25}\b(?:first|before)\b[^.?!\n]{0,30}\b(?:pay|arriv|deliver|receiv|accept)"
    r"|\b(?:i-?check|buksan|mabuksan|suriin|silipin)\b[^.?!\n]{0,30}\b(?:muna|pagdating|pag\s+dating|bago"
    r"|parcel|package|box|kahon|item|produkto|order)\b"
    r"|\b(?:tingnan|tignan|makita|natingnan)\b[^.?!\n]{0,30}\b(?:bago|pagdating|pag\s+dating)\b"
    r"|\b(?:pwede|puwede|pwd|pde|pwedi|pwedeng|pd)\b[^.?!\n]{0,20}\b(?:tingnan|tignan|makita|buksan|i-?check|suriin)\b"
    r"|\b(?:cek|periksa|buka)\b[^.?!\n]{0,30}\b(?:dulu|sebelum|paket|barang)\b"
    r"|(?:أفتح|افتح|أفحص|افحص|أتأكد|اتأكد|فتح|فحص|معاينة|أعاين)[^.?!\n]{0,40}"
    r"(?:الطرد|الشحنة|المنتج|البضاعة|الذهب|قبل\s*(?:ال)?دفع|قبل\s*ما\s*[أا]دفع|عند\s*الاستلام)"
    r"|(?:أشوف|اشوف)[^.?!\n]{0,30}(?:قبل\s*(?:ال)?دفع|قبل\s*ما\s*[أا]دفع|قبل\s*الاستلام)"
    r"|驗貨|验货|開箱|开箱|先看|先檢查|先检查|可以看|xem\s*hàng|kiểm\s*(?:tra\s*)?hàng|mở\s*(?:hàng|kiện|hộp)",
    re.I | re.U)


def khach_hoi_kiem_hang(msgs, so_tin=4):
    """Một trong `so_tin` tin khách gần nhất có hỏi / nhắc chuyện mở-xem-kiểm hàng trước khi trả tiền."""
    kh = [lam_sach(m.get("text") or "").strip() for m in (msgs or []) if m.get("boi") == "khach"]
    return any(KHACH_HOI_KIEM.search(t) or _tra_shipper_cau(t) for t in kh[-so_tin:] if t)   # TRA_SHIPPER_2709


# 🚚 TRA_SHIPPER_2709 — KHÁCH HỎI "KHÔNG ƯNG THÌ TRẢ LẠI CHO SHIPPER ĐƯỢC KHÔNG" (ca Marlyn Busito · Veloura Collection UAE, 27/09).
# "Just in case I'm not happy or I don't like the item can I return it to the Rider?" → luật 31 nhánh B (câu hỏi HIỆU QUẢ sau khi dùng)
# ra câu né "I understand your worry… try 1 set first?" — chủ shop: "AI rep chưa trọng tâm câu hỏi". Đo sổ 8 nước: 5 câu kiểu này,
# 2 câu né (Marlyn, Olie), 1 câu hứa "return it on the spot with the same rider" (Seeba — luật 15/09 cấm hứa), 2 câu AI không gửi.
# Luật: thị trường COD → câu đầu trả lời THẲNG: được mở kiểm hàng trước khi trả tiền shipper; không hứa trả lại / không mất tiền.
_TRA_VERB = (r"(?:return|give\s+(?:it\s+|them\s+)?back|send\s+(?:it\s+|them\s+)?back|hand\s+(?:it\s+)?back|refuse|reject"
             r"|i-?balik|ibabalik|ipabalik|isauli|isasauli)")
_KHONG_UNG = (r"(?:(?:don'?t|dont|do\s+not)\s+(?:like|love)|not\s+(?:happy|satisfied|nice|beautiful|the\s+same)"
              r"|(?:doesn'?t|does\s+not|didn'?t)\s+(?:fit|suit|look)|ayaw\s+ko|(?:hindi|di)\s+(?:ko\s+)?n?[am]agustuhan"
              r"|(?:hindi|di)\s+(?:ko\s+)?gusto)")
_TRA_SHIPPER = re.compile(
    r"\b" + _TRA_VERB + r"\b[^.?!\n]{0,40}\b(?:rider|courier|driver|delivery\s*(?:guy|man|boy|person|agent)|deliveryman|shipper"
    r"|mensahero|kurir|same\s+(?:person|guy|rider|time)|on\s+the\s+spot|upon\s+delivery|at\s+the\s+door)\b"
    r"|\b" + _KHONG_UNG + r"\b[^.?!\n]{0,60}\b" + _TRA_VERB + r"\b"
    r"|\b" + _TRA_VERB + r"\b[^.?!\n]{0,40}\b(?:if|kung)\s+(?:i\s+|i'?m\s+|i\s+am\s+)?" + _KHONG_UNG
    + r"|(?:ارجع|أرجع|ارجعه|أرجعه|ارجعها|أرجعها|أرده|ارده|أرفض|ارفض)[^.?!\n]{0,30}(?:المندوب|للمندوب|الدليفري|السائق)",
    re.I | re.U)
_HOI_GIA_DINH = re.compile(r"[?？؟]|\b(?:can|could|may|possible|allowed|pwede|puwede|pwedi|pde|pwd|maaari|if|in\s*case|what\s+if"
                           r"|kung|sakali|sakaling|pag)\b|ممكن|لو\s|إذا|اذا|يصير", re.I | re.U)
_HOI_HIEU_QUA = re.compile(r"\b(?:work|works|worked|working|effective|effect|results?|improvement|epekto|ipiktibo|tumalab|bisa)\b"
                           r"|مفعول|نتيجة|فعال", re.I | re.U)
_DA_TRA_THAT = re.compile(r"\b(?:i\s+(?:already\s+)?(?:returned|gave\s+(?:it\s+)?back|refused|rejected|sent\s+(?:it\s+)?back)"
                          r"|ibinalik\s+ko|isinauli\s+ko|pinabalik\s+ko)\b", re.I)
# Câu AI HỨA trả lại / không mất tiền — luật 15/09 (ca Seeba Kbabu) cấm.
HUA_TRA_SHIPPER = re.compile(
    r"\b(?:no\s+risk|risk[-\s]?free|money\s*back|full\s+refund|return\s+(?:it\s+|them\s+)?(?:on\s+the\s+spot|right\s+away|to\s+the\s+"
    r"(?:rider|courier|driver)|with\s+the\s+(?:same\s+)?(?:rider|courier|driver))|give\s+(?:it\s+)?back\s+to\s+the\s+(?:rider|courier|driver)"
    r"|(?:don'?t|do\s+not|won'?t|will\s+not)\s+(?:have|need)\s+to\s+pay|(?:pay|paying)\s+only\s+if|only\s+pay\s+if"
    r"|refuse\s+(?:it|the\s+(?:item|parcel|delivery|order))|i-?balik\s+(?:mo\s+|niyo\s+|nyo\s+)?(?:lang\s+)?sa\s+rider"
    r"|hindi\s+(?:mo\s+|niyo\s+)?(?:na\s+)?kailangang?\s+magbayad)\b|ترجعه\s*(?:مع|لل)\s*المندوب|ما\s*تدفع", re.I | re.U)


def _tra_shipper_cau(t):
    """Câu khách HỎI (giả định) trả lại shipper khi không ưng — không phải hỏi hiệu quả, không phải kể chuyện đã trả."""
    t = t or ""
    return bool(_TRA_SHIPPER.search(t) and _HOI_GIA_DINH.search(t) and not _HOI_HIEU_QUA.search(t)
                and not _DA_TRA_THAT.search(t))


def khach_hoi_tra_shipper(msgs, mkey=None):
    """Câu khách hỏi "không ưng thì trả lại shipper được không" trong ≤4 tin khách từ lần cuối AI/sale nhắn chữ; "" nếu không.
    Chỉ thị trường COD (Mỹ/Úc trả tiền trước, luật 11_my_uc lo)."""
    if (mkey or "") in ("usa", "australia"):
        return ""
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") in ("ai", "nguoi") and (m.get("text") or "").strip():
            break
        if m.get("boi") == "khach":
            t = lam_sach(m.get("text") or "").strip()
            if t:
                kh.append(t)
            if len(kh) >= 4:
                break
    for t in kh:
        if _tra_shipper_cau(t):
            return t[:160]
    return ""


# 📷 KHÁCH NÓI ẢNH PAGE VỪA GỬI BỊ MỜ (cùng ca Marlyn: "It's blurred" sau tấm giấy chứng nhận AI gửi → AI đáp chuyện size nhẫn cũ —
# bản ghi chỉ có "[có ảnh/file]", model không biết ảnh nào). Đo sổ: 3 câu kiểu này / 2 tuần, 1 câu lạc đề (Marlyn).
_CHE_MO = re.compile(r"\b(?:blur\w*|blury|not\s+clear|unclear|pixel\w*|malabo|labo"
                     r"|(?:can'?t|cannot|cant|could\s*n'?t)\s+(?:see|read)\s+(?:it|this|that|clearly|properly|anything|the\s+(?:photo|pic"
                     r"|picture|image|certificate|text|words|letters|writing))"
                     r"|(?:di|hindi)\s+(?:ko\s+)?(?:makita|mabasa)\s+(?:ng\s+)?(?:maayos|malinaw)?)\b"
                     r"|مو\s*واضح|غير\s*واضح|مش\s*واضح|看不清|模糊|不清楚", re.I | re.U)
_MAT_KHACH = re.compile(r"\b(?:eyes?|vision|sight|mata|paningin|glasses|salamin|location|address|house|bahay|retake|re-?send"
                        r"|i'?ll\s+(?:send|take)|i\s+will\s+(?:send|take)|my\s+(?:photo|pic|picture|palm|hand|selfie))\b|عيون|عيني|نظر|眼",
                        re.I | re.U)
_NHAN_ANH_LOAI = {"cn": "GIẤY CHỨNG NHẬN", "fb": "ảnh FEEDBACK của khách cũ", "sp": "ảnh SẢN PHẨM"}


def khach_che_anh_mo(msgs, mkey=None, conv_id=None):
    """(câu khách, tên loại ảnh) khi khách vừa nói ảnh page gửi bị mờ / không đọc được và page chưa đáp chữ sau đó; None nếu không."""
    msgs = msgs or []
    cau, i_cau, n = None, -1, 0
    for i in range(len(msgs) - 1, -1, -1):
        m = msgs[i]
        if m.get("boi") in ("ai", "nguoi") and (m.get("text") or "").strip():
            break
        if m.get("boi") == "khach":
            n += 1
            t = lam_sach(m.get("text") or "").strip()
            if t and len(t) <= 120 and _CHE_MO.search(t) and not _MAT_KHACH.search(t):
                cau, i_cau = t, i
                break
            if n >= 3:
                break
    if not cau:
        return None
    # tấm ảnh GẦN NHẤT trước câu đó (≤6 tin) phải do phía page gửi — ảnh của chính khách ("I will retake") thì không phải
    _anh_gan_ = [msgs[j] for j in range(i_cau - 1, max(-1, i_cau - 7), -1) if msgs[j].get("co_dinh_kem") or msgs[j].get("anh")]
    if not _anh_gan_ or _anh_gan_[0].get("boi") not in ("ai", "nguoi", "botcake"):
        return None
    loai = "ảnh page vừa gửi"
    try:
        d = qht.load_json(_f_anh_loai_da_gui(mkey), {}).get(str(conv_id)) or {}
        if d:
            k, lu = max(d.items(), key=lambda kv: kv[1] or 0)
            if time.time() - (lu or 0) < 3600:
                loai = _NHAN_ANH_LOAI.get(k, loai)
    except Exception:                                  # noqa: BLE001 — sổ ảnh hỏng thì gọi chung "ảnh page vừa gửi"
        pass
    return cau[:100], loai


# Mệnh đề trong câu: ngăn bằng gạch dài / chấm phẩy / hai chấm, hoặc ", and / so / plus / at / kaya …"
# ("COD naman — pwede mo i-check muna bago bayaran", "… 109 SAR, free delivery, and you can check it before paying").
_NGAT_ME_DE = re.compile(r"\s+[—–-]\s+|;\s+|\s+—|—\s+|:\s+"
                         r"|,\s+(?=(?:and|so|plus|at|kaya|pero|but|since)\s)", re.I)
# Mệnh đề dẫn còn trơ lại sau khi gỡ ("Just to let you know — <ý kiểm hàng>") → bỏ cả câu.
_DAN_TRO = re.compile(r"^\W*(?:just\s+(?:to\s+let\s+you\s+know|so\s+you\s+know|wanted\s+to\s+let\s+you\s+know)|also|and|plus"
                      r"|remember|by\s+the\s+way|good\s+news|the\s+best\s+part(?:\s+is)?|that(?:'|’)?s\s+why\s+we\s+do\s+cod"
                      r"|ang\s+maganda\s+po|kaya|at|since\s+it(?:'|’)?s\s+(?:cod|cash\s+on\s+delivery))\W*$", re.I)
_EMOJI_DUOI = re.compile("([\U0001F300-\U0001FAFF☀-➿❤]️?)\\s*$")


def cat_cau_kiem_hang(t):
    """Gỡ ý kiểm hàng khỏi tin mà giữ phần còn lại. Không gỡ gọn được thì None (để model sửa nhẹ).

    Từng câu dính KIEM_HANG_RA: (1) bỏ đúng MỆNH ĐỀ dính nếu phần còn lại của câu đứng được; (2) không thì bỏ cả câu,
    trừ khi câu mang yêu cầu hành động NGOÀI cụm kiểm hàng (_CAU_VIEC: hỏi, xin SĐT/địa chỉ, chọn gói). Phần phải
    bỏ mà có con số (giá / ngày) → None, không đánh rơi số.
    """
    goc = (t or "").strip()
    giu = []
    for c in re.split(_NGAT_CAU, goc):
        if not KIEM_HANG_RA.search(c):
            giu.append(c)
            continue
        md = [x for x in _NGAT_ME_DE.split(c) if x.strip()]
        con = [x for x in md if not KIEM_HANG_RA.search(x)]
        bo = [x for x in md if KIEM_HANG_RA.search(x)]
        if len(md) > 1 and con and len(" ".join(con)) >= 12 and not _DAN_TRO.match(" ".join(con)):
            if any(re.search(r"\d", KIEM_HANG_RA.sub("", x)) for x in bo):
                return None
            con = [x.strip(" ,") for x in con]
            if md[0].strip(" ,") != con[0]:
                con[0] = con[0][:1].upper() + con[0][1:]
            s = " — ".join(con)
            duoi = re.search("(?:[.!?]+|[\U0001F300-\U0001FAFF☀-➿❤]️?)\\s*$", c)
            d_ = duoi.group(0).strip() if duoi else ""
            if d_ and not s.endswith(d_):
                s = s.rstrip(" ,.") + (d_ if d_[0] in ".!?" else " " + d_)
            giu.append(s)
            continue
        if re.search(r"\d", KIEM_HANG_RA.sub("", c)) or _CAU_VIEC.search(KIEM_HANG_RA.sub(" ", c)):
            return None                   # câu còn số / lời mời / câu hỏi ngoài cụm kiểm hàng → để model sửa
        em = _EMOJI_DUOI.search(c)        # câu bỏ đi có emoji đuôi (😊) → giữ emoji cho câu trước
        if em and giu and not _EMOJI_DUOI.search(giu[-1]):
            giu[-1] = re.sub(r"\.\s*$", "", giu[-1].rstrip()) + " " + em.group(1)
    kq = _don_cau(" ".join(giu))
    if len(kq) < 20 or kq == goc or KIEM_HANG_RA.search(kq):
        return None
    return kq


def cat_cau_tha_khach(t):
    """Bỏ các câu/cụm thả khách ("Take your time!") khỏi tin; còn quá ngắn thì trả nguyên."""
    cau = re.split(r"(?<=[.!?])\s+", t or "")
    giu = [c for c in cau if not THA_KHACH.search(c)]
    kq = " ".join(giu).strip()
    return kq if len(kq) >= 40 else (t or "")


# CHỮ NỘI BỘ LỘ RA KHÁCH (chủ shop 20/09, ca Jean Navarro — Golden Soap House KSA:
# "Our script doesn't list dark spot removal"). Khách không được biết sau lưng có kịch bản:
# biết rồi thì mọi câu sau đó đọc như máy đọc bài, không phải sale nhắn.
# Ranh giới từ \b là thứ giữ cho cổng này không bắt oan: "prescription", "non-prescription",
# "description" đều chứa chuỗi "script" nhưng KHÔNG khớp. "prompt" chỉ bắt khi đi với
# system/my/the — "prompt delivery", "prompt reply" là chữ bán hàng bình thường.
LO_NOI_BO = re.compile(
    r"\bscripts?\b"
    r"|\bkịch\s*bản\b"
    r"|\b(?:system|my|the)\s+prompts?\b"
    r"|\bmy\s+(?:instructions|training|guidelines)\b"
    r"|\b(?:as an|i'?m an|i am an)\s+(?:ai|a\.?i\.?)\b"
    r"|\blanguage model\b",
    re.I | re.U)

# Ở Úc/Anh "script" còn là ĐƠN THUỐC ("a script from your doctor") — nghĩa hợp lệ, không chặn.
_LO_DON_THUOC = re.compile(r"doctor|pharmac|chemist|prescri|refill|GP\b", re.I)


def lo_noi_bo(t):
    """Cụm chữ nội bộ đầu tiên trong `t`, hoặc None. Bỏ qua "script" nghĩa đơn thuốc."""
    for m in LO_NOI_BO.finditer(t or ""):
        if m.group(0).lower().startswith("script") \
                and _LO_DON_THUOC.search(t[max(0, m.start() - 45):m.end() + 45]):
            continue
        return m.group(0)
    return None


def cat_cau_lo_noi_bo(t):
    """Bỏ nguyên câu có chữ nội bộ, giữ phần còn lại. Không sạch được thì trả None để đi đường khác."""
    goc = (t or "").strip()
    kq = _don_cau(" ".join(c for c in re.split(_NGAT_CAU, goc) if not lo_noi_bo(c)))
    if len(kq) < 40 or kq == goc or lo_noi_bo(kq):
        return None
    return kq


# HỨA "ĐỂ TÔI HỎI SHOP RỒI BÁO LẠI" (chủ shop 20/09, ca Loida Caadlawon — Lapad Jewelry KSA in UAE).
# Khách hỏi "Ilang grams maam", AI đáp "hindi ko pa sure ang exact grams — icheck ko muna sa shop at
# ibabalita ko agad sa iyo". Khách tự trả lời luôn: "It weighs 3.6 grams" — khách biết hàng rõ hơn
# người bán. Câu hứa này là đường cụt: không ai đi hỏi shop, không ai báo lại, khách ngồi đợi một tin
# không bao giờ tới, sale cũng không biết có việc. Thà trả lời bằng con số dòng hàng của shop (bảng
# TRONG_LUONG_CHUAN bên dưới) rồi chốt tiếp, hoặc treo cho sale — nhưng KHÔNG hứa suông.
# Đo 20/09 trên 9.504 tin AI đã gửi: bắt 24 tin (0,25%), soi tay 24/24 đều đáng chặn (thông số hàng,
# giờ mở cửa, size, ảnh mẫu, giá gói không có trong bảng).
HUA_BAO_LAI = re.compile(
    r"""(?:
        \b(?:i|we)\s*(?:'|’)?(?:ll|\s*will|\s*can|\s*need\s+to|\s*have\s+to)?\s*(?:double[- ]?)?check\s+
          (?:it\s+|that\s+|this\s+|on\s+it\s+)?with\s+(?:the\s+|our\s+|my\s+)?
          (?:shop|store|team|staff|supplier|warehouse|seller|owner)\b
      | \blet\s+me\s+(?:double[- ]?)?check\s+(?:it\s+|that\s+|this\s+)?
          (?:with\s+(?:the\s+|our\s+|my\s+)?(?:shop|store|team|staff|supplier|warehouse)|what\s+\w+\s+i\s+can)\b
      | \b(?:get|come)\s+back\s+to\s+you\b
      | \b(?:i|we)\s*(?:'|’)?(?:ll|\s*will)\s+(?:confirm|update|let\s+you\s+know|inform\s+you)\b
          [^.!?]{0,40}\b(?:shortly|later|soon|right\s+away|asap|in\s+a\s+bit|once\s+i|after\s+i)\b
      | \b(?:i|we)\s*(?:'|’)?(?:ll|\s*will)\s+ask\s+(?:our|the|my)\s+(?:team|sales|staff|shop|supplier)\b
      | \b(?:i|we)\s*(?:'|’)?m\s+not\s+sure\s+(?:about\s+)?(?:the\s+)?(?:exact|weight|length|size|grams?|measurement)\b
      | \b(?:i|we)\s+(?:don|do\s+not)\s*(?:'|’)?t\s+have\s+the\s+exact\b
      | \bhindi\s+ko\s+(?:pa\s+)?(?:sure|alam)\b
      | \b(?:i-?(?:che-?)?check|i-?tsek(?:in)?|tsek(?:in)?)\s+ko\s+(?:po\s+)?(?:muna\s+)?(?:sa|kay)\b | \bipapa-?che?ck\s+ko\b
      | \bipapatanong\s+ko\b | \bitatanong\s+ko\b | \btatanungin\s+ko\b
      | \b(?:babalitaan|ibabalita)\s+(?:ko|namin)\s+(?:po\s+)?(?:kayo|kita|sa\s+inyo|sa\s+iyo|agad)\b
      | \bibabalita\s+ko\b
      # 22/09: "babalitaan kita agad" (không có ko/namin) và "titignan ko po sa team" lọt cổng — đo 14.726 tin AI
      # trong log: thêm đúng 1 bắt (ca Julie Cambarijan, hứa thật), 0 oan; "babalitaan ka namin pag nasa courier na" miễn.
      | \bbabalitaan\s+(?:po\s+)?(?:kita|ka|kayo)\b
      | \b(?:titignan|titingnan|tingnan)\s+ko\s+(?:po\s+)?(?:muna\s+)?(?:sa|kay)\s+(?:team|shop|store|staff|supplier)\b
      # 22/09 ca Steph Reyes (Veloura UAE): "For 3 sets, let me have our team confirm the exact price for you" lọt cổng.
      | \b(?:let\s+me\s+have|i\s*(?:'|’)?ll\s+have|i\s+will\s+have|let)\s+(?:our|the|my)\s+
          (?:team|sales|staff|shop|store|supplier)\s+(?:confirm|check|verify|get\s+back)\b
      | \b(?:our|the)\s+(?:team|sales|staff|shop|store)\s+(?:will|can|would)\s+(?:confirm|check|verify|send|share|give)\s+
          (?:you\s+)?(?:the\s+)?(?:exact\s+|final\s+|best\s+)?(?:price|cost|total)\b
      | \bsasabihin\s+ko\s+(?:po\s+)?agad\b
      | \bwala\s+(?:po\s+)?(?:akong|kaming)\s+exact\b
    )""", re.I | re.X | re.U)

# Hứa HỢP LỆ, không phải né câu hỏi: tỉ giá đổi tiền (thay đổi từng ngày, nói chắc mới là bịa), đơn
# ĐÃ đặt (báo khi hàng lên courier), khiếu nại/hoàn tiền/lừa đảo (luật riêng: chuyển sale), và câu
# xác nhận emirate/giờ giao sau khi đã chốt đơn.
MIEN_HUA = re.compile(
    r"\bexchange\s+rate|\brate\s+(?:ngayon|today)|\bpeso\b|\bconversion\b"
    r"|\bcourier\b|\btracking\b|\brider\b|\bbiker\b|nasa\s+courier"
    r"|\byour\s+order\b|\bang\s+order\s+(?:mo|niyo|ninyo)\b|\brefund\b|\breturn\b|\bcomplaint\b"
    r"|\bemirate\b|\bdelivery\s+time\b|\bdelivery\s+date\b|\bschedule\b|\bscam+er\b|\bscam\b", re.I | re.U)


def hua_bao_lai(t):
    """Cụm hứa-báo-lại đầu tiên trong `t`, hoặc None. Bỏ qua các ca hứa hợp lệ (MIEN_HUA)."""
    m = HUA_BAO_LAI.search(t or "")
    if not m:
        return None
    if MIEN_HUA.search((t or "")[max(0, m.start() - 70):m.end() + 70]):
        return None
    return m.group(0)


# Câu nối chỉ có nghĩa khi đứng sau lời hứa ("Let me check with our team. In the meantime, 1 or 2?") — cắt lời hứa
# thì bỏ luôn câu nối, đừng để khách đọc "In the meantime" lơ lửng (log 20→22/09: 6/11 câu cắt máy mở đầu như vậy).
_NOI_SAU_HUA = re.compile(r"^(?:in\s+the\s+meantime|meanwhile|for\s+now|samantala|sa\s+ngayon)\s*,?\s*", re.I | re.U)


def _bo_noi_sau_hua(c):
    c2 = _NOI_SAU_HUA.sub("", c)
    return c2[:1].upper() + c2[1:] if c2 != c else c


def cat_cau_hua_bao_lai(t):
    """Bỏ nguyên câu chứa lời hứa, giữ phần còn lại. Không sạch được thì None."""
    goc = (t or "").strip()
    kq = _don_cau(" ".join(_bo_noi_sau_hua(c) for c in re.split(_NGAT_CAU, goc) if not hua_bao_lai(c)))
    if len(kq) < 40 or kq == goc or hua_bao_lai(kq):
        return None
    return kq


# CẮT LỜI HỨA XONG MÀ CHỈ CÒN CHÀO + CÂU CHỐT (chủ shop 22/09: *"sao đơn này khách hỏi 1 đường, bạn rep 1 nẻo"*,
# ca Rosalie M Tubiona · Key Jewelry Saudi): khách "Pwede na po ba yan I sanla sa pinas", AI định đáp "Ipapa-check ko…",
# cắt máy còn đúng "Gusto niyo po bang mag-order muna ng 1 o 2 necklaces?". Đo log 6 nước 20→22/09: 11 lần cắt máy,
# 10 lần phần còn lại kiểu đó ("In the meantime, would you like 1 or 2 necklaces?", "Would you like to try it once?").
# Câu hứa CHÍNH là câu trả lời — cắt đi thì khách hỏi mà không ai đáp. Câu như vậy KHÔNG gửi, treo cho sale.
_CAU_CHAO = re.compile(r"^(?:hi|hello|hey|good\s+(?:morning|afternoon|evening|day)|sure|okay|ok|noted|thanks|thank\s+you"
                       r"|salamat|sorry|hala|ay|dear|مرحبا|اهلا|أهلا|شكرا)\b", re.I | re.U)
# Câu hỏi CHỐT (mời mua / hỏi số lượng) — câu hỏi có nội dung ("Yes, it's 18K gold, would you like…?") không tính.
_HOI_CHOT = re.compile(
    r"^(?:(?:would|do|shall|should|can|may|will)\s+(?:you|i|we)\b|how\s+many\b|which\b|want\s+(?:me|to)\b"
    r"|(?:gusto|nais)\s+(?:mo|niyo|ninyo|nyo)\b|ilan\b|ilang\b|tama\s+ba\b)", re.I | re.U)
_CAU_KHONG_BIET = re.compile(
    r"\b(?:don'?t|do\s+not|doesn'?t)\s+have\s+(?:that|the|this|any|exact|more)\s+(?:exact\s+)?(?:details?|info|information|data)\b"
    r"|\bnot\s+sure\b|\bhindi\s+ko\s+(?:pa\s+)?(?:sure|alam)\b"
    r"|\bwala\s+(?:po\s+)?(?:akong|kaming)\s+(?:info|detalye|impormasyon)\b", re.I | re.U)
_CAU_XIN_TT = re.compile(
    r"\b(?:send|give|share|provide|drop)\b[^.!?]{0,50}\b(?:contact|number|address|name|details|location|emirate)\b"
    r"|\b(?:ipadala|ibigay|pakibigay|i-?send|makuha)\b[^.!?]{0,50}\b(?:number|address|pangalan|contact)\b", re.I | re.U)
_CAU_DO_DANH = re.compile(r"\bi'?m\s+sure\s+you'?ll\s+(?:love|like)\b|\byou\s+won'?t\s+regret\b"
                          r"|\bsigurado\s+(?:po\s+)?ako(?:ng)?\b|\bmagugustuhan\s+(?:mo|niyo|ninyo)\b", re.I | re.U)
_EMOJI_CAU = re.compile("[\U0001F300-\U0001FAFF\u2600-\u27BF\u2764\ufe0f]+")


def _la_cau_chot(c):
    """Câu không chở câu trả lời nào: chào, câu hỏi chốt / mời mua, xin thông tin giao hàng, 'tôi không có thông tin'."""
    s = _EMOJI_CAU.sub("", _NOI_SAU_HUA.sub("", (c or "").strip())).strip(" ,.!")
    if not s:
        return True
    if _CAU_CHAO.match(s) and len(s.split()) <= 4:
        return True
    if (s.endswith(("?", "؟")) or re.search(r"\bba(?:ng)?\b", s, re.I)) and _HOI_CHOT.match(s):
        return True
    return bool(_CAU_KHONG_BIET.search(s) or _CAU_XIN_TT.search(s) or _CAU_DO_DANH.search(s))


def chi_con_cau_chot(t):
    """True = mọi câu trong `t` đều là chào / câu hỏi chốt / xin thông tin giao hàng — không chở câu trả lời nào."""
    cau = [c for c in re.split(_NGAT_CAU, (t or "").strip()) if c.strip()]
    return bool(cau) and all(_la_cau_chot(c) for c in cau)


# ─────────── TRỌNG LƯỢNG VÀNG KHI KỊCH BẢN PAGE KHÔNG GHI (chủ shop 20/09) ───────────
#
# *"dùng cân nặng như các page khác có dữ liệu — page khác báo bao nhiêu thì báo bấy nhiêu"*.
# Đo 20/09: 127 page trang sức, chỉ 49 page có ghi trọng lượng trong kịch bản; 73 page KHÔNG
# (UAE 19, Saudi 16, Mỹ 16, Kuwait 10, Đài 8, Qatar 4) — page nào rơi vào đó thì khách hỏi gram
# là AI không có gì để đáp. Bảng dưới đây là số của chính shop, đếm trên các page CÓ ghi:
#
# CHỦ SHOP CHỐT 20/09: *"page nào không có dữ liệu, cứ lấy dữ liệu khối lượng như vậy nhé, chọn cái
# page nào NẶNG NHẤT ấy"* — nên bảng này lấy MỨC CAO NHẤT đo được ở các page có ghi, không lấy mức
# phổ biến. Số trong ngoặc là page giữ mức đó:
#
#   nhẫn       3,5 g  (Infinity Jewelry Saudi - Taiwan: "~2.5-3.5g"; phổ biến chỉ 1 g)
#   dây        5,3 g  (Flat Jewelry KSA in Dubai: "Weight: 5.3 grams"; phổ biến 2,2 g)
#   đôi bông   3,2 g  (Golden Grace PH: "3,2 grams 2 earrings"; phổ biến 1,5-2 g)
#   bộ 3 món   6 g    (Malabar Gold: "The set weighs approximately 5-6g")
#   lắc/vòng   2 g    (Lazurde Jewelry KSA, Kalyan Jewellers Kuwait: "approximately 2 grams")
#              KHÔNG lấy 16 g của Gold Charm Bracelet US: page charm nặng ấy đã tự ghi số trong kịch
#              bản nên không cần gợi ý, còn chữ "charm" ở page khác là BÙA HỘ MỆNH (Mang Mulat:
#              "proteksyon charm") — gán 16 g vàng cho vòng mảnh 109 AED thì khách nhận là từ chối.
#
# ⚠️ ĐÃ LOẠI: "40 grams 1 necklace" (Golden Elegance Taiwan) — gấp 16 lần page nặng nhì, và 40 g vàng
# 18K thì tiền vàng thôi đã gấp mấy chục lần giá bán; nói số đó ra là khách biết ngay có gì sai.
#
# Số này chỉ dùng khi KỊCH BẢN PAGE KHÔNG CÓ. Page có ghi thì đọc kịch bản — số của page luôn thắng.
TRONG_LUONG_CHUAN = {
    "bo":       "the full set is about 6 grams of gold",
    "day":      "the necklace is about 5,3 grams of gold",
    "nhan":     "the ring is about 3,5 grams of gold",
    "bong":     "the pair of earrings is about 3,2 grams of gold",
    "lac":      "the bracelet is about 2 grams of gold",
}

# SỐ RIÊNG CỦA MỘT PAGE — đặt trước bảng chung, dùng khi chính SALE của shop đã trả lời khách một con
# số cụ thể trên page đó (số của shop luôn đúng hơn số suy từ dòng hàng). Ca Loida Caadlawon 20/09:
# AI hứa đi hỏi shop, sale phải nhảy vào chữa "It weighs 3.6 grams" — nên nhẫn Lapad lấy đúng 3,6 g.
TRONG_LUONG_PAGE = {
    "1219685227891442": "the ring is about 3,6 grams of gold",   # Lapad Jewelry KSA in UAE
    "1113027875236221": "the ring is about 3,6 grams of gold",   # Lapad Jewelry KSA
}

_MON = {
    # ⚠️ "ring" trơn là BẪY TAGALOG: "may isa pa ring tao", "kahit lumipat pa ring" — "pa ring" nghĩa
    # là "vẫn". Page bói bài Mang Mulat dính 3 lần vì vậy. Đòi ngữ cảnh trang sức hoặc số nhiều.
    "nhan": r"(?:gold|18\s*k|saudi|birthstone|lapad|wedding|engagement|couple)\s+rings?\b"
            r"|\brings?\s+(?:size|sizes)\b|\brings\b|singsing",
    "day": r"necklaces?|chains?|pendants?|kwintas",
    "bong": r"earrings?|hoops?|hikaw",
    "lac": r"bracelets?|bangles?|pulseras",
}
_CO_SO_GAM = re.compile(r"[0-9]+(?:[.,][0-9]+)?\s*(?:g\b|gr\b|gram)", re.I)
# Dấu hiệu vàng thật (không nhận "gold" trơn: "Golden Buddha", "gold plated", "lucky gold" đều có).
# "750" trơn KHÔNG tính: ở page tâm linh nó là giá tiền (750 PHP), không phải tuổi vàng.
_VANG_THAT = re.compile(
    r"\b18\s*k\b|\bau\s*750\b|saudi\s+gold"
    r"|750\s*(?:stamp|hallmark|mark|code)|(?:stamp|hallmark|code|mark)\w*\s*(?:with\s+)?750", re.I)
# Hàng đá / phong thuỷ / xu: có chữ gold nhưng không phải dây vàng — bảng cân không áp được.
_DA_PHONG_THUY = re.compile(
    r"\bjade\b|\bcrystal|\bgemstone|\bagate\b|\bobsidian\b|\bfeng\s*shui\b|\bbeads?\b"
    r"|\blucky\s+(?:charm|bracelet|aura)\b|\bpixiu\b|\bcoins?\b|\bamulet\b|\btalisman\b", re.I)
_LA_BO = re.compile(r"\b(?:jewel\w*|gold|birthstone|necklace|complete|full)\s+set\b|\bset\s+of\s+[0-9]", re.I)


# ══ CÂU VÀNG CHỈ CHO PAGE VÀNG (chủ shop 22/09: *"sao lại như vậy"*) ════════════════════════════════════
# Ca Alminda Cariaga · Clear Sight Optical Care Store Bahrain: AI nói thuốc nhỏ mắt là *"genuine 18K gold na may
# 750 stamp at may kasamang certificate"*; ca Mira Basco Porras · Hair Repair Therapy PH in Saudi: *"1 Hair Serum +
# 1 Hair Spray — genuine 18K gold po ito"*. Gốc: lệnh SỬA NHẸ của cổng "hứa báo lại" viết cứng câu vàng cho MỌI page,
# mà gói sửa nhẹ không mang kịch bản → model chép y nguyên. Đo log 6 nước: 11 lượt sửa nhẹ "hứa báo lại", 2 lượt
# ra câu vàng ở page không bán vàng (đúng 2 ca trên), 0 ca khác trong sổ việc.
_MA_VANG = re.compile(r"\bplated\b|\bplating\b|\bgold[\s-]*filled\b|mạ\s*vàng", re.I)
_VANG_CHU = re.compile(r"\b(?:18|21|22|24)\s*k\b|\bau\s*750\b|\b750\b|\bkarat\b|\bcarat\b|\bgold\b|\bginto\b"
                       r"|\bemas\b|ذهب|عيار|金", re.I | re.U)
_MAU_MO_TA_SP = re.compile(r"^/?(?:chao\w*|gioi_?thieu\w*|intro\w*|vang\w*|tp|thanh_?phan\w*|cong_?dung\w*"
                           r"|chat_?lieu\w*|hdsd\w*|huong_?dan\w*|info\w*|san_?pham\w*|sp)$", re.I)
# Dòng GIÁ / KHUYẾN MÃI / GIAO HÀNG — không phải mô tả sản phẩm. Tiền tệ phải bắt cả khi dính chữ: kịch bản Hair
# Repair ghi "Only 169 SARwith FREE Shipping" (thử 22/09: lọt dòng này là model đổi "Buy 1 Get 1" khách hỏi thành
# "Buy 2 Get 2 … 169 SAR").
_TIEN_TE = r"(?:AED|SAR|BHD|KWD|QAR|OMR|USD|PHP|dhs?|riyals?|dinars?|pesos?)"
_DONG_GIA_KM = re.compile(r"\b" + _TIEN_TE + r"\b|\d\s*" + _TIEN_TE + r"|(?:AED|SAR|BHD|KWD|QAR|OMR|USD|PHP)\s*\d"
                          r"|NT\$|\$\s*\d|\d+\s*%\s*(?:off|discount)|\b(?:off|promo\w*|sale|discount|offer)\b"
                          r"|\bbuy\s*\d+\s*(?:get|take)\s*\d+|\bb\d+t\d+\b|free\s+(?:shipping|delivery)|\bcod\b"
                          r"|cash\s+on\s+delivery|limited|khuyến\s*mãi", re.I)


def la_page_vang_that(kb_page):
    """Page bán VÀNG 18K THẬT (dây / nhẫn / bộ vàng) — chỉ page này máy mới được dặn sẵn câu "vàng 18K thật, tem 750,
    kèm giấy chứng nhận". Cùng điều kiện với bảng cân (trong_luong_goi_y), thêm loại hàng MẠ vàng."""
    t = json.dumps(kb_page or {}, ensure_ascii=False)
    return bool(_VANG_THAT.search(t)) and not _DA_PHONG_THUY.search(t) and not _MA_VANG.search(t)


def vang_lac_page(tin, kb_page):
    """Câu có chữ VÀNG (gold / 18K / 750 / ginto / ذهب…) mà kịch bản page KHÔNG hề có chữ nào như vậy."""
    if not _VANG_CHU.search(tin or ""):
        return False
    return not _VANG_CHU.search(json.dumps(kb_page or {}, ensure_ascii=False))


def thong_tin_sp_page(kb_page, toi_da=900):
    """Mô tả SẢN PHẨM bằng chữ của kịch bản page (mẫu chào hàng / vàng / thành phần / cách dùng) cho lượt gọi NHỎ
    không mang kịch bản (sửa nhẹ). Bỏ dòng giá / khuyến mãi (sửa nhẹ cấm thêm giá) và ô điền #{…}; chữ kiểu đậm
    "𝗟𝗜𝗠𝗜𝗧𝗘𝗗" đưa về chữ thường (NFKC) trước khi lọc. Rỗng = không có."""
    ra, n = [], 0
    for m in (kb_page or {}).get("mau") or []:
        if not _MAU_MO_TA_SP.match((m.get("tu_khoa") or "").strip()):
            continue
        for tin in m.get("tin") or []:
            for d in re.sub(r"#\{[^}]*\}", "", unicodedata.normalize("NFKC", tin or "")).splitlines():
                d = " ".join(d.split())
                if len(d) < 4 or _DONG_GIA_KM.search(d) or d in ra:
                    continue
                ra.append(d)
                n += len(d) + 1
            if n >= toi_da:
                break
        if n >= toi_da:
            break
    return ("PRODUCT INFO (the shop's own sales script — the only product facts you may state):\n"
            + "\n".join(ra)[:toi_da]) if ra else ""


def dieu_chac_chan_page(kb_page):
    """Điều AI được nói CHẮC khi kịch bản không ghi đúng thứ khách hỏi — thay cho lời hứa "kiểm tra rồi báo lại"
    (22/09, ca Rosalie M Tubiona · Key Jewelry Saudi). Page vàng thật: chủ shop THÍCH AI khẳng định vàng cầm / bán lại /
    đem kiểm được ở bất kỳ đâu, kể cả nước của khách (19/09, ca Abdlean · Glamora). Page khác: chỉ điều kịch bản ghi."""
    if la_page_vang_that(kb_page):
        return ("(vàng 18K thật, tem 750 ở khoá, kèm giấy chứng nhận, tiệm vàng nào cũng kiểm được, nhận hàng kiểm rồi "
                "mới trả tiền; khách hỏi CẦM ĐỒ (sanla / isangla / pawn), BÁN LẠI hay đem kiểm ở nơi khác — kể cả về "
                "Philippines / nước của khách — thì khẳng định CÓ, tự tin: vàng 18K thật thì tiệm vàng, tiệm cầm đồ nào "
                "cũng nhận) ")
    return ("— CHỈ điều kịch bản page GHI RÕ về sản phẩm (công dụng, thành phần, cách dùng…); CẤM tự thêm chất liệu, "
            "vàng/18K, giấy chứng nhận, cân nặng mà kịch bản không ghi — ")


def lenh_sua_hua_bao_lai(kb_page, pid=None):
    """(lệnh sửa nhẹ, khối PRODUCT INFO) cho câu nháp HỨA HỎI SHOP RỒI BÁO LẠI. Page vàng thật giữ nguyên lệnh 20/09;
    page khác trả lời bằng chữ của kịch bản page, cấm thêm vàng / chứng nhận / cân nặng (vá 22/09)."""
    tl = trong_luong_goi_y(kb_page, pid)
    vang = la_page_vang_that(kb_page)
    sp = "" if (tl or vang) else thong_tin_sp_page(kb_page)
    if tl:
        chac = f"State the figure plainly: {tl}. "
    elif vang:
        chac = ("Answer with what is certain about the product (genuine 18K gold, 750 stamp, certificate "
                "in every order) ")
    elif sp:
        chac = ("Answer with what is certain about THIS product, using only facts written in PRODUCT INFO above — "
                "never add a material, gold/18K, certificate, weight or guarantee that is not written there. ")
    else:
        chac = ("Answer only with what the draft already says about the product — never add a material, gold/18K, "
                "certificate, weight or guarantee. ")
    lenh = ("The draft promises to ask the shop/team and get back to the customer later "
            "(\"let me check with the shop\", \"I'll get back to you\", \"icheck ko muna sa shop\", "
            "\"babalitaan kita\"). Nobody ever does: the customer waits for a message that never "
            "comes and the sale dies. Rewrite WITHOUT any promise to check later and without saying "
            "you are unsure. " + chac
            + "Then close with one question. Same language as the draft, 1-2 short sentences, "
              "keep every other number unchanged.")
    return lenh, sp


def trong_luong_goi_y(kb_page, pid=None):
    """Câu trọng lượng để đưa model, suy từ dòng hàng của shop. None = kịch bản page đã có số.

    Thứ tự: số riêng của page (sale shop đã nói) → kịch bản page có ghi gram (trả None, model đọc
    thẳng kịch bản) → dò xem page bán món gì rồi lấy số dòng hàng tương ứng ở TRONG_LUONG_CHUAN.
    """
    if not kb_page:
        return None
    if pid and str(pid) in TRONG_LUONG_PAGE:
        return TRONG_LUONG_PAGE[str(pid)]
    s = json.dumps(kb_page, ensure_ascii=False)
    if _CO_SO_GAM.search(s):
        return None
    if not _VANG_THAT.search(s) or _DA_PHONG_THUY.search(s):
        # Chỉ vàng 18K thật mới có bảng cân. "gold" trơn không đủ: 20 page vòng đá / phong thuỷ
        # (Al Noor Lucky Bracelet, Lucky Charm House, Luxe Jade, Nanbu Coins…) cũng đầy chữ gold,
        # mà vòng đá nặng gấp nhiều lần vòng vàng 2 g — đáp số vàng cho vòng đá là sai trắng.
        return None
    dem = {k: len(re.findall(rx, s, re.I)) for k, rx in _MON.items()}
    co = [k for k, n in dem.items() if n]
    if not co:
        return None
    if _LA_BO.search(s) and len(co) >= 2:
        return TRONG_LUONG_CHUAN["bo"]
    return TRONG_LUONG_CHUAN[max(co, key=lambda k: dem[k])]


# KHÁCH HỎI THÔNG SỐ HÀNG (nặng bao nhiêu, dài bao nhiêu, size mấy). Dò đủ các tiếng khách hay dùng:
# Anh, Tagalog, Ả Rập, Indo — "Ilang grams maam" (ca Loida) không có dấu hỏi nên không được đòi "?".
HOI_THONG_SO = re.compile(
    r"\bhow\s+(?:many|much)\s+(?:gram|gm|g\b)|\bgrams?\b|\bweigh\w*\b|\bweight\b"
    r"|\bhow\s+long\b|\blength\b|\bhow\s+big\b|\bsize\b|\bmeasurement\b|\binches\b|\bcm\b|\bmm\b"
    r"|\bilang\s+gram|\bgaano\s+ka(?:bigat|haba|laki)|\btimbang\b|\bhaba\b|\blaki\b|\bsukat\b"
    r"|كم\s*جرام|الوزن|وزنه|الطول|المقاس"
    r"|\bberapa\s+gram\b|\bberat\b|\bukuran\b", re.I | re.U)


# "weight" của NGƯỜI, không phải của hàng: page trà giảm cân / gen nịt bụng hỏi cân nặng khách suốt
# ("I want to lose weight", "my weight is 70kg", "berat badan"), page áo quần hỏi size người mặc.
# Bắt nhầm mấy câu này là AI đi trả lời "dây chuyền nặng 2,2 g" giữa cuộc tư vấn giảm cân.
_CAN_CUA_KHACH = re.compile(
    r"\b(?:lose|losing|loss|reduce|my|your|her|his|ideal|current|target)\s+weight\b"
    r"|\bweight\s+(?:loss|gain|problem|now|is|po)\b|\bkg\b|\bkilos?\b|\blbs\b|\bpounds\b"
    r"|\b(?:mag|nag|pa)?bawas\s+(?:ng\s+)?timbang\b|\btimbang\s+(?:ko|mo|niya|namin|ninyo)\b"
    r"|\bberat\s+badan\b|\w*payat\w*|\btaba\b|\bslim\w*\b|\bdiet\b|\bmababawas\b"
    r"|\bsize\s+(?:ko|mo|niya)\b|\bmy\s+size\b|\bbra\b|\bwaist\b|\bcup\b", re.I | re.U)


# ── KHÁCH HỎI SIZE / KÍCH THƯỚC (chủ shop 23/09, ca Lee M Julian · Zahra Luxe Jewelry Kuwait) ───────────────────────────
# Khách "What the size the ring" → AI "Our 18K Gold Jewelry Set is a real 18K Saudi gold set … Would you like to reserve 1 set
# or 2 sets today?". Chủ shop: *"sao khách hỏi 1 đường rep 1 nẻo vậy"*. Gốc: dòng 📏 coi "kịch bản có số GRAM" (Zahra ghi
# "10,28 Grams") là "kịch bản CÓ thông số" dù khách hỏi SIZE; và nhánh không-có-số dặn "trả lời bằng thứ mình CHẮC CHẮN (vàng
# 18K, giấy chứng nhận…) rồi chốt tiếp" — đúng câu lạc đề ấy. Đo sổ so_chi_phi: 73 câu hỏi size/độ dài ở page kịch bản không
# ghi size ("What size available", "Ilan inches po kwentas", "How many inches????"). Nay: không nguồn → treo cho sale, 0 đồng.
# Khách BÁO size ("Size 11 and 7", "Ring size 5") và hỏi thời gian ("How long to arrive") KHÔNG tính.
_TU_KICH_THUOC = (r"(?:\b(?:sizes?|length|lenght|haba|kahaba|kalaki|sukat|diameter|inch(?:es)?|cm|mm|ukuran|panjang)\b"
                  r"|المقاس|مقاس|الطول)")
HOI_KICH_THUOC = re.compile(
    r"\b(?:what|whats|which|how|ano|anong|anu|ilan|ilang|gaano|avail\w*|meron|may|pwede|kasya)\b[^.?!\n]{0,30}"
    + _TU_KICH_THUOC + r"|" + _TU_KICH_THUOC + r"[^.?!\n]{0,20}\?|\b(?:length|size|haba)\s+(?:pls|please|po)\b"
    r"|\bhow\s+big\b|\bhow\s+long\s+(?:is|are)\s+(?:the|it|this|that|your)\b|\bgaano\s+ka(?:haba|laki)\b"
    r"|\bilang\s+(?:inch|inches|cm|mm)\b|\bhow\s+many\s+(?:inch|inches|cm|mm)\b|كم\s+(?:المقاس|مقاس|الطول)", re.I | re.U)
_BAO_SIZE = re.compile(r"\bsize\s*(?:is\s*)?\d|\b\d+(?:\.\d)?\s*(?:size|sz)\b|\b\d{2}\s*[a-e]\b", re.I)
_HOI_THOI_GIAN = re.compile(r"\b(?:arriv\w*|deliver\w*|ship\w*|take|takes|days?|wait|dating|darating|matagal)\b", re.I)
_CO_SO_KICH_THUOC = re.compile(
    r"\d+(?:[.,]\d+)?\s*(?:cm|mm|inch|inches)\b|\d+(?:[.,]\d+)?\s*[\"”″](?=\s|$|[,.)])"
    r"|\bsizes?\s*(?:#|no\.?)?\s*[:\-]?\s*\d|\bsizes?\s*[:\-]?\s*(?:xs|s|m|l|xl|xxl|free|small|medium|large)\b"
    r"|\badjustable\b|\bfree\s*size\b|\bopen\s*(?:ring|size|design)\b|\bresizable\b|\bone\s+size\b"
    r"|\bfits?\s+(?:all|most)\b|\blength\s*[:\-]?\s*\d|\bsize\s+chart\b|\bsizes?\s+available\b", re.I)


# "Size 5 ng ring available?" = HỎI còn size 5 (ca Roxie Velliza 23/09: AI tự khẳng định "available ang Size 5" dù kịch bản
# Veloura không ghi size) — khác "Size 11 and 7" (khách BÁO size). Có cả câu hỏi GIÁ ("how much size 6?") thì để model báo giá.
_HOI_CON_SIZE = re.compile(r"\?|\b(?:available|avail|meron|may|have|has|pwede|kasya|stock|got)\b", re.I)


# 💍 SIZE NHẪN MẶC ĐỊNH (chủ shop 23/09: *"KỊCH BẢN K GHI SIZE THÌ BÁO LÀ NHẪN CÓ THỂ ĐIỀU CHỈNH ĐƯỢC"*) — như luật độ dài 16–22
# inches: page trang sức, khách hỏi / báo size NHẪN, kịch bản + tin sale không ghi size → trả lời nhẫn adjustable (free size), không
# treo. Page không phải trang sức (răng giả, áo lót…) hay khách hỏi size món khác thì vẫn treo như cũ.
_HOI_NHAN = re.compile(r"\b(?:rings?|singsing|sing[\s-]*sing|sing2x?|finger|daliri)\b|خاتم|خواتم", re.I | re.U)
_HOI_DIEU_CHINH = re.compile(r"\badjust\w*|\bresiz\w*|\bfree\s*size\b|\bnababago\b", re.I)
_LA_HANG_VANG = re.compile(r"(?i)\bjewel\w*|\bgold\b|\b18\s*k\b|\bsaudi\s+gold\b|\bnecklace|\bbracelet|\bearrings?|\brings?\b")


def _size_nhan_mac_dinh_ap_duoc(kb_page, cau):
    """Khách hỏi / báo size NHẪN (hoặc hỏi nhẫn có chỉnh được không) ở page trang sức mà kịch bản / sale không ghi size."""
    t = lam_sach(cau or "")
    if not t.strip() or _HOI_DO_DAI.search(t) or _HOI_CAN.search(t):
        return False
    # câu BÁO size phải có chữ size ("18c" = 18K, "32A st." là địa chỉ — không phải size)
    hoi = (khach_hoi_kich_thuoc(t) or bool(_BAO_SIZE.search(t) and re.search(r"(?i)\bsizes?\b|\bsz\b", t))
           or bool(_HOI_DIEU_CHINH.search(t) and _HOI_NHAN.search(t)))
    if not hoi or kich_thuoc_co_nguon(kb_page):
        return False
    chu = _chu_kich_ban(kb_page)
    if not _LA_HANG_VANG.search(chu):
        return False
    khac = [k for k in ("necklace", "bracelet", "earrings") if _LOAI_TS_RX[k].search(t)]
    if khac and not _HOI_NHAN.search(t):
        return False                                 # hỏi size dây chuyền / lắc / bông tai — không phải nhẫn
    if _HOI_NHAN.search(t):
        return True
    # câu không nhắc nhẫn ("What size?") → chỉ khi NHẪN là hàng chính của page (page dây chuyền hỏi size ≠ size nhẫn)
    so = {k: len(rx.findall(chu)) for k, rx in _LOAI_TS_RX.items()}
    return so["ring"] > 0 and so["ring"] >= max(so["necklace"], so["bracelet"], so["earrings"])


def _do_dai_mac_dinh_ap_duoc(kb_page, cau):
    """Câu hỏi ĐỘ DÀI ở page trang sức mà kịch bản không ghi → luật 16–22 inches (chủ shop 20/09, DO_DAI_MAC_DINH) trả lời."""
    s = json.dumps(kb_page or {}, ensure_ascii=False)
    return bool(_HOI_DO_DAI.search(cau or "") and _LA_TRANG_SUC.search(s) and not _KB_CO_DO_DAI.search(s))


def khach_hoi_kich_thuoc(t):
    """Khách đang HỎI size / độ dài / kích thước của hàng (không phải báo size, không phải hỏi bao lâu giao)?"""
    t = lam_sach(t or "")
    if not HOI_KICH_THUOC.search(t) or (_BAO_SIZE.search(t) and (not _HOI_CON_SIZE.search(t)
                                                               or HOI_GIA.search(t.lower()))):
        return False
    if (re.search(r"\bhow\s+long\b", t, re.I) and _HOI_THOI_GIAN.search(t)
            and not re.search(r"\bsizes?\b|\blength\b|\bcm\b|\binch", t, re.I)):
        return False
    return True


def _chu_kich_ban(kb_page):
    return "\n".join(t for x in (kb_page or {}).get("mau") or [] for t in (x.get("tin") or []))


def kich_thuoc_co_nguon(kb_page, msgs=None):
    """Kịch bản page hoặc tin Botcake / sale trong hội thoại có ghi size / độ dài / kích thước không."""
    nguon = _chu_kich_ban(kb_page) + "\n" + "\n".join(m.get("text") or "" for m in (msgs or [])
                                                      if m.get("boi") in ("botcake", "nguoi"))
    return bool(_CO_SO_KICH_THUOC.search(nguon))


def khach_hoi_kich_thuoc_treo(msgs, kb_page):
    """Câu khách hỏi size mà KHÔNG nguồn nào ghi → trả câu đó để treo cho sale; không thì None.

    Chỉ xét tin khách CUỐI (≤25 chữ, câu dài là kể chuyện); page tư vấn theo bước (tâm linh) không áp."""
    kh = [m for m in (msgs or []) if m.get("boi") == "khach" and lam_sach(m.get("text") or "").strip()]
    if not kh or (msgs or [])[-1].get("boi") != "khach":
        return None
    t = lam_sach(kh[-1]["text"])
    if (len(t.split()) > 25 or not khach_hoi_kich_thuoc(t) or kich_ban_theo_buoc(kb_page)
            or _do_dai_mac_dinh_ap_duoc(kb_page, t)       # độ dài dây chuyền: luật 16–22 inches trả lời
            or _size_nhan_mac_dinh_ap_duoc(kb_page, t)):  # size nhẫn: nhẫn điều chỉnh được (chủ shop 23/09)
        return None
    return None if kich_thuoc_co_nguon(kb_page, msgs) else t


# 🧩 KHÁCH HỎI BỘ CÓ KÈM MÓN GÌ (chủ shop 23/09, ca فاطمه امدد · Zahra Luxe Jewelry Kuwait): "Have bracelet there same" → AI
# "Yes, the set includes a bracelet"; "Where's bracelet" → "kasama po ang bracelet sa set… kasama ng necklace at earrings". Chủ
# shop: *"set này làm gì có vòng tay"*. Kịch bản Zahra chỉ ghi "18K Gold Jewelry Set", không kể bộ gồm món gì → model bịa. Đo sổ:
# 37 câu hỏi món mà kịch bản KHÔNG nhắc ("Do you have a bracelet", "meron ba kayo ring", "Necklace, earrings, ring and bracelet in
# one set?") → treo cho sale, 0 đồng; 64 câu hỏi món kịch bản CÓ nhắc ("This set is with ring?") → model trả lời như cũ.
# Page trang sức MỘT loại không áp (luồng ảnh loại khác — loai_ts_khach_hoi — lo).
_HOI_CO_KHONG = re.compile(r"\?|\b(?:where|wheres|have|has|got|with|include[sd]?|including|kasama|meron|may|is\s+there"
                           r"|are\s+there|same|also|din|rin|ba|any)\b|فيه|معه|مع\s", re.I | re.U)
_KE_CHUYEN_DON_CU = re.compile(r"\bdati\b|\bbefore\s+i\b|\bi\s+(?:was|already)\s+order|\border\s*k\b|\btinapon\b|\bnangitim\b"
                               r"|\bpeke\b|\bfake\b|\bwhy\s+did\s+(?:you|u)\b", re.I)


# 🧩 BỘ GỒM GÌ THEO ẢNH (chủ shop 24/09, ca Ghuy Esguerra · Amora Jewelry Taiwan: *"page này bán cả vòng tay mà"*). Kịch bản
# chỉ ghi "Complete 4-piece set" + dòng gram "1 necklace | 1 ring | 2 earrings" (thiếu lắc) nhưng ảnh chào hàng gửi mọi khách
# đều có LẮC TAY trong hộp bộ → model kể theo dòng gram "4-piece: 1 necklace, 1 ring, 2 earrings, walang bracelet", khách hỏi
# "Yong may bracelet" → treo. Ảnh page đã gửi khách là nguồn thật: máy đọc MÓN trong ảnh sản phẩm của kịch bản (sổ
# state/chung/mon_anh_sp.json, đọc sẵn + đọc bù chạy nền, ~0,0001 USD/ảnh). Bộ = các món trong ảnh có ≥2 loại món (ảnh lẻ một
# món có thể là hàng bán thêm). Zahra Luxe Kuwait (23/09 "set này làm gì có vòng tay"): ảnh chỉ dây chuyền + nhẫn + bông tai
# → hỏi lắc vẫn treo. Tắt đọc bù: AI_MON_ANH=0.
_NHAC_MON_ANH = (
    "Look carefully at this jewelry product photo. For EACH item, decide by SIZE and SHAPE:\n"
    "- ring = a SMALL closed band sized for ONE FINGER (often has one stone or motif on top);\n"
    "- bracelet = a LONG chain or bangle sized for the WRIST (clearly longer than a ring, usually has a clasp);\n"
    "- necklace = a long chain for the neck (may have a pendant);\n"
    "- earrings = small studs/drops, usually a matching pair.\n"
    "First describe each item in a few words, then answer. Reply in this exact format:\n"
    "ITEMS: <short list>\n"
    "JSON: {\"product\": true|false, \"necklace\": n, \"bracelet\": n, \"ring\": n, \"earrings\": n}\n"
    "product=false if this is not a close photo of the jewelry for sale (store display with many pieces, certificate, "
    "text banner, screenshot, a person/model merely WEARING jewelry in an ad for another product such as cream or tea).")
# Page phải là page BỘ TRANG SỨC (chữ kịch bản có jewel / set) — 24/09: page kem Golden Youth Beauty có ảnh người mẫu đeo lắc.
_LA_BO_TS = re.compile(r"(?i)jewel|\bsets?\b|طقم|مجوهرات|套|首飾|alahas")
_MON_ANH = {"mt": None, "d": {}}
_MON_ANH_DANG = set()                # ảnh đang đọc bù (mỗi tiến trình một lần / ảnh)
_KHOA_MON_ANH = _thr_gui.Lock()
_MON_BO = ("necklace", "bracelet", "ring", "earrings")


def _f_mon_anh():
    return os.path.join(SCRIPT_DIR, "state", "chung", "mon_anh_sp.json")


def _so_mon_anh():
    try:
        mt = os.path.getmtime(_f_mon_anh())
    except OSError:
        return _MON_ANH["d"]
    if _MON_ANH["mt"] != mt:
        _MON_ANH["d"], _MON_ANH["mt"] = qht.load_json(_f_mon_anh(), {}), mt
    return _MON_ANH["d"]


def doc_mon_anh(u):
    """Đọc MÓN trong một ảnh sản phẩm bằng model — HAI lần, món nào cả hai lần đều thấy mới tính (24/09: đọc một lần nhầm
    nhẫn thành lắc ở ảnh "January" dùng chung 5 page) — rồi ghi sổ (đọc lại + gộp + đổi tên, 8 tiến trình dùng chung)."""
    try:
        b64 = _anh_nen(u)
        ds = [_hoi_anh_json(b64, _NHAC_MON_ANH, 260) for _ in range(2)]
    except Exception:                                  # noqa: BLE001 — ảnh hỏng thì thôi, lượt sau thử lại
        ds = []
    if len(ds) < 2 or not all(d and any(k in d for k in _MON_BO) for d in ds):
        _MON_ANH_DANG.discard(u)
        return None
    r = {"sp": all(bool(d.get("product")) for d in ds), "luc": int(time.time()), "doc": 2}
    for k in _MON_BO:
        so = []
        for d in ds:
            try:
                so.append(max(0, int(d.get(k) or 0)))
            except (TypeError, ValueError):
                so.append(0)
        r[k] = min(so)
        r[k + "_max"] = max(so)
    with _KHOA_MON_ANH:
        so_ = qht.load_json(_f_mon_anh(), {})
        so_[u] = r
        tam = f"{_f_mon_anh()}.tam{os.getpid()}"
        with open(tam, "w", encoding="utf-8") as fh:
            json.dump(so_, fh, ensure_ascii=False)
        os.replace(tam, _f_mon_anh())
    return r


def _anh_sp_kich_ban(kb_page):
    """Ảnh trong kịch bản page, trừ mẫu chuyển tiền / feedback (ảnh khách cũ có thể là hàng khác)."""
    ra = []
    for m in (kb_page or {}).get("mau") or []:
        ten = _ten_mau(m)
        if _MAU_ANH_TIEN.search(ten) or re.search(r"(?i)feed\s*back|review|\bfb\b|danh\s*gia|đánh\s*giá", ten):
            continue
        for u in m.get("anh") or []:
            if isinstance(u, str) and u not in ra:
                ra.append(u)
    return ra[:12]


def bo_theo_anh(kb_page, doc_bu=True):
    """Loại món thấy trong ẢNH BỘ của kịch bản (ảnh ≥2 loại, ≥3 món) → set; không phải page bộ trang sức / chưa đọc được ảnh
    nào → None.

    Ảnh chưa có trong sổ → đọc bù CHẠY NỀN (lượt sau có), lượt này dùng phần đã có."""
    if not _LA_BO_TS.search(_chu_kich_ban(kb_page)):
        return None
    so, thay, co = _so_mon_anh(), set(), False
    for u in _anh_sp_kich_ban(kb_page):
        r = so.get(u)
        if r is None:
            if doc_bu and u not in _MON_ANH_DANG and os.environ.get("AI_MON_ANH", "1").strip() != "0":
                _MON_ANH_DANG.add(u)
                _thr_gui.Thread(target=doc_mon_anh, args=(u,), daemon=True).start()
            continue
        co = True
        if max(r.get(k + "_max", r.get(k, 0)) for k in _MON_BO) > 3:
            continue                                   # tủ trưng bày / nhiều bộ một ảnh — không phải ảnh MỘT bộ
        ks = {k for k in _MON_BO if r.get(k)}
        # ≥3 món: 1 sợi dây chụp cận hay bị đếm thành dây chuyền + lắc (24/09, Golden Elegance Taiwan)
        if r.get("sp") and len(ks) >= 2 and sum(r.get(k + "_max", r.get(k, 0)) for k in ks) >= 3:
            thay |= ks
    return thay if co else None


_PHU_DINH_MON = re.compile(r"\b(?:walang|wala|wla|no|without|not|only|lang|lng|missing|kulang)\b", re.I)
# Khách hỏi bộ gồm gì mà không gọi tên món ("Anong kasama ng isang set", "what's included", "ilang piraso").
_HOI_BO_GOM = re.compile(
    r"\b(?:kasama|included?|includes|including|inclusions?|laman|come?s?\s+with|what'?s\s+in(?:side)?|what\s+is\s+in(?:side)?"
    r"|complete\s+set|kumpleto|(?:how\s+many|ilang?|ilan\s+ang)\s+(?:pieces?|pcs|piraso|items?))\b"
    r"|يشمل|كم\s+قطع|包含|幾件|几件", re.I | re.U)


def khach_hoi_bo_gom(msgs, kb_page, mkey=None, pid=None):
    """Chuỗi tin khách CHƯA được đáp hỏi bộ gồm gì / nhắc tên món, ở page bán BỘ mà ảnh bộ đã đọc được → chuỗi kể món; không → None."""
    if loai_ts_chinh(mkey, pid):
        return None
    chua = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            chua.append(lam_sach(m.get("text") or ""))
        elif m.get("boi") != "hethong":
            break
    t = " \n ".join(x for x in reversed(chua) if x.strip())
    if not t or len(t.split()) > 40:
        return None
    if not _HOI_BO_GOM.search(t):
        # nhắc tên món thì phải là hỏi có / không / nói thiếu món — hỏi size / giá / cân / độ dài, địa chỉ "ring road" thì thôi
        if (not any(rx.search(t) for rx in _LOAI_TS_RX.values())
                or not (_HOI_CO_KHONG.search(t) or _PHU_DINH_MON.search(t))
                or khach_hoi_kich_thuoc(t) or HOI_GIA.search(t) or _HOI_CAN.search(t) or _HOI_DO_DAI.search(t)
                or re.search(r"(?i)\bring\s+(?:road|rd)\b", t)):
            return None
    bo = bo_theo_anh(kb_page)
    if not bo or len(bo) < 2:
        return None
    return " · ".join(f"{k} ({_LOAI_TS_TEN.get(k, k)})" for k in _MON_BO if k in bo)


def bo_theo_anh_ngay(kb_page, toi_da=6):
    """BO_GOM_B_2609 — như bo_theo_anh nhưng ảnh bộ CHƯA đọc thì đọc NGAY (tối đa `toi_da` ảnh, mỗi ảnh 2 lượt model) thay vì chạy nền
    cho lượt sau (ca Densel Jhen 26/09: page mới, khách hỏi bộ gồm gì → treo oan)."""
    if not _LA_BO_TS.search(_chu_kich_ban(kb_page)) or os.environ.get("AI_MON_ANH", "1").strip() == "0":
        return bo_theo_anh(kb_page, doc_bu=False)
    so = _so_mon_anh()
    for u in [u for u in _anh_sp_kich_ban(kb_page) if u not in so][:toi_da]:
        if u in _MON_ANH_DANG:
            continue
        _MON_ANH_DANG.add(u)
        try:
            doc_mon_anh(u)
        finally:
            _MON_ANH_DANG.discard(u)
    return bo_theo_anh(kb_page, doc_bu=False)


def khach_hoi_thanh_phan_treo(msgs, kb_page, mkey=None, pid=None):
    """(câu khách, [loại kịch bản không nhắc]) khi khách hỏi bộ / hàng có kèm món X mà kịch bản + tin Botcake / sale KHÔNG nhắc
    X; không thì None. Chỉ tin khách CUỐI, ≤25 chữ."""
    if (msgs or [{}])[-1].get("boi") != "khach" or loai_ts_chinh(mkey, pid):
        return None
    _cuoi = (msgs or [{}])[-1]
    for _m in reversed(msgs or []):                  # BO_GOM_2609 — ảnh khách gửi SAU câu hỏi không xoá câu hỏi (ca Nimfs)
        if _m.get("boi") != "khach":
            break
        if lam_sach(_m.get("text") or "").strip():
            _cuoi = _m
            break
        if not _m.get("anh"):
            break
    t = lam_sach(_cuoi.get("text") or "")
    if not t.strip() or len(t.split()) > 25 or not _HOI_CO_KHONG.search(t) or _KE_CHUYEN_DON_CU.search(t):
        return None
    ks = sorted(k for k, rx in _LOAI_TS_RX.items() if rx.search(t))
    if not ks:
        return None
    nguon = _chu_kich_ban(kb_page) + "\n" + "\n".join(m.get("text") or "" for m in (msgs or [])
                                                      if m.get("boi") in ("botcake", "nguoi"))
    thieu = [k for k in ks if not _LOAI_TS_RX[k].search(nguon)]
    if thieu:
        try:                                         # 🧩 24/09 — món có trong ẢNH BỘ page đã gửi khách là có nguồn
            _bo = bo_theo_anh_ngay(kb_page) or set()   # BO_GOM_B_2609 — ảnh chưa đọc thì đọc ngay
            if len(_bo) >= 2:
                return None                          # chủ shop 26/09: có ảnh bộ → AI tự trả lời theo ảnh (cả "không có lắc"), không đợi sale
            thieu = [k for k in thieu if k not in _bo]
        except Exception:                            # noqa: BLE001 — đọc sổ hỏng thì treo như cũ
            pass
    return (t, thieu) if thieu else None


# 🧩 BO_GOM_2609 — AI NÓI BỘ CÓ MÓN MÀ ẢNH BỘ PAGE + KỊCH BẢN + TIN BOTCAKE / SALE KHÔNG CÓ (26/09, ca Nimfs Palmones · Lazurde
# Jewelry KSA — xem va_bo_gom). Tin AI cũ KHÔNG phải nguồn (câu sai tự lan: khách chụp lại câu AI gửi ngược vào). Câu có phủ định
# ("walang bracelet", "no bracelet") không tính.
_PHU_DINH_CAU = re.compile(r"(?i)\b(?:walang|wala|wla|hindi|no|not|without|except|doesn'?t|don'?t|isn'?t|aren'?t|separately"
                           r"|hiwalay|tidak|tanpa|bukan)\b|ليس|بدون|غير|不|沒|没")


# Món CỦA KHÁCH ("existing ring mo", "your bracelet") không phải món trong bộ; "ring" sau đại từ / trợ từ Tagalog là "rin" + ng
# ("pwede mo ring piliin" = cũng có thể chọn) — đo sổ 26/09: 3 câu Mario Jewelry bắt oan vì hai kiểu này.
_MON_CUA_KHACH_TRUOC = re.compile(r"(?i)\b(?:existing|own|your|yours|my)\s+(?:\w+\s+)?$")
_MON_CUA_KHACH_SAU = re.compile(r"(?i)^\s+(?:mo|niyo|ninyo|nyo|ko)\b")
_RING_TRO_TU = re.compile(r"(?i)\b(?:mo|ko|ka|po|nyo|niyo|ninyo|natin|namin|kami|tayo|kayo|sila|siya|ako|ikaw|ito|iyan|yan|pa|na"
                          r"|lang|lng|din|rin|naman|sana|kaya)\s+$")


def _mon_trong(t):
    """Loại món bộ nhắc trong câu (bỏ chữ 'earrings' trước khi dò 'ring'; bỏ món của khách, 'ring' = trợ từ Tagalog)."""
    ra = set()
    for k in _MON_BO:
        x = (t or "") if k != "ring" else _LOAI_TS_RX["earrings"].sub(" ", t or "")
        for mt in _LOAI_TS_RX[k].finditer(x):
            truoc, sau = x[max(0, mt.start() - 30):mt.start()], x[mt.end():mt.end() + 8]
            if (_MON_CUA_KHACH_TRUOC.search(truoc) or _MON_CUA_KHACH_SAU.search(sau)
                    or (k == "ring" and _RING_TRO_TU.search(truoc))):
                continue
            ra.add(k)
            break
    return ra


def bo_page_that(kb_page, msgs, mkey=None, pid=None):
    """(món bộ page theo ảnh, món có nguồn = ảnh + kịch bản + tin Botcake / sale) cho page BỘ đã đọc ảnh (≥2 loại); không → (None, None)."""
    if loai_ts_chinh(mkey, pid):
        return None, None
    bo = bo_theo_anh(kb_page, doc_bu=False)
    if not bo or len(bo) < 2:
        return None, None
    nguon = _chu_kich_ban(kb_page) + "\n" + "\n".join(m.get("text") or "" for m in (msgs or [])
                                                      if m.get("boi") in ("botcake", "nguoi"))
    return bo, set(bo) | _mon_trong(nguon)


def mon_bo_khong_nguon(tin, kb_page, msgs, mkey=None, pid=None):
    """Món câu AI nói CÓ (câu không phủ định) mà ảnh bộ page + kịch bản + tin Botcake / sale đều không có → list; không → []."""
    bo, co = bo_page_that(kb_page, msgs, mkey, pid)
    if not bo:
        return []
    sai = set()
    for cau in re.split(r"(?<=[.!?。！？])\s+|\n+", tin or ""):
        if cau.strip() and not _PHU_DINH_CAU.search(cau):
            sai |= _mon_trong(cau) - co
    return [k for k in _MON_BO if k in sai]


def anh_khach_mon_la(msgs, kb_page, mkey=None, pid=None):
    """Ảnh khách gửi (chưa được đáp) có món bộ page không có → (mô tả, [món lạ], [món bộ page]); không → None."""
    bo, co = bo_page_that(kb_page, msgs, mkey, pid)
    if not bo:
        return None
    for m in reversed(msgs or []):
        if m.get("boi") == "hethong":
            continue
        if m.get("boi") != "khach":
            break
        la = _mon_trong(m.get("mo_ta") or "") - co
        if la:
            return (m.get("mo_ta") or "")[:160], [k for k in _MON_BO if k in la], [k for k in _MON_BO if k in bo]
    return None


# Câu nhận ảnh khách là bộ của shop ("iyan nga po ang set", "that's the set") — cấm khi ảnh khách có món bộ page không có.
_XAC_NHAN_ANH_BO = re.compile(r"(?i)\b(?:iyan|yan|ito|eto|ganyan|ganito)\s+(?:nga\s+)?(?:po\s+)?(?:ang\s+)?(?:set|design)\b"
                              r"|\bthat'?s\s+(?:exactly\s+)?(?:the|our|it)\b|\bthis\s+is\s+(?:exactly\s+)?(?:the|our)\s+(?:set|design)\b")


def lenh_sua_bo_gom(bo, sai):
    """Lệnh sửa nhẹ câu AI kể bộ có món không có thật."""
    return (f"Our set (per the page's own product photos) contains ONLY: {', '.join(k for k in _MON_BO if k in bo)}. The draft "
            f"says the set includes / we have: {', '.join(sai)} — that is NOT true. Rewrite: remove that claim. Do NOT say the "
            "customer's photo is our set ('iyan nga ang set', 'that's the set') and do NOT answer yes/opo to having it — say kindly "
            "that our set includes only the real items. Keep everything else, same language, short, keep the final question.")


def sua_bo_gom_hop_le(t, kb_page, msgs, mkey=None, pid=None):
    """Bản sửa nhẹ dùng được: không còn món không nguồn, không nhận ảnh khách (có món lạ) là bộ của shop."""
    return (len(t or "") >= 15 and not mon_bo_khong_nguon(t, kb_page, msgs, mkey, pid)
            and not (_XAC_NHAN_ANH_BO.search(t) and anh_khach_mon_la(msgs, kb_page, mkey, pid)))


# 🏭 XUAT_XU_2609 — KHÁCH HỎI HÀNG SẢN XUẤT Ở NƯỚC NÀO (26/09, ca Edmon Alamis · Minty Fresh Smile KSA: AI "wala pong nakasaad sa info
# namin kung saang bansa ito ginawa" → khách "Thank you and goodbye"; giấy FDA page gửi khách ghi nhà máy ở Laguna, Philippines).
# "Shop ở nước nào / which country are you in" KHÔNG phải câu này (AI trả lời chuyện giao hàng là đúng).
_HOI_XUAT_XU = re.compile(
    r"(?i)\bmade\s+in\b|\bmade\s+(?:from|by|in)\s+(?:which|what)\b|\bwhere\s+(?:is|was)\s+(?:it|this|this\s+product|the\s+product)\s+"
    r"(?:made|manufactur\w*|produced|from)\b|\bwhere\s+made\b|\bfrom\s+where\s+(?:is\s+)?(?:it|this)\s+made\b|\bfrom\s+which\s+country\b"
    r"|\b(?:which|what)\s+country\s+(?:made|products?|manufactur\w*|brand|origin)\b"
    r"|\b(?:which|what)\s+country\b[^?.!]{0,25}\b(?:made|came\s+from|come\s+from|comes\s+from|manufactur\w*)\b"
    r"|\bcountry\s+of\s+origin\b|\borigin\s+of\s+(?:the\s+|this\s+)?product\b|\bsaan\s+(?:po\s+)?(?:ba\s+)?(?:gawa|ginawa|galing)\b"
    r"|\bsaang\s+bansa\b|\bgawa\s+(?:po\s+)?(?:ba\s+)?(?:saan|sa\s+(?:china|korea|japan|pinas|philippines|usa|thailand|vietnam))\b"
    r"|\bbuatan\s+(?:mana|negara)\b|\bproduk\s+(?:dari\s+)?(?:mana|negara\s+mana)\b|صنع\s+في|صناعة\s+(?:وين|اين|أين|اي)|بلد\s+المنشأ"
    r"|المنشأ|哪[裡里国國]製|產地|产地|कहाँ\s+का\s+बना|کہاں\s+کا\s+بنا")
_NUOC_XX = (r"philippines|south\s+korea|korea|japan|china|usa|united\s+states|thailand|malaysia|vietnam|taiwan|india|germany|france|italy"
            r"|turkey|indonesia|saudi\s+arabia|uae|switzerland|singapore|australia|spain|united\s+kingdom|england|canada|pakistan")
_XX_CHU = re.compile(r"(?i)\b(?:made\s+in|product\s+of|manufactured\s+in|country\s+of\s+origin\s*[:：]?)\s*(" + _NUOC_XX + r")\b"
                     r"|\b(?:\d{2}\s*k\s+)?(saudi|dubai)\s+gold\b")
_NHAC_XUAT_XU = ("Read this product document / label photo. Where is the product MANUFACTURED? Look for 'Made in', 'Product of', "
                 "'Manufacturer Address', 'Manufactured by', 'Country of origin'. Do NOT infer it from the language, the FDA agency's "
                 "country, the brand, the distributor or the importer. Reply ONLY JSON: {\"nuoc\": \"<country in English>\" or null, "
                 "\"bang_chung\": \"<the exact words from the image that show it, max 120 chars>\"}")
_KHOA_XX = _thr_gui.Lock()
# Bằng chứng phải NÓI RÕ là nơi sản xuất — địa chỉ công ty / nhà phân phối trơn ("EXPOSE VIETNAM CO., LTD Add: … Vietnam", đo 26/09 ở
# Nature's Daily Care) không tính: chưa chắc là nhà máy.
_XX_BC = re.compile(r"(?i)made\s+in|manufactur|product\s+of|country\s+of\s+(?:origin|manufacture)|produced\s+(?:in|by)|xuất\s+xứ|sản\s+xuất"
                    r"|صنع|المنشأ|製造|产地|產地")


def _f_xuat_xu_anh():
    return os.path.join(SCRIPT_DIR, "state", "chung", "xuat_xu_anh.json")


def doc_xuat_xu_anh(u):
    """Nước SẢN XUẤT ghi trong ảnh giấy tờ / nhãn (model, mỗi ảnh 1 lần, ghi sổ) → {'nuoc', 'bc'}; nuoc None = ảnh không ghi."""
    so = qht.load_json(_f_xuat_xu_anh(), {})
    if u in so:
        return so[u]
    try:
        d = _hoi_anh_json(_anh_nen(u), _NHAC_XUAT_XU, 200) or {}
    except Exception:                                  # noqa: BLE001 — đọc hỏng thì lượt sau thử lại
        return None
    if not d:
        return None
    nuoc, bc = d.get("nuoc") or None, str(d.get("bang_chung") or "")[:160]
    if nuoc and not re.search(re.escape(str(nuoc).split()[-1]), bc, re.I):
        nuoc = None                                    # bằng chứng không chứa tên nước → không tin
    r = {"nuoc": nuoc, "bc": bc if nuoc else "", "luc": int(time.time())}
    with _KHOA_XX:
        so = qht.load_json(_f_xuat_xu_anh(), {})
        so[u] = r
        tam = f"{_f_xuat_xu_anh()}.tam{os.getpid()}"
        with open(tam, "w", encoding="utf-8") as fh:
            json.dump(so, fh, ensure_ascii=False)
        os.replace(tam, _f_xuat_xu_anh())
    return r


# XUAT_XU_B_2609 — LUẬT XUẤT XỨ CHỦ SHOP 26/09: dược mỹ phẩm = Hàn Quốc, trang sức = Saudi; khách vặn giấy tờ / chữ nước khác → "bên em
# có nhà máy sản xuất ở đó". Phân loại theo tên page + chữ kịch bản (đo 260 page: 101 trang sức, 127 mỹ phẩm, 32 khác — lọc tay phần lẫn).
_XX_TS = re.compile(r"(?i)\b(?:18\s*k|21\s*k|22\s*k|24\s*k|karat|jewel\w*|necklaces?|bracelets?|earrings?|rings?|pendants?|bangles?"
                    r"|anklets?|saudi\s+gold|gold\s+sets?|birthstones?|kwintas|hikaw|singsing)\b|ذهب|مجوهرات|金飾|首飾|項鍊|手鍊")
_XX_VANG_THAT = re.compile(r"(?i)\b(?:18\s*k|21\s*k|22\s*k|24\s*k|karat|750|saudi\s+gold|dubai\s+gold)\b|ذهب\s+(?:عيار|سعودي)|18K金")
_XX_MP = re.compile(r"(?i)\b(?:skin\w*|creams?|serum|lotion|toothpaste|teeth|tooth|whiten\w*|gel|oil|shampoo|conditioner|hair|scalp|tea"
                    r"|capsules?|supplements?|feminine|wash|soap|collagen|acne|pimples?|melasma|dark\s+spots?|wrinkles?|masks?|balm|drops"
                    r"|eyes?|vision|slim\w*|detox|herbal|cosmetic\w*|beauty|spray|patch(?:es)?|ointment|varicose|veins?|joints?|bust"
                    r"|breast|womb|menstrual|cramps?|gums?|breath|enamel|moisturi\w*|sunscreen|whitening|rejuven\w*|denture\w*|oral"
                    r"|derma\w*|glow|ginseng|ginger|wart|gout|nail|make\s*up|lip)\b")
_XX_KHAC = re.compile(r"(?i)\b(?:glasses|eyeglass\w*|bra|lifting\s+bra|perfume|dior|home|mall|hub|gallery|keychain|binder|feng\s*shui"
                      r"|fengshui|buddha|pixiu|rosary|coins?|mystic|master|blessings?|prosperity|fortune|jade|shoes?|stride|vault"
                      r"|savings)\b")
_XX_TEN_NUOC = (("South Korea", re.compile(r"(?i)\bkorea\w*\b")), ("Japan", re.compile(r"(?i)\bjapan\w*\b")))


# XUAT_XU_C_2609 — chủ shop 26/09: "thương hiệu quần áo thì ở nhật" — page bán ĐỒ MẶC (áo ngực nâng, đồ lót, định hình, gen, legging).
_XX_QA = re.compile(r"(?i)\b(?:bras?|lifting\s+bra|brassiere|shapewear|lingerie|underwear|panty|panties|corset|girdle|waist\s*trainer"
                    r"|body\s*suit|leggings?)\b|حمالة\s+صدر|ملابس\s+داخلية|內衣|塑身")


def loai_xuat_xu(kb_page, mkey=None):
    """(nước, căn cứ) theo LUẬT chủ shop 26/09; page không thuộc nhóm nào → None."""
    ten = str((kb_page or {}).get("ten_page") or "")
    s = _chu_kich_ban(kb_page) + "\n" + ten
    ts, mp = len({x.lower() for x in _XX_TS.findall(s)}), len({x.lower() for x in _XX_MP.findall(s)})
    if _XX_QA.search(s):                               # XUAT_XU_C_2609 — đồ mặc: đứng trước trang sức / mỹ phẩm
        return "Japan", "luật chủ shop 26/09: thương hiệu quần áo = sản xuất tại Nhật Bản"
    if mkey != "usa" and not _XX_KHAC.search(ten) and ((ts >= 2 and ts >= mp and _XX_VANG_THAT.search(s))
                                                       or re.search(r"(?i)\b(?:jewel\w*|gold)\b", ten)):
        return "Saudi Arabia", "luật chủ shop 26/09: trang sức = sản xuất tại Saudi"   # kịch bản mỏng thì theo tên page vàng
    if _XX_KHAC.search(ten) or (ts >= 2 and ts >= mp):
        return None                                    # kính / áo ngực / nước hoa / tạp hoá / phong thủy / trang sức mạ — để sale
    for nuoc, rx in _XX_TEN_NUOC:
        if rx.search(ten):
            return nuoc, f"tên page «{ten}»"
    if mp >= 2 or _XX_MP.search(ten):
        return "South Korea", "luật chủ shop 26/09: dược mỹ phẩm = sản xuất tại Hàn Quốc"
    return None


_NOI_KH_NHAC = (("Philippines", r"philippines?|pinas|pilipinas|filipino|tagalog"), ("Vietnam", r"vietnam\w*|viet\s*nam"),
                ("China", r"china|chinese|chaina"), ("Thailand", r"thai\w*"), ("Japan", r"japan\w*"), ("South Korea", r"korea\w*"),
                ("Indonesia", r"indonesia\w*|indo"), ("Malaysia", r"malaysia\w*"), ("India", r"india\w*|hindi"),
                ("USA", r"usa|america\w*"), ("Turkey", r"turkey|turkish"), ("Saudi Arabia", r"saudi\w*|ksa"),
                ("UAE", r"uae|dubai|emirates?"), ("Taiwan", r"taiwan\w*"))
_VAN_XX = re.compile(r"(?i)\b(?:fda|label|box|packag\w*|certificate|cert|sticker|nakasulat|nakalagay|written|writing|letters?|sulat|code"
                     r"|barcode|why|bakit|bat|pero|but|sabi|says|said|however|made\s+in|gawa)\b|تغليف|مكتوب|ليش|ليه|لماذا")
_AI_NOI_XX = re.compile(r"(?i)made\s+in|manufactur\w*|factory|gawa\s+(?:sa|ng)|galing\s+(?:sa|ng)|ginawa\s+sa|produced\s+in|sản\s+xuất"
                        r"|صنع|مصنع|製造")


def khach_van_xuat_xu(msgs, kb_page=None, mkey=None):
    """Khách vặn "giấy tờ / chữ trên hộp là nước khác" sau khi page đã nói nơi sản xuất → (câu khách, nơi khách nhắc); không → None."""
    if not any(m.get("boi") in ("ai", "nguoi", "botcake") and _AI_NOI_XX.search(m.get("text") or "") for m in (msgs or [])[-10:]):
        return None
    da_noi = (loai_xuat_xu(kb_page, mkey) or (None,))[0]
    for t in _khach_sau_tin_shop(msgs, 2):
        if not _VAN_XX.search(t):
            continue
        for nuoc, rx in _NOI_KH_NHAC:
            if re.search(r"(?i)\b(?:" + rx + r")\b", t) and nuoc != da_noi:
                return t[:140], nuoc
    return None


def xuat_xu_page(kb_page, mkey=None, pid=None, doc=True):
    """(nước, bằng chứng) nơi SẢN XUẤT theo chữ kịch bản, không có thì theo ảnh GIẤY TỜ page; không nguồn → None."""
    lx = loai_xuat_xu(kb_page, mkey)                   # XUAT_XU_B_2609 — luật chủ shop 26/09 đứng trước giấy tờ
    if lx:
        return lx
    m = _XX_CHU.search(_chu_kich_ban(kb_page))
    if m:
        if m.group(1):
            return m.group(1).title(), m.group(0)
        return ("Saudi Arabia" if m.group(2).lower() == "saudi" else "UAE (Dubai)"), m.group(0)
    so = None if doc else qht.load_json(_f_xuat_xu_anh(), {})
    for u in anh_chung_nhan(kb_page, 3, mkey, pid):
        r = doc_xuat_xu_anh(u) if doc else so.get(u)
        if r and r.get("nuoc") and _XX_BC.search(r.get("bc") or ""):
            return r["nuoc"], r["bc"]
    return None


def khach_hoi_xuat_xu(msgs):
    """Câu khách (chưa được đáp) hỏi hàng SẢN XUẤT ở nước nào → câu đó; không thì ""."""
    return next((t for t in _khach_sau_tin_shop(msgs, 2) if _HOI_XUAT_XU.search(t)), "")


def khach_hoi_thong_so(t):
    """Khách đang hỏi thông số vật lý của HÀNG (gram / độ dài / size hàng)?"""
    t0 = lam_sach(t or "")
    if _CAN_CUA_KHACH.search(t0):
        return False
    return bool(HOI_THONG_SO.search(t0))


# ─────────── KHÁCH Ở THỊ TRƯỜNG KHÁC PAGE (luật mục 3 — chủ shop 20/09, ca Cel Boongaling) ───────────
#
# Page Key Jewelry Saudi, khách "Doha Qatar po ako", page đã nói "we only delivery saudi" và hỏi "do you
# have saudi address" → khách "No". AI vẫn nhắn "Kahit sa Qatar po kayo, pwede pa rin — libre ang
# shipping", rồi lượt sau xin luôn "Ano pong complete address ninyo sa Doha?". Mục 3 của LUAT_AI_SALE
# cấm đúng chuyện này: page thuộc thị trường nào thì bán giá + giao thị trường đó; khách xác nhận ở
# nước khác → TREO + ghi chú cho sale, để sale quyết chuyện chuyển shop. Luật này trước nay chỉ nằm
# trong chữ cho model đọc, không có cổng máy — nên model bỏ qua được.
#
# Đo 20/09 trên 488 tin khách thật (6 thị trường, API): bắt 0 ca oan; bộ 12 câu mẫu đúng 12/12.
NUOC_TP = {
    "uae": r"\buae\b|united\s+arab|dubai|abu\s*dhabi|sharjah|ajman|fujairah|ras\s*al\s*khaimah|umm\s*al\s*quwain|\bemirates?\b"
           r"|\bab+[ou]+\s*d+h?a+b+[iy]\b|\bal[\s-]+ain\b",        # 23/09: "Abodhabi"/"Abudabi" (ca Emilyrose); "alain" liền = tên người
    "saudi": r"\bksa\b|\bsaudi\b|riyadh|jeddah|dammam|khobar|makkah|\bmecca\b|madinah|\bmedina\b|tabuk|\babha\b|jizan|yanbu"
             r"|jubail|\bta'?if\b|\bqa(?:s|ss|ee)im\b|\bburaid?y?ah\b|khamis\s*mushai?t|\bhofuf\b|al\s*ahsa|\bnajran\b"
             r"|hafr\s*al\s*batin|\bjedda\b|\bmekkah?\b",           # 23/09: thành phố còn thiếu (đo kho cũ: "Jubail")
    "qatar": r"\bqatar\b|\bdoha\b|al\s*wakrah|al\s*rayyan|\blusail\b",
    "kuwait": r"\bkuwait\b|salmiya|hawally|farwaniya|\bjahra\b|fahaheel|mangaf|mahboula",
    "oman": r"\boman\b|muscat|salalah|\bsohar\b|\bnizwa\b|\bseeb\b",
    "bahrain": r"\bbahrain\b|manama|\briffa\b|muharraq|isa\s*town|hamad\s*town",
    "taiwan": r"\btaiwan\b|taipei|kaohsiung|taichung|tainan",
    "japan": r"\bjapan\b|tokyo|osaka|nagoya|kyoto",
    "usa": r"\busa\b|united\s+states|\bamerica\b|new\s+york|california|texas|florida",
    "philippines": r"philippines?|pilipinas|\bpinas\b|manila|\bcebu\b|davao|zamboanga|baguio|cavite|bulacan|pampanga|iloilo|batangas|quezon\s+city",
}
# Tên nước nằm trong TÊN HÀNG ("18K Saudi Gold"), không phải nơi ở của khách.
_TEN_HANG_NUOC = re.compile(
    r"saudi\s+gold|18\s*k\s+saudi|pure\s+saudi|gold\s+saudi|japan\w*\s+(?:bra|lifting|technology)", re.I)
# Khách tự nói nơi ở CỦA MÌNH.
_TOI_DANG_O = re.compile(
    r"\b(?:i'?m|i\s+am|im)\s+(?:here\s+)?(?:in|at|from)\b"
    r"|\bi\s+(?:live|stay|staying|living|reside|work|working)\s+(?:in|at|here\s+in)\b"
    r"|\bmy\s+(?:address|location|place)\s+(?:is\s+)?(?:in|at)\b|\bbased\s+in\b|\bcurrently\s+in\b"
    r"|\bnasa\b|\bnandito\b|\bandito\b|\bdito\s+sa\b|\btaga\b|\bpo\s+ako\b|\bako\s+po\b|\bnakatira\b"
    r"|أنا\s+في|عندي\s+عنوان", re.I | re.U)
# Người KHÁC ở nước đó ("nasa Philippines ang nanay ko") — khách vẫn ở nước của page.
_NGUOI_KHAC_O = re.compile(
    r"\b(?:my|aking|akin|ang)\s+(?:mother|mom|nanay|inay|father|dad|tatay|sister|ate|brother|kuya|kapatid"
    r"|wife|asawa|husband|son|anak|daughter|friend|kaibigan|family|pamilya|cousin|pinsan|auntie|tita|tito)\b"
    r"|\b(?:nanay|tatay|asawa|anak|kapatid|pinsan|tita|tito|kaibigan)\s+ko\b", re.I)
# Chuyện sẽ xảy ra / đã qua, không phải nơi ở bây giờ ("babalik ako sa Pinas next month").
# Thêm QUÀ MANG VỀ: "Sa akin at pasalubong sa Pinas" (ca Gold Charm Bracelet US) — khách vẫn đang ở
# nước của page, chỉ mua để xách về. Khác hẳn "padala sa Pinas" (nhờ GỬI sang đó) — câu đó vẫn treo.
_KHONG_PHAI_BAY_GIO = re.compile(
    r"\b(?:babalik|uuwi|pauwi|going\s+back|will\s+be\s+back|next\s+month|next\s+week|bukas|vacation|bakasyon"
    r"|when\s+i\s+(?:go|return|come)|balak|plano|soon|last\s+year|noon|dati"
    r"|pasalubong|regalo|souvenir|take\s+home|bring\s+home|dalhin)\b", re.I)
# Câu HỎI — kể cả Tagalog không dấu "?" ("Pilipinas LNG po ba yan mam" là hỏi, không phải khai nơi ở).
_LA_HOI_NUOC = re.compile(
    r"\?|\bba\b|\bmay(?:roon|ron|on)?\b|\bmeron\b|\bpwede\b|\bsaan\b|\bano\b|\bkailan\b|\bpaano\b|\bmagkano\b"
    r"|\b(?:do|does|did|is|are|can|could|would|will|have|has)\s+(?:you|u|it|they|i|we)\b"
    r"|\bhow\b|\bwhat\b|\bwhere\b|\bwhen\b|هل|كم|أين", re.I | re.U)
# Page vừa hỏi "có địa chỉ <nước mình> không / bạn đang ở đâu", khách đáp KHÔNG.
_PAGE_HOI_NOI_O = re.compile(
    r"(?:do\s+you\s+have|may|meron|mayroon)\b[^?]{0,40}\b(?:address|adres)\b"
    r"|\bare\s+you\s+(?:in|currently\s+in|based\s+in|living\s+in)\b|\bnasa\b[^?]{0,20}\bpo\s+ba\s+kayo\b"
    r"|\bsaan\s+(?:po\s+)?kayo\b|\bwhich\s+(?:city|emirate|area)\b", re.I | re.U)
_KHACH_DAP_KHONG = re.compile(
    r"^\s*(?:no+|nope|nah|wala|wala\s+po|hindi|hindi\s+po|di\s+po|walang|not\s+yet|none|لا)\s*[.!]?\s*$",
    re.I | re.U)


# NƯỚC SHOP KHÔNG KINH DOANH (chủ shop 2026-09-21, ca Melah M Enalang · DOC Alipion-Tooth ARMOR KSA).
# Khách "sa pinas po mag order" trên page Saudi → ghi chú cũ bảo sale "kiểm kho PHILIPPINES đã có mã SP
# này chưa". Chủ shop: *"ở philipines là từ chối khách mà, báo chúng tôi chỉ giao ở ả rập xê út; trường
# hợp báo sale check kho khác là các kho hiện tôi kinh doanh chứ, tôi có kinh doanh ở philipines đâu"*.
# → Nước CÓ trong markets.json (Qatar, UAE…): treo cho sale như cũ — sale quyết chuyển shop.
#   Nước KHÔNG có (Philippines…): không kho, không shop, không ai chuyển đi đâu được → AI TỪ CHỐI ngay
#   trong chat ("bên mình chỉ giao trong <nước page>"), không treo, không làm phiền sale. Vẫn cấm lên đơn.
def thi_truong_cua_minh(k):
    """Nước này shop có kinh doanh không — markets.json là danh sách DUY NHẤT."""
    return bool(k) and k != "khong_ro" and k in (HS._markets() or {})


# Tên nước để NÓI VỚI KHÁCH (markets.json chỉ có tên tiếng Việt: "MỸ", "ĐÀI LOAN"…).
TEN_NUOC_KHACH = {
    "uae": "the UAE", "saudi": "Saudi Arabia", "kuwait": "Kuwait", "qatar": "Qatar", "oman": "Oman",
    "bahrain": "Bahrain", "taiwan": "Taiwan", "japan": "Japan", "usa": "the USA", "spain": "Spain",
    "romania": "Romania", "bulgaria": "Bulgaria", "philippines": "the Philippines",
}
# Câu từ chối phải GỌI TÊN nước mình giao — mà khách Ả Rập / Đài / Nhật viết tên nước bằng chữ của họ,
# NUOC_TP chỉ có chữ Latin. Bảng này để kiểm câu model soạn đã nói rõ nơi giao hay chưa.
TEN_NUOC_BAN_DIA = {
    "uae": r"الامارات|الإمارات|امارات|دبي|أبوظبي|ابوظبي|الشارقة",
    "saudi": r"السعودي|السعودية|السعوديه|المملكة|الرياض|جدة|جده|الدمام",
    "kuwait": r"الكويت", "qatar": r"قطر|الدوحة|الدوحه", "oman": r"عمان|عُمان|مسقط",
    "bahrain": r"البحرين|المنامة", "taiwan": r"台灣|台湾", "japan": r"日本",
    "spain": r"España|Espana", "romania": r"România", "bulgaria": r"България",
}


def noi_ro_noi_giao(tin, mkey):
    """Câu soạn cho khách CÓ gọi tên nước của page không (chữ Latin hay chữ bản địa)?"""
    t = lam_sach(tin or "")
    if not t:
        return False
    return bool((NUOC_TP.get(mkey) and re.search(NUOC_TP[mkey], t, re.I))
                or (TEN_NUOC_BAN_DIA.get(mkey) and re.search(TEN_NUOC_BAN_DIA[mkey], t, re.I | re.U)))


# CÂU CHỦ SHOP ĐƯA (23/09): "chúng tôi đang kinh doanh hoạt động tại UAE, bạn có địa chỉ nhà ở UAE không?". Page ĐÃ hỏi
# câu đó mà khách vẫn không có địa chỉ ở nước page → xin lỗi ngắn, KHÔNG hỏi lại (hỏi lại = nhắn lặp).
def cau_ngoai_tt(mkey, da_hoi=False):
    pg = TEN_NUOC_KHACH.get(mkey) or str(mkey).upper()
    if da_hoi:
        return f"Sorry, we currently operate only in {pg} and can only deliver to an address in {pg}."
    return f"We currently operate in {pg}. Do you have a home address in {pg}?"


# 24/09 (ca Omapas E. Lyn'skie · DOC Alipion-Tooth ARMOR KSA): nhận ra page ĐÃ nói câu TỪ CHỐI ("Sorry, we currently operate only
# in X…" — dịch sang tiếng khách) để lượt sau không ép lặp lại đúng câu đó (trùng → cổng nhan_lap chặn → khách không nhận gì).
_XIN_LOI_TC = re.compile(r"\b(?:sorry|pasensya|paumanhin|patawad|maaf|apologi[sz]e)\b|عذر|آسف|معذرت|দুঃখিত|माफ|क्षमा|抱歉|對不起|对不起"
                         r"|すみません|申し訳", re.I | re.U)


def da_tu_choi_ngoai_tt(msgs, mkey):
    """Trong 8 tin page gần nhất có câu xin lỗi + nói rõ chỉ giao ở nước page (câu TỪ CHỐI đã gửi) → True."""
    n = 0
    for m in reversed(msgs or []):
        if m.get("boi") not in ("ai", "nguoi", "botcake"):
            continue
        t = lam_sach(m.get("text") or "")
        if not t:
            continue
        n += 1
        if n > 8:
            break
        if _XIN_LOI_TC.search(t) and noi_ro_noi_giao(t, mkey):
            return True
    return False


def da_hoi_dia_chi_page(msgs, mkey):
    """Phía page (AI/sale/Botcake) đã hỏi khách câu có tên nước page + dấu hỏi trong 8 tin gần nhất chưa."""
    for m in (msgs or [])[-8:]:
        if m.get("boi") in ("ai", "nguoi", "botcake"):
            t = lam_sach(m.get("text") or "")
            if noi_ro_noi_giao(t, mkey) and re.search(r"[?؟？]", t):
                return True
    return False


def dong_ngoai_thi_truong(nuoc_kh, cau_kh, mkey, da_hoi=False):
    """Khối nhắc cho prompt: khách muốn nhận hàng ở nước shop không bán → từ chối thẳng, lịch sự."""
    kh = TEN_NUOC_KHACH.get(nuoc_kh) or str(nuoc_kh).upper()
    pg = TEN_NUOC_KHACH.get(mkey) or str(mkey).upper()
    if da_hoi:
        return (f'🌍 KHÁCH KHÔNG Ở {pg.upper()} ("{cau_kh}") và page ĐÃ hỏi khách có địa chỉ nhà ở {pg} không. ⛔ CẤM hỏi '
                f'lại câu đó. ✅ VIẾT ĐÚNG câu này, dịch sang tiếng khách, không thêm gì: "{cau_ngoai_tt(mkey, True)}" '
                f'⛔ CẤM hứa giao / ship quốc tế / hứa hỏi lại team, ⛔ CẤM báo giá, ⛔ CẤM chào hàng, ⛔ CẤM lên đơn.')
    if str(cau_kh or "").startswith("SĐT "):
        return (f'🌍 {cau_kh} — khách CHƯA cho địa chỉ nào ở {pg}. Shop CHỈ giao trong {pg}, không kinh doanh ở '
                f'{kh}. CHƯA được chốt: viết ĐÚNG hai câu này, dịch sang tiếng khách, không thêm gì: '
                f'"{cau_ngoai_tt(mkey)}" ⛔ CẤM nói đã nhận/xác nhận địa chỉ hay đơn, ⛔ CẤM hẹn ngày giao, '
                f'⛔ CẤM nói shipper sẽ gọi, ⛔ CẤM lên đơn — cho tới khi khách nói đang ở {pg}.')
    return (f'🌍 KHÁCH MUỐN NHẬN HÀNG Ở {re.sub(r"^the ", "", kh, flags=re.I).upper()}: "{cau_kh}" — shop KHÔNG kinh doanh ở nước đó: không '
            f'kho, không shop, không hãng giao nào đi tới. Đơn đó KHÔNG BAO GIỜ giao được. ÁP LUẬT TỪ CHỐI: '
            f'nói THẲNG và lịch sự bằng tiếng khách, 1-2 câu: bên mình CHỈ giao trong {pg}, không ship sang '
            f'{kh}. ✅ VIẾT ĐÚNG HAI CÂU NÀY, dịch sang tiếng khách, không thêm gì: "{cau_ngoai_tt(mkey)}" ⛔ CẤM hứa giao / hứa ship quốc tế / hứa hỏi lại team, ⛔ CẤM xin địa '
            f'chỉ hay SĐT ở {kh}, ⛔ CẤM báo giá tiếp, ⛔ CẤM chào hàng thêm, ⛔ CẤM lên đơn.')


# Khách LỠ nhắc nước khác rồi tin SAU lại nói đang ở đúng nước của page: cửa dưới xét 6 tin khách gần
# nhất nên câu cũ còn chặn đơn thêm vài lượt. Tin mới hơn nói đúng nước page thì câu cũ hết hiệu lực.
def khach_o_dung_thi_truong(text, mkey):
    """Khách nói rõ mình đang ở ĐÚNG nước của page (hoặc cho địa chỉ ở đó)?"""
    rx = NUOC_TP.get(mkey)
    t = _TEN_HANG_NUOC.sub(" ", lam_sach(text or ""))
    if not rx or not t.strip() or _NGUOI_KHAC_O.search(t) or _KHONG_PHAI_BAY_GIO.search(t) or _LA_HOI_NUOC.search(t):
        return False
    m = re.search(rx, t, re.I)
    if not m:
        return False
    return bool(_TOI_DANG_O.search(t[max(0, m.start() - 80):m.end() + 80])
                or len(t.strip()) <= 40 or HS.TU_DIA_CHI.search(t))


# ══ CHỈ BÁN Ở NƯỚC SHOP KINH DOANH (chủ shop 23/09, ca Faruk Shaik · Kreain Nature Saudi) ══
# Khách Bangladesh cho SĐT "01873890974" + địa chỉ chữ Bengali "থানা কালিয়াপুর, জেলা গাজীপুর" (huyện/tỉnh Gazipur).
# Máy chỉ biết tên 11 nước mình + Philippines, bằng chữ Latin → không thấy gì; model tự biết "khách ở Bangladesh,
# ngoài thị trường" (ghi vào ghi_chu 4 lượt liền) mà vẫn gửi "địa chỉ đã xác nhận, shipper sẽ gọi", "giao 3-7 ngày".
# Chủ shop: *"tôi đã dặn là chỉ bán ở các nước tôi đang kinh doanh"*. Sổ việc 8 nước: model tự ghi "khách ở <nước
# lạ>, không giao được" ~55 lượt (Bangladesh, Ấn Độ, Pakistan, Nepal, Indonesia, Hungary…) — máy không nghe lần nào.
# → Bốn đường vào cùng một cửa từ chối (khach_khac_thi_truong + cổng vòng gửi):
#   (1) tên nước lạ (Latin + chữ bản địa) kèm lời "tôi đang ở / gửi tới";
#   (2) KHUÔN ĐỊA CHỈ chỉ nước ngoài mới có (থানা/জেলা, kecamatan/desa, tehsil…);
#   (3) SĐT nước lạ mà khách CHƯA cho địa chỉ nào trong nước page (số Philippines không tính — OFW dùng nhiều);
#   (4) lưới cuối: ghi_chu/ly_do của CHÍNH model nói khách ở nước lạ / ngoài thị trường.
NUOC_NGOAI_TP = {
    "bangladesh": r"bangladesh(?!i)|\bdhaka\b|chittagong|chattogram|\bsylhet\b|comilla|cumilla|gazipur|narayanganj|rajshahi"
                  r"|\bkhulna\b|barisal|barishal|\brangpur\b|mymensingh|noakhali|বাংলাদেশ(?![ীি])|ঢাকা|চট্টগ্রাম|সিলেট|কুমিল্লা"
                  r"|গাজীপুর|নারায়ণগঞ্জ|রাজশাহী|খুলনা|বরিশাল|রংপুর|ময়মনসিংহ|নোয়াখালী",
    "india": r"\bindia\b|\bkerala\b|mumbai|\bdelhi\b|chennai|hyderabad|bangalore|bengaluru|kolkata|tamil\s*nadu|भारत|इंडिया"
             r"|ഇന്ത്യ|കേരള",
    "pakistan": r"pakistan(?!i)|karachi|lahore|islamabad|peshawar|rawalpindi|پاکستان",
    "nepal": r"\bnepal\b|kathmandu|नेपाल",
    "sri_lanka": r"sri\s*lanka|\bcolombo\b|ශ්‍රී\s*ලංකා",
    "indonesia": r"indonesia(?!n)|\bindo\b|jakarta|surabaya|bandung|\bjawa\s+(?:barat|tengah|timur)|sumatera|sumatra|\blombok\b",
    "egypt": r"\begypt\b|\bcairo\b|\bمصر\b|\bالقاهرة\b",
    "yemen": r"\byemen\b|\bsana'?a\b|\bاليمن\b|\bصنعاء\b",
    "sudan": r"\bsudan\b|khartoum|\bالسودان\b",
    "jordan": r"\bjordan\b|\bamman\b|\bالأردن\b|\bالاردن\b",
    "ethiopia": r"ethiopia(?!n)|addis\s*ababa",
    "kenya": r"\bkenya\b|nairobi|mombasa",
    "uganda": r"\buganda\b|kampala",
    "nigeria": r"nigeria(?!n)|\blagos\b",
    "ghana": r"\bghana\b|\baccra\b",
    "morocco": r"morocco|casablanca",          # KHÔNG "المغرب" — cũng là giờ cầu Maghrib
    "malaysia": r"malaysia(?!n)|kuala\s*lumpur",
    "singapore": r"singapore",
    "hong_kong": r"hong\s*kong",
    "vietnam": r"vietnam(?!ese)|viet\s+nam",
    "uk": r"united\s+kingdom|\blondon\b|\bengland\b",
    "canada": r"\bcanada\b|toronto|vancouver",
    "hungary": r"hungary|budapest",
}
TEN_NUOC_KHACH.update({
    "bangladesh": "Bangladesh", "india": "India", "pakistan": "Pakistan", "nepal": "Nepal", "sri_lanka": "Sri Lanka",
    "indonesia": "Indonesia", "egypt": "Egypt", "yemen": "Yemen", "sudan": "Sudan", "jordan": "Jordan",
    "ethiopia": "Ethiopia", "kenya": "Kenya", "uganda": "Uganda", "nigeria": "Nigeria", "ghana": "Ghana",
    "morocco": "Morocco", "malaysia": "Malaysia", "singapore": "Singapore", "hong_kong": "Hong Kong",
    "vietnam": "Vietnam", "uk": "the UK", "canada": "Canada", "hungary": "Hungary",
    "ngoai_khong_ro": "that country",
})
# Tên nước page bằng chữ Bengali / Hindi / Urdu — câu từ chối model viết bằng tiếng khách ("আমরা শুধু সৌদি আরবের
# ভিতরেই ডেলিভারি করি") phải được noi_ro_noi_giao nhận ra, không thì cửa bắt sửa mãi rồi treo.
for _k_, _rx_ in {
    "saudi": r"সৌদি|सऊदी|سعودی", "uae": r"আমিরাত|দুবাই|आमिरात|दुबई|امارات", "kuwait": r"কুয়েত|কুয়েত|कुवैत|کویت",
    "qatar": r"কাতার|कतर", "oman": r"ওমান|ओमान", "bahrain": r"বাহরাইন|बहरीन|بحرین",
}.items():
    TEN_NUOC_BAN_DIA[_k_] = (TEN_NUOC_BAN_DIA.get(_k_) + "|" + _rx_) if TEN_NUOC_BAN_DIA.get(_k_) else _rx_
# "Tôi đang ở / gửi tới" cho các nước lạ. KHÔNG có "I'm from" / "taga" (quê quán — thợ Bangladesh ở Saudi nói
# "I'm from Bangladesh" là nói quốc tịch, vẫn đang ở Saudi).
_TOI_DANG_O_NGOAI = re.compile(
    r"\b(?:i'?m|i\s+am|im|iam)\s+(?:here\s+|now\s+|currently\s+|staying\s+|living\s+|still\s+)?(?:in|at)\b"
    r"|\b(?:i'?m|i\s+am|im|iam)\s+now\b"
    r"|\bi\s+(?:live|stay|staying|living|reside|work|working)\s+(?:in|at|here\s+in)\b"
    r"|\bmy\s+(?:address|location|place|home\s+address)\b|\bbased\s+in\b|\bcurrently\s+in\b|\baddress\b"
    r"|\b(?:ship|send|deliver|delivery|courier|parcel|kirim|padala)\w*\b"
    r"|\bnasa\b|\bnandito\b|\bandito\b|\bdito\s+sa\b|\bnakatira\b|\bpadala\s+sa\b"
    r"|\b(?:saya|aku|sy|ak)\s+(?:di|tinggal|lagi\s+di|sekarang\s+di|posisi)\b|\btinggal\s+di\b|\bposisi\s+di\b"
    r"|\balamat\b|\bkirim\s+ke\b"
    r"|আছি|থাকি|ঠিকানা|পাঠা|ডেলিভারি|যাবে|যায়|में\s+(?:हूँ|हूं|रहता|रहती)|पता|میں\s+ہوں|رہتا|پتہ"
    r"|أنا\s+في|انا\s+في|ساكن\s+في|اسكن\s+في|موجود\s+في|عنواني|عندي\s+عنوان", re.I | re.U)
# KHUÔN ĐỊA CHỈ chỉ nước ngoài mới có — tự nó đã là địa chỉ, không cần lời "tôi đang ở". Đo trên tin khách thật
# của 8 nước (/root/thu_ngoai_tt2/do.py): chữ nào oan là bỏ. "গ্রাম" (làng) KHÔNG dùng — tiếng Bengali cũng là "gram".
_DIA_CHI_NGOAI = (
    ("bangladesh", re.compile(r"থানা|জেলা|উপজেলা|ডাকঘর|\bupazila\b|\bupozila\b|\bzilla?\b", re.I | re.U)),
    ("india", re.compile(r"\btehsil\b|\btaluka\b|\bpin\s*code\b|जिला|तहसील|पिन\s*कोड", re.I | re.U)),
    ("indonesia", re.compile(r"\bkecamatan\b|\bkabupaten\b|\bkelurahan\b|\bkec\s*[.:]|\bkab\s*[.:]|\bdesa\b\s*[.:]?\s*\w"
                             r"|\brt\s*\.?\s*0?\d{1,3}\s*/?\s*rw\s*\.?\s*0?\d{1,3}\b", re.I)),
)


# Tin CHỈ có tên nơi đó ("Bangladesh", "Pakistan po") — câu trơ nhận được; còn "I am Bangladesh", "My country
# Bangladesh", "From nepal" là QUỐC TỊCH (đo 23/09: thợ Nam Á ở Vịnh nói vậy rất nhiều) → không tính.
_DEM_NGOAI = re.compile(r"\b(?:po|sir|maam|ma'?am|mam|madam|bro|brother|bhai|ji|ok|okay|pls|please|kak|pak|mas|here|now"
                        r"|currently|di|sa)\b|ভাই|আপু|জি|দাদা", re.I | re.U)


def _chi_ten_noi(t, m):
    con = _DEM_NGOAI.sub(" ", t[:m.start()] + " " + t[m.end():])
    return not re.search(r"[^\W\d_]", con)


# Nhắc nước lạ mà KHÔNG phải nơi đang ở: ngôn ngữ, tiền, hàng sản xuất ở đó, chuyện đã qua / sắp đi.
_KHONG_PHAI_NOI_O_NGOAI = re.compile(
    r"\b(?:bahasa|bhsa|bhs|language|english|inglis|arabic|tagalog|money|currency|uang|rupees?|taka|made\s+in"
    r"|was|were|ago|went|going\s+to|will\s+go|travel\w*|flight|visit\w*|vacation|holiday|last\s+(?:year|month|week))\b"
    r"|টাকা|ভাষা", re.I | re.U)


_TEN_CHO = re.compile(
    r"\W*(?:\w+\W+)?(?:restaurant|resturant|restaurent|hotel|market|shop|store|mall|supermarket|cafe|cafeteria|bakery"
    r"|mosque|school|embassy|consulate|bank|exchange|cargo|salon|clinic|hospital|masjid)\b", re.I)


def dia_chi_nuoc_ngoai(t):
    """Tin có khuôn địa chỉ của nước shop KHÔNG kinh doanh không → tên nước; không thì None."""
    for k, rx in _DIA_CHI_NGOAI:
        if rx.search(t or ""):
            return k
    return None


# ══ ĐỊA CHỈ PHILIPPINES — PH_DIA_CHI_2509 (ca War Kins · DOC Alipion-Tooth ARMOR KSA, 25/09) ══
# Khách gửi "Contact Number: #09554756987 Complete Delivery Address: Prk Lapuville,Bgry Pangyan,Pob.Glan, Sarangani Province."
# → AI chốt đơn Saudi ("Your order total is 109 SAR… 3-7 days"), lên đơn nháp #77211. Máy mù: NUOC_TP["philippines"] chỉ biết
# vài thành phố lớn, _DIA_CHI_NGOAI không có khuôn PH, _co_dia_chi_trong_nuoc coi "địa chỉ không mang dấu nước nào" là địa chỉ
# TRONG nước; model tự ghi "Khách ở Sarangani (Philippines)" mà lưới (4) chỉ đọc tên nước đứng ngay sau "khách ở".
# (a) Khuôn hành chính CHỈ Philippines có (barangay / purok / sitio / poblacion / Blk-Lot, kể cả gõ sai "Bgry", "Baranggay",
#     "porok", "Prk") — tự nó đã là địa chỉ PH, kể cả địa chỉ người nhà (shop không giao sang PH).
# (b) Tên tỉnh/thành PH — phải kèm lời gửi/ở/địa chỉ, số + từ địa chỉ, đuôi tỉnh PH (del Sur / Occidental…), ≥2 tên PH, hoặc
#     tin chỉ có mỗi tên đó; người nhà ở đó / ngôn ngữ / tiền / chuyến đi thì không tính.
# Cả hai: có nơi trong nước page ("from Aurora province, now in Najran") hoặc chuyện sắp/đã qua ("pag-uwi ko") → không tính.
# Bẫy đo trên kho câu khách thật: "bgy po" = "bigay" · "pob ba" = "po ba" · "pork" = thịt heo · "Eastern/Makkah Province" là
# tỉnh Saudi (chữ "province" không tính) · "Laguna/San Pedro/Angeles" trùng địa danh Mỹ (không đưa vào bảng tên).
_DC_PH_MANH = re.compile(
    r"\b(?:brgy|bgry|brgry|brngy|brgay|brangay|barangay|baranggay|barangy)\b|\bbgy\.\s?\w"
    r"|\b(?:purok|porok|prk)(?=[\s\d.,:#-]|$)"
    r"|\bsitio\b|\bpoblacion\b|\bpob\.\s?[^\W\d_]{3,}"
    r"|\bbl(?:oc)?c?k\.?\s*\d+\w*\s*,?\s*lot\s*\d+|\blot\s*\d+\w*\s*,?\s*bl(?:oc)?c?k\b",
    re.I)
_TEN_PH = re.compile(
    r"\b(?:philippines?|pilipinas|pinas|manila|cebu|davao|zamboanga|baguio|cavite|bulacan|pampanga|iloilo|batangas"
    r"|quezon\s+city|pasig|romblon|negros|pangasinan|mindanao|luzon|visayas|antipolo|quirino|nueva\s+(?:ecija|vizcaya)"
    r"|zambales|bataan|olongapo|dagupan|tuguegarao|batanes|mindoro|palawan|puerto\s+princesa|masbate|albay|legazpi|capiz"
    r"|aklan|guimaras|siquijor|biliran|dinagat|bukidnon|lanao|camiguin|basilan|tawi[\s-]*tawi|kabankalan|makati|taguig"
    r"|caloocan|marikina|para[nñ]aque|las\s+pi[nñ]as|muntinlupa|malabon|navotas|mandaluyong|pasay|calamba|lucena"
    r"|tagaytay|dasmari[nñ]as|bacoor|cabanatuan|malolos|meycauayan|mabalacat|ormoc|calbayog|catbalogan|kalibo|dipolog"
    r"|dapitan|marawi|polomolok|alabel)\b|" + HS.R_PH_TINH.pattern, re.I)
_DUOI_TINH_PH = re.compile(r"\b(?:del\s+(?:sur|norte)|occidental|oriental)\b", re.I)


def dia_chi_philippines(t, mkey):
    """Tin khách là / có ĐỊA CHỈ ở Philippines (nước shop không kinh doanh) — PH_DIA_CHI_2509."""
    t = str(t or "")
    if not t.strip() or mkey == "philippines" or _KHONG_PHAI_BAY_GIO.search(t) or _co_noi_trong_nuoc(t, mkey):
        return False
    if _DC_PH_MANH.search(t):
        return True
    ten = [m for m in _TEN_PH.finditer(t) if not _TEN_CHO.match(t, m.end())]
    if not ten or _NGUOI_KHAC_O.search(t) or _KHONG_PHAI_NOI_O_NGOAI.search(t):
        return False
    return bool(_TOI_DANG_O_NGOAI.search(t) or (re.search(r"\d", t) and HS.TU_DIA_CHI.search(t))
                or _DUOI_TINH_PH.search(t) or len({m.group(0).lower() for m in ten}) >= 2 or _chi_ten_noi(t, ten[0]))


# SĐT nước lạ. Philippines KHÔNG có ở đây: khách OFW ở Vịnh cho số nhà là chuyện thường (luật SĐT nước ngoài 23/08).
# Số trần không mã nước chỉ nhận khuôn KHÔNG trùng số Vịnh/Đài: Bangladesh 01[3-9]+8 số (11 số), Pakistan 03+9 số.
_SDT_NGOAI = (
    ("bangladesh", re.compile(r"(?:\+|00)?880\d{10}|01[3-9]\d{8}")),
    ("india", re.compile(r"(?:\+|00)91[6-9]\d{9}")),
    ("pakistan", re.compile(r"(?:\+|00)?923\d{9}|03\d{9}")),
    ("nepal", re.compile(r"(?:\+|00)9779[78]\d{8}")),
    ("sri_lanka", re.compile(r"(?:\+|00)947\d{8}")),
    ("indonesia", re.compile(r"(?:\+|00)628\d{8,11}")),
    ("egypt", re.compile(r"(?:\+|00)201[0125]\d{8}")),
)


def sdt_nuoc_ngoai(t):
    """(tên nước, số) nếu tin khách có SĐT của nước shop KHÔNG kinh doanh; không thì None."""
    for m in HS.R_SDT_CHUNG.finditer(HS.so_latin(t or "")):
        so = re.sub(r"[\s.\-()]", "", m.group(1))
        for k, rx in _SDT_NGOAI:
            if rx.fullmatch(so):
                return k, so
    return None


def _co_noi_trong_nuoc(t, mkey):
    """Tin khách có nhắc một nơi trong nước page (tên nước / thành phố / tỉnh theo bảng tỉnh POS) không."""
    if not t:
        return False
    if NUOC_TP.get(mkey) and re.search(NUOC_TP[mkey], t, re.I):
        return True
    if TEN_NUOC_BAN_DIA.get(mkey) and re.search(TEN_NUOC_BAN_DIA[mkey], t, re.I | re.U):
        return True
    try:
        return bool(HS._co_ten_tinh(t, mkey))
    except Exception:                                    # noqa: BLE001 — không tra được thì coi như không
        return False


def _co_dia_chi_trong_nuoc(t, mkey):
    """Nơi trong nước page, HOẶC một địa chỉ (building/flat/street…) không mang dấu nước nào khác.
    Chủ shop 23/09: "số nước ngoài nhưng địa chỉ UAE vẫn ok" — địa chỉ UAE hay không ghi tên tiểu vương quốc."""
    if _co_noi_trong_nuoc(t, mkey):
        return True
    if not t or not HS.TU_DIA_CHI.search(t) or HS.la_cau_hoi(t) or dia_chi_nuoc_ngoai(t):
        return False
    if dia_chi_philippines(t, mkey):                    # PH_DIA_CHI_2509 — địa chỉ PH không phải địa chỉ trong nước
        return False
    return not any(re.search(rx, t, re.I | re.U) for k, rx in list(NUOC_NGOAI_TP.items()) + list(NUOC_TP.items())
                   if k != mkey)


# Khách đáp "có" ngay sau câu page hỏi "bạn có đang ở <nước page> không?" → đang ở đúng nước.
_KHACH_DAP_CO = re.compile(
    r"^\s*(?:yes|yeah|yup|yep|ya|yah|iya|iyah|opo|oo|oo\s+po|haan|ji|jee|sure|correct|of\s+course"
    r"|হ্যাঁ|হ্যা|জি|জ্বি|জী|हाँ|हां|جی|نعم|ايوه|أيوه|أجل)(?=\W|$)", re.I | re.U)


def _page_hoi_dang_o(tp, mkey):
    return bool(tp) and (bool(_PAGE_HOI_NOI_O.search(tp))
                         or (noi_ro_noi_giao(tp, mkey) and bool(re.search(r"[?؟]", tp))))


# (4) Lưới cuối: model TỰ ghi "khách ở Bangladesh, ngoài thị trường" mà vẫn soạn câu chốt đơn.
_MODEL_NGOAI_TT = re.compile(r"ngoài\s+(?:thị\s+trường|vùng(?!\s+phủ)|phạm\s+vi\s+giao)|ở\s+nước\s+ngoài"
                             r"|ở\s+ngoài\s+(?:KSA|UAE|Saudi|Kuwait|Qatar|Oman|Bahrain|Taiwan|Đài)", re.I)
_MODEL_KHACH_O = re.compile(
    r"(?:khách\s+(?:đã\s+về|đang\s+ở|ở|nói\s+(?:đang\s+)?ở|sống\s+ở|hỏi\s+giao|muốn\s+(?:giao|gửi|ship))"
    r"|địa\s+chỉ(?:\s+(?:ở|tại))?)\s+(?:về\s+|sang\s+|tới\s+|đi\s+)?([^,.;:—()]{2,40})", re.I)
_TEN_NUOC_VN = (
    ("bangladesh", r"bangladesh|băng\s*la"), ("india", r"ấn\s*độ|\bindia\b|kerala"), ("pakistan", r"pakistan"),
    ("nepal", r"nepal"), ("sri_lanka", r"sri\s*lanka"), ("indonesia", r"indonesia|\bindo\b"),
    ("egypt", r"ai\s*cập|egypt"), ("yemen", r"yemen"), ("sudan", r"sudan"), ("jordan", r"jordan"),
    ("hungary", r"hungary"), ("malaysia", r"malaysia"), ("vietnam", r"việt\s*nam|vietnam"),
    ("philippines", r"philippines?|phi(?:\s*|-)?líp|\bpinas\b|pilipinas|cavite|mindanao|luzon|visayas|manila|cebu|davao"),
)


def ngoai_tt_theo_model(qd, mkey):
    """(nước, câu) nếu ghi_chu/ly_do của model nói khách ở nước shop KHÔNG kinh doanh; không thì None.

    Nước shop CÓ kinh doanh (Qatar…) không trả ở đây — đường treo kiểm kho vẫn chỉ tin lời khách qua máy dò.
    """
    txt = " ".join(str((qd or {}).get(k) or "") for k in ("ghi_chu", "ly_do"))
    if not txt.strip() or re.search(r"đơn\s+cũ|khiếu\s+nại|đã\s+nhận\s+hàng", txt, re.I):
        return None
    for m in _MODEL_KHACH_O.finditer(txt):
        for k, rx in _TEN_NUOC_VN:
            if re.match(r"\s*(?:" + rx + ")", m.group(1), re.I):      # tên nước đứng NGAY sau "khách ở"
                return k, txt[:160]
        # PH_DIA_CHI_2509: "Khách ở Sarangani (Philippines) nhưng chốt đơn Saudi" — tỉnh/thành trước, tên nước trong ngoặc
        # NGAY sau (ngoặc khác như "(quê Davao)" không tính); hoặc tên tỉnh/thành PH đứng ngay sau "khách ở".
        for k, rx in _TEN_NUOC_VN:
            if re.match(r"\s*\(\s*(?:" + rx + ")", txt[m.end(1):m.end(1) + 40], re.I):
                return k, txt[:160]
        if re.match(r"\s*(?:" + _TEN_PH.pattern + ")", m.group(1), re.I):
            return "philippines", txt[:160]
    if _MODEL_NGOAI_TT.search(txt):
        for k, rx in _TEN_NUOC_VN:
            if re.search(rx, txt, re.I):
                return k, txt[:160]
        # Không nêu tên nước: chỉ nhận khi KHÔNG nhắc nước nào của mình (kẻo "khách ở Qatar, ngoài thị trường UAE"
        # bị từ chối thay vì treo kiểm kho).
        if not any(re.search(rx, txt, re.I) for k, rx in NUOC_TP.items() if k != mkey):
            return "ngoai_khong_ro", txt[:160]
    return None


# TIN_LOT_2609 (ca Tia Tia): "Ke Indonesia" / "to India?" — "ke" (tiếng Indo) / "to" ngay trước tên nước = hỏi gửi về đó. Về quê /
# nghỉ phép ("pulang ke Indonesia", "uuwi sa Pinas") không tính.
_KE_NUOC = re.compile(r"(?i)\b(?:ke|to)\s+(?:the\s+)?$")
_VE_QUE = re.compile(r"(?i)\b(?:pulang|mudik|cuti|liburan|balik|uwi|umuwi|uuwi|bakasyon|vacation|holiday)\b")


def khach_o_nuoc_khac(text, mkey):
    """Tên thị trường khách nói rõ mình đang ở, nếu KHÁC `mkey`; None nếu không rõ."""
    t = _TEN_HANG_NUOC.sub(" ", lam_sach(text or ""))
    if dia_chi_philippines(t, mkey):                    # PH_DIA_CHI_2509 — trước cửa "người nhà ở đó": địa chỉ PH là không giao được
        return "philippines"
    if not t.strip() or _NGUOI_KHAC_O.search(t) or _KHONG_PHAI_BAY_GIO.search(t):
        return None
    for k, rx in list(NUOC_TP.items()) + list(NUOC_NGOAI_TP.items()):
        if k == mkey:
            continue
        m = re.search(rx, t, re.I | re.U)
        if not m:
            continue
        _vung = t[max(0, m.start() - 80):m.end() + 80]
        if k in NUOC_NGOAI_TP:
            # Nước shop KHÔNG kinh doanh (23/09): chỉ tính lời "đang ở / gửi tới" hoặc tin chỉ có tên nơi đó.
            if _KHONG_PHAI_NOI_O_NGOAI.search(_vung) or _TEN_CHO.match(t, m.end()) or _co_noi_trong_nuoc(t, mkey):
                continue
            if (_TOI_DANG_O_NGOAI.search(_vung) or _chi_ten_noi(t, m)
                    or (_KE_NUOC.search(t[:m.start()]) and not _VE_QUE.search(t))):   # TIN_LOT_2609 "Ke Indonesia"
                return k
            continue
        if _TOI_DANG_O.search(_vung):
            return k
        if len(t.strip()) <= 40 and not _LA_HOI_NUOC.search(t):   # câu trơ mỗi địa danh: "Doha Qatar"
            return k
    # Khuôn địa chỉ chỉ nước ngoài mới có (23/09, ca Faruk Shaik: "থানা কালিয়াপুর, জেলা গাজীপুর").
    k = dia_chi_nuoc_ngoai(t)
    if k and not _co_noi_trong_nuoc(t, mkey):
        return k
    return None


# NUOC_BAN_2609 (chủ shop 26/09, ca Shakir Ahmad Ansari · Nature's Daily Care in Saudi — chọn "AI trả lời + xin thông tin"): khách ở
# nước mình CÓ bán nhắn page nước khác → trước treo cho sale (8 tiếng không ai rep). Có page CÙNG TÊN bên nước khách → AI trả lời theo
# giá page đó + xin SĐT/địa chỉ; sale lên đơn bên shop nước khách (ghi chú). Không có page cùng tên → treo như cũ.
_TU_NUOC_TEN_PAGE = re.compile(r"\b(?:in\s+)?(?:saudi(?:\s+arabia)?|ksa|uae|dubai|kuwait|qatar|oman|bahrain|taiwan|tw|usa|us)\b", re.I)
TIEN_NUOC = {"uae": r"AED|dirhams?|درهم", "saudi": r"SAR|SR\b|riyals?|ريال", "kuwait": r"KWD|KD\b|dinars?",
             "qatar": r"QAR|QR\b", "oman": r"OMR|RO\b|rials?", "bahrain": r"BHD|BD\b", "taiwan": r"NT\$|TWD|元",
             "usa": r"USD|\$"}


def _goc_ten_page(ten):
    t = re.sub(r"[’`]", "'", str(ten or "").lower())
    t = _TU_NUOC_TEN_PAGE.sub(" ", t)
    return " ".join(re.sub(r"[^\w']+", " ", t).split())


def page_cung_ten_nuoc(mkey_kh, ten_page):
    """(pid, tên, kb) page CÙNG TÊN ở thị trường mkey_kh (thuộc shop nước đó, có kịch bản, có token) — không có / nhiều hơn 1 → None."""
    goc = _goc_ten_page(ten_page)
    if len(goc) < 6:
        return None
    d = os.path.join(SCRIPT_DIR, "state", mkey_kh)
    try:
        tok = json.load(open(os.path.join(d, "page_tokens.json"), encoding="utf-8"))
        kb = json.load(open(os.path.join(d, "kich_ban.json"), encoding="utf-8"))
        thuoc = set(str(x) for x in (json.load(open(os.path.join(d, "pages_cua_shop.json"), encoding="utf-8")).get("ids") or []))
    except Exception:                                    # noqa: BLE001
        return None
    ung = [(p, st.get("name")) for p, st in tok.items()
           if isinstance(st, dict) and p in kb and p in thuoc and _goc_ten_page(st.get("name")) == goc]
    return (ung[0][0], ung[0][1], kb[ung[0][0]]) if len(ung) == 1 else None


def dong_gia_page(kb, mkey_kh):
    """Các dòng ưu đãi có tiền của nước mkey_kh trong kịch bản page (không trùng, tối đa 6)."""
    rx = re.compile(r"\d[\d,.]*\s*(?:" + TIEN_NUOC.get(mkey_kh, r"$^") + r")|(?:" + TIEN_NUOC.get(mkey_kh, r"$^") + r")\s*\d", re.I)
    ra, gia_da = [], set()
    for m in (kb or {}).get("mau") or []:
        for tin in m.get("tin") or []:
            for dong in str(tin).splitlines():
                d = dong.strip()
                so = tuple(re.findall(r"\d+(?:[.,]\d+)?", rx.search(d).group(0))) if d and rx.search(d) else None
                if so and len(d) <= 160 and so not in gia_da:        # mỗi mức giá 1 dòng (kịch bản hay ghi 2 kiểu)
                    gia_da.add(so)
                    ra.append(d)
    return ra[:4]


def tra_loi_nuoc_ban(nhan, dem, qd, msgs, mkey, nuoc_kh, ten_kh, cau_kh, ten_page_goc, kb_page, gia):
    """Câu trả lời cho khách ở nước mình CÓ bán theo page cùng tên bên đó — trả qd mới (tra_loi + ghi chú) hoặc None (treo như cũ)."""
    sinh = page_cung_ten_nuoc(nuoc_kh, ten_page_goc)
    if not sinh:
        return None
    pid2, ten2, kb2 = sinh
    dong = dong_gia_page(kb2, nuoc_kh)
    if not dong:
        return None
    en_kh = TEN_NUOC_KHACH.get(nuoc_kh) or nuoc_kh
    en_pg = TEN_NUOC_KHACH.get(mkey) or mkey
    j = len(msgs or [])
    while j > 0 and (msgs[j - 1].get("boi") in ("khach", "hethong")):
        j -= 1
    da_tt = any(re.search(r"\d{7,}", re.sub(r"[\s\-]", "", m.get("text") or "")) for m in (msgs or [])[j:]
                if m.get("boi") == "khach")
    rx_kh = re.compile(TIEN_NUOC.get(nuoc_kh, r"$^"), re.I)
    rx_pg = re.compile(TIEN_NUOC.get(mkey, r"$^"), re.I)
    lenh = (f"The customer is in {en_kh}. We DO deliver in {en_kh} too (free delivery, cash on delivery). Reply in 1-3 short "
            f"sentences, same language as the customer: first answer what they asked (yes, we deliver in {en_kh} / their city). "
            + ("They have just sent their contact details: thank them briefly, say you noted them for delivery in "
               f"{en_kh}, and ask ONLY for what is still missing (phone number, or complete address in {en_kh} with area / "
               "building). Do not repeat prices." if da_tt else
               f"Then give our {en_kh} offers copied exactly from this list, each offer on its own line (prices in the "
               f"{en_kh} currency): " + " ;; ".join(dong) + f" — then ask which offer they want and for their phone number "
               f"and complete address in {en_kh}.")
            + f" NEVER mention {en_pg} prices or its currency. No delivery date, no 'I will check / get back to you', do not "
              "confirm an order.")
    seed = (qd or {}).get("tin_nhan") or f"Yes, we deliver in {en_kh} 😊"

    def _hop(t):
        if len(t.strip()) < 15 or rx_pg.search(t) or (not da_tt and not rx_kh.search(t)):
            return False
        pq = CG.kiem(t, mkey=mkey, kb_page=kb_page, gia=gia)
        return pq.ket == "qua" or not any(k in (pq.ma_loi or []) for k in ("duoi_gia_san", "sai_gia", "bia_gia", "gia_la"))
    moi = _thu_sua_nhe(nhan, dem, f"khách ở {ten_kh} — trả lời theo page {ten2}", seed, lenh, msgs, _hop)
    if not moi:
        return None
    print(f"{nhan} 🌍 khách ở {ten_kh} — có page cùng tên «{ten2}» bên đó → AI trả lời theo giá page đó, ghi chú sale lên đơn "
          f"bên shop {ten_kh}")
    return {"hanh_dong": "tra_loi", "tin_nhan": moi, "ly_do": f"khách ở {ten_kh} — trả lời theo page {ten2} (26/09)",
            "ghi_chu": (f"Khách ở {ten_kh} (\"{cau_kh}\") nhắn page này. AI đã trả lời theo giá page «{ten2}» và xin SĐT + địa "
                        f"chỉ. Khách gửi đủ thì LÊN ĐƠN BÊN SHOP {ten_kh} (page {ten2}) — KHÔNG lên đơn ở shop page này.")}


def khach_khac_thi_truong(msgs, mkey):
    """(tên thị trường khách đang ở | "khong_ro", câu khách) nếu khách ở nơi page không giao; None nếu không.

    Chỉ xét các tin khách GẦN ĐÂY (6 tin cuối) — luật 00_chung: lời nói từ những tuần trước không tính.
    """
    cap, truoc = [], None
    for m in (msgs or []):
        if m.get("boi") == "khach":
            cap.append((lam_sach(m.get("text") or ""), truoc))
        elif m.get("boi") in ("ai", "nguoi", "botcake"):
            truoc = lam_sach(m.get("text") or "")
    phu_nhan = None
    for t, tp in reversed(cap[-6:]):
        if not t.strip():
            continue
        if khach_o_dung_thi_truong(t, mkey):
            return None            # tin MỚI HƠN nói đang ở đúng nước page → câu cũ hết hiệu lực
        k = khach_o_nuoc_khac(t, mkey)
        if k:
            return k, t[:160]
        if _KHACH_DAP_CO.search(t) and _page_hoi_dang_o(tp, mkey):
            return None            # page hỏi "bạn có ở <nước page> không?" → khách đáp CÓ (23/09)
        if (TEN_NUOC_BAN_DIA.get(mkey) and re.search(TEN_NUOC_BAN_DIA[mkey], t, re.I | re.U)
                and (_TOI_DANG_O_NGOAI.search(t) or len(t.strip()) <= 40) and not _LA_HOI_NUOC.search(t)):
            return None            # "আমি সৌদি আরবে আছি" / "أنا في السعودية" — đang ở đúng nước page
        if phu_nhan is None and tp and _PAGE_HOI_NOI_O.search(tp) and _KHACH_DAP_KHONG.search(t):
            phu_nhan = t[:160]          # khách nói KHÔNG — đi tiếp xem tin trước có nêu tên nước không
    if phu_nhan:
        return "khong_ro", phu_nhan
    # SĐT nước shop KHÔNG kinh doanh mà cả hội thoại chưa có nơi nào trong nước page (23/09, ca Faruk Shaik
    # "01873890974"). Số Philippines không tính. Khách cho địa chỉ trong nước / đáp "có" thì cửa tự tắt.
    for t, tp in reversed(cap[-6:]):
        s = sdt_nuoc_ngoai(t)
        if s:
            if any(_co_dia_chi_trong_nuoc(x, mkey) for x, _ in cap):
                return None
            return s[0], f"SĐT {s[1]} (số {TEN_NUOC_KHACH.get(s[0], s[0])})"
    return None


# Khách hỏi CÂN NẶNG hay hỏi KÍCH THƯỚC — hai câu hỏi khác nhau. Ca "Length pls" từng bị đáp bằng
# gram (chủ shop 20/09: "đừng thay thông số khách hỏi"), nên bảng cân chỉ được đưa ra khi hỏi cân.
_HOI_CAN = re.compile(
    r"\bgrams?\b|\bgm\b|\bweigh\w*\b|\bweight\b|\bilang\s+gram|\bgaano\s+kabigat|\btimbang\b"
    r"|\u0643\u0645\s*\u062c\u0631\u0627\u0645|\u0627\u0644\u0648\u0632\u0646|\u0648\u0632\u0646\u0647|\bberapa\s+gram\b|\bberat\b", re.I | re.U)


def dong_thong_so(kb_page, cau, pid=None):
    """Dòng tình huống khi khách hỏi thông số hàng. Ba đường: kịch bản có số / suy từ dòng hàng / không có."""
    if _size_nhan_mac_dinh_ap_duoc(kb_page, cau):
        return ""                                  # dòng 💍 SIZE NHẪN trong goi_soan lo (chủ shop 23/09)
    rieng = TRONG_LUONG_PAGE.get(str(pid or ""))
    # Kịch bản «CÓ thông số» phải đúng LOẠI khách hỏi (23/09, ca Lee M Julian: Zahra ghi «10,28 Grams», khách hỏi size).
    if khach_hoi_kich_thuoc(cau) and not _HOI_CAN.search(cau or ""):
        co_san = kich_thuoc_co_nguon(kb_page) or _do_dai_mac_dinh_ap_duoc(kb_page, cau)
    else:
        co_san = (not rieng) and bool(kb_page) and bool(_CO_SO_GAM.search(json.dumps(kb_page, ensure_ascii=False)))
    hoi_can = bool(_HOI_CAN.search(cau or ""))
    goi_y = None if (co_san or not hoi_can) else trong_luong_goi_y(kb_page, pid)
    if co_san:
        cach = ("✅ KỊCH BẢN PAGE CÓ ghi thông số — tìm trong kịch bản và trả lời ĐÚNG con số đó, không tự "
                "đổi, không làm tròn khác đi. ⛔ Trả lời ĐÚNG THỨ khách hỏi: hỏi dài thì đáp cm/inch, hỏi "
                "nặng thì đáp gram — CẤM thay thông số này bằng thông số kia. ")
    elif goi_y:
        cach = (f"✅ Kịch bản page này không ghi, nhưng dòng hàng của shop thì có: {goi_y}. Trả lời "
                "bằng ĐÚNG con số đó, nói tự nhiên như người bán biết hàng mình. ")
    else:
        # 22/09: câu vàng 18K CHỈ cho page vàng thật (page thuốc nhỏ mắt / serum tóc từng bị dặn đúng câu này).
        _chac = ("(vàng 18K thật, tem 750 ở khoá, kèm giấy chứng nhận, mang ra tiệm vàng kiểm được, nhận hàng kiểm "
                 "rồi mới trả tiền) " if la_page_vang_that(kb_page) else
                 "— CHỈ điều kịch bản page GHI RÕ về sản phẩm (công dụng, thành phần, cách dùng…); CẤM tự thêm "
                 "chất liệu, vàng/18K, giấy chứng nhận, cân nặng mà kịch bản không ghi — ")
        cach = ("✅ Không có con số nào ĐÚNG THỨ KHÁCH HỎI (cấm đáp cân nặng khi khách hỏi độ dài/size và "
                "ngược lại) → trả lời bằng thứ mình CHẮC CHẮN " + _chac
                + "rồi chốt tiếp. Khách hỏi lại đúng con số lần nữa → hanh_dong 'treo', ghi_chu 'khách đòi "
                "thông số kịch bản không có — sale trả lời tay'. ")
    return (f"📏 KHÁCH HỎI THÔNG SỐ HÀNG: \"{cau[:140]}\" — khách muốn MỘT con số, không muốn nghe hẹn. "
            "⛔ CẤM hứa kiểu 'để tôi hỏi shop/team rồi báo lại', 'I'll check and get back to you', "
            "'icheck ko muna sa shop', ⛔ CẤM nói mình không chắc / không có thông tin / chưa biết. "
            + cach
            + "Tối đa 2 câu, đúng tiếng khách, kết bằng câu chốt (chọn gói / xin thông tin giao hàng).\n")


# ══ QUY CÁCH HÀNG — 1 HỘP MẤY GÓI / VIÊN / ML (chủ shop 22/09, ca Betchay Sanchez · Healthy Figure PH in Kuwait) ══
# Khách hỏi 3 lần một ý ("ilang paman po ba yan" → "I mean how many PCs" → "Sa isang pack po ilang shashe po ang
# laman"). AI đáp "Buy 1 Get 1 FREE ay 2 cups", rồi "Bawat pack po ay may 1 sachet"; sale vào sửa "One box contains
# 10 small packets." Chủ shop: *"sao lại 1 gói có 1 gói nhỏ?"*. Gốc: kịch bản page chỉ có "Mix 1 sachet…" và "1 CUP A
# DAY", không ghi 1 hộp mấy gói; khối 🎯 cấm nói không biết + cấm hứa báo lại → model ghép "1 sachet" thành quy cách,
# "1 cup" thành đơn vị bán. Đo sổ 8 nước: 2 page FITGUM, AI đã nói 7 con số khác nhau cho cùng một hộp (1 / 2 / 7 / 10
# / 15 / 30 sachets, "2 bottles") — số 10 chỉ ra khi sale đã nói trước trong hội thoại. Page kịch bản CÓ ghi (trà
# Nature's Daily Care "12 Tea Bags per Box", Mint Breeze "~30 tablets") thì AI đáp đúng cả.
# → (1) QUY_CACH_PAGE: con số SALE SHOP đã trả lời khách thật, đưa vào MỌI lượt của page (sai đơn vị bán "2 cups" cũng
#   từ đây). (2) khách hỏi quy cách mà kịch bản / bảng này / tin sale-Botcake trong hội thoại đều không có số → TREO cho
#   sale, không gọi model. (3) lưới: câu AI tự khẳng định "1 hộp có N …" mà không nguồn nào có số đó → cắt / treo.
_QC_FITGUM = ("FITGUM ACAI BERRY is sold by the BOX. Each box contains 10 sachets (small packets); one sachet makes one "
              "cup (a single drink). Promos count BOXES: Buy 1 Get 1 FREE = 2 boxes (20 sachets), Buy 2 Get 2 FREE = "
              "4 boxes (40 sachets), Buy 3 Get 3 FREE = 6 boxes (60 sachets).")
QUY_CACH_PAGE = {
    # Healthy Figure PH in Kuwait — sale trả lời khách Betchay Sanchez 22/09 ~14:55 VN: "One box contains 10 small packets."
    "1240652985789530": _QC_FITGUM,
    # Healthy Figure PH in Saudi — cùng mã POS "125 - Fitgum Acai Berry" (99/149/199 SAR = 2/4/6 hộp)
    "1136682156197501": _QC_FITGUM,
}

# Đơn vị BÊN TRONG hộp, chia 4 họ: đếm (gói / túi lọc / viên / miếng / cái), ml, chai, hộp ("1 kotak isinya 1 botol",
# "Buy 1 Get 1 = 2 boxes"). Gói với túi lọc cùng họ: "كيس شاي" (túi trà) phải khớp "12 Tea Bags" của kịch bản.
_QC_DV_DEM = (r"sachets?|satchets?|shashe|sashe|packets?|small\s+packs?|sticks?|pouch(?:es)?|sobre|tea\s*bags?|teabags?"
           r"|capsules?|caps|kapsul|tablets?|tabs|tableta|pills?|softgels?|butir|patch(?:es)?|strips?|gói|viên|túi|miếng"
           r"|包|袋|顆|颗|粒|片|كيس|اكياس|أكياس|ظرف|حبة|حبه|حبات|كبسولة|كبسولات")
_QC_DV_CAI = r"pcs|pc'?s|pieces?|piraso|peraso|pirasu|perasu|biji|cái|قطعة|قطعه"      # "cái" — dễ lẫn số cái của gói KM
_QC_DV_ML = r"ml|milliliters?|毫升"
# GRAM / CÂN NẶNG (23/09, chủ shop "xử lý luôn"): quét 91 câu khách hỏi gram trong sổ — page kịch bản CÓ số gram thì AI
# hay trả lời đúng nhưng cũng hay lờ đi (báo giá / ngày giao thay vì trả lời); page KHÔNG có số thì AI BỊA: Light Step Care
# KSA "How many grams in 1 bottle" → "100g jar". Page VÀNG không ghi gram thì KHÔNG treo — luật 20/09 (TRONG_LUONG_PAGE /
# bảng cân chuẩn, xem trong_luong_goi_y + _dong_hoi_gram): "3.6 grams" ở Lapad là số chủ shop chốt, không phải bịa. Họ riêng
# "g" — chỉ dùng cho câu KHÁCH hỏi + đọc nguồn; cổng câu AI (_QC_CAU) KHÔNG xét gram (AI cộng "2.2g + 1g + 2g = 5.2g" là đúng
# mà không khớp số nguồn nào). Cân nặng CƠ THỂ ("my weight is 65", "lose weight", "Timbang mga 63") KHÔNG phải câu này.
_QC_DV_G = r"grams?|gramos?|grms?|gms?|gr|g|جرام|غرام|قرام|جم|克"
_QC_HOI_G = (r"(?:how\s+many|how\s+much|hw\s+many|how\s+mny|ilang|ilan|ilng|berapa|brapa|brp|kitne|kitna)\W+"
             r"(?:(?!(?:per|a|each|every|x)\b)\w+\W+){0,2}?(?:grams?|gramos?|grms?|gms?|gr|g)\b"     # "how much per gram" = giá
             r"|كم\s*(?:جرام|غرام|قرام|جم)|كم\s*(?:ال)?وزن|(?:ال)?وزن\w{0,2}\s*كم|多少\s*克|[幾几]\s*克"
             r"|\bwh?a?t(?:'s|\s+is)\s+(?:the\s+)?weight\b|\bweight\s+of\s+(?:the|this|that|it|each|one|1|your)\b|^\W*weight\W*$"
             r"|\bhow\s+much\s+(?:is\s+)?(?:the\s+)?weight\s*(?:\?|$|and\b|&|of\s+(?:the|this|it|each|one|1)\b)"
             r"|\b(?:price|prices|presyo)\s*(?:&|and|at|\+|/)\s*weight\b|\bhow\s+heavy\b|\bgaano\s+(?:ka)?bigat\b")
_QC_DV_CHAI = r"bottles?|botol|bote|jars?|tubes?"                  # vỏ: "Each bundle comes with 2 bottles"
_QC_DV_HOP = r"boxes|box|kotak|kahon"                                 # page bán theo HỘP (FITGUM) mà nói "2 bottles" là sai
_QC_VO_HOP = (r"box|boxes|pack|pck|pak|packs|package|packet|packaging|bottle|jar|tube|pouch|bag|kit|set|bundle|carton|bucket"
           r"|item|kahon|pakete|bote|kotak|botol|hộp|chai|盒|瓶|علبة|علبه|العلبة|العلبه|الباكيت|القطعة|القطعه|الكيس")
# "pieces" gõ sai (23/09, ca Baimamot Utto) — prices/prizes CHỈ dùng trong mẫu "how many prices in one pack" của HOI_QUY_CACH.
_QC_PIECES_GO_SAI = r"pri[cz]es|pices|peices|peaces|pieaces|piecies|pecies|pitches"
_QC_HOI_SL = r"how\s+many|how\s+much|hw\s+many|how\s+mny|ilan|ilang|ilng|berapa|brapa|brp|kitne|kitni|كم|幾|几|多少"

# KHÁCH HỎI QUY CÁCH. Mẫu CHẶT (đo 116k tin khách): TỪ HỎI SỐ LƯỢNG + (đơn vị bên trong + vỏ hộp) hoặc chữ "bên trong"
# (laman / isi / inside). "How many pcs" TRƠN không vào — câu đó thường hỏi gói khuyến mãi được mấy cái, bảng giá trả
# lời được; "Ilang piraso ung 11kd" / "159 ilang piraso" (giá đó mấy cái) cũng không vào.
HOI_QUY_CACH = re.compile(
    r"(?:" + _QC_HOI_SL + r")\W+(?:\w+\W+){0,2}?(?:" + _QC_DV_DEM + "|" + _QC_DV_CAI + "|" + _QC_DV_ML + r")\b[^?.!\n]{0,30}?"
    r"\b(?:in|inside|per|each|of|for|sa|ng|nang|dalam|di|في|ب)\W+(?:\w+\W+){0,2}?(?:" + _QC_VO_HOP + r")\b"
    r"|\b(?:each|every|one|1|a|per|isang|isa|bawat|satu|se|واحد|一)\s*(?:" + _QC_VO_HOP + r")\b[^?.!\n]{0,25}?"
    r"(?:" + _QC_HOI_SL + r")\W+(?:\w+\W+){0,1}?(?:" + _QC_DV_DEM + "|" + _QC_DV_CAI + "|" + _QC_DV_ML + r"|laman|isi(?:nya)?|inside|in\s+it)\b"
    r"|\b(?:ilan|ilang|ilng)\b[^?.!\n]{0,25}?\blaman\b|\blaman\b[^?.!\n]{0,20}?\b(?:ilan|ilang)\b"
    r"|\b(?:berapa|brapa|brp)\s+isi(?:nya)?\b|\bisi(?:nya)?\s+(?:berapa|brapa|brp)\b"
    # 23/09 (ca Baimamot Utto · Nature's Daily Care in Uae): "How many prices in one pack?" — prices = PIECES gõ sai,
    # AI tưởng hỏi giá. Cùng họ sót trong sổ: "How many peices in one bag", "How many pitches are in a packet?", "How
    # many are in one pack?", "How much is inside a box?". "prices/prizes" chỉ tính khi SỐ NHIỀU + in/inside/per + vỏ
    # hộp — "how much price for one set" / "how many price per box" vẫn là hỏi giá.
    r"|\bhow\s+many\s+(?:" + _QC_PIECES_GO_SAI + r")\s+(?:(?:are|is)\s+(?:there\s+)?)?(?:in|inside|per)\s+"
    r"(?:(?:one|1|a|an|each|the|every|this|isang)\s*)?(?:" + _QC_VO_HOP + r")\b"
    r"|\bhow\s+many\s+(?:are|is)\s+(?:there\s+)?(?:in|inside)\s+(?:(?:one|1|a|an|each|the|every|this)\s*)?(?:"
    + _QC_VO_HOP + r")\b"
    r"|\bhow\s+much\s+(?:is\s+)?inside\s+(?:(?:one|1|a|an|each|the|every|this)\s*)?(?:" + _QC_VO_HOP + r")\b"
    r"|\bhow\s+many\b[^?.!\n]{0,30}?\b(?:inside|contains?|in\s+(?:it|there))\b"
    r"|(?:how\s+many|how\s+much|ilang|ilan|berapa|brp|كم)\s*(?:ml|毫升|مل)(?![a-z])"
    r"|(?:العلبة|العلبه|علبة|علبه|الكيس|القطعة|القطعه)\s*(?:فيها\s*)?كم\s*(?:حبة|حبه|كيس|ظرف|كبسولة|قطعة|قطعه)"
    r"|كم\s*(?:حبة|حبه|كيس|ظرف|كبسولة|قطعة|قطعه)\s*(?:في|ب)\s*(?:العلبة|العلبه|علبة|علبه|الكيس|القطعة|القطعه)"
    r"|[一1]\s*[盒瓶包]\s*(?:有)?\s*(?:幾|几|多少)\s*(?:包|顆|颗|粒|片|袋|ml|毫升)"
    r"|" + _QC_HOI_G,                                   # 23/09 hỏi gram / cân nặng món hàng
    re.I | re.U)
# Trong đoạn khớp mà có mấy chữ này thì là hỏi NGÀY giao / dùng bao lâu / tuổi / cân nặng khách — không phải quy cách.
_QC_KHONG_PHAI = re.compile(r"\b(?:days?|araw|hari|weeks?|months?|linggo|buwan|taon|years?|kg|kilos?|times)\b|يوم|أيام|ايام|天",
                             re.I | re.U)
# Khách hỏi SỐ LƯỢNG cái / gói (kể cả "how many pcs" trơn) — khi đó câu quy cách AI bịa chính là câu trả lời, cắt đi là
# khách hỏi mà không ai đáp → treo thay vì cắt.
_QC_HOI_SO_CAI = re.compile(r"(?:" + _QC_HOI_SL + r")\W+(?:\w+\W+){0,3}?(?:" + _QC_DV_DEM + "|" + _QC_DV_CAI + "|" + _QC_DV_ML
                         + r"|laman|isi(?:nya)?|inside|" + _QC_VO_HOP + r")\b", re.I | re.U)


def _qc_tin_khach_sau_shop(msgs):
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    sau.reverse()
    return sau


def khach_hoi_quy_cach(msgs):
    """Câu khách vừa hỏi QUY CÁCH (1 hộp mấy gói/viên/túi, bao nhiêu ml) — tin khách SAU tin cuối phía shop; None nếu không."""
    hoi = []
    for x in _qc_tin_khach_sau_shop(msgs):
        m = HOI_QUY_CACH.search(x)
        if m and not _QC_KHONG_PHAI.search(m.group(0)):
            hoi.append(x)
    return " / ".join(hoi)[-200:] if hoi else None


def khach_hoi_so_luong(msgs):
    """Khách (tin sau tin cuối phía shop) đang hỏi số cái / số gói / dung tích — kể cả "how many pcs" trơn."""
    return any(_QC_HOI_SO_CAI.search(x) and not _QC_KHONG_PHAI.search(_QC_HOI_SO_CAI.search(x).group(0))
               for x in _qc_tin_khach_sau_shop(msgs))


_QC_SO = r"(?<![\d.,])(\d+(?:[.,]\d+)?)"
# chữ đệm giữa số và đơn vị ("12 Tea Bags", "10 small packets") — không được là đơn vị khác / giới từ: "8g per Tea Bag"
# là 8 GRAM mỗi túi, không phải 8 túi.
_QC_DEM_CHU = r"(?:(?!(?:g|gm|gms|grams?|mg|kg|ml|oz|per|each|in|of|x|for|with|and|or|sa|ng|na)\b)[^\W\d_]+\s+)"
# CÂU AI KHẲNG ĐỊNH QUY CÁCH (mẫu chặt): "(vỏ) … có/chứa/= N (đơn vị)", "N (đơn vị) per/in a/sa isang (vỏ)", "N ml".
_QC_CAU = [
    re.compile(r"\b(?:each|every|one|1|a|per|the|this|isang|bawat|ang\s+isang|ang\s+1|ang\s+bawat|satu|se|sebuah|mỗi|một)"
               r"\s*(?:" + _QC_VO_HOP + r")\b[^.!?\n]{0,30}?(?:\b(?:has|have|contains?|comes?\s+with|includes?|holds?|is|are"
               r"|ay\s+may|may|ay|laman|isinya|isi|berisi|có|chứa|gồm)\b|=|:)\s*(?:about\s+|around\s+|approx\.?\s+|~\s*|mga\s+"
               r"|po\s+)?" + _QC_SO + r"\s*(?:x\s*)?" + _QC_DEM_CHU + r"{0,2}?(" + _QC_DV_DEM + "|" + _QC_DV_CAI + "|" + _QC_DV_ML + "|"
               + _QC_DV_CHAI + "|" + _QC_DV_HOP + r")(?![^\W\d_])", re.I | re.U),
    re.compile(_QC_SO + r"\s*(?:x\s*)?" + _QC_DEM_CHU + r"{0,2}?(" + _QC_DV_DEM + "|" + _QC_DV_CAI + "|" + _QC_DV_ML + r")\s*(?:po\s+)?"
               r"(?:per|/|in\s+(?:a|one|1|each|every|the)|each|sa\s+(?:isang|bawat|1)|bawat|ang\s+laman\s+ng\s+(?:isang|1)"
               r"|dalam\s+(?:1|satu|se))\s*(?:" + _QC_VO_HOP + r")\b", re.I | re.U),
    re.compile(_QC_SO + r"\s*(" + _QC_DV_ML + r")(?![a-z])", re.I | re.U),
    re.compile(r"(?:العلبة|العلبه|علبة|الكيس|القطعة)\s*(?:تحتوي\s*على|فيها|بها|=)\s*" + _QC_SO + r"\s*(" + _QC_DV_DEM + r")", re.U),
]
# NGUỒN (kịch bản / sale / bảng) được đọc RỘNG hơn: mọi "N <đơn vị bên trong>" ("12 Tea Bags", "~30 tablets", "30ml"),
# trừ liều dùng. Riêng "N pcs/pieces" chỉ nhận theo mẫu chặt — dòng gói KM "Buy 1 Get 1 = 2 pcs" không phải quy cách.
_QC_NGUON_RONG = re.compile(_QC_SO + r"\s*(?:x\s*)?" + _QC_DEM_CHU + r"{0,2}?(" + _QC_DV_DEM + "|" + _QC_DV_ML + "|" + _QC_DV_CHAI
                         + "|" + _QC_DV_HOP
                         + r")(?![^\W\d_])", re.I | re.U)
# Nguồn GRAM (23/09): "✔ Total Net Weight: 100g", "8g per Tea Bag", "The necklace is 2.2 grams" — đọc cả câu có chữ total /
# khuyến mãi (dòng "Total Net Weight" là quy cách thật, bộ lọc câu KM của _QC_NGUON_RONG sẽ vứt nó).
_QC_NGUON_G = re.compile(_QC_SO + r"\s*(" + _QC_DV_G + r")(?![^\W\d_])", re.I | re.U)
# LIỀU DÙNG / CÁCH PHA, không phải quy cách: "Use 1–2 sachets per day", "1 tea bag daily", "Mix 1 sachet with 150–200ml
# of warm water", "steep 1 bag in 200–300ml hot water".
_QC_LIEU_SAU = re.compile(r"^\W*(?:a|per|each|every|kada|bawat|sa\s+isang|after|before|/)?\s*(?:day|days|araw|daily|hari|week|linggo|meal"
                       r"|meals|serving|times?|beses|morning|night)\b", re.I | re.U)
# 24/09 (ca አቡ አብደላ አደም · Nature's Daily Care in Saudi): thêm chữ "nước / sữa" Amharic (ውሃ, ወተት), Tigrinya (ማይ đứng riêng),
# Sinhala, Tamil, Malayalam, Telugu, Kannada, Pashto, Swahili, Somali, Oromo, Hindi/Urdu viết Latin — thiếu thì câu pha "300ml ሙቅ ውሃ"
# (300 ml nước nóng, đúng mẫu HDSD) bị coi là "1 hộp 300 ml" → treo.
_QC_PHA = re.compile(r"\b(?:water|tubig|air\s+(?:hangat|panas|dingin)|milk|gatas|juice|agua|maji|biyo|bishaan|paani|pani)\b"
                     r"|ماء|水|पानी|پانی|পানি|জল|ውሃ|ውሀ|ወተት|(?<![\u1200-\u137f])ማይ(?![\u1200-\u137f])|වතුර|தண்ணீர்|வெள்ளம்|വെള്ളം"
                     r"|నీరు|నీళ్ళు|ನೀರು|اوبه",
                  re.I | re.U)
_QC_PHA_TRUOC = re.compile(r"\b(?:mix|ihalo|halo|steep|dissolve|timpla|brew|drink|inumin|take|use|gamitin|apply|chew|place|put|nguyain)\W+(?:\w+\W+){0,2}$",
                        re.I | re.U)


def _qc_la_lieu_dung(s, a, b):
    """Đoạn s[a:b] là LIỀU DÙNG / cách pha — không phải quy cách."""
    sau = re.split(r"[.!?\n]", s[b:b + 40])[0]
    truoc = re.split(r"[.!?\n]", s[max(0, a - 25):a])[-1]
    return bool(_QC_LIEU_SAU.match(sau) or _QC_PHA.search(sau) or _QC_PHA_TRUOC.search(truoc))


def _qc_ho_dv(dv):
    dv = " ".join((dv or "").lower().split())
    if re.fullmatch(r"(?:" + _QC_DV_G + r")", dv, re.I):
        return "g"
    if re.fullmatch(r"(?:" + _QC_DV_ML + r")", dv, re.I):
        return "ml"
    if re.fullmatch(r"(?:" + _QC_DV_CHAI + r")", dv, re.I):
        return "chai"
    if re.fullmatch(r"(?:" + _QC_DV_HOP + r")", dv, re.I):
        return "hop"
    return "dem"


def _qc_sach(t):
    """Như lam_sach nhưng GIỮ xuống dòng — kịch bản viết mỗi ý một dòng ("✔ 12 Tea Bags per Box"), gộp dòng là câu
    khuyến mãi dòng trên dính sang dòng quy cách dòng dưới."""
    t = re.sub(r"<[^>]+>", " ", CG.bo_chu_toan(t or ""))
    return "\n".join(" ".join(d.split()) for d in t.splitlines() if d.strip())


# Câu KHUYẾN MÃI / TỔNG ("Buy 1 Get 1 = 2 boxes (20 sachets)", "total 40 sachets") — số trong đó là TỔNG của gói, không
# phải quy cách 1 hộp. Nguồn đọc rộng bỏ các câu này, kẻo "(20 sachets)" thành "1 hộp 20 gói".
_QC_CAU_KM = re.compile(r"\b(?:buy|get|free|promos?|promotion|bundles?|combo|total|take|libre|gratis|mua|tặng|sale|off|discount"
                     r"|offer|kabuuan|lahat)\b|=|\+", re.I | re.U)


def _qc_tim_so(s, cac_rx, bo_km=False):
    ra = {}
    for rx in cac_rx:
        for m in rx.finditer(s):
            if _qc_la_lieu_dung(s, m.start(1), m.end()):
                continue
            if bo_km:
                a = max(s.rfind(x, 0, m.start()) for x in ".;!?\n") + 1
                b = min([i for i in (s.find(x, m.end()) for x in ".;!?\n") if i >= 0] or [len(s)])
                if _QC_CAU_KM.search(s[a:b]):
                    continue
            try:
                n = float(m.group(1).replace(",", "."))
            except ValueError:
                continue
            if n <= 0:
                continue
            a = max([s.rfind(x, max(0, m.start() - 90), m.start()) for x in ".!?\n✔•👉"] + [max(0, m.start() - 90) - 1]) + 1
            b = min([i for i in (s.find(x, m.end(), m.end() + 70) for x in ".!?\n✔•👉") if i >= 0] or [m.end() + 70])
            ra.setdefault((n, _qc_ho_dv(m.group(2))), " ".join(s[a:b].split()).strip(" ,;:—-"))
    return ra


def so_quy_cach(t):
    """{(số, họ): câu} — các câu KHẲNG ĐỊNH quy cách trong tin (mẫu chặt, dùng cho câu AI soạn)."""
    return _qc_tim_so(_qc_sach(t), _QC_CAU) if t else {}


def _qc_chu_nguon(kb_page, msgs, pid=None):
    nguon = [QUY_CACH_PAGE.get(str(pid or ""), "")]
    for m in (kb_page or {}).get("mau") or []:
        nguon += [x for x in (m.get("tin") or []) if x]
    nguon += [m.get("text") or "" for m in (msgs or []) if m.get("boi") in ("nguoi", "botcake")]
    return _qc_sach("\n".join(x for x in nguon if x))


def quy_cach_da_biet(kb_page, msgs, pid=None, ca_km=False):
    """{(số, họ): câu nguồn} — quy cách 1 hộp / 1 chai mà NGUỒN TIN ĐƯỢC có ghi: bảng QUY_CACH_PAGE, kịch bản page, tin
    SALE / Botcake trong hội thoại. Tin AI KHÔNG tính — chính AI từng nói 1 / 2 / 7 / 15 / 30 sachets cho cùng một hộp.
    ca_km=True: lấy cả số trong câu khuyến mãi (dùng cho họ vỏ chai / hộp: "Buy 1 Get 1 = 2 bottles")."""
    s = _qc_chu_nguon(kb_page, msgs, pid)
    ra = _qc_tim_so(s, [_QC_NGUON_RONG], bo_km=not ca_km)
    for k, v in _qc_tim_so(s, [_QC_NGUON_G]).items():    # gram (23/09) — giữ cả dòng "Total Net Weight: 100g"
        ra.setdefault(k, v)
    for k, v in _qc_tim_so(s, _QC_CAU).items():     # mẫu chặt ("Each box contains 10 sachets", "1 box = 2 pcs")
        ra.setdefault(k, v)
    return ra


def quy_cach_tra_loi_duoc(cau, kb_page, msgs, pid=None):
    """Nguồn tin được có số trả lời câu quy cách khách hỏi không (hỏi ml cần số ml; hỏi mấy gói/viên cần số đếm)."""
    ho = {h for _, h in quy_cach_da_biet(kb_page, msgs, pid)}
    if re.search(_QC_HOI_G, cau or "", re.I | re.U):          # 23/09 hỏi gram / cân nặng → cần số gram
        # LUẬT 20/09 (chủ shop, ca Loida · Lapad): page VÀNG không ghi gram → số riêng của page (TRONG_LUONG_PAGE) hoặc
        # bảng cân chuẩn (TRONG_LUONG_CHUAN) — KHÔNG treo. Vá gram 23/09 lần 1 treo cả mấy page này, chủ shop bắt lại.
        return ("g" in ho or bool(_CO_SO_GAM.search(json.dumps(kb_page or {}, ensure_ascii=False)))
                or bool(trong_luong_goi_y(kb_page, pid)))
    if re.search(r"(?<![a-z])ml(?![a-z])|毫升|مل", cau or "", re.I | re.U):
        return "ml" in ho
    if re.search(r"\b(?:laman|isi(?:nya)?|inside|contains?|in\s+it)\b", cau or "", re.I):
        return bool(ho & {"dem", "ml"})
    return "dem" in ho


def _qc_so_khop(n, ho, biet, biet_vo, boi_so):
    if ho in ("chai", "hop"):
        return n == 1 or (n, ho) in biet_vo               # "1 kotak isinya 1 botol" — mặc định, không rủi ro
    cung = [b for b, h in biet if h == ho]
    return any(abs(n - b) < 1e-9 or (boi_so and n > b and abs(n / b - round(n / b)) < 1e-9 and round(n / b) <= 12)
               for b in cung)


def bia_quy_cach(tin, kb_page, msgs, pid=None):
    """Câu AI tự khẳng định quy cách ("1 pack = 1 sachet", "each box has 30 sachets", "each bottle is 150ml") mà nguồn
    tin được KHÔNG có đúng số đó → chuỗi mô tả; không thì None. Số gói/viên của 1 hộp phải KHỚP ĐÚNG (hộp 10 gói mà nói
    30 là sai, dù 30 = 3 hộp); ml được là bội số ("2 chai 100ml = 200ml")."""
    noi = so_quy_cach(tin)
    if not noi:
        return None
    biet = quy_cach_da_biet(kb_page, msgs, pid)
    biet_vo = {k for k in quy_cach_da_biet(kb_page, msgs, pid, ca_km=True) if k[1] in ("chai", "hop")}
    la = [f"{n:g} {({'ml': 'ml', 'chai': 'chai', 'hop': 'hộp'}).get(ho, 'gói/viên')}"
          for (n, ho) in sorted(noi, key=lambda x: (x[1], x[0])) if not _qc_so_khop(n, ho, biet, biet_vo, ho == "ml")]
    return ", ".join(la) if la else None


def _qc_so_le_con_lai(t, kb_page, msgs, pid=None):
    """Sau khi cắt: câu còn "N sachets / N ml" nào không khớp nguồn (kể cả số TỔNG như "14 sachets total" suy từ số bịa)?"""
    biet = quy_cach_da_biet(kb_page, msgs, pid)
    return [k for k in _qc_tim_so(_qc_sach(t), [_QC_NGUON_RONG]) if k[1] in ("dem", "ml")
            and not _qc_so_khop(k[0], k[1], biet, set(), True)]


def cat_cau_quy_cach(tin, kb_page, msgs, pid=None):
    """Bỏ phần quy cách tự bịa, giữ phần còn lại: ngoặc "(100ml)" thì bỏ ngoặc, không thì bỏ cả câu. Còn số gói/ml lạ,
    còn quá ngắn, hoặc chỉ còn chào + câu chốt → None (treo)."""
    goc = (tin or "").strip()

    def _bo_ngoac(m):
        return "" if bia_quy_cach(m.group(0), kb_page, msgs, pid) else m.group(0)
    t = re.sub(r"\s*\([^()]{0,60}\)", _bo_ngoac, goc)
    kq = _don_cau(" ".join(c for c in re.split(_NGAT_CAU, t) if c.strip() and not bia_quy_cach(c, kb_page, msgs, pid)))
    if (len(kq) < 40 or kq == goc or bia_quy_cach(kq, kb_page, msgs, pid) or _qc_so_le_con_lai(kq, kb_page, msgs, pid)
            or chi_con_cau_chot(kq)):
        return None
    return kq


def dong_quy_cach(pid, cau_hoi=None):
    """Dòng tình huống cho page có số quy cách do sale xác nhận (QUY_CACH_PAGE) — gắn MỌI lượt."""
    qc = QUY_CACH_PAGE.get(str(pid or ""))
    if not qc:
        return ""
    return ("📦 QUY CÁCH HÀNG (sale shop đã xác nhận — kịch bản không ghi): " + qc
            + (f" KHÁCH VỪA HỎI: \"{cau_hoi[:140]}\" → câu ĐẦU trả lời ĐÚNG con số này, đúng tiếng khách."
               if cau_hoi else "")
            + " ⛔ Gọi gói khuyến mãi bằng ĐÚNG đơn vị bán ở trên — CẤM gọi là cup / sachet / bottle, CẤM đổi con số, "
              "CẤM suy từ liều dùng ('1 sachet a day' là cách uống, KHÔNG phải số gói trong hộp).\n")


def _dong_hoi_gram(cau, kb_page, biet, pid=None):
    """Khách hỏi GRAM — nguồn theo đúng thứ tự dong_thong_so (luật 20/09): số riêng của page (TRONG_LUONG_PAGE, sale shop
    đã nói) → gram trong kịch bản / tin sale-Botcake → bảng cân chuẩn theo dòng hàng (page vàng thật). Không có → ""."""
    g = sorted({v for (_n, h), v in biet.items() if h == "g"})[:3]
    goi_y = TRONG_LUONG_PAGE.get(str(pid or "")) or (None if g else trong_luong_goi_y(kb_page, pid))
    if goi_y:
        nguon = f"kịch bản page không ghi, dòng hàng của shop thì có: {goi_y}"
    elif g:
        nguon = "kịch bản / tin sale CÓ ghi: " + " | ".join(g)
    else:
        return ""
    return (f"📦 KHÁCH HỎI CÂN NẶNG: \"{cau[:140]}\" — {nguon}. Câu ĐẦU trả lời ĐÚNG con số đó (gram), đúng tiếng khách, nói "
            "tự nhiên như người bán biết hàng mình. ⛔ CẤM đổi số, CẤM hứa hỏi shop rồi báo lại, CẤM lờ câu hỏi đi.\n")


def dong_hoi_quy_cach(cau, kb_page, msgs, pid=None):
    """Dòng tình huống: khách hỏi quy cách và kịch bản / tin sale CÓ số → trả lời đúng số đó."""
    biet = quy_cach_da_biet(kb_page, msgs, pid)
    if re.search(_QC_HOI_G, cau or "", re.I | re.U):             # 23/09 hỏi gram → khối riêng (luật 20/09)
        return _dong_hoi_gram(cau, kb_page, biet, pid)
    if not biet:
        return ""
    return (f"📦 KHÁCH HỎI QUY CÁCH: \"{cau[:140]}\" — kịch bản / tin sale CÓ ghi: "
            + " | ".join(sorted(set(biet.values()))[:3])
            + ". Câu ĐẦU trả lời ĐÚNG con số đó, đúng tiếng khách. ⛔ CẤM đổi số, CẤM suy từ liều dùng / cách pha.\n")


# SỐ / LINK WHATSAPP CỦA SHOP ĐÃ NGƯNG (chủ shop 20/09, ca Ismail — Sakura Skin Care KSA: AI gửi
# "wa.me/+12027736276" cho khách xin WhatsApp). Số đó không còn ai nhận: khách nhắn vào là đơn chết
# lặng, sale cũng không thấy. Kịch bản 286/337 page vẫn còn link nên model chép ra rất dễ — prompt
# không đủ, phải chặn bằng máy. HƯỚNG MỚI: không đưa số của mình nữa, mà XIN SỐ WHATSAPP CỦA KHÁCH
# rồi shop nhắn trước, khách gửi vị trí ở đó.
# Có số WhatsApp mới chạy được thì bỏ số đó khỏi danh sách này — không phải sửa chỗ nào khác.
SO_WA_NGUNG = ("12027736276", "971543610815", "18702097265")


def _pat_so_wa(s):
    """Số viết rời ("+971 54 361 0815", "1-202-773-6276") vẫn phải bắt được."""
    return r"\+?\s*" + r"[\s.\u2011\u2013()-]{0,2}".join(s)


WA_SHOP = re.compile(
    r"(?:https?://)?(?:www\.)?(?:wa\.me|wa\.link|api\.whatsapp\.com/send|chat\.whatsapp\.com)/?\S*"
    + "".join("|" + _pat_so_wa(x) for x in SO_WA_NGUNG), re.I | re.U)

CHE_WA = "[dead WhatsApp number - never send it; ask the customer for THEIR WhatsApp instead]"


# CHỐI VIỆC BÊN MÌNH NHẮN WHATSAPP (chủ shop 20/09, ca Marry F Mamauag — Golden Soap House KSA).
# Nhân viên shop CÓ nhắn khách qua WhatsApp. Luật "không đưa số của mình" sáng nay bị model hiểu
# rộng thành phủ nhận: "hindi po ako ang nag-message sa WhatsApp niyo… hindi po ako iyon". Khách
# đang nói chuyện với đúng shop mà bị chối thì mất tin ngay. Cấm cứng, không tin prompt.
CHOI_WA = re.compile(
    r"hindi\s+(?:po\s+)?(?:ako|kami)\s+(?:ang\s+)?(?:nag-?|nagme|nag\s)?(?:message|text|contact)"
    r"|hindi\s+(?:po\s+)?(?:ako|kami)\s+(?:iyon|yun|yon|ito)"
    r"|(?:di|hindi)\s+(?:po\s+)?(?:ako|kami)\s+(?:ang\s+)?(?:nag-?(?:message|text|usap|kausap)|kausap)"
    r"|(?:that|it|this)\s+(?:was\s?n[o']?t|is\s?n[o']?t|wasn't)\s+(?:me|us)"
    r"|\b(?:i|we)\s+(?:did\s?n[o']?t|didn't|never)\s+(?:message|text|contact|write|send you)"
    r"|\bnot\s+(?:me|us)\s+who\b"
    r"|\b(?:we|i)\s+(?:do\s?n[o']?t|don't)\s+(?:have|use)\s+whats?\s*app"
    r"|wala\s+(?:po\s+)?kaming\s+whats?\s*app"
    r"|\u0644\u0633\u062a\s+\u0623\u0646\u0627|\u0644\u0645\s+\u0623\u0631\u0627\u0633\u0644\u0643|\u0645\u0627\s+\u0631\u0627\u0633\u0644\u062a\u0643",
    re.I | re.U)


def cat_wa_shop(t):
    """Bỏ HẲN câu nào có link/số WhatsApp đã ngưng; còn lại quá ngắn thì trả None.

    Cố ý KHÔNG gỡ mỗi con số trong câu: đo trên 96 tin AI đã gửi thật, gỡ trơ để lại câu cụt
    ("You can reach us on WhatsApp here:", "Our WhatsApp number is.") — khách đọc ra lỗi. Trả None
    = chỗ gọi phải soạn lại (xin số của KHÁCH) hoặc treo; thà im còn hơn gửi số chết.
    """
    goc = (t or "").strip()
    giu = [c for c in re.split(_NGAT_CAU, goc) if c.strip() and not WA_SHOP.search(c)]
    kq = _don_cau(" ".join(giu))
    if WA_SHOP.search(kq) or len(kq) < 40:
        return None
    return kq


# "لا لا ماقد اشتريت" / "No" / "first time" ĐÁP câu page vừa hỏi "bạn mua ở page khác à?" là TRẢ LỜI (khách
# mới), không phải từ chối — ca محمد جعفر 19/09 (Al Shifa Denture Saudi): AI níu "sao bạn còn lưỡng lự?" rồi gửi
# 6 ảnh feedback cho khách vừa nói "tôi chưa mua". Chỉ tính khi MỌI tin khách sau câu hỏi đó đều là kiểu này.
_CHUA_MUA_O_DAU = re.compile(
    r"^\W*(?:(?:لا|no|nope|nah|hindi|wala|di|not|never|none|la|po)\b\W*)+$"
    r"|ما\s*(?:قد\s*)?اشتريت|ماشتريت|لم\s+(?:أ|ا)?شتر|ما\s*(?:قد\s*)?طلبت|اول\s+مرة|أول\s+مرة"
    r"|\b(?:never|not|haven'?t|havent|didn'?t|didnt|did\s+not|have\s+not)\s+(?:yet\s+)?(?:bought|buy|order(?:ed)?"
    r"|purchased?|avail(?:ed)?)|\bfirst\s+time|\b(?:hindi|di|wala)\s+pa\s+(?:po\s+)?(?:ako|akong|ko|kami)", re.I | re.U)


def _dap_hoi_nham_shop(msgs):
    msgs = msgs or []
    i = max((k for k, m in enumerate(msgs) if m.get("boi") in ("ai", "nguoi", "botcake")), default=None)
    if i is None or not CG._HOI_NHAM_SHOP.search(lam_sach(msgs[i].get("text") or "")):
        return False
    sau = [lam_sach(m.get("text") or "").strip() for m in msgs[i + 1:] if m.get("boi") == "khach"]
    sau = [x for x in sau if x]
    return bool(sau) and all(_CHUA_MUA_O_DAU.search(x) for x in sau)


# "OK THANKS" SAU KHI PAGE ĐÁP CÂU HỎI — KHÁCH ĐÃ Ở BƯỚC GIAO HÀNG (chủ shop 23/09, ca Riesalyn Galvez Dela Cruz ·
# Hitana Store in Saudi, #76709): "Ok I will order 2 sets" → "0548165797 Al faysaliyah dist." → "How many days
# deliver???" → page "It takes 3-7 days" → "Ok thanks" → luật Fe Borabo coi là từ chối → nhánh níu "Shall I reserve
# today's promo… only valid today" với khách đang chờ giao hàng. Lời cảm ơn / ậm ừ NGAY SAU khi phía shop (AI /
# Botcake / sale) trả lời một CÂU HỎI của khách (ngày giao, phí ship, COD…), mà trong PHIÊN này khách đã cho SĐT bản
# địa / địa chỉ / câu chốt số lượng (theo HS.trich) → khách đang nhận câu trả lời, KHÔNG phải từ chối.
# "No thanks" / "not interested" / "mahal" không lọt bộ chữ dưới → vẫn là từ chối như cũ.
_CAM_ON_AM_U = re.compile(
    r"^\W*(?:(?:ok+(?:ay|ey|ie|i|s)?|oky|okey|okie|okies|kay|oo+|opo|sige|noted|got\s*it|alright|all\s*right|sure"
    r"|yes+|yeah|yup|yep|copy|great|perfect|thank\s*(?:s|you|u)|thanks?|thankyou|thnx|thnks|tnx|tysm|ty"
    r"|salamat|maraming|so\s+much|very\s+much|a\s+lot|for\s+(?:the\s+)?(?:info|information|reply|response|update|answer)"
    r"|شكرا|شكراً|مشكور|مشكورة|تمام|طيب|اوك|أوك|اوكي|أوكي|ماشي|حسنا|謝謝|多謝|好的"
    r"|po|dear|maam|ma'?am|mam|sir|madam|sis|ate|kuya|bro|na|then|you|u|too)(?:\W+|$))+$", re.I | re.U)


def _khach_dang_hoi(u):
    """Câu khách là câu hỏi: dấu ?, chữ hỏi đầu/giữa câu, hỏi giá hay mấy ngày giao; câu NGẮN (≤ 12 từ) nhắc phí ship /
    cách trả tiền cũng tính (Tagalog hay bỏ dấu ?). Bỏ link trước khi xét — "?g_st=" trong link Google Maps không phải
    hỏi; tin FORM dài có chữ "shipping" cũng không phải hỏi (đo 24/09 trên 14.000 lượt: 3 ca lỏng kiểu này)."""
    u = re.sub(r"https?://\S+", " ", u or "").strip()
    if not u:
        return False
    ngan = len(u.split()) <= 12
    return bool(HS.la_cau_hoi(u) or HS.la_cau_hoi_dia_chi(u) or chi_hoi_gia_hay_giao(u) or HOI_GIA.search(u.lower())
                or (ngan and (_HOI_PHI_SHIP.search(u) or khach_hoi_thanh_toan(u))))


def cam_on_o_buoc_giao_hang(msgs, mkey=None):
    """Tin khách CUỐI chỉ là cảm ơn / ậm ừ, đứng NGAY SAU tin phía shop trả lời một câu hỏi của khách, và trong phiên
    này khách đã cho SĐT bản địa / địa chỉ / số lượng → True. Không biết thị trường thì thử mọi thị trường trong
    markets.json (mỗi tiến trình chat chỉ chạy một nước, nhưng hàm từ chối không nhận mkey)."""
    msgs = msgs or []
    i = next((k for k in range(len(msgs) - 1, -1, -1)
              if msgs[k].get("boi") == "khach" and lam_sach(msgs[k].get("text") or "").strip()), None)
    if i is None:
        return False
    t = lam_sach(msgs[i].get("text") or "").strip()
    if len(t.split()) > 8 or not _CAM_ON_AM_U.match(t):
        return False
    # Lùi qua các tin cảm ơn liền nhau ("ok" rồi "thanks") + tin hệ thống → tin ngay trước phải là PHÍA SHOP có chữ.
    j = i - 1
    while j >= 0 and (msgs[j].get("boi") == "hethong" or (msgs[j].get("boi") == "khach" and (
            not lam_sach(msgs[j].get("text") or "").strip() or _CAM_ON_AM_U.match(lam_sach(msgs[j].get("text") or "").strip())))):
        j -= 1
    if j < 0 or msgs[j].get("boi") not in ("ai", "botcake", "nguoi") or not lam_sach(msgs[j].get("text") or "").strip():
        return False
    # Lùi qua cụm tin phía shop → cụm tin khách liền trước (≤ 3 tin) phải có MỘT câu hỏi, và không tin nào là từ chối / chê đắt.
    while j >= 0 and msgs[j].get("boi") != "khach":
        j -= 1
    hoi = []
    while j >= 0 and len(hoi) < 3 and msgs[j].get("boi") in ("khach", "hethong"):
        if msgs[j].get("boi") == "khach":
            u = lam_sach(msgs[j].get("text") or "").strip()
            if u:
                hoi.append(u)
        j -= 1
    if not hoi or not any(_khach_dang_hoi(u) for u in hoi) or any(khach_dang_tu_choi(u) or la_che_dat(u) for u in hoi):
        return False
    # Khách đã ở bước giao hàng — chỉ xét tin trong PHIÊN hiện tại (dau_phien), không lấy địa chỉ 3 tháng trước.
    p = msgs[dau_phien(msgs):i + 1]
    ds = [mkey] if mkey else [k for k in HS._markets() if not str(k).startswith("_")]
    for mk in ds:
        try:
            co = HS.trich(p, mk)
        except Exception:                                  # noqa: BLE001 — bảng thị trường hỏng thì bỏ nước đó
            continue
        if (co.get("sdt") and not co.get("sdt_ngoai")) or co.get("dia_chi") or co.get("so_luong"):
            return True
    return False


# Lời ĐỆM sau lời từ chối ("To much" → "Sorry", "mahal po" → "pasensya na") — 24/09, ca Muskan Kc Iboss · Dubai Luxe Charm.
_XIN_LOI_DEM = re.compile(r"\b(?:sorry|sori|sorri|soory|sowwy|sry|pasensya|pasensiya|pacensya|pasenxa|patawad|apologi[sz]e"
                          r"|excuse\s+me)\b|آسف|اسف|معليش|معذرة", re.I | re.U)


def _chuoi_khach_chua_dap(msgs):
    """Các tin khách (có chữ) sau tin page gần nhất, cũ → mới."""
    ra = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                ra.append(m)
        elif m.get("boi") != "hethong":
            break
    return ra[::-1]


# Lời từ chối CHUNG CHUNG, không thêm ý mới ("thanks no need", "Its ok thanks", "No money") — đứng sau lời chê đắt thì lý do
# vẫn là GIÁ. Câu có ý mới ("So many people buy this but no effect", "Next time we don't budget now") thì giữ câu mới.
_TU_CHOI_CHUNG = re.compile(r"\b(?:no|nope|need|thanks?|thx|ty|you|u|ok|okay|its?|it'?s|sige|nalang|lang|na|maybe|next|time"
                            r"|later|money|pera|wala|salamat|po)\b", re.I)


def _loi_dem_ngan(t):
    t = lam_sach(t or "")
    if "?" in t or re.search(r"\d", t):
        return False
    con = _TU_CHOI_CHUNG.sub(" ", _CHAO_DEM.sub(" ", CHAO_TAM_BIET.sub(" ", _XIN_LOI_DEM.sub(" ", t))))
    return len(re.findall(r"[^\W\d_]+", con, re.U)) <= 1


def _tu_choi_truoc_loi_dem(msgs):
    """Tin từ chối trong chuỗi khách CHƯA được đáp mà mọi tin SAU nó chỉ là lời đệm (sorry / chào / cảm ơn / emoji) → tin đó;
    không thì None."""
    chua = _chuoi_khach_chua_dap(msgs)
    for j in range(len(chua) - 1, -1, -1):
        t = lam_sach(chua[j].get("text")).strip()
        if khach_dang_tu_choi(t):
            return chua[j] if j < len(chua) - 1 else None
        con = _CHAO_DEM.sub(" ", CHAO_TAM_BIET.sub(" ", _XIN_LOI_DEM.sub(" ", t)))
        if "?" in t or re.search(r"\d", t) or re.findall(r"[^\W\d_]+", con, re.U) or not _XIN_LOI_DEM.search(t):
            return None                              # tin sau lời từ chối có nội dung khác / không phải lời xin lỗi đệm
    return None


def tinh_huong_tu_choi(msgs):
    """(câu khách, lượt níu 1..LUOT_NIU+1, tập giá đã báo) nếu tin cuối của khách là lời từ chối — hoặc lời chào/cảm
    ơn ngay sau lời từ chối (ca Lucy JJ 14/09); không thì None. Lượt LUOT_NIU+1 = đã níu đủ, treo cho sale."""
    kh = [m for m in (msgs or []) if m.get("boi") == "khach" and lam_sach(m.get("text")).strip()]
    _dem_tc = _tu_choi_truoc_loi_dem(msgs)             # "To much" → "Sorry" (24/09)
    if not kh or not (khach_dang_tu_choi(kh[-1]["text"]) or khach_chao_sau_tu_choi(msgs) or _dem_tc):
        return None
    if _dap_hoi_nham_shop(msgs):
        return None
    if _dap_cau_hoi_giao(msgs):              # 26/09: "No, sa PO Box lang" đáp câu hỏi giao hàng của page
        return None
    # Khách hỏi giá mà CHƯA ai báo con số (ca Madu Pathiraja 23/09 · Kuwait Luxe Charm): "How much" → "Price" →
    # "Ok .. thanks" trong 16 giây, không tin page nào có giá. Luật Fe Borabo ("ok thanks" = từ chối) chỉ đúng khi
    # khách ĐÃ thấy giá; coi là từ chối thì nhánh níu cấm nêu giá → AI gửi câu giữ ưu đãi, khách vẫn không có giá.
    if khach_dang_cho_gia(msgs):
        return None
    # "Ok thanks" ngay sau khi page trả lời câu hỏi, khách đã cho SĐT/địa chỉ/số lượng (ca Riesalyn 23/09) → không
    # phải từ chối; để nhánh níu "Shall I reserve today's promo" không chạy với khách đang chờ giao hàng.
    if cam_on_o_buoc_giao_hang(msgs):
        return None
    # Đếm trong PHIÊN hiện tại (sau mốc mở phiên mới, ≤ LUONG_HIEU_LUC_GIAY) — trần 5 lượt thì một câu "ok thanks"
    # tuần trước cũng đủ đẩy khách sang treo sớm.
    dau = max([k for k, m in enumerate(msgs) if m.get("boi") == "hethong" and _MO_PHIEN_MOI.search(m.get("text") or "")]
              or [0])
    moi = _moc_giay(kh[-1].get("luc"))
    kh_p = [m for m in msgs[dau:] if m.get("boi") == "khach" and lam_sach(m.get("text")).strip()
            and (moi is None or (_moc_giay(m.get("luc")) or moi) >= moi - LUONG_HIEU_LUC_GIAY)] or kh[-1:]
    lan = sum(1 for j, m in enumerate(kh_p) if khach_dang_tu_choi(m["text"]) or _la_chao_sau_tu_choi(kh_p, j))
    # Câu đưa model: lời CHÊ ĐẮT trong chuỗi chưa đáp nếu có ("To much" rồi "Sorry" / "mahal" rồi "thank you") — khối
    # CHÊ ĐẮT + chứng minh giá dò theo câu này; không thì lời từ chối trước lời đệm; không thì tin cuối như cũ.
    _chuoi = _chuoi_khach_chua_dap(msgs)
    _cd = [j for j, m in enumerate(_chuoi) if la_che_dat(m.get("text") or "")]
    _cau_m = _dem_tc or kh[-1]
    if _cd and all(_loi_dem_ngan(m.get("text")) for m in _chuoi[_cd[-1] + 1:]):
        _cau_m = _chuoi[_cd[-1]]                  # tin sau chỉ là "thanks / no / no need / sorry / no money"
    return lam_sach(_cau_m["text"])[:120], min(max(lan, 1), LUOT_NIU + 1), tien_page_da_noi(msgs)


# FEEDBACK KHÁCH THẬT Ở LƯỢT NÍU 2 (chủ shop 14/09 tối, ca Lucy JJ): 131/290 page có mẫu tên "Feedback…" kèm ảnh.
MAU_FEEDBACK = re.compile(r"feed\s*back|testimon|review|phản\s*hồi|đánh\s*giá", re.I)


# Nội dung của một mẫu FEEDBACK khi câu trả lời nhanh không được đặt tên (Pancake trả shortcut rỗng cho
# 1.345 mẫu / 176 page — đo 20/09). Phải chặt: "lucky customers who can still secure…" là lời chào hàng.
_ND_FEEDBACK = re.compile(
    r"\bfeed\s*backs?\b|\breviews?\b|\btestimonial|\b(?:happy|satisfied)\s+(?:and\s+|at\s+)?(?:happy\s+|satisfied\s+)?"
    r"customers?\b|\breceived\s+theirs\b|آراء|تقييم", re.I | re.U)


def mau_feedback(kb_page, msgs):
    """Mẫu feedback CÓ ẢNH của page mà hội thoại chưa gửi (nhiều ảnh nhất trước), không có thì None.

    Ưu tiên mẫu ĐẶT TÊN "Feedback"; page không đặt tên mẫu thì dò theo NỘI DUNG (20/09, chủ shop:
    *"có thẻ feedback có nội dung và ảnh luôn r mà"* — đúng với 161/337 page, số còn lại mẫu không có tên).
    """
    mau = (kb_page or {}).get("mau") or []
    ds = [m for m in mau
          if MAU_FEEDBACK.search(m.get("tu_khoa") or "") and m.get("anh") and (m.get("tu_khoa") or "").strip()]
    if not ds:                       # không có mẫu đặt tên → dò nội dung, bắt buộc có ảnh
        ds = [m for m in mau if m.get("anh") and _ND_FEEDBACK.search(" ".join(m.get("tin") or []))]
    ds = [m for m in ds if not da_gui_huong_dan(msgs or [], m)]
    return max(ds, key=lambda m: len(m["anh"]), default=None)


def feedback_luot_niu(msgs, kb_page, pid, mkey=None):
    """Mẫu feedback phải gửi kèm lượt này (lượt níu 2, page này gửi được ảnh), không thì None."""
    tc = tinh_huong_tu_choi(msgs)
    if not tc or tc[1] != 2 or not anh_gui_duoc(mkey, pid) or hen_giao_theo_luong(msgs):
        return None
    return mau_feedback(kb_page, msgs)


# KHACH_VUA_CHON_GOI — chủ shop 2026-09-14, ca Gha Cabilin Plaza (Kreain Nature PH - Ksa): page hỏi
# "buy 1 get 1 hay buy 2 get 2?", khách "Only 1 items to try / If good and true i order more", AI đáp
# 430 ký tự chào lại B1G1 + giảng COD + "thử trước rồi mua thêm", câu cuối mới xin SĐT (còn lọt chữ
# "SĐT"). *"khách đã chốt số lượng 1, thì bạn rep xin thông tin để gửi hàng, chứ rep cái gì vậy"*.
# Gốc: HS.trich không nhận "1 items" nên hồ sơ ghi "còn thiếu số lượng". Luật cứng ở vòng soạn:
# khách vừa chọn gói mà tin AI dài / không xin thông tin giao hàng → bắt soạn lại đúng một lần.
XIN_THONG_TIN = re.compile(
    r"contact|phone|mobile|whatsapp|\bnumber\b|\bno\.|address|location|\bname\b|tirahan|numero"
    r"|رقم|عنوان|اسم|موقع|電話|地址|姓名", re.I | re.U)
TIN_CHOT_GOI_TOI_DA = 300
# Khách còn HỎI cách dùng / NGHI hiệu quả → chưa phải chốt gói, dù có "1 bottle", "this one".
CON_NGHI = re.compile(
    r"\b(?:use|used|using|usage|apply|question|options?|possible|show\s+me|price|magkano|mgkano|mkano"
    r"|halimbawa|haw|koto|effective|effect|results?|work(?:s|ing)?|sure|real|really|original|legit"
    r"|fake|safe|side\s*effects?|how|what|why|can|could|does|do\s+you|is\s+it|are\s+you|ba|kaya|totoo"
    r"|gamitin|gumagana|epektibo|hiyang)\b|هل|كيف|فعال|مضمون|أصلي", re.I | re.U)


DON_CU_CHU = re.compile(r"\bmy\s+order\b|\breceived?\b|\bdeliver(?:ed|y)\b|\bparcel\b", re.I)
# KHÁCH XIN FEEDBACK (chủ shop 20/09: *"khách hỏi feedback thì b phải gửi cho khách chứ"*). Tin thường là
# đúng một chữ "Feedback" do khách BẤM NÚT của Botcake (ca Neethu Anil · Oman Gold Lucky Jewelry).
XIN_FEEDBACK = re.compile(
    r"\bfeed\s*backs?\b|\bfeedbacks?\b|\bfeedbck\b|\bfeedbak\b|\bfidback\b|\breviews?\b|\btestimonial"
    r"|\bproofs?\b|\b(?:customers?|real|actual)\s+(?:photos?|pictures?|pics?|feedbacks?|reviews?)"
    r"|\bpatunay\b|\bpatotoo\b|تقييم|مراجع|تجارب|آراء", re.I | re.U)
# ĐỘ DÀI DÂY CHUYỀN — chủ shop 20/09: page trang sức nào kịch bản không ghi thì lấy 16–22 inches.
_HOI_DO_DAI = re.compile(r"\b(?:length|lenght|lenth)\b|\b\d{1,2}\s*(?:inch|inches)\b|\binch(?:es)?\b"
                         r"|how\s+many\s+inch|الطول|كم\s*طول", re.I | re.U)
_KB_CO_DO_DAI = re.compile(r"\b\d{1,2}\s*(?:-|–|to)\s*\d{1,2}\s*(?:inch|inches|cm)\b"
                           r"|\b\d{1,2}\s*(?:inch|inches)\b|\blength\b|طول", re.I | re.U)
_LA_TRANG_SUC = re.compile(r"\b(?:necklace|chain|pendant|bracelet|earrings?)\b|سلسلة|قلادة", re.I | re.U)
DO_DAI_MAC_DINH = "16–22 inches"


# 💬 "FEEDBACK" = KHÁCH XIN XEM PHẢN HỒI (chủ shop 23/09, ca Roxie Velliza · Veloura Collection): khách bấm "Feedback", Botcake
# gửi 6 ảnh feedback (không chữ) → AI vẫn vào và viết "Salamat po sa feedback, Roxie" = cảm ơn phản hồi CỦA KHÁCH. Chủ shop:
# *"FEEDBACK ở đây là khách xin phản hồi của những khách hàng khác"*. khach_xin_feedback chỉ nhìn tin khách SAU tin page cuối —
# Botcake đã chen ảnh vào nên không thấy; hàm dưới nhìn tin khách MỚI NHẤT trong 6 tin gần nhất.
_CAM_ON_FEEDBACK = re.compile(
    r"\b(?:salamat|thanks?|thank\s+you|maraming\s+salamat)\b[^.!?\n]{0,25}\b(?:feed\s*back|reviews?)\b"
    r"|cảm\s+ơn\s+(?:phản\s+hồi|feedback|nhận\s+xét)|شكرا[^.!?\n]{0,20}(?:تقييم|رأي)", re.I | re.U)


def khach_vua_xin_feedback(msgs):
    """Tin khách MỚI NHẤT (trong 6 tin gần nhất) là lời xin xem feedback / review ("Feedback", "reviews?")."""
    for m in reversed((msgs or [])[-6:]):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            # 28/09: trần 8 chữ làm trượt "any feed back s mga naka bili n if real" (10 chữ, ca Rhina
            # Medina) — nới lên 14 và loại thẳng câu CẢM ƠN feedback thay vì dựa vào độ dài.
            return (bool(t) and len(t.split()) <= 14 and bool(XIN_FEEDBACK.search(t))
                    and not _CAM_ON_FEEDBACK.search(t))
    return False


def co_anh_feedback(kb_page, msgs, mkey=None, pid=None):
    """Page có ảnh feedback gửi được ngay lượt này không (mẫu /Feedback, hoặc ảnh dò bằng chữ)."""
    if mkey and pid and not anh_gui_duoc(mkey, pid):
        return False
    m = mau_feedback(kb_page, msgs)
    return bool([u for u in ((m or {}).get("anh") or []) if u] or anh_feedback(kb_page))


def feedback_chua_duoc_dap(msgs, lui=6):
    """Lời xin xem feedback còn TREO: khách xin trong `lui` tin gần nhất, mà từ đó tới giờ page chưa
    gửi tấm ảnh nào và AI cũng chưa nói gì.

    Ca Rhina Medina · Lapad Jewelry KSA 28/09 (chủ shop *"sao b k gửi feedback cho khách"*): khách xin
    feedback, Botcake chen vào đáp chuyện vàng thật bằng CHỮ → `khach_xin_feedback` chỉ soi tin khách
    CHƯA ĐƯỢC ĐÁP nên hoá mù, AI im. Botcake/sale gửi ẢNH sau lời xin thì coi như đã đáp (khách đã thấy
    feedback rồi); AI đã nói gì đó sau lời xin cũng thôi — tránh lặp ở page không gửi được ảnh."""
    ds = (msgs or [])[-lui:]
    vt = None
    for k, m in enumerate(ds):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t and XIN_FEEDBACK.search(t) and not _CAM_ON_FEEDBACK.search(t):
                vt = k
    if vt is None:
        return False
    for m in ds[vt + 1:]:
        if m.get("boi") in ("ai", "nguoi", "botcake") and (m.get("co_dinh_kem") or m.get("anh")):
            return False
        if m.get("boi") == "ai" and lam_sach(m.get("text") or "").strip():
            return False
    return True


def khach_xin_feedback(msgs, so_tin=3):
    """Khách vừa xin feedback / ảnh khách thật trong các tin chưa được đáp — hoặc lời xin cũ vẫn còn
    treo vì Botcake chen chữ vào giữa (xem `feedback_chua_duoc_dap`)."""
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                kh.append(t)
        elif m.get("boi") != "hethong":
            break
    if any(XIN_FEEDBACK.search(t) for t in kh[:so_tin]):
        return True
    return feedback_chua_duoc_dap(msgs)
# KHÁCH XIN ẢNH SẢN PHẨM (chủ shop 2026-09-20, ca Jeana Miranda · Flat Jewelry KSA in Dubai 09:34 CEST):
# khách gửi ảnh vòng tay + "Like this breclet" + "Give me pictures"; AI đáp *"the bracelet designs we have are
# the ones our team already sent above — please pick the one you like"* kèm ghi chú nhờ sale, rồi 4 phút sau
# SALE phải tự gửi ảnh + "We only have this design". Chủ shop: *"sao b k gửi mà báo sale gửi"*.
# Đo sổ việc 10→20/09: 68 lượt AI ghi chú nhờ sale gửi ảnh, **62 lượt (91%) là page CÓ SẴN mẫu kèm ảnh**
# (4–7 ảnh) — AI cầm ảnh trong tay mà vẫn đẩy việc sang người. Đo regex trên 824 tin khách thật: khớp 8 tin
# (1,0%), cả 8 đều là xin ảnh/mẫu thật; "Send ko po ung pic" / "The last pic i send" (khách GỬI ảnh) không dính.
XIN_ANH_KHACH = re.compile(
    # ① tin gần như chỉ có chữ "ảnh" ("Picture", "Only picture", "photo po")
    r"^\W*(?:can\s+i\s+see\s+|pa|please\s+|pls\s+|only\s+|just\s+|more\s+|other\s+|another\s+|any\s+|the\s+|some\s+)*"
    r"(?:pic|pics|picture|pictures|photo|photos|pix|image|images|foto|fotos|larawan|litrato|gambar)"
    r"(?:\s*(?:please|pls|po|naman|lang|ya|dong|sir|ma'?am))*\W*$"
    # ② câu xin rõ ràng
    r"|\b(?:send|give|show|share|post|upload)\s+(?:me\s+|us\s+|to\s+me\s+|the\s+|some\s+|more\s+|other\s+|another\s+|a\s+|any\s+)*"
    r"(?:pic|pics|picture|pictures|photo|photos|image|images|video|videos|design|designs|model|models|sample|samples|catalog\w*|larawan|foto|gambar)\b"
    r"|\b(?:can|could|may|pwede)\s+(?:i|we|ko|po)?\s*(?:see|view|check|makita|tingnan)\b"
    r"|\bi\s+(?:want|wanna|would\s+like|need)\s+to\s+see\b|\blet\s+me\s+see\b|\blooking\s+for\s+(?:pic|photo)"
    r"|\b(?:any|more|other|another|different|new)\s+(?:pic|pics|picture|pictures|photo|photos|design|designs|model|models|style|styles|colou?rs?)\b"
    r"|\bpa(?:hingi|kita|tingin|send|picture|photo)\b|\bmay\s+(?:larawan|picture|photo)\b|\bpatingin\b|\bpakita\b"
    # "Pki flex ng items nyo" (Taglish: flex = khoe / cho xem — ca Bardenas 23/09)
    r"|\b(?:pa|paki|pki|pakii)\s*-?\s*flex\b|\bflex\s+(?:naman|mo|nyo|ninyo|po|ng|the|your|ur)\b"
    r"|\bminta\s+(?:foto|gambar)\b|\bada\s+(?:foto|gambar)\b|\bkirim\s+(?:foto|gambar)\b"
    # ③ Ả RẬP — phải có LỜI XIN, KHÔNG bắt trơn chữ "صورة" (chủ shop 2026-09-20 tối, ca كمال عبد الوهاب
    # · Sakura Skin Care KSA 17:29 CEST): khách viết "ارسلت لك صورة من اليد اعاني منها في اليدين الاثنين"
    # = *tôi ĐÃ GỬI cho bạn ảnh bàn tay tôi* — khách GỬI ảnh chứ không xin, vậy mà cổng bắn, AI đính 3 ảnh
    # /chaohang vào câu tư vấn. Nhánh tiếng Anh vốn đã đòi động từ (send/show me + pic); nhánh Ả Rập thì
    # chỉ có mỗi DANH TỪ nên mọi câu có chữ ảnh đều dính.
    r"|^\W*(?:ال)?صور(?:ه|ة)?\s*[؟!.]*\W*$"
    r"|\b(?:ارسل|أرسل|رسل|ابعث|أبعث|ابعت|اعطني|أعطني|عطني|ورني|وريني|ارني|أرني|نزل|حط)"
    r"\s*(?:لي|لنا|لى|ل)?\s*(?:ال)?صور"
    r"|\b(?:ابغى|ابغي|أبغى|أبغي|ابي|أبي|ابغا|ودي|عايز|عاوز|اريد|أريد|محتاج|ممكن|بدي|وين|فين|عندك|عندكم"
    r"|فيه|اشوف|أشوف)\s+(?:\S+\s+){0,2}(?:ال)?صور"
    r"|(?:^|\W)في\s+(?:ال)?صور"
    r"|照片|圖片|图片|相片",
    re.I | re.U)
# Mẫu ảnh nào là ẢNH SẢN PHẨM (đo 1.348 mẫu có ảnh của 326/338 page: /chaohang 208, không tên 207,
# /feedback 147, /hdsd 74, rồi tới loạt mẫu THANH TOÁN /paypal /venmo /moneygram…).
_MAU_ANH_SP = re.compile(r"\bchao\s*hang\b|\bchaohang\b|\bgioi\s*thieu\b|\bgioithieu\b|\bintro\w*\b|\bproduct\w*\b"
                         r"|\bsan\s*pham\b|\bsanpham\b|\bttsp\b|\bthiet\s*ke\b|\bdesigns?\b|\bmau\s*ma\b"
                         r"|\bcatalog\w*\b|\bmodels?\b", re.I)
# Hạng hai: bảng giá / combo — ảnh ở đó thường cũng là ảnh sản phẩm, nhưng nhường mẫu chào hàng.
_MAU_ANH_SP2 = re.compile(r"\bgia\b|\bbao\s*gia\b|\bbaogia\b|\bprice\w*\b|\bcombo\b|\bkhuyen\s*mai\b"
                          r"|\buu\s*dai\b|\bnoi\s*bat\b|\bsale\b|\bpromo\w*\b", re.I)
# ⛔ KHÔNG bao giờ lấy làm "ảnh sản phẩm": ảnh hướng dẫn CHUYỂN TIỀN (khách xin ảnh vòng tay mà nhận ảnh
# tài khoản PayPal là hỏng hội thoại), feedback (đã có luật riêng), địa chỉ cửa hàng, WhatsApp.
_MAU_ANH_CAM = re.compile(r"paypal|venmo|zelle|cash[\s_]*app|check|cheque|money[\s_]*order|money[\s_]*gram|western"
                          r"|debit|credit|deposit|bank|thanh\s*toan|feedback|review|testimon|hdsd|huong\s*dan"
                          r"|xac\s*nhan|xacnhan|dia\s*chi|diachi|address|store|whatsapp|zalo|levelup", re.I)


# ── KHÁCH MUỐN XEM HÀNG TRƯỚC KHI MUA = XIN ẢNH (chủ shop 21/09, ca Elvie Dela Torre · ChunHo Golden Jewerly) ──
# "Gusto ko nga muna mkita pls bago ako mag order sau" — XIN_ANH_KHACH ở trên đòi chữ ảnh/pic hoặc "i want to see",
# nên câu Tagalog "gusto ko(ng) makita" và "pwede ko po bang makita muna" trượt hết; AI đáp "bukas po tingnan niyo
# muna" (hẹn khách tới tiệm) thay vì gửi ngay 10 ảnh /chaohang mà page có sẵn. Đo 34.055 tin khách thật: nhánh này
# bắt 21 tin, soát tay đều là khách đòi xem hàng. Loại ra: "makita ang store niyo" (hỏi cửa hàng — luật 34),
# "makita ang kapalaran ko" / "ano ang hinaharap ko" (page xem bói, không phải xin ảnh hàng), "see my order status".
_XEM_SP = r"(?:makita|mkita|makit|kita|tingnan|tignan|tingin|see|view)"
MUON_XEM_SP = re.compile(
    r"\bgusto\s+(?:ko|kong|namin|nmin|naming|nya|niya)\b[^.?!\n]{0,24}?\b" + _XEM_SP + r"\b"
    r"|\b(?:pwede|puwede|pede|puede|pwd|maari|maaari)\b[^.?!\n]{0,20}?\b(?:makita|mkita|tingnan|tignan|see)\b"
    r"|\b(?:i|we)\s+(?:just\s+)?(?:want|wanna|wan|would\s+like|like|need)\s+(?:to\s+)?see\b"
    r"|\b(?:makita|mkita|kita)\s+(?:ko\s+|po\s+|na\s+)*muna\b"
    r"|\bsee\s+(?:it|them|those|these|the\s+\w+)\s+first\b",
    re.I | re.U)
_KHONG_XEM_SP = re.compile(
    r"\b(?:stores?|shops?|branch(?:es)?|tindahan|showrooms?)\b"
    r"|\b(?:kapalaran|hinaharap|swerte|palad|fortune|future|horoscope|destiny)\b"
    r"|\b(?:my|aking)\s+(?:order|parcel|package|delivery|item)\b|\border\s+status\b|\btracking\b",
    re.I | re.U)


def muon_xem_san_pham(t):
    """Khách muốn XEM hàng trước khi mua — cũng phải gửi ảnh sản phẩm, đừng hẹn khách tới tiệm."""
    t = t or ""
    if not t.strip() or _KHONG_XEM_SP.search(t):
        return False
    return bool(MUON_XEM_SP.search(t))


# "PAKI SEND NG <MÓN>" = gửi giùm (ảnh) cái món đó — ca Lynjove Comuiaq · Key Jewelry Saudi 23/09: "pwd po ba paki send ng
# necklace at grams nya po" lọt vì nhánh ② chỉ nhận "send + pic/design…", không biết "ng necklace". Đo 27.262 tin khách:
# thêm 8 tin ("Pa send ng pic", "Pa send ng ibang design", "P send po Ng ibang Items", "Pkisend po ng pic na may diamond"…).
# ⛔ Câu có order/address/bukas là GỬI HÀNG, không phải xin ảnh ("Order ako … pa send nga one set mag kano").
_XIN_ANH_SEND_NG_MON = (r"(?:necklace|necklaces|neklace|kwintas|bracelet|bracelets|pulseras|ring|rings|singsing|earrings?|hikaw"
                        r"|set|sets|design|designs|item|items|product|products|model|models|style|styles|sample|samples"
                        r"|pic|pics|picture|pictures|photo|photos|larawan|litrato|image|images|video|videos)")
_XIN_ANH_SEND_NG = re.compile(
    r"\b(?:paki|pki|pakii|pa)\s*-?\s*send\s+(?:(?:mo|nyo|niyo|po|na|nga|naman|me|ulit|lang)\s+)*"
    r"(?:(?:ng|nang|ung|yung|ang|mga|the|a|of|your|ur)\s+)*(?:\w+\s+)?" + _XIN_ANH_SEND_NG_MON + r"\b"
    r"|\bsend\s+(?:(?:mo|nyo|niyo|po|nga|naman)\s+)+(?:(?:ng|nang|ung|yung|ang|mga)\s+)+(?:\w+\s+)?"
    + _XIN_ANH_SEND_NG_MON + r"\b", re.I)
_XIN_ANH_SEND_NG_LOAI = re.compile(
    r"\b(?:order|address|addres|adress|location|sa\s+bahay|dito\s+sa|to\s+my|bukas|tomorrow)\b", re.I)


# CHỮ NỐI BẰNG DẤU CHẤM (25/09, ca Emmalyn Bentolan · Golden Soap House KSA): "Its.realy.true", "I.want.to.buy.this.so.what.wei.I.do",
# "Im.her.in.khamis.city…" — khách gõ không có dấu cách, mọi bộ dò ý khách (\b + \s+) trượt hết. Đo 34.692 tin khách: 210 tin có
# ≥2 chỗ chữ.chữ. Chỉ đổi khi ≥2 chỗ để "St.Mary", "wa.link" lẻ không đổi; số "99.5" không đụng (chỉ chấm giữa hai CHỮ).
_CHAM_NOI_CHU = re.compile(r"(?<=[^\W\d_])\.(?=[^\W\d_])")


def _chu_khach(t):
    """lam_sach + tách chữ nối bằng dấu chấm — dùng cho các bộ dò Ý KHÁCH (xin ảnh, hỏi thật, cầm đồ, vàng mạ…)."""
    t = lam_sach(t or "").strip()
    return _CHAM_NOI_CHU.sub(" ", t) if len(_CHAM_NOI_CHU.findall(t)) >= 2 else t


# CÂU NGẮN HỎI THẬT (25/09): "Its really true", "This is real?", "It's legit po maam", "True gold???" — cả tin chỉ có vậy. Phải có
# chủ ngữ (it's/this is/is it…) HOẶC từ nhấn (really/realy/100%) HOẶC dấu hỏi: "True" / "Real" trơn có thể là đáp câu khác.
_THAT_GIA_NGAN = re.compile(
    r"^\W*(?P<chu>(?:it'?s|its|it\s+is|is\s+it|is\s+this|this\s+is|are\s+you\s+sure|sure)\s+)?"
    r"(?P<nhan>(?:really|realy|rly|reallly|truly|trully|very|100%?)\s+)?"
    r"(?:true|real|legit|ligit|original|orig|authentic|genuine|totoo|tunay)\b"
    r"(?:\s+(?:ba|po|poba|pb|b|ma'?am|maam|mam|madam|dear|sir|gold|product|item|na|or\s+not|or\s+fake))*\W*$", re.I)


# CÂU NGHI TIẾNG INDONESIA (26/09, ca Fathima Indio: "Ini bener … aku takut bohong"). Đo 39.380 tin khách: 7 tin, đều là hỏi
# thật/sợ bị lừa ("bohong gk niih", "ini asli atao abal abal", "Takut palsu…").
_NGHI_THAT_ID = re.compile(
    r"\btakut\s+(?:di\s*)?(?:tipu|bohong|penipu\w*|palsu|scam)\b|\bpenipu\w*\b|\bketipu\b|\bditipu\b"
    r"|\b(?:asli|ori|original|bener(?:an)?|beneran|real)\s+(?:gak|ga|nggak|ngga|tidak|kah|gk|g|atau\s+palsu)\b"
    r"|\b(?:bohong|palsu|kw)\s+(?:gak|ga|nggak|tidak|kah|gk)\b|\bini\s+bener\b|\bini\s+asli\b", re.I)


def _hoi_that_ngan(t):
    m = _THAT_GIA_NGAN.search(t or "")
    return bool(m and (m.group("chu") or m.group("nhan") or re.search(r"[?？؟]", t)))


# XIN ẢNH TIẾNG BENGAL / HINDI / URDU (25/09, ca Forid Mia · Tummy Ease KSA: "জরুরী এক পিক চাই"). Danh từ ảnh + động từ xin
# (muốn / gửi / cho xem) trong cùng câu — danh từ trơn KHÔNG tính (khách GỬI ảnh cũng nói "pic"); ⛔ dạng ĐÃ gửi
# (भेजा / بھیجی / পাঠিয়েছি) không tính. Chữ Ấn / Ả Rập có dấu nguyên âm
# không phải \w nên KHÔNG dùng \b cho chữ gốc, đo khoảng cách bằng ký tự. Đo 35.285 tin khách: +6 tin ("পিক দেন দেকি", "Ring er pic
# den", "mere ko one pic chahiye", "Jo video me dikha rhe o pic bhejo", "دوسیٹ کا تصویر بیج دو"), 0 oan.
_XIN_ANH_NAM_A_DT = (r"(?:পিক|পিকচার|ফটো|ছবি|পিকটা|ছবিটা|ফটোটা|पिक|पिक्चर|फोटो|फ़ोटो|तस्वीर|तस्वीरें|फोटोज"
                     r"|تصویر|تصاویر|تصویریں|پک|پکچر|فوٹو|فوتو)")
_XIN_ANH_NAM_A_DG = (r"(?:চাই|চাইয়ে|চাহিয়ে|দেন|দিন|দাও|দেও|পাঠান|পাঠাও|পাঠাবেন|দেখান|দেখাও|লাগবে"
                     r"|चाहिए|चाहिये|भेजो|भेजें|भेजिए|भेजिये|भेज(?![ाीे])|दो|दीजिए|दीजिये|दिखाओ|दिखाइए|दिखाइये"
                     r"|چاہیے|چاہئے|چاہیئے|بھیجو|بھیجیں|بھیج(?![اےی])|دو|دیں|دکھاؤ|دکھائیں|دکھا)")
_XIN_ANH_NAM_A = re.compile(
    _XIN_ANH_NAM_A_DT + r"[^.!?\n]{0,25}?" + _XIN_ANH_NAM_A_DG + r"|" + _XIN_ANH_NAM_A_DG + r"[^.!?\n]{0,10}?" + _XIN_ANH_NAM_A_DT
    + r"|\b(?:pic|pics|picture|photo|photos|foto|tasveer|tasvir|tasweer|chobi|chhobi)\s+(?:\w+\s+){0,2}?"
    r"(?:chahiye|chaiye|chahie|chahiya|bhejo|bhejen|bhejiye|bhej|dijiye|dijie|den|dao|dikhao|dikhaiye|dikhayen|pathan|pathao"
    r"|lagbe)\b", re.I | re.U)


def khach_xin_anh(msgs, so_tin=3):
    """Khách vừa XIN ẢNH sản phẩm trong các tin chưa được đáp (giống khach_xin_feedback)."""
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                kh.append(t)
        elif m.get("boi") != "hethong":
            break
    return any(XIN_ANH_KHACH.search(t) or muon_xem_san_pham(t)
               or (_XIN_ANH_SEND_NG.search(t) and not _XIN_ANH_SEND_NG_LOAI.search(t))
               or _XIN_ANH_NAM_A.search(t) for t in kh[:so_tin])


def _ten_mau(m):
    """Tên mẫu + chủ đề, bỏ dấu, tách chữ — để dò bằng \b (chủ đề Pancake dạng '138809taisaogia159')."""
    t = qht.norm((m.get("tu_khoa") or "") + " "
                 + re.sub(r"^[0-9a-f]{6}", "", str(m.get("chu_de_id") or "")))
    return re.sub(r"[^a-z0-9]+", " ", t.lower())


def mau_anh_cho_khach(kb_page):
    """Mẫu ảnh SẢN PHẨM để gửi khi khách xin ảnh — không có thì None (lúc đó mới nhờ sale).

    Chọn theo THỨ HẠNG chứ không phải cứ nhiều ảnh là lấy: page Flat Jewelry KSA in Dubai có
    /chaohang (3 ảnh sản phẩm) và một mẫu không tên chủ đề 'taisaogia159' (5 ảnh tiệm vàng thu
    lại) — lấy theo số ảnh là khách xin ảnh vòng tay nhận về ảnh tiệm cầm đồ.
    """
    ds = [m for m in (kb_page or {}).get("mau") or [] if m.get("anh")]
    con = [m for m in ds if not _MAU_ANH_CAM.search(_ten_mau(m))]
    if not con:
        return None
    def hang(m):
        t = _ten_mau(m)
        return (2 if _MAU_ANH_SP.search(t) else 1 if _MAU_ANH_SP2.search(t) else 0,
                len(m.get("anh") or []))
    return max(con, key=hang)


# ── ẢNH BỘ SƯU TẬP CỦA PAGE (chủ shop 21/09, ca Lanie Antonio Jacinto · Mario Jewelry UAE) ─────────────
# *"phần bộ sưu tập k có mẫu khác cho bạn gửi sao"*: khách xin "another design" — kịch bản page chỉ có bộ Knot (2 ảnh
# mẫu /chaohang lại là giấy chứng nhận + ảnh cận móc khoá), trong khi THƯ MỤC ẢNH của page có bộ đá trắng + bộ trái
# tim, đúng 2 ảnh sale Thu Hiền phải tự gửi. Thư mục lẫn lộn (giấy tờ, ảnh chat, cửa hàng, hàng của page khác) nên
# lọc SẴN ngoài giờ chạy: phan_loai_bo_suu_tap.py (model đọc ảnh ~$0,0001/ảnh) + chon_mau.py (kiểu hàng chính theo
# ảnh kịch bản / tên SP POS — KHÔNG theo số đông thư mục; kiểm lần 2 từng ảnh) → state/<tt>/mau_khac.json. Chỉ bật
# cho page trang sức / phụ kiện. Chủ shop chọn: gửi ảnh sản phẩm sạch khách CHƯA xem, mẫu khác CÙNG bảng giá page,
# note đơn cho sale kiểm mẫu. Tắt nhanh: AI_ANH_BST=0 trong .env (không cần restart).
_MAU_KHAC = {}                        # mkey -> {"mt": mtime, "d": {...}}
_DH_ANH = {}                          # url -> dHash (int) | None — ảnh đã có trong hội thoại


def mau_khac_page(mkey, pid):
    """Ảnh sản phẩm lọc sẵn của page (state/<tt>/mau_khac.json), nạp lại khi file đổi."""
    f = os.path.join(SCRIPT_DIR, "state", mkey or "chung", "mau_khac.json")
    try:
        mt = os.path.getmtime(f)
    except OSError:
        return None
    c = _MAU_KHAC.get(mkey)
    if not c or c["mt"] != mt:
        c = _MAU_KHAC[mkey] = {"mt": mt, "d": qht.load_json(f, {})}
    return c["d"].get(str(pid))


def _dhash_anh(url):
    """dHash 64 bit, tính ĐÚNG như chon_mau.py (ảnh qua _anh_nen rồi thu 9x8 xám) để so ảnh trùng."""
    if url in _DH_ANH:
        return _DH_ANH[url]
    v = None
    try:
        import base64
        import io
        from PIL import Image
        im = Image.open(io.BytesIO(base64.b64decode(_anh_nen(url)))).convert("L").resize((9, 8))
        px = list(im.getdata())
        v = int("".join("1" if px[r * 9 + c] > px[r * 9 + c + 1] else "0"
                        for r in range(8) for c in range(8)), 2)
    except Exception:                                    # noqa: BLE001 — ảnh hỏng thì coi như chưa thấy
        v = None
    if len(_DH_ANH) > 5000:
        _DH_ANH.clear()
    _DH_ANH[url] = v
    return v


def anh_bo_suu_tap_cho_khach(mkey, pid, msgs, toi_da=4):
    """Ảnh SẢN PHẨM lọc sẵn từ bộ sưu tập của page mà khách CHƯA thấy trong hội thoại này.

    None = page không bật (không phải trang sức/phụ kiện, chưa lọc, hoặc AI_ANH_BST=0) → đi đường mẫu kịch bản cũ.
    [] = khách đã xem hết → cũng đi đường cũ. Ảnh page/sale/Botcake đã gửi bị loại theo dHash (cùng ảnh tải lên
    hai lần là hai URL — ca Lanie: Botcake chào bằng đúng 2 ảnh bộ Knot có trong thư mục).
    """
    if os.environ.get("AI_ANH_BST", "1").strip() == "0":
        return None
    p = mau_khac_page(mkey, pid)
    if not p or not p.get("bat") or not p.get("anh"):
        return None
    da_thay = [u for m in (msgs or []) if m.get("boi") in ("botcake", "nguoi", "ai")
               for u in (m.get("anh") or []) if u][-12:]
    from concurrent.futures import ThreadPoolExecutor as _TPE_BST
    with _TPE_BST(max_workers=4) as bom:
        dh_da = [h for h in bom.map(_dhash_anh, da_thay) if h is not None]
    ra = []
    for u in p["anh"]:
        h = (p.get("dh") or {}).get(u)
        hv = int(h, 16) if h else None
        if u in da_thay or (hv is not None and any(bin(hv ^ x).count("1") <= 6 for x in dh_da)):
            continue
        ra.append(u)
        if len(ra) >= toi_da:
            break
    return ra


# ── KHÁCH HỎI LOẠI TRANG SỨC KHÁC (chủ shop duyệt 23/09, ca Bardenas Leonicar · Solid Big Infinity Ring Gold UAE) ─────
# Page nhẫn, khách hỏi "May kwentas po ba kyo" rồi "At saka bracelet" → AI viết "Yes sis, may kwentas at bracelet din po
# kami" mà KHÔNG gửi ảnh, quay lại xin thông tin chốt nhẫn; khách phải tự đòi "Pki flex ng items nyo" rồi AI lại giao sale.
# Thư mục ảnh page CÓ ảnh lắc / dây chuyền (state/chung/anh_loai_bst.json đã phân loại) — chỉ là bộ sưu tập (mau_khac) lọc
# theo kiểu CHÍNH của page. Chủ shop duyệt: khách hỏi loại khác → AI tự gửi ảnh loại đó từ thư mục page. KHÔNG nêu giá
# (bảng giá page chỉ cho hàng chính) → tra_loi_treo + ghi chú sale báo giá. Page không có ảnh loại đó → không khẳng định
# có/không, để sale. Chỉ page trang sức MỘT loại (nhẫn / dây chuyền / lắc / bông tai) đã bật bộ sưu tập.
# Đo sổ so_chi_phi: ~60 câu khách nhắc loại khác; bộ lọc ý-hỏi bỏ câu kể đơn cũ ("dati order kwintas… nangitim"), chê
# ("Not bracelet the ring", "why did you sale bracelet… fake"), hỏi món có kèm trong bộ không ("Kasama ba ung singsing").
# Tắt nhanh: AI_ANH_LOAI_KHAC=0 trong .env.
_LOAI_TS = {
    "necklace": r"neck\s?laces?|nec?klaces?|nicklaces?|necklase|kwintas|kwentas|kuwintas|kuwentas|kalung|pendants?|chains?"
                r"|قلادة|قلاده|سلسال|سلسلة|سلسله",
    "bracelet": r"bra[cs]e?lets?|brac?lets?|braslet|bangles?|pulseras?|gelang|اسوار\w*|أسوار\w*|إسوار\w*|غوايش|غويشة",
    "earrings": r"ear\s?rings?|hikaw|anting|حلق|اقراط|أقراط|تراكي",
    "ring": r"rings?|singsing|cincin|خاتم|خواتم",
}
_LOAI_TS_RX = {k: re.compile(r"(?<!\w)(?:" + v + r")(?!\w)", re.I | re.U) for k, v in _LOAI_TS.items()}
_LOAI_TS_ANH = {"necklace": ("necklace", "chain", "jewelry_set"), "bracelet": ("bracelet",),
                "earrings": ("earrings", "jewelry_set"), "ring": ("ring",)}
_LOAI_TS_TEN = {"necklace": "dây chuyền", "bracelet": "lắc tay", "earrings": "bông tai", "ring": "nhẫn"}
_Y_HOI_LOAI = re.compile(
    r"\?|\b(?:do|does|did)\s+(?:you|u)\s+(?:have|sell|got)|\b(?:you|u|ur)\s+(?:have|got|sell)\b|\bhave\s+(?:you|u)\b"
    r"|\bany\b|\bmeron\b|\bmay\b|\bmy\b|\bpwede\b|\bpede\b|\bsend\b|\bshow\b|\bpics?\b|\bpicture|\bphoto|\bwant\b|\bneed\b"
    r"|\blike\b|\bgusto\b|\bsaka\b|\balso\b|\bdin\b|\brin\b|\bonly\b|\bwala\b|\bada\b|\bpunya\b"
    r"|\bba\b|\bkau\b|\bkayo\b|\bkyo\b|\bkaung\b|\bkayong\b"
    r"|\bfor\s+(?:women|woman|men|man|mans|girls?|boys?|my|her|him)\b"
    r"|عندك|عندكم|فيه|ابغى|ابغي|ابي|أبي|ارسل|أرسل|ممكن|وين|اريد|أريد", re.I | re.U)
_KHONG_HOI_LOAI = re.compile(
    r"\bnot\s+(?:the\s+|a\s+)?\w*(?:lace|let|ring|hikaw|kwintas|kwentas|bangle)\w*|\bwhy\s+did\s+(?:you|u)\b|\bfake\b|\bpeke\b"
    r"|\bdati\b|\bbefore\s+i\b|\bi\s+(?:was|already)\s+order|\border\s*k\b|\btinapon\b|\bnangitim\b|\bkasama\b|\bkasali\b"
    r"|\bincluded?\b", re.I)


_CHON_MAU = re.compile(r"\b(?:this|that|ito|iyan|yan|yung|yong|number|no\.?|#)\s*\d|\b\d\s*(?:st|nd|rd|th)\b"
                       r"|\b(?:first|second|third|last|una|pangalawa|ikalawa|huli)\b|\bthis\s+one\b|\bthat\s+one\b", re.I)
_KIEU_ANH_LOAI = {"necklace": "necklace", "chain": "necklace", "jewelry_set": "necklace", "bracelet": "bracelet",
                  "earrings": "earrings", "ring": "ring"}


def _loai_anh_vua_gui(msgs, chinh):
    """Loại trang sức KHÁC hàng chính có trong ảnh phía shop gửi ở 8 tin gần nhất."""
    pl = _anh_loai_bst()
    ra = set()
    for m in (msgs or [])[-8:]:
        if m.get("boi") in ("ai", "nguoi", "botcake"):
            for u in m.get("anh") or []:
                v = pl.get(u) or {}
                k = _KIEU_ANH_LOAI.get(v.get("kieu")) if v.get("loai") == "san_pham" else None
                if k and k != chinh:
                    ra.add(k)
    return ra


def _loai_ts_trong(t, chinh):
    """Các loại trang sức KHÁC hàng chính mà câu khách `t` hỏi (có ý hỏi mua / hỏi có không / xin xem)."""
    t = lam_sach(t or "")
    if not t.strip() or _KHONG_HOI_LOAI.search(t):
        return set()
    if chinh in _LOAI_TS and re.search(r"\b(?:want|like|need|gusto|only)\s+(?:the\s+)?(?:" + _LOAI_TS[chinh] + r")(?!\w)",
                                       t, re.I):
        return set()                                     # "Bracelet? I want the ring" — khách đòi hàng CHÍNH
    ks = {k for k, rx in _LOAI_TS_RX.items() if k != chinh and rx.search(t)}
    if ks and (len(t.split()) <= 3 or _Y_HOI_LOAI.search(t) or HOI_GIA.search(t) or XIN_ANH_KHACH.search(t)):
        return ks
    return set()


def loai_ts_chinh(mkey, pid):
    """Kiểu hàng chính của page trang sức MỘT loại đã bật bộ sưu tập ('ring'/'necklace'/'bracelet'/'earrings'), không thì None."""
    p = mau_khac_page(mkey, pid)
    if not p or not p.get("bat"):
        return None
    k = "necklace" if p.get("kieu") == "chain" else p.get("kieu")
    return k if k in _LOAI_TS else None


def loai_ts_khach_hoi(mkey, pid, msgs, conv=None):
    """Loại trang sức KHÁC hàng chính khách đang hỏi → set; rỗng nếu không hỏi / page không phải trang sức một loại.

    Xét chuỗi tin khách CHƯA được đáp; có loại (hoặc khách xin xem hàng mà không nhắc hàng chính) thì gom thêm loại khách
    đã nhắc trong 6 tin gần nhất — ca Bardenas: "May kwentas po ba kyo" (AI đáp chuyện giao hàng) rồi "At saka bracelet"."""
    if os.environ.get("AI_ANH_LOAI_KHAC", "1").strip() == "0":
        return set()
    chinh = loai_ts_chinh(mkey, pid)
    if not chinh:
        return set()
    chua = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            chua.append(m.get("text") or "")
        elif m.get("boi") != "hethong":
            break
    if not chua:
        return set()
    bay_gio = set().union(*(_loai_ts_trong(t, chinh) for t in chua))
    nhac_chinh = any(_LOAI_TS_RX[chinh].search(lam_sach(t)) for t in chua)
    if not bay_gio and not khach_xin_anh(msgs):
        # Khách vừa xem ảnh loại khác (AI đã gửi ở hội thoại này — sổ ảnh "lk") rồi hỏi giá / chọn mẫu mà không gọi tên
        # loại ("how much the 2nd one?") → vẫn là hỏi loại khác: cấm để model báo giá hàng chính cho lắc tay.
        if (nhac_chinh or not conv or not anh_loai_da_gui(mkey, conv, "lk")
                or not any(HOI_GIA.search(lam_sach(t)) or _CHON_MAU.search(lam_sach(t)) for t in chua)):
            return set()
        return _loai_anh_vua_gui(msgs, chinh)
    if not bay_gio and nhac_chinh:
        return set()
    gan = [m.get("text") or "" for m in (msgs or [])[-6:] if m.get("boi") == "khach"]
    return bay_gio | set().union(*(_loai_ts_trong(t, chinh) for t in gan))


_ANH_LOAI_BST = {"mt": None, "d": {}}


def _anh_loai_bst():
    f = os.path.join(SCRIPT_DIR, "state", "chung", "anh_loai_bst.json")
    try:
        mt = os.path.getmtime(f)
    except OSError:
        return {}
    if _ANH_LOAI_BST["mt"] != mt:
        _ANH_LOAI_BST["d"], _ANH_LOAI_BST["mt"] = qht.load_json(f, {}), mt
    return _ANH_LOAI_BST["d"]


def anh_loai_khac_cho_khach(mkey, pid, msgs, loai, toi_da=4):
    """(ảnh SẢN PHẨM các loại `loai` trong THƯ MỤC ẢNH page mà khách CHƯA thấy, tổng số ảnh page có của các loại đó).

    Chia đều giữa các loại (khách hỏi dây chuyền + lắc → 2 + 2). Ảnh trùng ảnh page/sale/Botcake/AI đã gửi bị loại theo
    dHash như anh_bo_suu_tap_cho_khach."""
    pl = _anh_loai_bst()
    theo = {}
    for k in sorted(loai or ()):
        theo[k] = [a["u"] for a in thu_muc_anh(mkey, pid) if a.get("u")
                   and (pl.get(a["u"]) or {}).get("loai") == "san_pham"
                   and (pl.get(a["u"]) or {}).get("kieu") in _LOAI_TS_ANH.get(k, ())]
    tong = len({u for ds in theo.values() for u in ds})
    if not tong:
        return [], 0
    da_thay = [u for m in (msgs or []) if m.get("boi") in ("botcake", "nguoi", "ai")
               for u in (m.get("anh") or []) if u][-16:]
    from concurrent.futures import ThreadPoolExecutor as _TPE_LK
    with _TPE_LK(max_workers=4) as bom:
        dh_da = [h for h in bom.map(_dhash_anh, da_thay) if h is not None]

    def chua_thay(u):
        h = (pl.get(u) or {}).get("dh")
        hv = int(h, 16) if h else None
        return u not in da_thay and not (hv is not None and any(bin(hv ^ x).count("1") <= 6 for x in dh_da))
    hang = {k: [u for u in ds if chua_thay(u)] for k, ds in theo.items()}
    ra = []
    while len(ra) < toi_da and any(hang.values()):
        for k in sorted(hang):
            if hang[k] and len(ra) < toi_da:
                u = hang[k].pop(0)
                if u not in ra:
                    ra.append(u)
    return ra, tong


# ══ ẢNH ĐI KÈM CÂU TRẢ LỜI (chủ shop 2026-09-20 tối) ═══════════════════════════════════════════
# *"mấy câu khách hỏi có thật k, bạn rep xong gửi thêm ảnh cho khách đi, mấy cái ảnh chứng nhận ấy;
#  khách hỏi feedback, rep xong gửi ảnh feedback; khách hỏi về sản phẩm, tư vấn xong gửi thêm ảnh sp"*
# (ca Evelyn Peralta · Nature's Daily Care in Uae 22:31 — "Is this tea legit" được trả lời chay,
# trong khi mẫu /chaohang của chính page đó có sẵn tờ giấy phép).
#
# ẢNH CHỨNG NHẬN KHÔNG DÒ ĐƯỢC BẰNG TÊN MẪU. Đo 1.020 ảnh của 326 page: tên mẫu có chữ chứng nhận
# chỉ ở 32 page, còn giấy tờ thật thì nằm rải trong /chaohang, /Feedback, mẫu KHÔNG TÊN. Nên phải
# đọc CHỮ TRONG ẢNH — state/anh_chu.json {url: {"chu": "<chữ đọc được>"}}, đọc SẴN ngoài giờ chạy
# bằng doc_chu_anh.py (Vision của macOS, ~0,08 giây/ảnh). ⚠️ ĐỪNG đọc ảnh trong vòng chạy: thử
# tesseract ngay trên VPS 20/09, 4 nhân đang nuôi 6 service AI Sale → >120 giây/ảnh, hỏng cả vòng.
# Đo 1.020 ảnh: 63 ảnh giấy tờ ở 120/326 page; 30 ảnh tiền (paypal/check/western union) bị loại hẳn.
_ANH_GIAY = re.compile(                      # chữ chỉ có trên GIẤY TỜ thật
    r"certificate\s+of|certificate\s+no|certificates?\b.{0,20}\bauthenticity|this\s+is\s+to\s+certify"
    r"|certifies\s+that|certification\b|ministry\s+of\s+health|food\s+and\s+drug\s+administration"
    r"|food\s+safety|product\s+announcement|test\s+report|analysis\s+report|laborator"
    r"|registration\s+(?:certificate|no|number)|giấy\s*chứng\s*nhận|chứng\s*nhận|kiểm\s*nghiệm"
    r"|cục\s*an\s*toàn|công\s*bố\s*sản\s*phẩm"
    # báo cáo giám định đá/trang sức (22/09): tờ AIG của mẫu /vang, OCR đọc "REPORTNO.", "Jeweiry Report",
    # "CEMOLOGICAL LABORATOBIES". Đo 1.237 ảnh đã đọc chữ: ba chữ này chỉ thêm ĐÚNG tấm đó.
    r"|\breport\s*no\b|\bjewe\w{0,3}\s+report\b|[gc]emolog\w*", re.I | re.U)
_ANH_DAU = re.compile(                       # huy hiệu FDA/GMP/Halal — một cái chưa đủ, hai cái mới tính
    r"\bfda\b|\bgmp\b|\biso\s*\d|halal|approved|certified|quality\s+(?:guarantee|tested|inspected)"
    r"|\bpassed\b|authentic|inspect", re.I)
_ANH_CHAT = re.compile(r"active\s+now|customer\s+feedback|\bmessenger\b|typing|sent\s+\d", re.I)
_ANH_TIEN_CHU = re.compile(r"mobile\s+deposit|endorse\s+here|pay\s+to\s+the\s+order|routing|paypal|venmo"
                           r"|zelle|cash\s*app|western\s+union|money\s*gram|bank\s+transfer|iban", re.I)
_MAU_ANH_TIEN = re.compile(r"paypal|venmo|zelle|cash[\s_]*app|check|cheque|money[\s_]*order|money[\s_]*gram"
                           r"|western|debit|credit|deposit|bank|thanh\s*toan", re.I)
_ANH_CHU_BO = {"luc": 0, "d": {}}            # nạp lại khi file đổi, không đọc đĩa mỗi lượt


def _f_anh_chu():
    return os.path.join(SCRIPT_DIR, "state", "anh_chu.json")


def chu_trong_anh(u):
    """Chữ đã đọc sẵn trong ảnh này; chưa đọc ảnh nào thì rỗng (không đoán, không OCR tại chỗ)."""
    try:
        m = os.path.getmtime(_f_anh_chu())
    except OSError:
        return ""
    if m != _ANH_CHU_BO["luc"]:
        _ANH_CHU_BO["d"] = qht.load_json(_f_anh_chu(), {})
        _ANH_CHU_BO["luc"] = m
    return ((_ANH_CHU_BO["d"].get(u) or {}).get("chu") or "")


# Chữ TRANG SỨC / VÀNG — cho giấy tờ lấy từ THƯ MỤC ẢNH (22/09): thư mục lẫn hàng page khác (Kreain Nature
# Oman để giấy FDA kem đánh răng), nên chỉ page trang sức mới lấy, và tờ giấy cũng phải nói về vàng/trang sức.
_CN_TRANG_SUC = re.compile(
    r"\b(?:gold|18\s*k|21\s*k|22\s*k|24\s*k|karat|jewel\w*|diamond|moissanite|jade|silver|925"
    r"|necklace|bracelet|earrings?|rings?|pendant|bangle)\b|ذهب|مجوهرات|金|銀", re.I | re.U)


# GIẤY CHỨNG NHẬN ĐÚNG MÓN (chủ shop 23/09, ca Madu Pathiraja · Kuwait Luxe Charm): page bán DÂY CHUYỀN đá màu, AI nói
# "These necklaces are 18K gold… each one comes with its certificate" rồi máy kèm tờ giấy "Product Name: Infinity Ring" lấy từ
# thư mục ảnh (thư mục lẫn hàng page khác). Đo: tờ "Infinity Ring" nằm ở 3 page không bán nhẫn (Kuwait / Dubai Luxe Charm —
# dây chuyền, Veloura Luxe Jewelry Qatar — bông tai), phiếu AIG "diamond ring" ở Zahra Luxe Jewelry Saudi (dây chuyền).
# Loại món của tờ giấy: dòng "Product Name" trong chữ ảnh trước, phân loại ảnh (anh_loai_bst) sau; không rõ thì cho qua.
# Page bán nhiều loại (không có kiểu chính) thì không lọc.
_TEN_SP_GIAY = re.compile(r"product\s*name\s*[:|]?\s*\|?\s*([^|\n]{2,60})", re.I)


def _loai_chinh_page(kb_page, mkey=None, pid=None):
    """Loại trang sức chính của page: bộ sưu tập đã lọc (loai_ts_chinh), không có thì chữ kịch bản chỉ nhắc ĐÚNG một loại."""
    k = loai_ts_chinh(mkey, pid) if (mkey and pid) else None
    if k:
        return k
    chu = _chu_kich_ban(kb_page)
    co = [k for k, rx in _LOAI_TS_RX.items() if rx.search(chu)]
    return co[0] if len(co) == 1 else None


def _giay_hop_hang(u, t, chinh):
    """Tờ giấy ảnh `u` (chữ `t`) nói về món khớp loại `chinh` của page? Không rõ món / page không có loại chính → True."""
    if not chinh:
        return True
    m = _TEN_SP_GIAY.search(t or "")
    loai = {k for k, rx in _LOAI_TS_RX.items() if rx.search(m.group(1))} if m else set()
    if not loai:
        kv = _KIEU_ANH_LOAI.get((_anh_loai_bst().get(u) or {}).get("kieu"))
        if kv and (_anh_loai_bst().get(u) or {}).get("kieu") != "jewelry_set":
            loai = {kv}
    return not loai or chinh in loai


def anh_chung_nhan(kb_page, toi_da=2, mkey=None, pid=None):
    """Ảnh GIẤY TỜ / chứng nhận của page — giấy tờ thật trước, ảnh gắn huy hiệu FDA/GMP sau.

    Kịch bản không có tấm nào mà có mkey+pid → tìm trong THƯ MỤC ẢNH, CHỈ ở page trang sức (22/09: 7 page
    trang sức để giấy chứng nhận vàng 18K trong thư mục — Dubai Luxe Charm, Malabar Gold KSA, Zahra Luxe…).
    Không có thì rỗng (lúc đó chỗ gọi lùi về ảnh sản phẩm — vẫn hơn trả lời chay)."""
    ra = []
    for m in (kb_page or {}).get("mau") or []:
        if _MAU_ANH_TIEN.search(_ten_mau(m)):
            continue                                  # mẫu chuyển tiền: ảnh tài khoản, không phải giấy tờ
        for u in m.get("anh") or []:
            t = chu_trong_anh(u)
            if not t or _ANH_TIEN_CHU.search(t):
                continue
            g = len({x.lower() for x in _ANH_GIAY.findall(t)})
            d = len({x.lower() for x in _ANH_DAU.findall(t)})
            if g < 1 and d < 2:
                continue
            if g == 0 and _ANH_CHAT.search(t):
                continue                              # ảnh chụp màn hình chat khen hàng — đó là feedback
            ra.append((2 if g else 1, g + d, u))
    ra.sort(key=lambda x: (-x[0], -x[1]))
    kq = []
    for _, _, u in ra:
        if u not in kq:
            kq.append(u)
    if kq or not (mkey and pid):
        return kq[:toi_da]
    if not _CN_TRANG_SUC.search(json.dumps(kb_page or {}, ensure_ascii=False)):
        return []
    _chinh_cn = _loai_chinh_page(kb_page, mkey, pid)
    ra = []
    for x in thu_muc_anh(mkey, pid):
        u = x.get("u")
        t = chu_trong_anh(u) if u else ""
        if not t or _MAU_ANH_TIEN.search(x.get("ten") or "") or _ANH_TIEN_CHU.search(t):
            continue
        if _ANH_CHAT.search(t) or _ANH_FB_MANH.search(t) or _ANH_FB_KHACH.search(t):
            continue                                  # ảnh chat khách khoe nhận hàng kèm giấy — đó là feedback
        g = len({y.lower() for y in _ANH_GIAY.findall(t)})
        if g < 1 or not _CN_TRANG_SUC.search(t):
            continue                                  # huy hiệu trơn / giấy của hàng khác thì không lấy
        if not _giay_hop_hang(u, t, _chinh_cn):
            continue                                  # giấy của MÓN KHÁC (ca Madu 23/09 — xem _giay_hop_hang)
        ra.append((g + len({y.lower() for y in _ANH_DAU.findall(t)}), u))
    ra.sort(key=lambda x: -x[0])
    for _, u in ra:
        if u not in kq:
            kq.append(u)
    return kq[:toi_da]


# ẢNH FEEDBACK NẰM TRONG MẪU KHÁC — cùng bài với ảnh chứng nhận. `mau_feedback` chỉ thấy mẫu ĐẶT
# TÊN feedback hoặc mẫu có NỘI DUNG feedback: 164/338 page. Đọc chữ trong ảnh thấy thêm **63 page**
# có ảnh feedback thật (ảnh chụp màn hình khách khen, bảng "CUSTOMER FEEDBACK", "Verified Buyer")
# nằm trong /chaohang, /SUCKHOE+GIADINH, mẫu không tên → phủ 227/338 page.
_ANH_FB_MANH = re.compile(r"customer\s+feedback|\bfeedbacks?\b|\breviews?\b|testimonial|patotoo"
                          r"|verified\s+buyer", re.I)
_ANH_FB_CHAT = re.compile(r"active\s+now|active\s+\d|\b\d{1,2}:\d{2}\s*(?:am|pm)\b|\byesterday\b|\btoday\b"
                          r"|\bseen\b|\bsent\b", re.I)
_ANH_FB_KHACH = re.compile(r"dumating\s+na|natanggap|salamat|thank\s+you\s+so\s+much|received\s+my"
                           r"|nakuha\s+ko|ang\s+ganda|sobrang|super\s+ganda", re.I)


def anh_feedback(kb_page, toi_da=4):
    """Ảnh FEEDBACK của page dò bằng chữ trong ảnh — dùng khi kịch bản không có mẫu /Feedback."""
    ra = []
    for m in (kb_page or {}).get("mau") or []:
        if _MAU_ANH_TIEN.search(_ten_mau(m)):
            continue
        for u in m.get("anh") or []:
            t = chu_trong_anh(u)
            if not t or u in ra:
                continue
            if _ANH_FB_MANH.search(t) or (_ANH_FB_CHAT.search(t) and _ANH_FB_KHACH.search(t)):
                ra.append(u)
    return ra[:toi_da]


def anh_san_pham(kb_page, toi_da=3):
    """Ảnh SẢN PHẨM để gửi kèm câu tư vấn (cùng cách chọn với lúc khách xin ảnh)."""
    m = mau_anh_cho_khach(kb_page)
    return [u for u in (m.get("anh") or []) if u][:toi_da] if m else []


# ══ ẢNH PHẢI ĐÚNG THÁNG KHÁCH HỎI (chủ shop 2026-09-21) ═══════════════════════════════════════
# Ca **Elsam Elsam · Veloura Collection in Uae 10:07**: khách nhắn *"April birth stone"* rồi
# *"Patingin po ako NG picture po ng April"* — AI gửi đúng 3 ảnh của mẫu /chaohang, mà tấm đầu là
# bộ trang sức **tháng 1 (January)**. Chủ shop: *"khách muốn đá sinh tháng 4, sao lại gửi ảnh
# tháng 1"*.
#
# Gốc: ảnh đi theo MẪU — cả cụm ảnh của mẫu, không ai soi từng tấm (anh_kem_luot). Page Veloura
# chỉ có 1 ảnh gắn nhãn tháng (January) + 1 bảng đủ 12 tháng, nên MỌI khách hỏi tháng nào cũng
# nhận về ảnh tháng 1. Page BirthStone Jewelry USUS thì ngược lại: có sẵn /THANG1…/THANG12, ảnh
# đúng tháng nằm ngay đó mà không ai chọn.
#
# Dò tháng của ẢNH: đọc chữ trong ảnh (state/anh_chu.json) và **chỉ nhận khi tấm ảnh gần như chỉ
# có mỗi tên tháng** — đo 3.041 ảnh đã OCR: 15 ảnh có chữ ngắn (11 ảnh đúng là nhãn tháng
# "January"…"December", OCR lệch "Jamuary"/"Aprill" vẫn nhận nhờ lệch 1 ký tự), còn 249 ảnh khác
# có tên tháng đều là feedback/giấy tờ/bảng giá — ở đó "March 12" là NGÀY, không phải nhãn tháng.
_THANG_EN = ["january", "february", "march", "april", "may", "june", "july", "august",
             "september", "october", "november", "december"]
_THANG_TL = ["enero", "pebrero", "marso", "abril", "mayo", "hunyo", "hulyo", "agosto",
             "setyembre", "oktubre", "nobyembre", "disyembre"]
_THANG_AR = ["يناير", "فبراير", "مارس", "ابريل", "مايو", "يونيو", "يوليو", "اغسطس",
             "سبتمبر", "اكتوبر", "نوفمبر", "ديسمبر"]
# Chữ tắt — ⛔ KHÔNG nhận "jan", "jun", "mar": trong tiếng Tagalog "jan" là *diyan* ("ang
# pakinabang ko jan"), còn "Jun"/"Mar" là tên người. Đo 1.900 tin khách: "jan" bắt oan 1 tin.
_THANG_TAT = {"feb": 2, "apr": 4, "jul": 7, "aug": 8, "sept": 9, "sep": 9,
              "oct": 10, "nov": 11, "dec": 12}
# Chữ đi kèm cho biết tháng đó là THÁNG SINH, không phải ngày giao / ngày lương.
# Chữ cho biết tháng đó là NGÀY GIAO / NGÀY LƯƠNG / ngày đặt — cắt trước, kể cả câu ngắn
# ("Delivery September 30").
_NGAY_GIAO_LUONG = re.compile(
    r"\bdeliver\w*|\bdelivery\b|\bship\w*|\barriv\w*|\bdumating\b|\bpadala\b|\bsahod\b|\bsahud\b"
    r"|\bsalary\b|\bsweldo\b|\bpayday\b|\border\w*\b(?!\s+(?:is|are)\b)|\bnext\s+month\b|\bbayad\b|توصيل|الراتب|راتب"
    # 22/09 (kho tin Đài): "I will pay you on october" là ngày TRẢ TIỀN; còn "My order is March and October" là
    # khách CHỌN tháng — "order is/are" không phải ngày đặt hàng.
    r"|\bpay\b|\bpaid\b|\bpayment\b|\bmagbabayad\b|\bbabayaran\b", re.I)
_NGU_CANH_THANG = re.compile(
    r"birth\w*|bday|\bborn\b|kapanganakan|ipinanganak|\bstones?\b|zodiac|horoscope"
    r"|colou?rs?|\bkulay\b|مواليد|ميلاد|برج|حجر"
    # 22/09 (ca Marah Martin · Glamora Jewelry: "OCOTOBER OPAL CAN YOU SEND THE PICTURE FROM HERE.."): tên ĐÁ
    # sinh tháng, chữ ẢNH, chữ MÓN HÀNG cũng nói tháng đó là tên hàng — cùng bộ chữ với _THANG_LA_HANG (cổng
    # hẹn quá hạn, 14/09). Trước đó câu dài hơn 3 chữ mà thiếu birth/stone/color là rơi hết, kể cả câu viết
    # đúng "Can you send picture of october".
    r"|garnet|amethyst|aquamarine|bloodstone|diamond|emerald|pearl|moonstone|alexandrite|\brub(?:y|ies)\b"
    r"|peridot|sardonyx|spinel|sapphire|\bopals?\b|tourmaline|topaz|citrine|turquoise|tanzanite|zircon"
    r"|\b(?:pics?|pictures?|photos?|images?|larawan|litrato|fotos?)\b|صور"
    r"|\b(?:sets?|designs?|pendants?|necklaces?|rings?|earrings?|bracelets?|jewel\w*|kwintas|singsing|hikaw)\b"
    r"|\bavail\w*|\bstocks?\b|\bmonth\s+of\b|\bbuwan\b|طقم|خاتم|سلسال|قلادة"
    # 22/09 (kho tin Stone Jewelry Saudi - Taiwan): HỎI GIÁ tháng đó ("How much Po June") và xin XEM bằng tiếng
    # Tagalog ("Patingin po ng july") cũng là hỏi bộ của tháng đó.
    r"|\bh(?:o)?w\s+much\b|\bmagkano\b|\bmagkanu\b|\bmagkno\b|\bmgkano\b|\bprices?\b|\bpresyo\b|بكم|سعر"
    r"|\bpatingin\b|\bpakita\b|\bpatingnan\b|\bpatignan\b", re.I)
# Cụm THỜI GIAN quanh tên tháng — tháng đó là lúc MUA / lúc nhận, không phải tháng sinh (22/09): "sa October pa"
# (tới tháng 10 mới lấy), "hanggang / until / pagdating ng / katapusan ng October".
# Chữ SINH / ĐÁ / MÀU — đủ chắc để giữ tháng khách nói TRƯỚC chữ giao hàng / lương trong cùng câu (22/09).
_NGU_CANH_SINH = re.compile(
    r"birth\w*|bday|\bborn\b|kapanganakan|ipinanganak|\bstones?\b|zodiac|colou?rs?|\bkulay\b|مواليد|ميلاد|برج|حجر"
    r"|garnet|amethyst|aquamarine|bloodstone|diamond|emerald|pearl|moonstone|alexandrite|\brub(?:y|ies)\b"
    r"|peridot|sardonyx|spinel|sapphire|\bopals?\b|tourmaline|topaz|citrine|turquoise|tanzanite|zircon", re.I)
# "Jan" TRONG DANH SÁCH THÁNG ("Jan at June", "Dec.and Jan." — kho tin Veloura / Glamora 22/09). Đứng một mình "jan"
# vẫn là Tagalog *diyan* ("pic jan", "jan n 7-11") nên không nhận; nối với tên tháng khác bằng and/at/&/,/ thì là tháng 1.
_TEN_THANG_RE = "|".join(sorted(set(_THANG_EN + _THANG_TL) | set(_THANG_TAT), key=len, reverse=True))
_JAN_TRONG_DS = re.compile(r"\bjan\b\.?\s*(?:and|at|&|,|/|or)\s*(?:" + _TEN_THANG_RE + r")\b"
                           r"|\b(?:" + _TEN_THANG_RE + r")\b\.?\s*(?:and|at|&|,|/|or)\s*jan\b")
_THOI_HAN_THANG = re.compile(
    r"\bsa\s+([a-z]{3,12})\.?\s+pa\b"
    r"|\b(?:hanggang|until|till|untill|pagdating\s+ng|katapusan\s+ng)\s+(?:sa\s+|ng\s+)?([a-z]{3,12})\b", re.I)


def _lech1(a, b):
    """Hai chữ chỉ lệch nhau tối đa 1 ký tự (OCR đọc 'January' thành 'Jamuary', 'April'→'Aprill')."""
    if a == b:
        return True
    if abs(len(a) - len(b)) > 1:
        return False
    if len(a) == len(b):
        return sum(x != y for x, y in zip(a, b)) == 1
    if len(a) > len(b):
        a, b = b, a
    i = 0
    while i < len(a) and a[i] == b[i]:
        i += 1
    return a[i:] == b[i + 1:]


# Chữ ≥ 6 ký tự nằm sát tên tháng mà KHÔNG phải tháng — tên người hay gặp ở khách Philippines.
# Chữ ĐỆM trong câu liệt kê tháng ("July and January po") — không mang nghĩa ngày giờ (22/09).
_TU_DEM = {"and", "at", "or", "o", "po", "poh", "pu", "lang", "lng", "ang", "ung", "yung", "yong", "sa", "ng", "ko",
           "ako", "pls", "please", "plz", "sis", "maam", "ma'am", "mam", "madam", "mdm", "sir", "ok", "okay", "yes",
           "oo", "opo", "the", "a", "is", "are", "my", "i", "im", "i'm", "am", "for", "of", "also", "naman", "din",
           "rin", "na", "ba", "dear", "hi", "hello"}
_KHONG_PHAI_THANG = {"augusto", "augusta", "auguste", "augusti", "pedrero"}


def _go_sai1(a, b):
    """Chữ khách GÕ lệch đúng 1 lỗi so với b: thừa / thiếu / sai 1 ký tự, hoặc đảo 2 ký tự liền nhau.

    Khác _lech1 (lỗi OCR) ở chỗ nhận thêm lỗi đảo chữ — người gõ nhanh hay đảo ("otcober", "novmeber")."""
    if _lech1(a, b):
        return True
    if len(a) != len(b):
        return False
    k = [i for i in range(len(a)) if a[i] != b[i]]
    return len(k) == 2 and k[1] == k[0] + 1 and a[k[0]] == b[k[1]] and a[k[1]] == b[k[0]]


def _la_ten_thang(w):
    """Số tháng của MỘT chữ khách gõ: đúng tên (Anh / Tagalog), chữ tắt, hoặc tên DÀI (≥ 6 chữ) gõ lệch 1 lỗi.
    Không phải tháng thì None."""
    w = (w or "").lower().rstrip(".")
    if w in _KHONG_PHAI_THANG:
        return None
    for ds in (_THANG_EN, _THANG_TL):
        for i, m in enumerate(ds, 1):
            if w == m or (len(m) >= 6 and len(w) >= 6 and _go_sai1(w, m)):
                return i
    return _THANG_TAT.get(w)


def _thang_cua_ten_mau(ten):
    """Tháng suy từ TÊN mẫu: /THANG4, /thang_4, /April — cứu ảnh mà OCR đọc hỏng
    (ảnh tháng 6 của BirthStone Jewelry USUS, Vision đọc ra 'aunf')."""
    t = qht.norm(ten or "")
    m = re.search(r"\bth?ang[\s_-]*(\d{1,2})\b", t)
    if m and 1 <= int(m.group(1)) <= 12:
        return int(m.group(1))
    for i, x in enumerate(_THANG_EN, 1):
        # ⛔ bỏ "may": tên mẫu tiếng Việt "công-việc-may-mắn" của page Aurelia Jewelry US bị đọc
        # thành tháng 5, mở oan cổng này cho một page KHÔNG bán theo tháng sinh.
        if x != "may" and re.search(r"\b" + x + r"\b", t):
            return i
    return None


def thang_cua_anh(u, ten_mau=""):
    """Tháng mà TẤM ẢNH này nói — None nếu không chắc (ảnh nhiều chữ, ảnh không nhãn tháng).

    ⛔ Đừng nới thành 'ảnh nào có tên tháng': 249/264 ảnh có tên tháng là feedback/giấy tờ,
    ở đó chữ tháng là ngày gửi hàng. Chặt như vậy mới không cắt oan ảnh feedback."""
    t = (chu_trong_anh(u) or "").strip()
    tu = [w.lower() for w in re.findall(r"[A-Za-z]{3,12}", t)]
    # Ảnh nhãn tháng của các page này là "January" hoặc "OPAL/TOURMALINE | october" — chữ RẤT ít.
    # Nới tới 5 chữ / 60 ký tự để nhận nốt ảnh tháng 10-11-12 của Veloura, vẫn chặn ảnh feedback,
    # giấy tờ, bảng giá (đo 1.237 ảnh: không ảnh nào mới lọt sai).
    if tu and len(tu) <= 5 and len(t) <= 60:
        ra = {i for w in tu for i, m in enumerate(_THANG_EN, 1)
              # ⛔ tháng ngắn (may/june/july) phải khớp Y HỆT: lệch-1 biến "pay"/"day" thành "may"
              # (ảnh "Scan to pay", "Wash face | Apply 2-3 drops" từng bị nhận là tháng 5).
              if (w == m if len(m) <= 4 else _lech1(w, m))}
        if len(ra) == 1:
            return ra.pop()
    return _thang_cua_ten_mau(ten_mau) or _thang_theo_ban_do(u, t) or None


# BẢN ĐỒ ẢNH → THÁNG DÙNG CHUNG (quet_thu_muc_anh.py dựng, state/anh_thang.json): cùng một tấm
# ảnh dùng cho nhiều page, page nào đặt tên đích danh ("Tháng6.jpeg", mẫu /THANG6) thì mọi page
# dùng ảnh đó đều biết. Cứu đúng ảnh tháng 6 của bộ đá sinh tháng — Vision đọc chữ "June" viết
# tay thành "aunf", không page nào tự đọc ra.
_BD_THANG = {"luc": 0, "d": {}}


def _f_anh_thang():
    return os.path.join(SCRIPT_DIR, "state", "anh_thang.json")


def _thang_theo_ban_do(u, chu=""):
    """Tháng của ảnh theo bản đồ dùng chung: khớp URL, không thì khớp CHỮ đọc được trong ảnh
    (cùng tấm ảnh tải lên hai lần là hai URL khác nhau, nhưng chữ đọc ra giống hệt)."""
    try:
        m = os.path.getmtime(_f_anh_thang())
    except OSError:
        return None
    if m != _BD_THANG["luc"]:
        _BD_THANG["d"] = qht.load_json(_f_anh_thang(), {})
        _BD_THANG["luc"] = m
    d = _BD_THANG["d"] or {}
    # Giá trị 0 = ĐÃ ĐỌC và ảnh KHÔNG có tên tháng (doc_thang_anh.py ghi lại để khỏi đọc lại) —
    # phải trả None, không thì chỗ lọc coi nó là "tháng 0" rồi bỏ oan tấm ảnh.
    th = (d.get("theo_url") or {}).get(u)
    if th:
        return th
    c = (chu or "").strip().lower()
    return ((d.get("theo_chu") or {}).get(c) or None) if 4 <= len(c) <= 24 else None


# MAY_SET_2809 (ca Mhel Primavera Tagulao · Glamora Jewelry 28/09): AI hỏi "1 set o 2 sets?", khách đáp "May 2 sets" = bộ tháng 5,
# 2 bộ (chủ shop chốt) — máy coi "may" là Tagalog 'có', không biết tháng, cửa báo giá kèm ảnh bộ JANUARY. Đo so_chi_phi 8 nước
# + kho 1.441 hội thoại page tháng: "may 9", "may 20", "may 26, 1978", "May 05,1974 ako magkanu po" (page đá sinh tháng) đều là
# NGÀY SINH tháng 5 mà máy bỏ sót. ⛔ "may + số + đơn vị" là 'có': "may 16 inches poh kau", "may 1 box free po ba?", "may 3 akong
# anak" — nên chỉ nhận: "may <ngày>" CẢ TIN (thêm po/ako), "may <ngày> <năm sinh>", và "May <n> set(s)/pcs" CẢ TIN, không dấu hỏi.
# Mọi đường ảnh tháng chỉ chạy ở page có ảnh nhãn tháng, nên page khác không đổi gì.
_MAY_NGAY_SINH = re.compile(
    r"^[\s.!,]*mayo?\s*(?:0?[1-9]|[12]\d|3[01])(?:st|nd|rd|th)?[\s.!,]*(?:(?:po|poh|pu|ako)[\s.!,]*)?$"
    r"|\bmayo?\s*(?:0?[1-9]|[12]\d|3[01])(?:st|nd|rd|th)?\s*[,./-]?\s*(?:19[3-9]\d|200\d|201[0-5])\b")
_MAY_CHON_BO = re.compile(
    r"^[\s.!,]*mayo?\s*(?:[1-9]|10)\s*(?:sets?|pcs?|pieces?|bo)\b[\s.!,]*(?:(?:po|poh|pu|lang|lng|only|na)[\s.!,]*)*$")


def _thang_trong_cau(t, chat=True):
    """Các THÁNG khách nói trong MỘT câu — tiếng Anh, Tagalog, Ả Rập, chữ tắt (Apr, Sept).

    Trả về tập tháng, vì khách hỏi hai tháng một lúc là chuyện thường ("Anong kulay ung April
    sis at February") — lấy một tháng là gửi thiếu ảnh.

    ⚠️ 'may' (Anh: có thể) và 'mayo' (Tagalog: 'may' = có) là chữ hay gặp nhất trong tin khách —
    chỉ tính là THÁNG 5 khi đứng một mình hoặc đi với chữ sinh/birthday."""
    s = qht.norm(t or "")
    ra = set()
    for i, m in enumerate(_THANG_EN, 1):
        if m != "may" and re.search(r"\b" + m + r"\b", s):
            ra.add(i)
    for i, m in enumerate(_THANG_TL, 1):
        if m != "mayo" and re.search(r"\b" + m + r"\b", s):
            ra.add(i)
    for i, m in enumerate(_THANG_AR, 1):
        if m in s:
            ra.add(i)
    for w, i in _THANG_TAT.items():
        if re.search(r"\b" + w + r"\.?\b", s):
            ra.add(i)
    # GÕ SAI TÊN THÁNG (22/09, ca Marah Martin · Glamora Jewelry): "OCOTOBER" dư một chữ o nên trượt
    # \boctober\b, AI gửi ảnh bộ sưu tập mà một tấm là bộ tháng 4. Tên tháng DÀI (≥ 6 chữ) nhận lệch 1 ký tự
    # hoặc đảo 2 ký tự liền nhau ("octuber", "otcober", "febuary", "oktober", "decembre"). ⛔ Tháng NGẮN phải
    # khớp y hệt: "march" lệch 1 là "marah" (chính tên khách ca này) / "match"; "hunyo"/"hulyo" lệch 1 là nhau.
    for w in re.findall(r"\b[a-z]{6,12}\b", s):
        i = _la_ten_thang(w)
        if i:
            ra.add(i)
    if (s.strip(" .!?") in ("may", "mayo")
            # "Month of MAY at SEPTEMBER po", "a set of May" (22/09, kho tin Glamora / Veloura): sau "of" / "ng" thì
            # "may" không thể là tiếng Anh 'có thể' hay Tagalog 'có'.
            or re.search(r"\b(?:months?|sets?|stones?|birthstones?|colou?rs?|kulay)\s+(?:of|ng)\s+mayo?\b", s)
            or re.search(r"\b(?:born|birth\w*|bday|kapanganakan|ipinanganak)\b[^.!?]{0,24}\bmayo?\b", s)
            or re.search(r"\bmayo?\b[^.!?]{0,24}\b(?:birth\w*|bday|kapanganakan)\b", s)
            or _MAY_NGAY_SINH.search(s) or _MAY_CHON_BO.search(s)):      # MAY_SET_2809
        ra.add(5)
    if ra and _JAN_TRONG_DS.search(s):
        ra.add(1)                                   # "Jan at June", "Dec.and Jan." (xem _JAN_TRONG_DS)
    if not ra or not chat:
        return ra
    # CHẶT: tháng chỉ tính là THÁNG SINH khi câu có chữ sinh/đá/màu, hoặc khách nhắn trống không
    # ("October", "At july?"). Đo 1.689 tin khách thật: cắt 24 câu NGÀY GIAO / NGÀY LƯƠNG
    # ("22 sep 10'o clock deliver", "Sa october 15 pa sahod ko", "Delivery September 30") — gửi
    # ảnh tháng 10 cho khách sinh tháng khác chỉ vì khách hẹn ngày lương thì còn sai hơn cũ.
    _cat_ = _NGAY_GIAO_LUONG.search(s)
    if _cat_:
        # 22/09 (kho tin Đài: "July birthstone Ruby color Delivery date october 9"): tháng nói TRƯỚC chữ giao / lương
        # mà đoạn đó có chữ sinh / đá / màu thì vẫn là tháng sinh; từ chữ giao trở đi là ngày giao — bỏ.
        _truoc_ = s[:_cat_.start()]
        return _thang_trong_cau(_truoc_, chat=False) if _NGU_CANH_SINH.search(_truoc_) else set()
    # THÁNG LÀ LÚC MUA, không phải tháng sinh (22/09, kho tin Oman Gold Lucky Jewelry): "2 sets po ang kunin ko
    # pero sa October pa po" = tới tháng 10 mới lấy. Chỉ bỏ ĐÚNG tháng nằm trong cụm thời gian đó. ⛔ KHÔNG cắt
    # "tên tháng + số ngày": ở page đá sinh tháng "September 6,1973", "June 11 1983", "October 30" là NGÀY SINH
    # (đo 1.780 câu khách của 14 page có ảnh nhãn tháng).
    ra -= {_la_ten_thang(mt.group(1) or mt.group(2)) for mt in _THOI_HAN_THANG.finditer(s)}
    if not ra:
        return set()
    if _NGU_CANH_THANG.search(s) or len(s.split()) <= 3:
        return ra
    # DANH SÁCH THÁNG ("July and January po", "My order is March and October" — kho tin Đài 22/09): ≥ 2 tháng mà
    # ngoài tên tháng chỉ còn chữ đệm và tối đa 1 chữ khác.
    if len(ra) >= 2 and len([w for w in re.findall(r"[a-z']+", s)
                             if w not in _TU_DEM and not _la_ten_thang(w)]) <= 1:
        return ra
    return set()


# 23/09 (chủ shop: "sao b k gửi thêm ảnh set tháng 2 cho khách luôn", ca Rovzjacrys Mejico · Veloura Collection): khách hỏi
# "vàng thật?" kèm NGÀY SINH "04 tháng 2" trong CÙNG câu → câu > 3 chữ, không có chữ born/birthday → luật CHẶT bỏ tháng → AI chỉ
# gửi ảnh chứng nhận, sale Trang tự gửi ảnh bộ tháng 2. Dạng NGÀY-THÁNG ("Feb 04", "04 February", "February 4th") ở page có ảnh
# tháng là NGÀY SINH (đo 1.780 câu khách 14 page — xem _thang_trong_cau) → nhận khi câu không có chữ giao / lương / đơn / nhận
# hàng và câu page ngay trước không hỏi ngày giao. "may" không tính (Anh 'có thể', Tagalog 'có': "may 2 po").
_THANG_SO_TEN = (r"(?:january|february|march|april|june|july|august|september|october|november|december"
                 r"|jan|febr?|mar|apr|jun|jul|aug|sept?|oct|nov|dec)")
_NGAY_THANG_SO = re.compile(r"\b(?:0?[1-9]|[12]\d|3[01])(?:st|nd|rd|th)?\s*(?:of\s+)?" + _THANG_SO_TEN + r"\b"
                            r"|\b" + _THANG_SO_TEN + r"\.?\s*(?:0?[1-9]|[12]\d|3[01])(?:st|nd|rd|th)?\b", re.I)


# Đo kho 3.017 hội thoại cũ: "tháng + ngày" KHÔNG năm phần lớn là NGÀY GIAO / GIỮ ĐƠN ("I want it on Oct. 8", "sa oct 5",
# "October 30 me reserve now", "Reschedule on 28 Sept", "October 1 sorry mam" sau khi đã chốt đơn); ngày sinh thật hay kèm
# NĂM ("November 8 1995", "Feb 21 1976"). → có năm sinh thì nhận; không năm thì chỉ câu NGẮN, không chữ hẹn ngày, lúc CHƯA
# vào chuyện đơn / giao hàng (page chưa nói "your order", chưa hỏi ngày nhận, khách chưa cho SĐT).
_NAM_SINH = re.compile(r"\b(?:19[3-9]\d|200\d|201[0-5])\b")
_HEN_NGAY = re.compile(r"\b(?:on|sa|by|until|till|til|after|before|this|next|last|pa|at|is|from|reserv\w*|resched\w*"
                       r"|sched\w*|want|need|possible|pwede|can|will|deliver\w*|receiv\w*)\b", re.I)
_PAGE_VAO_DON = re.compile(r"\bwhen\b|which\s+day|what\s+(?:day|date)|\bdate\b|kailan|petsa|\breserv\w*|\bresched\w*"
                           r"|you\s+will\s+receive", re.I)


def _thang_ngay_sinh(t, msgs, j):
    """Tháng của NGÀY SINH dạng ngày-tháng trong câu khách thứ j (câu luật chặt đã bỏ) → {tháng} hoặc set()."""
    s = qht.norm(t or "")
    if not _NGAY_THANG_SO.search(s) or _NGAY_GIAO_LUONG.search(s) or _THANG_KHONG_SINH.search(s):
        return set()
    ra = _thang_trong_cau(t, chat=False)
    ra -= {_la_ten_thang(mt.group(1) or mt.group(2)) for mt in _THOI_HAN_THANG.finditer(s)}
    if len(ra) != 1:
        return set()
    if not _NAM_SINH.search(s):
        if len(s.split()) > 6 or _HEN_NGAY.search(s):
            return set()
        _pg_ = [lam_sach(x.get("text") or "") for x in (msgs or [])[:j]
                if x.get("boi") in ("ai", "nguoi", "botcake") and (x.get("text") or "").strip()][-8:]
        if any(_PAGE_VAO_DON.search(p) or _SALE_XU_DON.search(p) for p in _pg_):
            return set()
        if khach_gui_sdt_vi_tri([x for x in (msgs or [])[:j] if x.get("boi") == "khach"]):
            return set()
    truoc = next((lam_sach(x.get("text") or "") for x in reversed((msgs or [])[:j])
                  if x.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(x.get("text") or "").strip()), "")
    if truoc and _PAGE_HOI_NGAY.search(truoc) and not _NGU_CANH_THANG.search(truoc):
        return set()
    return ra


def thang_khach_hoi(msgs, so_tin=14):
    """Tháng sinh khách đã nói trong hội thoại — lấy lần nhắc GẦN NHẤT (khách đổi ý thì theo mới)."""
    dem = 0
    ms = msgs or []
    for j in range(len(ms) - 1, -1, -1):
        m = ms[j]
        if m.get("boi") != "khach":
            continue
        t = lam_sach(m.get("text") or "")
        th = _thang_trong_cau(t) or _thang_ngay_sinh(t, ms, j)
        if th:
            return th
        dem += 1
        if dem >= so_tin:
            break
    return set()


# THƯ MỤC ẢNH CỦA PAGE (chủ shop 2026-09-21: *"Glamora Jewelry có đây rồi mà"*) — 12 ảnh đá sinh
# tháng bt1…bt12 nằm trong THƯ MỤC ẢNH của page, kịch bản chỉ đính mỗi ảnh tháng 1. AI trước nay
# chỉ nhìn ảnh trong kịch bản nên không biết chúng tồn tại. `quet_thu_muc_anh.py` quét sẵn ra
# state/<tt>/thu_muc_anh.json (không gọi API trong vòng chạy).
#
# ⚠️ CHỈ dùng cho việc chọn ảnh ĐÚNG THÁNG. Thư mục ảnh là kho lẫn lộn (ảnh chat, ảnh giấy tờ,
# ảnh sale tự tải lên) — lấy bừa ra gửi khách là hỏng. Tháng của ảnh vẫn đọc bằng CHỮ TRONG ẢNH;
# tên file chỉ là đường lùi, vì chính Glamora đặt tên lệch: bt11.jpg in chữ "December",
# bt12.jpg in chữ "September".
_TMA_BO = {}                                  # mkey -> (mtime, dict)


def _f_thu_muc_anh(mkey):
    return os.path.join(SCRIPT_DIR, "state", mkey or "chung", "thu_muc_anh.json")


def thu_muc_anh(mkey, pid):
    """[{"u": url, "ten": tên file}] trong thư mục ảnh của page — chưa quét thì rỗng."""
    f = _f_thu_muc_anh(mkey)
    try:
        m = os.path.getmtime(f)
    except OSError:
        return []
    cu = _TMA_BO.get(mkey)
    if not cu or cu[0] != m:
        _TMA_BO[mkey] = (m, qht.load_json(f, {}))
    return ((_TMA_BO[mkey][1].get(str(pid)) or {}).get("anh") or [])


# Chữ NGÀY NHẬN / ĐƠN HÀNG mà _NGAY_GIAO_LUONG chưa có — ca Stone Jewelry (kho tin cũ 22/09): khách đã có đơn hỏi
# "What date my pack maam" rồi gõ "September" = tháng NHẬN HÀNG, sale đáp "Which day in September will you receive it?".
_THANG_KHONG_SINH = re.compile(r"\bdate\b|\bpack\w*|\bparcel\b|\breceiv\w*|\bkailan\b|\bpetsa\b|موعد|استلام", re.I)
# Câu PAGE hỏi ngày giao / ngày nhận (không tính "order": "Do you wanna order 1 or 2 pcs?" rồi khách "march" là chọn bộ).
_PAGE_HOI_NGAY = re.compile(r"\b(?:deliver\w*|receiv\w*|arriv\w*|dating|date|which\s+day|what\s+day|kailan|petsa)\b"
                            r"|موعد|استلام|توصيل", re.I)


def khach_bao_thang_sinh(msgs):
    """Tháng SINH khách vừa nói trong chuỗi tin CHƯA được đáp (tin khách sau tin page cuối) → tập tháng, không thì set().

    Chủ shop 22/09 (ca Galas Elvira · Glamora Jewelry 12:34): khách bấm quảng cáo đá sinh tháng rồi gõ đúng "january"
    → 1 chữ → vo_nghia → AI TREO, sale Duyên tự gửi ảnh bộ tháng 1 + giá sau 3 phút. Tháng đọc bằng _thang_trong_cau
    (đã loại ngày giao / ngày lương trong cùng câu); thêm rào cả chuỗi: khách hay page vừa nói tới ngày nhận / giao /
    đơn hàng thì tháng đó là tháng NHẬN HÀNG, không phải tháng sinh.
    """
    chuoi, truoc = [], ""
    for m in reversed(msgs or []):
        b = m.get("boi")
        if b == "khach":
            chuoi.append(lam_sach(m.get("text") or ""))
        elif b in ("botcake", "nguoi", "ai") and lam_sach(m.get("text") or "").strip():
            truoc = lam_sach(m.get("text") or "")
            break
    ra = set()
    for t in chuoi:
        ra |= _thang_trong_cau(t)
    if not ra:
        return set()
    if any(_NGAY_GIAO_LUONG.search(t) or _THANG_KHONG_SINH.search(t) for t in chuoi):
        return set()
    if truoc and _PAGE_HOI_NGAY.search(truoc) and not _NGU_CANH_THANG.search(truoc):
        return set()
    return ra


def anh_nhieu_thang_cho_khach(kb_page, msgs, mkey, pid, toi_da=4):
    """Page đá sinh tháng (bảng ảnh ≥6 tháng), khách xin ảnh / mẫu khác mà CHƯA nói tháng → ≤1 ảnh BẢNG TỔNG HỢP (chữ trong ảnh
    có ≥4 tên tháng) + bộ của các THÁNG KHÁC NHAU, rải đều trong năm, khách chưa thấy (25/09, ca Lle Che · Glamora Jewelry:
    bộ sưu tập lọc sẵn chỉ còn 3 tấm, cả 3 là bộ tháng 4). Không phải page tháng → [] để đi đường bộ sưu tập cũ."""
    bang = _anh_theo_thang_page(kb_page, mkey, pid)
    if len(bang) < 6:
        return []
    nguon = [u for m in (kb_page or {}).get("mau") or [] for u in (m.get("anh") or []) if u]
    nguon += [x.get("u") for x in (thu_muc_anh(mkey, pid) if pid else []) if x.get("u")]
    tong = []
    for u in nguon:
        t = (chu_trong_anh(u) or "").lower()
        if u not in tong and sum(1 for x in _THANG_EN if x in t) >= 4:
            tong.append(u)
    thang = sorted(bang)
    chua = set(_anh_khach_chua_thay(msgs, tong[:3] + [bang[x][0] for x in thang if bang.get(x)]))
    ra = [u for u in tong[:3] if u in chua][:1]
    con = [x for x in thang if bang.get(x) and bang[x][0] in chua]
    can = toi_da - len(ra)
    if con and can > 0:
        buoc = max(1, len(con) // can)
        for x in (con[::buoc] + con)[:len(con)]:
            if len(ra) >= toi_da:
                break
            if bang[x][0] not in ra:
                ra.append(bang[x][0])
    return ra


def _anh_theo_thang_page(kb_page, mkey=None, pid=None):
    """{tháng: [ảnh]} của page — kịch bản trước, thư mục ảnh của page sau.

    Page không có ảnh nào gắn nhãn tháng thì rỗng, và luật "ảnh đúng tháng" đứng im."""
    d = {}
    for m in (kb_page or {}).get("mau") or []:
        ten = (m.get("tu_khoa") or "").strip()
        for u in m.get("anh") or []:
            th = thang_cua_anh(u, ten)
            if th:
                d.setdefault(th, []).append(u)
    for x in (thu_muc_anh(mkey, pid) if pid else []):
        u = x.get("u")
        if not u:
            continue
        th = thang_cua_anh(u, x.get("ten") or "")
        if th and u not in d.get(th, []):
            d.setdefault(th, []).append(u)
    return d


def anh_dung_thang_khach(kb_page, anh, msgs, nhan="", mkey=None, pid=None):
    """Bỏ ảnh SAI tháng khách hỏi, và thay bằng ảnh ĐÚNG tháng nếu kịch bản page có.

    Chỉ động vào page có ảnh gắn nhãn tháng (trang sức đá sinh tháng); page khác trả nguyên."""
    anh = [u for u in (anh or []) if u]
    if not anh:
        return anh
    bang = _anh_theo_thang_page(kb_page, mkey, pid)
    if not bang:
        return anh
    th = thang_khach_hoi(msgs)
    if not th:
        return anh
    ten_cua = {}
    for m in (kb_page or {}).get("mau") or []:
        for u in m.get("anh") or []:
            ten_cua.setdefault(u, (m.get("tu_khoa") or "").strip())
    giu, bo = [], []
    for u in anh:
        t = thang_cua_anh(u, ten_cua.get(u, ""))
        (giu if (t is None or t in th) else bo).append(u)
    dung = []
    for x in sorted(th):
        for u in bang.get(x) or []:
            if u not in giu and u not in dung:
                dung.append(u)
    if bo or dung:
        _t = "/".join(str(x) for x in sorted(th))
        print(f"{nhan} 🖼  khách hỏi tháng {_t} — bỏ {len(bo)} ảnh sai tháng"
              + (f", thay bằng {len(dung)} ảnh đúng tháng" if dung else
                 " (kịch bản page không có ảnh tháng này)"))
    return (dung + giu)[:4]


def anh_thang_cho_khach(kb_page, msgs, mkey, pid, conv_id=None):
    """(ảnh, loại) ĐÚNG tháng khách đã nói, khi page có ảnh tháng đó và hội thoại CHƯA nhận chùm này;
    không có thì ([], "").

    Đi TRƯỚC ảnh bộ sưu tập / ảnh mẫu kịch bản khi khách xin ảnh (chủ shop 22/09, ca Marah Martin · Glamora
    Jewelry: *"khách hỏi tháng 10 mà sao bạn lại gửi ảnh tháng 4"*). Ở page đá sinh tháng, bộ sưu tập là bộ
    của các THÁNG KHÁC — khách đã nói tháng thì ảnh bộ tháng đó mới là thứ khách xin."""
    th = thang_khach_hoi(msgs)
    if not th:
        return [], ""
    bang = _anh_theo_thang_page(kb_page, mkey, pid)
    anh = [u for x in sorted(th) for u in (bang.get(x) or [])][:4]
    loai = "th" + "-".join(str(x) for x in sorted(th))
    if not anh or (conv_id and anh_loai_da_gui(mkey, conv_id, loai)):
        return [], ""
    return anh, loai


# HỎI THẬT-GIẢ BẰNG CHỮ KHÁC: "legit", "totoo", "tunay", "real gold" — HOI_THAT_GIA không có những
# chữ này (nó dựng cho cửa CÂU CHỮ, đo trên "original|fake"), nên chính câu của ca Evelyn Peralta
# *"Is this tea legit"* rơi ra ngoài. Đo 99.562 tin khách thật: thêm 668 tin vào cửa ẢNH, soi 30 câu
# ngẫu nhiên khác nhau (205 câu) thì cả 30 đều là hỏi hàng thật ("legit ba Yan ma'am", "totoo po ba
# ito?", "Is it real gold?"). Cố ý KHÔNG nới HOI_THAT_GIA: nó đang lái cả cổng chữ "100% original".
_THAT_GIA_ANH = re.compile(
    r"\blegit\w*\b|\bligit\b|\btunay\b|\btotoo\b|\bhindi\s+(?:po\s+)?peke\b|\basli\b"
    r"|\breal\s+(?:gold|silver|18k|22k|jade|stone|diamond|pearl|product|item|one|thing|tea)\b"
    r"|\b(?:is|are)\s+(?:it|this|that|these|they|the)\b[^.!?]{0,24}\b(?:real|true)\b"
    r"|\bis\s+it\s+(?:really\s+)?true\b|\btrue\s+(?:po\s+)?ba\b|\btotoo\s+ba\b"
    r"|\bsiguro\s+ba\b|\bhindi\s+ba\s+(?:peke|fake)\b|حقيقي|حقيقية|مضمون|真的|真品", re.I | re.U)


def khach_hoi_that_gia(msgs, so_tin=3):
    """Khách vừa HỎI hàng thật hay giả / so với sàn, trong các tin chưa được đáp.

    Khác khach_so_noi_khac (cửa CÂU CHỮ): ở đó page bán vàng bị loại vì chất liệu phải theo kịch
    bản. Cửa ẢNH thì ngược lại — 120 page có giấy chứng nhận, phần lớn là trang sức, và tờ giấy
    là câu trả lời đúng nhất cho "gold ba talaga ito".
    """
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                kh.append(t)
        elif m.get("boi") != "hethong":
            break
    return any(SO_SAN_NOI_KHAC.search(t)
               or ((HOI_THAT_GIA.search(t) or _THAT_GIA_ANH.search(t))
                   and _CAU_HOI_TG.search(t) and not _khieu_nai_don_cu(t))
               or _hoi_that_ngan(t) or _NGHI_THAT_ID.search(t)
               for t in kh[:so_tin])


# CÂU AI NHẮC GIẤY CHỨNG NHẬN (chủ shop 22/09, ca Delia Ylagan · Oman Gold Lucky Jewelry): *"bạn nhắc tới chứng
# nhận, sao k gửi kèm ảnh giấy chứng nhận"*. Đo sổ việc 6 nước Vịnh 12 ngày: 706/9.444 tin AI nhắc certificate,
# chỉ 51 tin có kèm ảnh. 34,7 giờ từ lúc cổng ảnh chứng nhận bật (20/09 tối): AI nhắc giấy ở 153 hội thoại mà
# chỉ 6 hội thoại nhận ảnh — vì cổng cũ chỉ soi CÂU KHÁCH (legit/totoo/real gold). Đo 0 câu phủ định
# ("walang certificate") trong 706 câu; tiếng Ả Rập "شهادات العملاء" là LỜI KHEN khách nên bỏ ra.
_AI_NHAC_CN = re.compile(
    r"\bcertific\w*|\bcertified\b|\bsertipik\w*|\bsertifik\w*|\bbersertifikat\b|\bkatibayan\b"
    r"|شهاد[ةه]|شهادات|证书|證書|认证|認證|प्रमाणपत्र|प्रमाण\s+पत्र|সার্টিফিকেট|সনদ|\blab\s+report\b"
    # 25/09 (ca Emmalyn Bentolan): "100% real and FDA registered" — giấy FDA là giấy tờ; 72h 291 hội thoại nói FDA mà không kèm gì
    r"|\bFDA[\s-]*(?:registered|approved|certified|accredited|registration|approval)\b", re.I | re.U)
_AI_CHOI_CN = re.compile(
    r"(?:\bno|\bwithout|\bwalang?|\bwala\s+(?:pong?\s+)?|\bdon'?t\s+have\s+(?:a|any)?|\bdo\s+not\s+have"
    r"|\bhindi\s+(?:po\s+)?kasama|\bnot\s+(?:include|come\s+with))\s+(?:\w+\s+){0,2}(?:certific|sertip)"
    r"|birth\s+certific|(?:شهادة|شهاده|شهادات)\s+(?:ال)?عملا[ءئ]", re.I | re.U)


def ai_nhac_chung_nhan(tin):
    """Câu AI vừa soạn có nói tới giấy chứng nhận (certificate / certified / شهادة …) mà không phải câu phủ định."""
    t = tin or ""
    return bool(_AI_NHAC_CN.search(t)) and not _AI_CHOI_CN.search(t)


def _anh_khach_chua_thay(msgs, urls):
    """Bỏ ảnh khách ĐÃ thấy trong hội thoại (page/sale/Botcake/AI gửi) — cùng URL, hoặc dHash lệch ≤6 bit
    (Botcake/sale gửi lại cùng ảnh là URL khác, như ca Lanie 21/09)."""
    urls = [u for u in (urls or []) if u]
    da_thay = [u for m in (msgs or []) if m.get("boi") in ("botcake", "nguoi", "ai")
               for u in (m.get("anh") or []) if u][-12:]
    urls = [u for u in urls if u not in da_thay]
    if not urls or not da_thay:
        return urls
    from concurrent.futures import ThreadPoolExecutor as _TPE_CN
    with _TPE_CN(max_workers=4) as bom:
        dh_da = [h for h in bom.map(_dhash_anh, da_thay) if h is not None]
        dh_moi = list(bom.map(_dhash_anh, urls))
    return [u for u, h in zip(urls, dh_moi)
            if h is None or not any(bin(h ^ x).count("1") <= 6 for x in dh_da)]


def _mau_se_tu_kem(kb_page, tin, msgs):
    """Câu vừa soạn chính là một mẫu CÓ ẢNH chưa tới khách → anh_kem_luot tự kèm ảnh mẫu đó (vd /chaohang
    có chữ "Certified & Pawnable" + ảnh sản phẩm) — cửa "AI nhắc giấy" đừng giành chỗ của ảnh mẫu."""
    if not anh_theo_mau_bat():
        return False
    m = mau_cua_tin(kb_page, tin)
    return bool(m and (m.get("anh") or []) and not anh_mau_da_toi_khach(msgs, m))


# ══ AI BÁO GIÁ MÀ KHÁCH CHƯA THẤY ẢNH NÀO → KÈM ẢNH SẢN PHẨM (chủ shop 2026-09-23) ══════════════════════════
# Ca Sunshine Chen · Luxe Jewelry Taiwan 10:28 VN: khách bấm nút QC "Get discount now!", Botcake chỉ chào chữ
# "How can we help you?", AI báo "1290 TWD 1 set / 1790 TWD 2 sets" CHAY — chủ shop: *"không gửi ảnh sp à"*.
# Ba cửa ảnh cũ đều không mở: câu AI khớp mẫu /price (mẫu KHÔNG ảnh), còn "Get discount now!" không phải câu hỏi
# về sản phẩm. Đo 91 hội thoại cũ (>24h, token page) có lượt báo giá đầu không ảnh: 67 ca Botcake/sale đã gửi ảnh
# từ trước (khỏi gửi), 24 ca chưa tấm nào — 20 ca là tra_loi (phần lớn bấm QC + "how much"), 4 ca len_don (câu
# xác nhận đơn — không kèm). Cửa này dùng chung ô "sp" với cửa "khách hỏi sản phẩm": MỘT lần mỗi hội thoại.
# Tắt riêng: AI_ANH_BAO_GIA=0 trong .env (không cần restart).
def anh_bao_gia_bat():
    return str(os.environ.get("AI_ANH_BAO_GIA") or env().get("AI_ANH_BAO_GIA") or "1") != "0"


def bao_gia_chua_thay_anh(msgs, tin):
    """Câu AI vừa soạn có con số giá VÀ phía page chưa gửi tấm ảnh nào trong hội thoại.

    Tin "hethong" chỉ tính khi có URL ảnh thật (tin page bắn hàng loạt kèm ảnh): tin bấm quảng cáo cũng mang đính
    kèm (loại ad_click, không có URL ảnh) — tính co_dinh_kem ở đó là chặn đúng ca Sunshine."""
    if not anh_bao_gia_bat() or not CG.tien_trong(tin or ""):
        return False
    # Chỉ tính TRONG PHIÊN này (23/09 chiều, ca Josie Martinez · Kreain Nature PH in Uae): khách bấm QC lại sau ≥6 giờ
    # hỏi "how much" — ảnh Botcake chào ở phiên hôm qua đã trôi xa, chủ shop vẫn muốn kèm ảnh.
    msgs = msgs or []
    return not any((m.get("boi") in ("botcake", "nguoi", "ai") and (m.get("co_dinh_kem") or m.get("anh")))
                   or (m.get("boi") == "hethong" and m.get("anh")) for m in msgs[dau_phien(msgs):])


def _loai_da_gui_trong_phien(mkey, conv_id, loai, msgs):
    """Như anh_loai_da_gui nhưng chỉ tính lần gửi từ ĐẦU PHIÊN hiện tại; cả đoạn là một phiên (hoặc mốc hỏng)
    thì coi như đã gửi — thà thiếu ảnh còn hơn bắn lại cùng chùm ảnh trong một lần mua."""
    t = (qht.load_json(_f_anh_loai_da_gui(mkey), {}).get(str(conv_id)) or {}).get(loai)
    if not t:
        return False
    msgs = msgs or []
    i = dau_phien(msgs)
    t0 = _moc_giay(msgs[i].get("luc")) if 0 < i < len(msgs) else None
    return t0 is None or t >= t0


# ══ KHÁCH HỎI CẦM ĐỒ → ẢNH GIẤY CHỨNG NHẬN (chủ shop 2026-09-23 tối) ══════════════════════════════════════════
# Ca Mitchy Trias · Saudi Gold Jewelry - TW: "pwede poh yn isanla?" (cầm được không) → AI đáp đúng "Pwede pong isangla
# ito — genuine 18K…" nhưng KHÔNG kèm tờ giấy nào, dù page có sẵn 2 ảnh chứng nhận. Hai cửa cũ đều trượt: câu khách
# không có legit/totoo/real (_THAT_GIA_ANH), câu AI không có chữ "certificate" (_AI_NHAC_CN). Đo 27.012 tin khách khác
# nhau (so_chi_phi 8 nước): bắt 179 tin, soát tay đều là hỏi cầm được không / pawnable ("Nasasanla b yan", "Pawnable
# po ba", "Pwede isanla") hoặc kể từng mua hàng cầm không được — tờ giấy là câu trả lời đúng cho cả hai. ⛔ Lõi PHẢI có
# chữ n (san(g)la): bỏ n là dính "sala"/"salamat"/"salary". CHỈ page vàng thật (la_page_vang_that).
_CAM_DO = re.compile(
    r"\b(?:i|ma|na|n|pa|mag|nag|ipa|pina|mai|nai|mapa|maka)?(?:sa|s)?sang?lah?(?:h?(?:n|an|in|ng|oba|poba|ba))?\b"
    r"|\bsinang?la\w*|\bpawn\w*|\bpown\w*|典當|當鋪|当铺|典当", re.I | re.U)


def _cam_do_go_sai(t):
    """Chữ lệch ≤1 phép sửa so với pawnshop / pawnable ("oawnshop" — ca Grace Mendoza 25/09, o sát p trên bàn phím)."""
    for w in re.findall(r"[a-z]+", (t or "").lower()):
        if 7 <= len(w) <= 10 and any(_lech(w, g, 1) <= 1 for g in ("pawnshop", "pawnable")):
            return True
    return False


def cau_hoi_cam_do(msgs, so_tin=3):
    """Câu khách hỏi CẦM ĐỒ trong các tin chưa được đáp (mới nhất trước), không có → ""."""
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t and (_CAM_DO.search(t) or _cam_do_go_sai(t)) and not _khieu_nai_don_cu(t):
                return t
            so_tin -= 1
            if so_tin <= 0:
                return ""
        elif m.get("boi") != "hethong":
            return ""
    return ""


def khach_hoi_cam_do(msgs, so_tin=3):
    """Khách vừa hỏi / nhắc chuyện CẦM ĐỒ (sangla / pawnable) trong các tin chưa được đáp — trừ khiếu nại đơn cũ."""
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                kh.append(t)
        elif m.get("boi") != "hethong":
            break
    return any((_CAM_DO.search(t) or _cam_do_go_sai(t)) and not _khieu_nai_don_cu(t) for t in kh[:so_tin])


LY_DO_CAM_DO = "khách hỏi cầm đồ"

# KHÁCH HỎI VÀNG MẠ (24/09, ca Lynn De Guzman · Golden Fortune Energy Necklace Us: "Gold plated?"). Đo 28.403 tin khách:
# 116 tin, 98 ở page vàng thật — "is this real gold or gold plated only", "gold plated Po ba yan?", "Baka naman gold plated
# lang yan", "هل هذا ذهب حقيقي ام مطلي"; _THAT_GIA_ANH chỉ bắt 12 (đòi legit/real/totoo + dấu hỏi). Câu KỂ cũng tính ("My
# nbasa ako ng comment plated lng dw yn" = đọc bình luận nói là mạ) — tờ giấy là câu trả lời đúng. ⛔ "plat" trơn KHÔNG tính
# (địa chỉ "Plat HN1"). CHỈ page vàng thật: page bán hàng mạ thì không có giấy vàng để gửi, gửi là nói sai.
_VANG_MA = re.compile(
    r"\bplat(?:ed|ted|erd|ing|e)\b|\bgold[\s-]*plat\w*|\btubog\b|\bgold[\s-]*fill\w*|\bpinaplate\w*"
    r"|مطلي|مطليه|مطلية|طلاء|鍍金|镀金", re.I | re.U)


def khach_hoi_vang_ma(msgs, so_tin=3):
    """Khách vừa hỏi / nghi hàng là vàng MẠ trong các tin chưa được đáp — trừ khiếu nại đơn cũ."""
    kh = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                kh.append(t)
        elif m.get("boi") != "hethong":
            break
    return any(_VANG_MA.search(t) and not _khieu_nai_don_cu(t) for t in kh[:so_tin])


LY_DO_VANG_MA = "khách hỏi vàng mạ"


# GIẤY "KHÁCH ĐÃ THẤY" CHỈ TÍNH 10 TIN GẦN NHẤT (26/09, ca Fathima Indio · Nature's Daily Care in Saudi): tờ giấy nằm trong /chaohang
# Botcake chào từ đầu hội thoại nên máy bỏ, trong khi khách đang nghi ngay lúc này — phải thấy lại tờ giấy cạnh câu trả lời.
# Ô "cn" tính theo PHIÊN (bấm QC lại sau ≥6 giờ) thay vì cả hội thoại.
GAN_GIAY_TIN = 10


def _giay_chua_thay(msgs, urls):
    return _anh_khach_chua_thay((msgs or [])[-GAN_GIAY_TIN:], urls)


def _ai_vua_gui_giay(mkey, conv_id, phut=5):
    """CHÍNH AI đã gửi ảnh giấy chứng nhận cho hội thoại này trong `phut` phút qua (sổ anh_da_gui, ghi lúc ảnh đã tới khách)."""
    t = (qht.load_json(_f_anh_loai_da_gui(mkey), {}).get(str(conv_id)) or {}).get("cn")
    return bool(t) and time.time() - t < phut * 60


def _anh_bang_tong_thang(kb_page, mkey, pid):
    """Ảnh BẢNG tổng hợp các tháng của page (chữ trong ảnh có ≥4 tên tháng) — kịch bản trước, thư mục ảnh sau."""
    nguon = [u for m in (kb_page or {}).get("mau") or [] for u in (m.get("anh") or []) if u]
    nguon += [x.get("u") for x in (thu_muc_anh(mkey, pid) if pid else []) if x.get("u")]
    ra = []
    for u in nguon:
        t = (chu_trong_anh(u) or "").lower()
        if u not in ra and sum(1 for x in _THANG_EN if x in t) >= 4:
            ra.append(u)
    return ra


def _sp_page_thang(kb_page, anh, msgs, mkey, pid):
    """MAY_SET_2809: page đá sinh tháng (≥6 tháng có ảnh) mà khách CHƯA nói tháng — ảnh sản phẩm là bộ của MỘT tháng
    (/chaohang Glamora = bộ January) thì bỏ, thay bằng 1 ảnh BẢNG tổng hợp các tháng khách chưa thấy. Không có bảng →
    chỉ giữ ảnh không mang tháng (có thể rỗng: thà không ảnh còn hơn ảnh sai tháng). Khách đã nói tháng → trả nguyên
    (anh_dung_thang_khach lo). Page không bán theo tháng → trả nguyên."""
    anh = [u for u in (anh or []) if u]
    if not anh or not pid:
        return anh
    bang = _anh_theo_thang_page(kb_page, mkey, pid)
    if len(bang) < 6 or thang_khach_hoi(msgs):
        return anh
    ten_cua = {}
    for m in (kb_page or {}).get("mau") or []:
        for u in m.get("anh") or []:
            ten_cua.setdefault(u, (m.get("tu_khoa") or "").strip())
    mot = [u for u in anh if thang_cua_anh(u, ten_cua.get(u, ""))]
    if not mot:
        return anh
    tong = _anh_khach_chua_thay(msgs, _anh_bang_tong_thang(kb_page, mkey, pid)[:3])[:1]
    return tong + [u for u in anh if u not in mot and u not in tong]


def anh_theo_cau_hoi(kb_page, msgs, tin, mkey, pid, conv_id, hd=None):
    """Ảnh đi kèm câu trả lời khi lượt này CHƯA có ảnh nào → (ảnh, loại, nhãn log); không có → ([], None, "").

    1. khách hỏi hàng thật-giả → ảnh CHỨNG NHẬN; page không có giấy tờ (hoặc đã gửi) → ảnh sản phẩm (20/09);
    2. câu AI vừa soạn NHẮC giấy chứng nhận → ảnh chứng nhận (22/09) — page không có giấy thì thôi;
    3. khách hỏi về sản phẩm → ảnh sản phẩm (20/09);
    4. AI BÁO GIÁ mà khách chưa thấy tấm ảnh nào phía page → ảnh sản phẩm (23/09) — trừ câu lên đơn.
    Mỗi loại đúng MỘT lần cho một hội thoại (sổ anh_da_gui, ghi lúc ảnh đã tới khách); ảnh khách đã thấy thì bỏ."""
    # 26/09 tối — chủ shop: "có botcake gửi rồi cũng gửi lại nhé, bạn nhắc đến là phải gửi rồi": giấy Botcake/sale đã gửi KHÔNG
    # chặn nữa; AI nhắc giấy thì gửi kể cả ô "cn" của phiên đã dùng. Chỉ chặn khi CHÍNH AI vừa gửi giấy trong 5 phút.
    _nhac_cn_ = ai_nhac_chung_nhan(tin) and not _mau_se_tu_kem(kb_page, tin, msgs)
    _vua_gui_cn_ = _ai_vua_gui_giay(mkey, conv_id)
    if khach_hoi_that_gia(msgs):
        if not _vua_gui_cn_ and (_nhac_cn_ or not _loai_da_gui_trong_phien(mkey, conv_id, "cn", msgs)):
            a = anh_chung_nhan(kb_page, mkey=mkey, pid=pid)
            if a:
                return a, "cn", "khách hỏi hàng thật"
        # 24/09: không có (hoặc đã gửi) giấy → FEEDBACK + ảnh sản phẩm (trước chỉ ảnh sản phẩm)
        a, lo = anh_thay_giay(kb_page, msgs, mkey, conv_id)
        if a:
            return a, lo, LY_DO_THAY_GIAY
        return [], None, ""
    _cd_ = khach_hoi_cam_do(msgs)
    if _cd_ or khach_hoi_vang_ma(msgs):
        # 24/09: mở cho MỌI page (trước chỉ page vàng thật) — ca Lynn De Guzman ở page hàng MẠ, chủ shop vẫn muốn khách nhận
        # ảnh: page có giấy thì gửi giấy, không có thì feedback + ảnh sản phẩm.
        if not _vua_gui_cn_ and (_nhac_cn_ or not _loai_da_gui_trong_phien(mkey, conv_id, "cn", msgs)):
            a = anh_chung_nhan(kb_page, mkey=mkey, pid=pid)
            if a:
                return a, "cn", LY_DO_CAM_DO if _cd_ else LY_DO_VANG_MA
        a, lo = anh_thay_giay(kb_page, msgs, mkey, conv_id)
        if a:
            return a, lo, LY_DO_THAY_GIAY
    if _nhac_cn_ and not _vua_gui_cn_:
        _cn_ = anh_chung_nhan(kb_page, mkey=mkey, pid=pid)
        a = list(_cn_)
        if a:
            return a, "cn", "câu AI nhắc giấy chứng nhận"
        if not _cn_:                                   # page KHÔNG có tờ giấy nào (không phải "đã gửi rồi")
            a, lo = anh_thay_giay(kb_page, msgs, mkey, conv_id)
            if a:
                return a, lo, LY_DO_THAY_GIAY
    # 25/09: câu AI dẫn lời khách ("many customers share…") → kèm ảnh feedback (ô "fb", một lần mỗi hội thoại)
    if ai_nhac_feedback(tin) and not anh_loai_da_gui(mkey, conv_id, "fb") and not _mau_se_tu_kem(kb_page, tin, msgs):
        a = anh_feedback_cho_khach(kb_page, msgs)
        if a:
            return a, "fb", LY_DO_AI_NHAC_FB
    if khach_hoi_san_pham(msgs) and not anh_loai_da_gui(mkey, conv_id, "sp"):
        a = _sp_page_thang(kb_page, anh_san_pham(kb_page), msgs, mkey, pid)      # MAY_SET_2809
        if a:
            return a, "sp", "khách hỏi sản phẩm"
    if hd != "len_don" and bao_gia_chua_thay_anh(msgs, tin) and not _loai_da_gui_trong_phien(mkey, conv_id, "sp", msgs) \
            and not _mau_se_tu_kem(kb_page, tin, msgs):
        a = _sp_page_thang(kb_page, anh_san_pham(kb_page), msgs, mkey, pid)      # MAY_SET_2809
        if a:
            return a, "sp", LY_DO_BAO_GIA_ANH
    return [], None, ""


LY_DO_BAO_GIA_ANH = "AI báo giá mà khách chưa thấy ảnh nào"
LY_DO_THAY_GIAY = "không có giấy chứng nhận — gửi feedback + ảnh sản phẩm"
LY_DO_AI_NHAC_FB = "câu AI nhắc lời khách / feedback"

# CÂU AI NHẮC LỜI KHÁCH (25/09, ca Merna Espina · Madam Mystic Fengshui Expert USA). Đo sổ việc 72h / 13.028 lượt AI: 139 hội
# thoại khớp — "feedback" 51, "many customers" 46, "most customers" 27, "many of our customers" 7, Tagalog/Ả Rập/Indo lẻ.
# ⛔ Loại "customer service/care/support" và câu XIN feedback của khách ("send us your feedback").
_AI_NHAC_FB = re.compile(
    r"\b(?:many|lots?\s+of|most|some|a\s+lot\s+of|other|our|happy|previous|past|satisfied)\s+(?:of\s+our\s+)?"
    r"(?:customers?|clients?|buyers?)\b"
    r"|\bcustomers?\s+(?:have\s+)?(?:share|shared|said|say|says|love|loved|told|report\w*|tell|felt|feel|noticed|experienced"
    r"|got|saw)\b"
    r"|\breviews?\b|\btestimon\w*|\bfeedbacks?\b"
    r"|\bmarami(?:ng)?\s+(?:na\s+)?(?:po\s+)?(?:sa\s+(?:aming|ating|mga)\s+)?(?:customers?|kliyente|mamimili|kababayan"
    r"|nakabili|bumili|gumamit|nagsabi)\b"
    r"|\bmga\s+(?:customers?|kliyente|nakabili|bumili)\s+(?:namin|natin)\b"
    r"|عملائنا|العملاء|زبائننا|الزبائن|\bpelanggan\b|客人|顧客|客戶|好評|評價", re.I | re.U)
_AI_NHAC_FB_LOAI = re.compile(
    r"customer\s+(?:service|care|support)|send\s+(?:us\s+)?(?:your\s+)?feedback|your\s+feedback|give\s+(?:us\s+)?feedback",
    re.I)


def ai_nhac_feedback(tin):
    """Câu AI vừa soạn có dẫn lời khách / nhắc feedback (không phải xin feedback của khách)."""
    t = tin or ""
    return bool(_AI_NHAC_FB.search(t)) and not _AI_NHAC_FB_LOAI.search(t)


def anh_feedback_cho_khach(kb_page, msgs, toi_da=4):
    """Ảnh FEEDBACK khách chưa thấy: mẫu feedback của kịch bản (nhiều ảnh nhất) → không có thì dò chữ trong ảnh."""
    m = mau_feedback(kb_page, msgs)
    fb = [u for u in ((m or {}).get("anh") or []) if u] or anh_feedback(kb_page)
    return _anh_khach_chua_thay(msgs, fb)[:toi_da]


def anh_thay_giay(kb_page, msgs, mkey, conv_id):
    """Thay cho giấy chứng nhận (chủ shop 24/09): ≤2 ảnh FEEDBACK + ≤2 ảnh SẢN PHẨM khách chưa thấy → (ảnh, loại).
    Loại ghép bằng "+" ("fb+sp") để sổ anh_da_gui đánh dấu CẢ HAI ô — mỗi ô một lần mỗi hội thoại như cũ."""
    fb, sp = [], []
    if not anh_loai_da_gui(mkey, conv_id, "fb"):
        m = mau_feedback(kb_page, msgs)
        fb = [u for u in ((m or {}).get("anh") or []) if u] or anh_feedback(kb_page)
        fb = _anh_khach_chua_thay(msgs, fb)[:2]
    if not anh_loai_da_gui(mkey, conv_id, "sp"):
        sp = _anh_khach_chua_thay(msgs, anh_san_pham(kb_page))[:2]
    sp = [u for u in sp if u not in fb]
    loai = "+".join(x for x, a in (("fb", fb), ("sp", sp)) if a)
    return (fb + sp)[:4], (loai or None)


def _f_anh_loai_da_gui(mkey):
    return os.path.join(SCRIPT_DIR, "state", mkey or "chung", "anh_da_gui.json")


def anh_loai_da_gui(mkey, conv_id, loai):
    """Hội thoại này đã nhận chùm ảnh loại đó chưa — khách hỏi lại thì trả lời bằng LỜI,
    không bắn lại đúng chùm ảnh cũ vào mặt khách."""
    d = qht.load_json(_f_anh_loai_da_gui(mkey), {})
    return bool((d.get(str(conv_id)) or {}).get(loai))


def nho_anh_loai_da_gui(mkey, conv_id, loai):
    """Ghi lại lúc ảnh ĐÃ TỚI khách (gọi ở _phan_hoi, không gọi lúc quyết định — câu bị cổng chặn
    thì ảnh cũng không đi, đánh dấu sớm là mất luôn lượt gửi ảnh của hội thoại đó)."""
    f = _f_anh_loai_da_gui(mkey)
    d = qht.load_json(f, {})
    for _lo in str(loai).split("+"):                  # "fb+sp" (anh_thay_giay) → đánh dấu cả hai ô
        d.setdefault(str(conv_id), {})[_lo] = int(time.time())
    if len(d) > 4000:                                  # dọn hội thoại cũ hơn 30 ngày cho file khỏi phình
        cu = time.time() - 30 * 86400
        d = {k: v for k, v in d.items() if max(v.values() or [0]) > cu}
    try:
        os.makedirs(os.path.dirname(f), exist_ok=True)
        qht.save_json(f, d)
    except Exception as e:                             # noqa: BLE001 — sổ hỏng không giết lượt gửi
        print(f"  ⚠️  không ghi được sổ ảnh đã gửi: {e}")


# TIN CỦA SALE nói chuyện ĐƠN ĐÃ CÓ / GIAO HÀNG — sale đang xử đơn thì AI không chen (mục 7.4). Đọc phía
# sale vì tin khách ở những ca này thường trống nghĩa ("This one ok", "i will make a payment") nên DON_CU mù.
_SALE_XU_DON = re.compile(
    r"\byour\s+order\b|\border\s+(?:has\s+been|is|was)\s+(?:created|placed|confirmed|shipped|dispatched|out)"
    r"|\bdelivery\s+(?:system|team|staff|man|guy|date|time|address|company)|\bout\s+for\s+delivery\b"
    r"|\btransit\b|\btracking\b|\bcourier\b|\bshipping\s+company\b|\bre-?deliver|\bre-?schedul"
    r"|\bwaiting\s+for\s+your\s+confirmation\b|\bstaff\s+contacted\b|\bkeep\s+your\s+phone\b"
    r"|طلبك|شحنة|الشحن|المندوب|التوصيل", re.I | re.U)
# KHÁCH NÓI MUỐN MUA mà không nêu số lượng ("Gusto yang na sa picture", "I want this", "I'll take it") — chủ shop
# 14/09 tối, ca Remy Campos Baylor: *"khách đã bảo lấy 1 cái thì xin thông tin khách chứ ai lại hỏi có mua k"*.
MUON_MUA = re.compile(
    r"\bgusto\s+(?:(?:ko|nako|na\s+ko|po)\s+)?(?:po\s+)?(?:ito|nito|this|that|yan|yang|yung|nasa|na\s+sa|isa|one|1"
    r"|(?:ang\s+)?(?:bracelet|ring|necklace|set|cream|kwintas|singsing|buy\s*1|b1g1)|(?:bumili|mag-?order|i-?order|order|buy))\b"
    r"|\b(?:yes|opo|ok(?:ay)?)\s+(?:po\s+)?gusto\s+(?:ko|nako)(?:\s+po)?\s*[.!]*\s*$"
    r"|\b(?:kukunin|kunin|kuhanin|kuha)\s+(?:ko|nako|po|ako)\b|\b(?:bibili|bumili|magpa-?order|mag-?order)\s+(?:po\s+)?(?:ako|ko|nako)\b"
    r"|\bi['’]?\s*ll\s+(?:take|get|order|buy)\b|\bi\s+will\s+(?:take|get|order|buy)\s+(?:it|this|that|one|1|the|now|po)\b"
    r"|\bi\s+(?:want|wanna|would\s+like|need)\s+(?:to\s+(?:order|buy|get|avail|reserve)|this|that|it\b|one\b|1\b|the\s+one"
    r"|the\s+(?:bracelet|ring|necklace|set|cream|product|item)|in\s+the\s+(?:picture|photo))"
    r"|\b(?:i\s+)?(?:order|reserve)\s+(?:now|this|that|one|po|for\s+me)\b|\bi\s*(?:'m|am)\s+(?:ordering|buying|taking)\b"
    r"|\byes\s+i\s+(?:want|order|buy|take)\b|\b(?:ok(?:ay)?|yes)\s+(?:i\s+)?(?:order|buy|take)\b"
    r"|أبغى|ابغى|ابغي|أبي\s+(?:اطلب|أطلب|واحد)|أريد|اريد|ودي\s+اطلب|我要|要訂|想買|想要", re.I | re.U)


# KHÁCH HỎI VỀ SẢN PHẨM (công dụng / bệnh / cách dùng / an toàn / thật-giả) — chủ shop 14/09 tối, ca Noel B
# Mendoza (Wellora Wellness Saudi, TRUSO STOMACH): khách "Nakaka bawas ba ng bp yan bukod pang detox" (ngoài
# detox có hạ huyết áp không), AI đáp "1 box 89 SAR, COD, giao ngày lương, gửi SĐT" — không một chữ về huyết áp.
# *"lại spam giá rồi, trong khi khách hỏi tác dụng cơ mà"*. Đo trên 5.184 tin khách thật trước khi chốt regex:
# bỏ "how long/how many days" (hỏi giao hàng), "safe" trơn ("parcel is safe"), "for men/women", "results" trơn.
HOI_SP = re.compile(
    r"\b(?:effective|effectiv\w*|efective|side\s*effects?|good\s+for|works?\s+(?:for|on)|helps?\s+(?:with|for)"
    r"|how\s+(?:to|do\s+i|do\s+you|can\s+i)\s+use|how\s+does\s+(?:it|this)\s+work|ingredients?"
    r"|is\s+(?:it|this|thi\w)\s+(?:good|safe|effective|original|legit|real)|safe\s+(?:for|to\s+use|ba)"
    r"|can\s+(?:i|it)\s+(?:use|be\s+used)|does\s+(?:it|this)\s+(?:work|help|treat|cure|remove|lower|reduce|have)"
    r"|nakaka\w+\b.*\bba|mabisa|epekti\w*|epikti\w*|efekti\w*|hiyang|sangkap|gamitin|paggamit"
    r"|paano\s+(?:gamit\w*|inumin|ipahid)|legit\s+ba|original\s+ba|tumatalab|gumagana\s+ba"
    r"|efek\w*|ampuh|manjur|cocok\s+(?:gak|ga|untuk|buat)|aman\s+(?:gak|ga|tidak|nggak))\b"
    r"|فعال|يفيد|آمن|مكونات|طريقة\s+الاستخدام", re.I | re.U)
_HOI_BENH = re.compile(
    r"\b(?:bp|high\s*blood|blood\s*pressure|hypertension|presyon|diabetes|diabetic|buntis|pregnan\w*"
    r"|breast\s*feed\w*|nagpapasuso|maintenance|allerg\w*|ulcer|kidney|eczema|cholesterol|asthma)\b|ضغط|سكري",
    re.I | re.U)
_DAU_HOI_SP = re.compile(r"[?؟]|\b(?:ba|pwede|can|does|is\s+(?:it|this)|good\s+for|ok(?:ay)?\s+ba|bisa|boleh)\b|هل",
                         re.I | re.U)
_HOI_GIAO = re.compile(r"\b(?:deliver\w*|shipping|ship|parcel|arrive\w*|rider|courier|refund|return)\b", re.I)
# Hỏi "có khỏi / chữa được không" (ca Namzuged 19/09: "Mawawala po ba ang almuranas" / "Magagamot niya ba ito" không
# vào khối ❓ → model tự viết, kèm giá). Đi cùng _DAU_HOI_SP như _HOI_BENH; tên bệnh page bán lấy từ CG.BENH_PAGE.
_HOI_KHOI = re.compile(
    r"\b(?:mawawala|gagaling|magagamot|matatanggal|mapapagaling|nakakagaling|nakakagamot|gamot\s+(?:po\s+)?ba)\b"
    r"|\bwill\s+(?:it|this)\s+(?:cure|heal|remove|go\s+away|disappear)|\bcan\s+(?:it|this)\s+(?:cure|heal|treat|remove)"
    r"|يشفي|يعالج|\bsembuh\b|menyembuhkan", re.I | re.U)


# ══ CÂU HỎI TIẾNG TAGALOG KHÔNG CÓ DẤU "?" (chủ shop 2026-09-20) ══════════════════════
# Ca Vitaju Emet Alpas Sentillas (Women's Wellness in Saudi): "Mam kailan ba ma expire kc marami din ako na
# bili na pH care" (khi nào hết hạn) → AI bỏ qua câu hỏi, đẩy khuyến mãi + xin địa chỉ, khách chào đi luôn.
# Gốc: HS.la_cau_hoi chỉ nhận dấu "?" hoặc từ hỏi Anh/Ả Rập/Indo neo đầu câu; tiếng Tagalog nó chỉ biết
# magkano / ilang / pwede / meron — KHÔNG biết kailan, saan, bakit, ano, paano, particle "ba" giữa câu.
# Khách Philippines hiếm khi gõ dấu hỏi. Đo 9.880 tin khách thật (/root/thu_da_mua/tin_khach.jsonl): 194 câu
# hỏi Tagalog đang bị bỏ qua, gồm "paano po mag order", "gold ba Yan", "Ilan araw delivery po", "legit ba ito".
# CỐ Ý chỉ dùng cho cửa TRẢ LỜI CÂU HỎI (khach_hoi_trong_tam / khach_hoi_san_pham), KHÔNG sửa HS.la_cau_hoi —
# hàm đó còn gác dia_chi_du_tin và khach_vua_chon_goi, nhận nhầm câu hỏi ở đó là CHẶN mở đơn / chặn chọn gói.
CAU_HOI_TAG = re.compile(
    r"\b(?:kailan|kelan|kylan|kilan|kailang|anong\s+oras|bakit|bkit|sino|gaano|gano"
    r"|paano|papaano|pano|papano|panu|papanu"
    r"|saan|asan|ilan|ilang|ano|anu|anong|anung)\b"
    r"|\bba\b|\bdi\s*ba\b|\bdiba\b|\bhindi\s+ba\b", re.I | re.U)
# "kailangan" (cần) chứa "kailan" nhưng \b chặn được; mấy chữ dưới là lời KỂ, không phải hỏi.
_TAG_KHONG_HOI = re.compile(
    r"\b(?:kailangan|kailangang|kelangan|sabi\s+ko|bahala|kung\s+ano|kahit\s+ano|ano\s+man"
    r"|wala\s+akong|anniversary|congratulations)\b", re.I | re.U)


def hoi_tagalog(t):
    """True = câu hỏi tiếng Tagalog kiểu không gõ dấu "?"."""
    t = str(t or "")
    return bool(CAU_HOI_TAG.search(t)) and not _TAG_KHONG_HOI.search(t)


# ══ KHÁCH HỎI HẠN SỬ DỤNG ══════════════════════════════════════════════════
# Quét 337 kịch bản page của 8 nước: KHÔNG page nào có thông tin hạn sử dụng → model không có gì để nói,
# để tự do là nó bịa số. Chủ shop chốt 20/09: nói hàng mới nhập, hạn còn HƠN 2 NĂM, ngày in trên hộp.
# Đo 9.880 tin khách: bắt 3 câu, cả 3 đúng là hỏi HSD, 0 oan. Loại giấy tờ vùng Vịnh (iqama/visa hết hạn)
# và "promo/offer expire" (khuyến mãi hết hạn — chuyện khác).
HOI_HSD = re.compile(
    r"\bexpir\w*|\bexp\.?\s*date\b|\bshelf\s*life\b|\bmag\s*-?\s*expire\b|\bma\s*-?\s*expire\b"
    r"|\bpaso\b|\bnapaso\b|\bkadaluarsa\b|\bkedaluwarsa\b|\bkadaluwarsa\b"
    r"|الصلاحية|صلاحية|انتهاء|تنتهي|منتهي"
    r"|過期|有效期|保質期|保质期|賞味期限|有効期限"
    r"|hết\s*hạn|hạn\s*sử\s*dụng", re.I | re.U)
_HSD_KHONG_PHAI = re.compile(
    r"\biqama\b|\biqma\b|\bvisa\b|\bpassport\b|\bcontract\b|\blicen[cs]e\b"
    r"|\bpromo\b|\boffer\b|\bdiscount\b|اقامة|إقامة|تأشيرة|جواز|عقد", re.I | re.U)


def khach_hoi_hsd(msgs):
    """Câu khách vừa hỏi về HẠN SỬ DỤNG (tin khách SAU tin cuối phía shop), không thì None."""
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    sau.reverse()
    hoi = [x for x in sau if HOI_HSD.search(x) and not _HSD_KHONG_PHAI.search(x)]
    return " / ".join(hoi)[-200:] if hoi else None


def khach_hoi_san_pham(msgs):
    """Câu khách vừa hỏi về sản phẩm (tin khách SAU tin cuối phía shop), không thì None.

    Có hỏi giá / thanh toán / giao hàng trong cùng lượt thì None — cửa khác trả lời, khối này cấm nêu giá.
    """
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    sau.reverse()
    if not sau or any(_khong_phai_hoi_thuong(x) or _HOI_GIAO.search(x) for x in sau):
        return None
    hoi = [x for x in sau if HOI_SP.search(x)
           or ((_HOI_BENH.search(x) or _HOI_KHOI.search(x) or any(r[0].search(x) for r in CG.BENH_PAGE.values()))
               and (_DAU_HOI_SP.search(x) or hoi_tagalog(x)))]
    return " / ".join(hoi)[-200:] if hoi else None


# ══ KHÁCH SO SHOPEE / CHỖ KHÁC → KHẲNG ĐỊNH HÀNG CHÍNH HÃNG (chủ shop 2026-09-19) ══════════════════════════════════
# Ca Yael Cortes (Mint Breeze UAE): "You are so expensive and then why in shoppee is so cheap" → AI chỉ nói kiểm hàng
# rồi mới trả, lượt sau chào giảm giá. Chủ shop: *"khẳng định thêm là hàng chính hãng nữa cho tôi nhé"*. Luật chung
# (luat/00_chung.md) có rồi nhưng dòng tình huống từ chối / hạ giá lấn át → phải có dòng riêng trong gói.
# Đo 12.729 tin khách (so_chi_phi.jsonl): bắt rộng "original|fake" ra 119 tin — phần lớn là hỏi VÀNG thật ("original
# gold", "real gold?") và KHIẾU NẠI đã nhận hàng giả ("Why u send to me fake"). Hai loại đó KHÔNG vào cửa này: vàng thì
# chất liệu theo kịch bản (có page bán gold-plated), khiếu nại là chuyện đơn cũ. So với sàn / shop khác thì luôn vào.
SO_SAN_NOI_KHAC = re.compile(
    r"\bsho+p+e+\b|\blazada\b|\btiktok\s*shop\b|\btemu\b|\bamazon\b|\baliexpress\b|\bcarousell\b|\bdubizzle\b"
    r"|\bharaj\b|\bopensooq\b|蝦皮|露天"
    r"|\bcheaper\s+(?:in|at|on|from|sa)\b|\bmas\s+mura\s+(?:sa|dun|doon|don)\b"
    r"|\b(?:other|another|ibang)\s+(?:shop|store|seller|page|online)", re.I | re.U)
HOI_THAT_GIA = re.compile(
    r"\b(?:original|orig|authentic|genuine|orihinal|counterfeit|replica|imitation|peke|fake)\b"
    r"(?!\s*(?:price|presyo|bill|receipt))|أصلي|اصلي|مقلد|مزيف|正品|假貨|假的", re.I | re.U)
_VANG_BAC = re.compile(r"\b(?:gold|18\s*k|21\s*k|22\s*k|karat|carat|ginto|silver|pilak|sona)\b|ذهب|دهب|فضة|金|銀", re.I | re.U)
_DA_NHAN_HANG = re.compile(
    r"\b(?:send|sent|received?|dumating|natanggap|nakuha|nkuha|binili|bought|delivered|pinadala|already|before"
    r"|last\s+(?:time|month|week))\b|استلمت|وصلني", re.I | re.U)
_DA_NHAN_GOI = re.compile(   # hẹp hơn _DA_NHAN_HANG: "bought before on Shopee" vẫn là so giá trước khi mua
    r"\b(?:received?|got\s+(?:the|my)\s+(?:package|parcel|order|items?)|placed\s+my\s+order|have\s+the\s+products?"
    r"|did\s*n'?t\s+open|not\s+open(?:ed)?|dumating\s+na|natanggap)\b|استلمت|وصلني", re.I | re.U)
# 20/09 ca Hasna Kalim (Nature's Daily Care UAE): "Paano ko malaman na hindi fake" — câu HỎI thật-giả nhưng KHÔNG có
# dấu "?" và không có chữ "ba / is it" → cửa không bật, AI đi kể thành phần thảo dược thay vì khẳng định chính hãng.
# Đo 92.358 tin khách: thêm 18 tin vào cửa (56→74), đọc tay cả 18 đều đúng là nghi / hỏi hàng giả; câu khiếu nại
# ("its a fake and scam", "Your product is fake") vẫn nằm ngoài vì không có ý hỏi / lo sợ.
# Dấu hiệu ĐÃ NHẬN HÀNG CỦA MÌNH (khiếu nại đơn cũ) — khác với "tôi từng mua hàng giả ở chỗ khác online", câu sau là
# NGHI trước khi mua nên vẫn phải khẳng định chính hãng (ca Hasna Kalim 20/09: "I hope this is not fake like what i
# bought online" — chữ "bought" làm cửa tắt). Đo 92.376 tin khách: nới thế này chỉ thêm đúng câu đó, 13 tin khiếu nại
# ("the bottle you send to me", "ung nkuha ko noon fake") vẫn bị loại.
_DA_NHAN_MANH = re.compile(r"\b(?:received?|delivered|dumating|natanggap|nakuha|nkuha|pinadala"
                           r"|(?:you|u|kayo|niyo|nyo)\s+(?:sent|send|gave|pinadala))\b|استلمت|وصلني", re.I | re.U)
_NGHI_TRUOC_MUA = re.compile(r"\b(?:hope|hoping|sana|afraid|natatakot|takot|scared|worried|baka|paranoid)\b"
                             r"|\b(?:how|paano|papano|pano)\b[^.!]{0,30}\b(?:know|knw|tell|check|malaman|masabi"
                             r"|sigurado)\b", re.I | re.U)


def _khieu_nai_don_cu(t):
    """True = khách nói về hàng ĐÃ NHẬN của shop mình → không vào cửa "chính hãng" (chuyện đơn cũ, để sale xử)."""
    if _DA_NHAN_MANH.search(t):
        return True
    return bool(_DA_NHAN_HANG.search(t)) and not _NGHI_TRUOC_MUA.search(t)


_CAU_HOI_TG = re.compile(
    r"[?？؟]|\b(?:ba|is\s+(?:it|this|that)|are\s+(?:they|these|you)|sure)\b"
    # "làm sao biết" đa ngữ: how do I know / paano ko malaman / كيف أعرف / 怎麼知道 / gimana tahu / kaise pata
    r"|\b(?:how|paano|papano|pano)\b[^.!]{0,30}\b(?:know|knw|tell|check|malaman|masabi|sigurado|siguro)\b"
    r"|كيف\s*(?:أعرف|اعرف|أتأكد|اتأكد)|怎[麼么]知道|如何知道"
    r"|\b(?:gimana|bagaimana|macam\s*mana)\b[^.!]{0,30}\b(?:tahu|tau|pasti)\b|\bkaise\b[^.!]{0,20}\bpata\b"
    # "thật hay giả" hai vế: original or fake / أصلي ولا / yes or no
    r"|\b(?:original|orig|orihinal|authentic|genuine|legit|real)\b\s*(?:or|o)\s*\b(?:fake|peke|palsu|copy|imitation)\b"
    r"|\b(?:fake|peke|palsu)\b\s*(?:or|o)\s*\b(?:original|orig|orihinal|authentic|genuine|legit|real)\b"
    r"|\byes\s*or\s*no\b|أصلي\s*ولا|اصلي\s*ولا"
    # lo sợ mua phải hàng giả: "I hope this is not fake", "sana original", "only if not fake"
    r"|\b(?:hope|hoping|sana|afraid|natatakot|takot|scared|worried|baka)\b"
    r"|\bif\s+(?:its?\s+|it\W{0,2}s\s+|this\s+is\s+)?not\s+(?:fake|peke|original)\b", re.I | re.U)


def khach_so_noi_khac(msgs, kb_page=None):
    """Câu khách so với Shopee / sàn / shop khác, hoặc HỎI hàng thật-giả, trong các tin khách từ lần cuối AI / sale
    nhắn (tin Botcake không tính là đã trả lời). AI / sale đã nhắn sau câu đó → None (khỏi nói lại).
    Hỏi thật-giả ở page bán vàng/bạc → None: chất liệu theo kịch bản page, không nói "chính hãng" chung chung."""
    ban_vang = None
    so_tin = 0
    for m in reversed(msgs or []):
        b = m.get("boi")
        if b in ("ai", "nguoi"):
            return None
        if b != "khach":
            continue
        t = lam_sach(m.get("text")).strip()
        if not t:
            continue
        so_tin += 1
        if so_tin > 6:
            return None
        if SO_SAN_NOI_KHAC.search(t) and not _DA_NHAN_GOI.search(t):
            return t[:200]
        if HOI_THAT_GIA.search(t) and _CAU_HOI_TG.search(t) and not _VANG_BAC.search(t) and not _khieu_nai_don_cu(t):
            if ban_vang is None:
                ban_vang = bool(_VANG_BAC.search(json.dumps(kb_page or "", ensure_ascii=False)))
            if not ban_vang:
                return t[:200]
    return None


# Chủ shop 20/09 (ca Hasna Kalim): câu trả lời khách nghi hàng giả phải nói thêm CHỨNG NHẬN và Ý KIỂM HÀNG.
# Chỉ nhận cụm chứng nhận GHI RÕ trong kịch bản page ("FDA Approved", "FDA registered", "Halal certified"…) — đo
# 337 page: 104 page có chữ FDA, 70 page ghi rõ approved/registered. Chữ "FDA" trần KHÔNG dùng, kẻo model tự thêm
# "approved". Kịch bản không ghi gì → cấm nhắc chứng nhận, câu vẫn phải có "100% original" + COD kiểm hàng.
_CN_KICH_BAN = re.compile(
    r"\bFDA[\s-]*(?:approved|registered|registration|certified|cleared)\b|\bGMP[\s-]*certified\b|\bHACCP\b"
    r"|\bhalal[\s-]*certified\b|\bISO\s*\d{4,5}\b"
    # 20/09 chủ shop xác nhận: page chỉ ghi "FDA" trần cũng là hàng có FDA thật → nhận thêm các cách viết khẳng định
    r"|\bcertified\s+by\s+the\s+FDA\b|\bregistered\s+with\s+(?:the\s+)?FDA\b|\bterdaftar\b[^\"]{0,40}\bFDA\b"
    r"|\baprubado\s+ng\s+FDA\b|\bnaka[\s-]?rehistro\b[^\"]{0,20}\bFDA\b", re.I)
# Câu DẶN NỘI BỘ, không phải khẳng định: "check the original label to confirm … certifications such as 'FDA Cleared'"
# (SmileFit Denture) — nhắc chứng nhận theo câu này là bịa.
_CN_KHONG_CHAC = re.compile(r"(?:such\s+as|please\s+check|to\s+confirm|to\s+verify|kiểm\s+tra)[^\"]{0,60}$", re.I)
CHINH_HANG_RA = re.compile(r"100\s*%|\b(?:original|orihinal|authentic|genuine|legit)\b|أصلي|اصلي|正品", re.I | re.U)


def chung_nhan_kich_ban(kb_page):
    """Cụm chứng nhận CÓ THẬT trong kịch bản page → chuỗi để nhắc lại nguyên văn; không có → ""."""
    s = json.dumps(kb_page or "", ensure_ascii=False)
    for m in _CN_KICH_BAN.finditer(s):
        if _CN_KHONG_CHAC.search(s[max(0, m.start() - 80):m.start()]):
            continue                       # câu dặn "xem nhãn để biết chứng nhận như…" — không phải lời khẳng định
        t = m.group(0).strip()
        tl = t.lower()
        if "fda" in tl and not re.search(r"approved|registered|registration|certified|cleared|aprubado", tl):
            return "FDA registered"        # cách viết vòng ("certified by the FDA", "terdaftar di FDA") → nói mức khiêm tốn
        return t
    return ""


# "magkano" (bao nhiêu tiền, Tagalog) GÕ SAI — 23/09, ca Taylaran Mercy (DOC Alipion-Tooth ARMOR KSA): khách gõ "magno po",
# HOI_GIA không nhận → lượt soạn bị dặn "LƯỢT NÀY KHÔNG NÊU GIÁ" → AI hỏi lại "para saan po ba?" thay vì báo giá. Chủ shop:
# *"từ này ý của khách là hỏi giá, sau bạn báo giá nhé"*. Quét 23.890 câu khách trong sổ: cả họ biến thể cũng lọt — magkaano
# (18 lần), magcano, magakano, magkakano, mgakano, magakno, maggano, magkkano, magbkano, magkqno, magkzno, magjano, mkano,
# mgno, magano; "mga kano po" / "mag gano po" cũng là hỏi giá (đo sổ). "magno"/"magano" TRƠN còn là HỌ người (Magno, Magaño
# — gập dấu thành magano): "Adela magno tel 052…" có thật trong sổ → chỉ tính khi ĐỨNG ĐẦU TIN (được có một lời chào /
# đệm trước: hi, hello, ok, sis, maam, po…) VÀ sau nó là po/ba/yan/sir/maam… hoặc hết tin/dấu "?". "Adela Magno po" không tính.
# Dùng chung cho HOI_GIA, _GIA_TU (chi_hoi_gia_hay_giao), _HOI_GIA_HEP, _GIA_GO_SAI, TIN_MAU_QC.
_TRUOC_MAGNO = "|".join(
    [r"(?<=^)"] + [rf"(?<=^{w}{s})" for w in (
        r"hi", r"hello", r"helo", r"hilo", r"hlo", r"hey", r"hy", r"hai", r"po", r"ok", r"oky", r"okay", r"sis", r"maam",
        r"mam", r"madam", r"sir", r"ate", r"kuya", r"hi\spo", r"hello\spo", r"hi\ssis", r"hi\smaam", r"hi\smam", r"hi\ssir",
        r"hello\smaam", r"hello\ssir") for s in (r"\s", r",\s", r",", r"\.\s")])
_MAGKANO_GO_SAI = (
    r"m[ae]?g[ae]?\s?(?:kk?|c|gk|bk|kq|kz|j|g)[aeo]{0,2}(?:k[ae])?n[ou0](?:po|ng)?"
    r"|mk[ae]?n[ou]|mgno"
    # VIET_MAU_2709 — "magka" tách rời (ca Gina Molud "magka yan"; sổ: "Magka ano isa", "Magka no poh maam", "Magka anu po" — 13 câu).
    # "magka iba" (khác nhau), "magka pera" (có tiền) KHÔNG tính.
    r"|m[ae]?gka\s+(?:a?n[ou]|anu)|m[ae]?gka(?=\s+(?:yan|iyan|yun|ito|to)\s*\W*$)"
    r"|(?:" + _TRUOC_MAGNO + r")maga?n[ou]"
    r"(?=\s*(?:po+|pi|p0|ba|yan|yn|iyan|ito|nito|to|sir|ser|maam|ma'am|mam|madam|mdm|sis|dear)\b|\W*$)")


# Đo khach_hoi_trong_tam trên 1.752 tin khách UAE (14/09): HOI_GIA/HOI_MUA sót giá gõ sai ("mgkno", "Maam mag Kano po",
# "cek harga/hwo much", "How Mac many", "Ano to na 79?"), muốn đặt ("Can I oder now", "how to get this"), khiếu nại
# ("Why did you sent me the small size"). Mấy loại đó KHÔNG được vào khối cấm giá / mời mua.
_GIA_GO_SAI = re.compile(
    r"\b(?:" + _MAGKANO_GO_SAI + r"|m[ae]?g\s*k[ae]?no|mgkno|mgkano|magkno|harga|hwo\s*much|how\s*m\w{0,3}\s*(?:much|many)|price|prize|presyo"
    r"|kitna|kitne|(?:k|q)(?:i|e|ee|ii)m+(?:a|e)?t|kimt|cost|rate|how\W{0,2}s?\s*m[auie](?:ch|tch|ss|ck|h)|hm+|berapa|brp|hrga)\b"
    r"|\d{2,}|\d[.,]\d|\b\d+\s*(?:pcs?|set|box|bottle|pack)|بكم|سعر|多少|價", re.I | re.U)
_MUON_DAT = re.compile(r"\b(?:order|oder|ordr|buy|purchase|how\s+(?:to|can\s+i)\s+get|reserve|book|pesen|can\s+i\s+have\s+one)\b",
                       re.I)
_KHIEU_NAI = re.compile(r"\b(?:sent\s+me|received|confirmed\s+an\s+order|too\s+(?:small|big)|wrong|refund|return"
                        r"|didn'?t|call(?:ed)?|my\s+address|waiting|till\s+now|update|not\s+com\w*|why\s+not"
                        r"|my\s+(?:delivery|order|parcel)|how\s+many\s+(?:times|messages)|i\s+(?:send|sent|give|gave)|already\s+told"
                        r"|pera|shod)\b", re.I)


def _khong_phai_hoi_thuong(x):
    """Tin khách là hỏi giá / muốn đặt / thanh toán / đơn cũ-khiếu nại / từ chối / tin mẫu quảng cáo."""
    low = x.lower()
    return bool(HOI_GIA.search(low) or HOI_MUA.search(x) or _GIA_GO_SAI.search(x) or _MUON_DAT.search(x)
                or _KHIEU_NAI.search(x) or khach_hoi_thanh_toan(x) or re.search(DON_CU, low)
                or TU_CHOI.search(x) or DOI_LUONG.search(x) or TIN_MAU_QC.match(x.strip()))


# "Length pls" / "Size available pls" / "More info please" — XIN THÔNG TIN, không có dấu "?" nên
# `HS.la_cau_hoi` mù (ca Neethu Anil 20/09, Oman Gold Lucky Jewelry). Mẫu CHẶT: phải có danh từ thông tin,
# vì "<gì đó> pls" chung chung bắt oan "Yes please" / "1 set pls" / "order please" (đồng ý, chọn gói).
_XIN_TT_PLS = re.compile(
    r"\b(?:length|long|size|sizes|color|colour|weight|gram|grams|karat|carat|material|detail|details|"
    r"info|infos|information|picture|pictures|photo|photos|pic|pics|video|location|address|whatsapp|"
    r"number|stock|available|availability)\b[^?]{0,25}\b(?:pls|plz|plss|pleas|please)\b", re.I)


def khach_hoi_trong_tam(msgs):
    """Câu HỎI khách vừa gửi (sau tin cuối phía shop) mà KHÔNG phải hỏi giá — giao hàng, size, chất liệu, công dụng…

    Chủ shop 14/09 tối: trả lời đúng trọng tâm câu khách hỏi rồi mới mời mua, không phải câu nào cũng đọc giá.
    Hỏi giá / muốn mua / thanh toán / đơn cũ → None (cửa khác lo). Trả câu hỏi (≤200 ký tự).
    """
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    sau.reverse()
    if not sau or any(_khong_phai_hoi_thuong(x) for x in sau):
        return None
    hoi = [x for x in sau if HS.la_cau_hoi(x) or hoi_tagalog(x) or HOI_SP.search(x) or _XIN_TT_PLS.search(x)
           or (_HOI_BENH.search(x) and _DAU_HOI_SP.search(x))]
    return " / ".join(hoi)[-200:] if hoi else None


SO_TRON = re.compile(r"^\W*(?:[1-6]|[١-٦]|وحده|وحدة|واحده|واحدة|ثنتين|اثنين|اثنتين)\W*$")


_HOI_CHON_SO = re.compile(r"(\d{1,2})\s*(?:or|o|hay|ou|أو|أم)\s*(\d{1,2})", re.I | re.U)
# Đơn vị đi kèm thì con số KHÔNG phải số lượng hàng ("delivery takes 3 or 5 days").
_DON_VI_SAU_SO = re.compile(r"^\W{0,3}(?:days?|araw|weeks?|linggo|months?|buwan|years?|taon|hours?|oras"
                            r"|inch(?:es)?|cm|mm|gram(?:s|o)?|kg|يوم|أيام|سنة)\b", re.I | re.U)
_SO_AR = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")


def _page_hoi_chon_so(tt, t):
    """Tin page vừa hỏi khách CHỌN giữa mấy con số ("2 o 5?", "1 or 2?") và khách đáp đúng một trong số đó."""
    if "?" not in tt and "؟" not in tt:
        return False
    so = re.sub(r"\D", "", (t or "").translate(_SO_AR))
    if not so:
        return False
    for m in _HOI_CHON_SO.finditer(tt.translate(_SO_AR)):
        if _DON_VI_SAU_SO.match(tt.translate(_SO_AR)[m.end():m.end() + 12]):
            continue
        if int(so) in (int(m.group(1)), int(m.group(2))):
            return True
    return False


def so_tron_sau_bang_gia(msgs):
    """19/09 (ca Fatima Miftah · ChunHo Golden Jewerly; chủ shop: "một ở đấy là số lượng khách muốn"): tin khách CUỐI
    là số trơn 1-6 / ١-٦ / "وحده"… và tin gần nhất phía page (Botcake/sale/AI) trước nó có bảng giá → trả nguyên chữ
    khách nói (= số lượng khách chọn), không thì None. HS.trich không bắt số trơn vì không có ngữ cảnh."""
    kh = [j for j, m in enumerate(msgs or []) if m.get("boi") == "khach"]
    if not kh:
        return None
    t = lam_sach(msgs[kh[-1]].get("text") or "").strip()
    if not SO_TRON.match(t):
        return None
    tr = next((m for m in reversed(msgs[:kh[-1]]) if m.get("boi") in ("botcake", "nguoi", "ai")), None)
    if tr is None:
        return None
    _tt = lam_sach(tr.get("text") or "")
    if CG.tien_trong(_tt):
        return t
    # 28/09 (ca Dolly Carreon · Gold Charm Bracelet US): AI hỏi thẳng "Ilan po ang gusto ninyong matanggap,
    # 2 o 5?" — câu hỏi CHỈ CÓ SỐ LƯỢNG, không có giá → luật cũ đòi bảng giá nên trượt, khách đáp "5" thành
    # tin vô nghĩa → TREO, sale phải chốt hộ. Page vừa hỏi chọn giữa mấy con số thì con số khách đáp CHÍNH LÀ
    # câu trả lời.
    return t if _page_hoi_chon_so(_tt, t) else None


# ── KHÁCH TRẢ LỜI TUỔI BẰNG SỐ TRƠN (chủ shop 22/09, ca Anne Yude · Nature's Daily Care in Saudi) ─────────────
# Kịch bản chào hàng của page kết bằng "May I know your age and which symptoms you're currently experiencing?". Phiên
# 04/09 Botcake hỏi đúng câu đó, khách đáp "62 high sugar". 21/09 khách bấm quảng cáo mới, "magkano" → Botcake im, AI
# báo giá + hỏi "2 boxes or 4 boxes?" → khách "62" → AI "Sorry Anne, I didn't quite get that 😊 Did you mean you'd like
# 2 boxes or 4 boxes?". *"này là tuổi khách hàng mà, bạn rep gì kì vậy"*. Bản ghi gửi model đã lược phiên cũ
# (dau_phien) nên model chỉ thấy câu hỏi gói của chính nó; luật "số trơn = số sản phẩm" kéo nó đi hỏi lại gói.
# Cùng họ (20/09, ca Mohammad Rayyan Bangcas, cùng page): Botcake hỏi tuổi 15:32, 12 tiếng sau khách "45" rồi "43" →
# tin 1 chữ → vo_nghia → TREO; sale Thu Hiền tự gửi mẫu "At 43 years old, you can use this product…".
# Chỉ tính SỐ TRƠN 15-99 (kèm "years old"/"yrs"/"taon"/"سنة", "I'm 62" cũng được); bỏ số là giá / sàn / số sản phẩm
# của một gói; bỏ khi tin page ngay trước đang xin số nhà / địa chỉ / cân nặng / ngày; nhường bộ dò trả giá.
# 342 kịch bản chỉ 14 page hỏi tuổi (trà, gel, skincare, kính…) — nên phải có câu hỏi tuổi thật mới bắn.
HOI_TUOI = re.compile(
    r"\b(?:your\s+age|how\s+old|ilang\s+taon(?:\s+na)?(?:\s+po)?\s+(?:kayo|ka|sila|ninyo)|edad\s+(?:mo|nyo|ninyo)"
    r"|berapa\s+(?:umur|usia)|kitne\s+saal|umar\s+kitni)\b|كم\s+عمر|عمرك|عمركم|বয়স\s+কত|उम्र\s+क्या", re.I | re.U)
# Phải là câu HỎI: "…before your age." (Golden Noor KSA) không tính.
_HOI_TUOI_LA_HOI = re.compile(r"[?؟]|\b(?:may|can|could)\s+i\s+(?:know|ask)\b|\bplease\s+(?:tell|share)\b|\bpwede\b", re.I)
# Nhóm 1 = chữ đứng trước ("I'm", "Im", "age", "ako"), nhóm 3 = đơn vị sau ("years old", "yrs", "taon") — có một
# trong hai là khách NÓI RÕ tuổi.
TUOI_TRON = re.compile(
    r"^\W*((?:i\s*am|i'?m|im|my\s+age\s+is|age|edad\s+ko|ako\s+ay|ako|عمري|umur\s+saya)\s*[:\-]?\s*)?"
    r"(\d{2})\s*\+?\s*"
    r"(years?\s*old|yrs?\.?\s*old|yrs?\.?|y\.?o\.?|years?|taon(?:\s+na)?|anyos|سنة|سنه|سنين|سنوات|عام|tahun|saal)?"
    r"(?:\s*(?:na\s+po|po|na|lang|only|old|ako|dear|sir|ma'?am|mam|madam|sis))*\W*$", re.I | re.U)
# Tin page ngay trước chuỗi khách đang xin một con số KHÁC → số trơn là câu trả lời cho câu đó (ca Iqbal 21/09 cùng
# page: AI xin "the building name or number", khách "20"). Chỉ các ô SỐ cụ thể — không bắt chữ "address" / "day"
# chung chung: ca Reginaldo 19/09 (Nature's Daily Care UAE) AI hỏi gói "…then send your contact number and complete
# address", khách "51" (tuổi — Botcake vừa hỏi), AI chốt bừa "Buy 3 Get 3"; "araw-araw" (mỗi ngày) cũng không phải hỏi ngày.
HOI_SO_KHAC = re.compile(
    r"\b(?:(?:building|bldg|villa|house|flat|apartment|apt|room|street|block|plot|unit|gate)\s*(?:name\s+or\s+)?"
    r"(?:number|no\.?|#)|floor|zone|po\s*box|zip|postal|kg|kilo\w*|weight|timbang|height|tangkad|cm|size|sukat"
    r"|what\s+(?:day|date|time)|which\s+(?:day|date)|kailan|anong\s+araw|petsa)\b"
    r"|وزن|طول|رقم\s+(?:المبنى|الفيلا|البيت|الشقة)|مقاس|متى|أي\s+يوم", re.I | re.U)
_HOI_TIEN_KEM = re.compile(r"\b(?:paisa|paise|pesa)\b", re.I)
HOI_CAN_NANG = re.compile(r"\b(?:kg|kilo\w*|weight|timbang|height|tangkad)\b|وزن|طول", re.I | re.U)
# Câu AI hỏi lại kiểu "không hiểu" / "ý bạn là…" — với khách vừa đáp tuổi là sai hẳn.
AI_HOI_LAI_SO = re.compile(
    r"\b(?:didn'?t\s+(?:quite\s+)?(?:get|catch|understand)|not\s+sure\s+what\s+you\s+mean|did\s+you\s+mean"
    r"|do\s+you\s+mean|could\s+you\s+clarify|hindi\s+ko\s+(?:po\s+)?(?:na)?(?:intindihan|gets|nakuha)|ibig\s+mo\s+bang)\b"
    r"|ما\s+فهمت|لم\s+أفهم|تقصد", re.I | re.U)
_MAU_TUOI_KB = re.compile(r"\(\s*[^()]{0,25}\)\s*(?:years?\s*old|yrs?\b|taon|سنة)", re.I | re.U)
_SO_AR = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")


def _cau_hoi_tuoi(t):
    """Câu HỎI tuổi trong một đoạn chữ (nguyên câu, ≤ 200 ký tự), không thì None."""
    t = re.sub(r"<[^>]+>", " ", CG.bo_chu_toan(str(t or "")))
    for c in re.split(r"(?<=[?؟!.])\s+|\n+", t):
        if HOI_TUOI.search(c) and _HOI_TUOI_LA_HOI.search(c):
            return re.sub(r"\s+", " ", c).strip()[:200]
    return None


def mau_tuoi_kich_ban(kb_page):
    """Mẫu tư vấn theo tuổi của kịch bản ("💚 At ( tuổi khách ) years old, you can use this product…"), không thì None."""
    for m in (kb_page or {}).get("mau") or []:
        for tin in m.get("tin") or []:
            if _MAU_TUOI_KB.search(str(tin or "")):
                return str(tin).strip()
    return None


def khach_tra_loi_tuoi(msgs, kb_page=None, gia=None):
    """Chuỗi tin khách chưa được đáp có SỐ TUỔI trả lời câu hỏi tuổi của page → dict, không thì None.

    {"tuoi": n, "loi": chữ khách, "cau_hoi": câu page hỏi tuổi, "chac": bool, "cu": lời khách từng đáp, "can": bool}
    chac=True  — page ĐÃ hỏi tuổi trong phiên này, hoặc khách từng nói đúng số này ngay sau một câu hỏi tuổi (phiên cũ).
    chac=False — câu hỏi tuổi chỉ có ở kịch bản / phiên cũ → khối nhắc nói "nhiều khả năng", không ép soạn lại.
    can=True   — câu hỏi tuổi đi kèm cân nặng ("Ilang taon ka na at ilang kg ang target mo?") → số có thể là cân nặng.
    """
    msgs = msgs or []
    sau, j = [], len(msgs)
    for k in range(len(msgs) - 1, -1, -1):
        m = msgs[k]
        if m.get("boi") == "khach":
            t = _chu_khach(m.get("text"))
            if t:
                sau.append(t)
            j = k
        elif m.get("boi") != "hethong":
            break
    n = loi = None
    _moi_hon = False                                  # TUOI_MOI_HON_2709
    ro = False
    for _i_t, t in enumerate(sau):                      # tin mới nhất trước
        _moi_hon = _i_t > 0                             # TUOI_MOI_HON_2709 — khách đã nhắn tiếp sau câu tuổi
        mt = TUOI_TRON.match(t)
        if mt and 15 <= int(mt.group(2)) <= 99:
            n, loi, ro = int(mt.group(2)), t, bool(mt.group(1) or mt.group(3))
            break
    if n is None:
        return None
    # Cùng lượt khách còn hỏi giá ("Paisa batao" + "50") → con số dính tới tiền, để model đọc cả lượt.
    if any(HOI_GIA.search(t.lower()) or _HOI_TIEN_KEM.search(t) for t in sau if t != loi):
        return None
    truoc = next((lam_sach(m.get("text") or "") for m in reversed(msgs[:j])
                  if m.get("boi") in ("botcake", "nguoi", "ai") and lam_sach(m.get("text") or "").strip()), "")
    if not ro and HOI_SO_KHAC.search(truoc) and not _cau_hoi_tuoi(truoc):
        return None
    # Con số là GIÁ / SÀN page đã nói (khách gõ "99" = chọn gói 99 SAR), hay số sản phẩm của một gói → không phải tuổi.
    g = gia or {}
    tien = set(g.get("gia_ban") or []) | set((g.get("san_theo_gia") or {}).values()) | {g.get("san_thap_nhat")}
    for m in msgs:
        if m.get("boi") != "khach":
            tien |= set(CG.tien_trong(m.get("text")))
    for tin in CG._chu_page(kb_page):
        tien |= set(CG.tien_trong(tin))
    so_goi = ({a + b for a, b in CG.bang_goi_gia(kb_page)} | set(CG._bang_don_vi(kb_page))) if kb_page else set()
    if n in tien or n in so_goi:
        return None
    if gia and khach_tra_gia(msgs, gia):
        return None
    # Trong phiên này khách ĐÃ nói một tuổi khác (ca Muhammad Baksh 19/09: "40" → AI tư vấn 40 tuổi → sau đó
    # "Paisa batao" + "50") → con số mới không phải tuổi. Số trước đó là giá ("99" = chọn gói 99 SAR, ca Noraida
    # 18/09 rồi mới "Im67") thì không tính là tuổi cũ.
    dp = dau_phien(msgs)
    for x in msgs[dp:j]:
        if x.get("boi") == "khach":
            mx = TUOI_TRON.match(lam_sach(x.get("text") or "").strip())
            if (mx and 15 <= int(mx.group(2)) <= 99 and int(mx.group(2)) != n
                    and int(mx.group(2)) not in tien and int(mx.group(2)) not in so_goi):
                return None
    # Câu hỏi tuổi: trong phiên này → chắc; phiên cũ → chắc khi khách từng nói đúng số này ngay sau câu đó;
    # chỉ có ở kịch bản → không chắc.
    cau, cu, chac = None, "", False
    for k in range(j - 1, -1, -1):
        m = msgs[k]
        if m.get("boi") not in ("botcake", "nguoi", "ai"):
            continue
        c = _cau_hoi_tuoi(m.get("text"))
        if not c:
            continue
        cau = cau or c
        if k >= dp:
            chac = True
            break
        kh = next((lam_sach(x.get("text") or "") for x in msgs[k + 1:j]
                   if x.get("boi") == "khach" and lam_sach(x.get("text") or "").strip()), "")
        if kh and re.search(rf"(?<!\d){n}(?!\d)", kh.translate(_SO_AR)):
            cu, chac = kh[:80], True
            break
    if not cau:
        cau = next((c for c in (_cau_hoi_tuoi(tin) for tin in CG._chu_page(kb_page)) if c), None)
    if not cau:
        return None
    return {"tuoi": n, "loi": loi[:60], "cau_hoi": cau, "chac": chac, "cu": cu, "moi_hon": _moi_hon,
            "can": bool(HOI_CAN_NANG.search(cau))}


def dong_tra_loi_tuoi(tt, kb_page=None):
    """Khối nhắc cho prompt: con số khách vừa gửi là TUỔI (hoặc câu trả lời thăm khám), tư vấn theo đó."""
    n = tt["tuoi"]
    mau = None if tt.get("can") else mau_tuoi_kich_ban(kb_page)
    if tt.get("can"):
        dau = (f'⚠️ KHÁCH ĐANG TRẢ LỜI CÂU HỎI THĂM KHÁM CỦA PAGE bằng con số "{tt["loi"]}" — page hỏi: '
               f'"{tt["cau_hoi"]}". Con số là câu trả lời cho câu đó (tuổi hoặc cân nặng — đọc câu page hỏi, khách '
               'thường đáp theo thứ tự hỏi)')
    elif tt.get("chac"):
        dau = (f'⚠️ KHÁCH ĐANG TRẢ LỜI CÂU HỎI TUỔI CỦA PAGE: khách gửi "{tt["loi"]}" = {n} TUỔI — page đã hỏi: '
               f'"{tt["cau_hoi"]}"' + (f' (phiên trước khách đã trả lời câu đó: "{tt["cu"]}")' if tt.get("cu") else ""))
    else:
        dau = (f'⚠️ KHÁCH GỬI SỐ TRƠN "{tt["loi"]}" — NHIỀU KHẢ NĂNG LÀ TUỔI ({n}): kịch bản page có hỏi tuổi '
               f'("{tt["cau_hoi"]}"), khách quen luồng này hay đáp trước cả khi page kịp hỏi')
    return (dau + f'. {n} KHÔNG phải số lượng / số hiệu gói / giá (không gói nào có {n} sản phẩm), kể cả khi tin gần '
            'nhất của page đang hỏi chọn gói. ÁP LUẬT THĂM KHÁM: câu ĐẦU tư vấn theo điều khách vừa cho'
            + (' — kịch bản có sẵn mẫu tư vấn theo tuổi, viết theo đúng mẫu đó (điền tuổi khách, đúng tiếng khách): "'
               + re.sub(r"\s+", " ", mau)[:500] + '"' if mau else '')
            + '; rồi hỏi nốt ý page hỏi mà khách chưa trả lời (triệu chứng…), hoặc mời chọn gói nếu đã đủ. '
            '⛔ CẤM "I didn\'t quite get that" / "Sorry, I didn\'t understand", CẤM hỏi lại "ý bạn là 2 hộp hay 4 hộp", '
            'CẤM coi con số này là số lượng, CẤM lên đơn vì nó.'
            + ('' if tt.get("chac") or tt.get("can") else
               ' Chỉ khi hội thoại cho thấy RÕ con số là thứ khác (khách đang trả giá, số nhà…) mới xử theo nghĩa đó.'))


def tuoi_bi_hieu_nham(t, tt):
    """Tin AI cho khách vừa đáp tuổi mà hỏi lại kiểu 'không hiểu', coi con số là số lượng, hoặc (khi chắc là tuổi)
    không hề nhắc tới tuổi đó."""
    t = str(t or "").translate(_SO_AR)
    n = tt["tuoi"]
    if AI_HOI_LAI_SO.search(t):
        return True
    if re.search(rf"(?<!\d){n}\s*(?:box|boxes|pcs|pieces?|items?|bottles?|sets?|packs?|tubes?|jars?)\b", t, re.I):
        return True
    return bool(tt.get("chac") and not tt.get("can") and not tt.get("moi_hon")   # TUOI_MOI_HON_2709
                and not re.search(rf"(?<!\d){n}(?!\d)", t))


def khach_vua_chon_goi(msgs, mkey, gia=None):
    """Lời khách vừa chọn gói/số lượng (các tin khách SAU tin cuối phía shop), không thì None.

    Câu hỏi ("1 item how much?") và lời từ chối không tính — đó là việc của cửa khác.
    """
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    sau.reverse()
    if not sau or any(HS.la_cau_hoi(x) or khach_dang_tu_choi(x) or CON_NGHI.search(x) for x in sau):
        return None
    # Câu chọn gói phải NGẮN (≤ 8 từ) — đo chạy thật 14/09 chiều, 3/3 lần bắt đầu tiên là oan:
    # "This one can use for fugal resh" (hỏi cách dùng), "1 bottle are you sure effective" (nghi ngờ),
    # một câu Tigrinya 13 từ có "109" (hỏi cách dùng + hỏi giá). Khách còn hỏi/nghi thì để cửa khác trả lời.
    # Tin GỘP số lượng + SĐT + địa chỉ thì dài hơn 8 từ nhưng vẫn là lời CHỐT — ca Menskie Trazares
    # Bayonla 20/09 (Nature's Daily Care in Saudi): "only 1 / 0554318991 / Exit 12 Rawdah 12 Riyadh",
    # cửa ≤8 từ đóng nên AI hỏi lại đúng cái khách vừa trả lời ("how many boxes — 1, 2, or 3?").
    # Mở thêm khi có KHÚC NGẮN chốt số lượng (HS.sl_trong_khuc chỉ cắt ở chỗ khách tự ngắt).
    chon = [x for x in sau if (len(x.split()) <= 8 or HS.sl_trong_khuc(x))
            and HS.trich([{"boi": "khach", "text": x}], mkey, gia).get("so_luong")]
    # Nói MUỐN MUA mà không kèm số lượng cũng là chốt (ca Remy 14/09) — câu ≤ 12 từ.
    chon = chon or [x for x in sau if len(x.split()) <= 12 and MUON_MUA.search(x)
                     and not re.search(r"\b(?:if|kung|where|when|next|later|soon|month|buwan)\b|next\s*(?:month|week|time)|month", x, re.I)
                     and not (TU_CHOI.search(x) or DOI_LUONG.search(x) or NGAY_HEN.search(x) or DON_CU_CHU.search(x))]
    return " / ".join(sau)[:160] if chon else None


# SỐ LƯỢNG KHÁCH NÓI MƠ HỒ TRÊN PAGE BÁN THEO GÓI (chủ shop 2026-09-21, ca Ming Hui Sapeda ·
# Veloura Lip Beauty Saudi — khách "Only 2 ok", AI chốt "Buy 2 Get 4 Free, 6 lipsticks").
# Chỉ xét các tin khách SAU tin cuối phía shop, y như khach_vua_chon_goi. Bỏ câu từ chối và câu
# mang SĐT / địa chỉ (số nhà, block… đã có bộ dò riêng của hồ sơ) để không hỏi lại oan.
# KHÁCH ĐÁP SỐ TRƠN SAU CÂU PAGE HỎI CHỌN GÓI (CHON_GOI_2809 — chủ shop 28/09, ca Mohammad Saheb · Hally Skincare PH in Saudi:
# Botcake 'Will you choose the "buy 1 get 1 free" or the "buy 2 get 2 free" offer?', khách "2" → máy MUA_N_TANG_N_2409 đọc "2" =
# 2 sản phẩm = Mua 1 tặng 1 và ép model chốt gói đó; chủ shop: "khách chọn mua 2 rồi"). Khi page vừa gọi tên ≥2 gói trong câu
# hỏi chọn, con số trơn khách đáp là SỐ MUA của gói được gọi tên (thứ tự cũng trùng: gói thứ 2 = "buy 2"), không phải tổng.
# Số có đơn vị ("2 pcs") vẫn đi luật tổng cũ. Số không khớp số MUA gói nào → không đoán, để luật cũ lo.
_R_CAU_CHON = re.compile(r"[?؟]|\b(?:or|o|hay|which|choose|pick|alin|pili|piliin|prefer)\b|chọn|hoặc|أو|أي|اختار", re.I | re.U)
_R_DEM_CHON = re.compile(
    r"\b(?:po|poh|mam|maam|ma'?am|madam|dear|sis|sir|ok|okay|okey|yes|yup|opo|oo|na|ang|yung|yong|i|want|choose|pick|take|"
    r"gusto|ko|ku|ito|yan|this|that|the|number|num|no|option|offer|promo|package|set|combo|please|pls|plz)\b"
    r"|[#.,;:!()️⃣\s]", re.I)
_THU_TU_CHON = {"1st": 1, "first": 1, "una": 1, "2nd": 2, "second": 2, "ikalawa": 2, "pangalawa": 2, "3rd": 3, "third": 3}


def goi_page_hoi_chon(msgs):
    """[(mua, tặng)] theo thứ tự page gọi tên trong câu HỎI CHỌN ở tin cuối phía shop (≥2 gói khác nhau), không thì []."""
    shop = None
    for m in reversed(msgs or []):
        if m.get("boi") not in ("khach", "hethong"):
            shop = str(m.get("text") or "")
            break
    if not shop:
        return []
    for cau in reversed([x for x in re.split(r"\n|(?<=[?!؟])\s+", CG.bo_chu_toan(shop)) if x.strip()]):
        if not _R_CAU_CHON.search(cau):
            continue
        ra = []
        for m in CG.R_KM_TANG.finditer(cau):
            g = [x for x in m.groups() if x]
            goi = (1, 1) if g[0].lower() == "bogo" else tuple(int(CG._SO_CHU_KM.get(x.lower(), x)) for x in g[:2])
            if goi not in ra:
                ra.append(goi)
        if len(ra) >= 2:
            return ra
    return []


def khach_dap_chon_goi(msgs, kb_page):
    """Page vừa hỏi chọn giữa các gói + khách đáp CHỈ một con số / thứ tự → dict như CG.goi_khach_noi (cach "chon"), không thì None."""
    goi = goi_page_hoi_chon(msgs)
    if not goi:
        return None
    t = None
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                t = lam_sach(m["text"]).strip()
                break
        elif m.get("boi") != "hethong":
            break
    if not t or len(t) > 30:
        return None
    tt = t.translate(str.maketrans("٠١٢٣٤٥٦٧٨٩", "0123456789")).lower()
    n = next((v for k, v in _THU_TU_CHON.items() if re.search(r"\b" + k + r"\b", tt)), None)
    if n is not None:
        con = re.sub(r"\b(?:1st|first|una|2nd|second|ikalawa|pangalawa|3rd|third)\b", "", tt)
        if _R_DEM_CHON.sub("", con).strip() or n > len(goi):
            return None
        chon = goi[n - 1]
    else:
        if _R_DEM_CHON.sub("", tt).strip("0123456789") or not re.fullmatch(r"\D*\d\D*", tt):
            return None
        n = int(re.search(r"\d", tt).group())
        mua = [g for g in goi if g[0] == n]
        if len(mua) != 1:
            return None
        chon = mua[0]
    pg, _ = CG.cau_trong_hoi_thoai((msgs or [])[dau_phien(msgs):])
    try:
        bang = CG.bang_goi_gia(kb_page, pg)
    except Exception:
        bang = {}
    return {"goi": chon, "gia": bang.get(chon) or set(), "so": n, "cach": "chon", "loi": t[:60], "ds": goi}


def sl_mo_ho_goi(msgs, kb_page, mkey=None, gia=None):
    """Số lượng khách vừa nêu KHÔNG khớp gói nào của page → dict cho prompt, không thì None."""
    if khach_dap_chon_goi(msgs, kb_page):           # CHON_GOI_2809 — khách đáp câu page hỏi chọn gói, không mơ hồ
        return None
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    pg, _ = CG.cau_trong_hoi_thoai((msgs or [])[dau_phien(msgs):])
    for t in sau:                                   # tin mới nhất trước
        if khach_dang_tu_choi(t):
            continue
        if mkey:
            _hs = HS.trich([{"boi": "khach", "text": t}], mkey, gia)
            if _hs.get("dia_chi") or _hs.get("sdt"):
                continue
        mm = CG.goi_mo_ho(kb_page, pg, t)
        if mm:
            return mm
    return None


def sl_khop_goi(msgs, kb_page, mkey=None, gia=None):
    """Câu có con số MỚI NHẤT của khách (sau tin cuối phía shop) khớp ĐÚNG một gói → dict CG.goi_khach_noi, không thì None.

    MUA_N_TANG_N_2409 — nói thẳng gói nào cho model: "2 pc" từng bị đọc thành Mua 2 tặng 2 (ca Dilaila 24/09), page Mua N
    tặng N thì "3 packs" = Mua 3 tặng 3. Câu mới nhất không khớp gói nào thì THÔI, không lùi về câu cũ (khách đổi ý)."""
    _cg_ = khach_dap_chon_goi(msgs, kb_page)        # CHON_GOI_2809 — page vừa hỏi chọn gói, "2" = gói Mua 2
    if _cg_:
        return _cg_
    sau = []
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]))
        elif m.get("boi") != "hethong":
            break
    pg, _ = CG.cau_trong_hoi_thoai((msgs or [])[dau_phien(msgs):])
    for t in sau:                                   # tin mới nhất trước
        if khach_dang_tu_choi(t):
            continue
        if mkey:
            _hs = HS.trich([{"boi": "khach", "text": t}], mkey, gia)
            if _hs.get("dia_chi") or _hs.get("sdt"):
                continue
        if CG.so_khach_muon(t) is None and not CG.km_trong(t):
            continue
        if _R_HOI_GOI.search(t):
            return None          # khách đang HỎI ("How many pcs in 1 pck?", "3 pic how much") → để model trả lời câu hỏi
        return CG.goi_khach_noi(kb_page, pg, t)
    return None


_R_HOI_GOI = re.compile(r"[?؟]|\b(?:how|magkano|ilan|what)\b|كم", re.I | re.U)


def dong_khop_goi(mm):
    """Khối nhắc cho prompt: con số khách nói = gói nào (số nhận + giá) — chốt đúng gói đó, không hỏi lại."""
    a, b = mm["goi"]
    gia = "/".join(f"{x:g}" for x in sorted(mm["gia"]))
    ly = {"so_mua": ("page bán MUA N TẶNG N nên con số là SỐ MUA của gói" if mm["cach"] == "so_mua" and a == b
                     else "khách nói rõ số MUA của gói"),
          "tong": f"đúng gói cho {a + b} sản phẩm",
          "chon": ("page vừa hỏi khách chọn giữa " + " hay ".join(f"mua {x} tặng {y}" for x, y in mm.get("ds") or ())
                   + " nên con số khách đáp là gói khách CHỌN, KHÔNG phải số sản phẩm")}[mm["cach"]]
    return ('✅ SỐ LƯỢNG KHÁCH NÓI ĐÃ KHỚP GÓI: khách nói "' + mm["loi"] + f'" — {ly} → gói MUA {a} TẶNG {b} '
            f'(khách nhận {a + b}, giá {gia or "đúng dòng gói này trong bảng giá page"}). Xác nhận ĐÚNG gói này + giá này, KHÔNG hỏi lại gói, KHÔNG đổi sang gói '
            'khác; còn thiếu tên / SĐT / địa chỉ thì xin luôn trong cùng tin.')


# KHÁCH ĐÁP DÃY SỐ SAU CÂU HỎI CHỌN MÀU = MÃ MÀU (CHON_MAU_2809 — chủ shop 28/09, ca Dalumpines Belinda · Veloura Lip
# Beauty Saudi: Botcake "Which color would you like to choose?", khách "3,13,16" → AI "do you mean 3 lipsticks or 6?").
# Máy dò số lượng đã trả None (3 số khác nhau) nhưng MODEL tự đọc "3" theo luật SỐ TRƠN TRÊN PAGE BÁN THEO GÓI. Cùng họ ca Noena
# 25/09 ("no.1-5-6-7" đọc thành ngày). Nói thẳng cho model: đó là mã màu; số màu khớp đúng một gói thì chốt gói đó.
_R_HOI_MAU = re.compile(r"\b(?:colou?rs?|kulay|shades?)\b|màu|لون|اللون", re.I | re.U)
_R_HOI_CHON = re.compile(r"[?؟]|\b(?:which|what|choose|pick|select|anong|alin|pili|piliin|gusto)\b|chọn|nào|أي|اختار",
                         re.I | re.U)
_R_HOI_SO_LUONG = re.compile(r"\bhow\s+many\b|\bilan(?:g)?\b|\bwhich\s+(?:bundle|package|promo|set)\b|\bmấy\b|bao\s+nhiêu|gói\s+nào|كم",
                             re.I | re.U)
_R_DEM_MAU = re.compile(
    r"\b(?:po|poh|mam|maam|ma'?am|madam|dear|sis|ok|okay|okey|yes|yup|opo|oo|lang|lng|na|ang|yung|yong|i|want|like|choose|"
    r"gusto|ko|ku|ito|yan|iyan|this|that|the|and|at|saka|tsaka|also|colou?rs?|kulay|shades?|numbers?|nos?|no|code)\b"
    r"|[#.,;/&+\-–—()!\s]", re.I)


def khach_chon_mau(msgs, kb_page=None):
    """Tin cuối phía shop HỎI CHỌN MÀU + khách đáp chỉ gồm mã số (1-99) → {"ma", "loi", "cau", "goi", "bang"} / None."""
    sau, shop = [], None
    for m in reversed(msgs or []):
        if m.get("boi") == "khach":
            if lam_sach(m.get("text")).strip():
                sau.append(lam_sach(m["text"]).strip())
        elif m.get("boi") != "hethong":
            shop = str(m.get("text") or "")
            break
    if not sau or not shop:
        return None
    cau = next((d for d in reversed([lam_sach(x).strip() for x in re.split(r"\n|(?<=[?!.؟])\s+", shop)])
                if _R_HOI_MAU.search(d) and _R_HOI_CHON.search(d)), None)
    if not cau or _R_HOI_SO_LUONG.search(lam_sach(shop)):   # "màu nào, lấy mấy cái?" → con số có thể là số lượng
        return None
    for t in sau:                                   # tin mới nhất trước
        if len(t) > 40 or re.search(r"\d{3,}", t) or _R_DEM_MAU.sub("", t).strip("0123456789"):
            continue
        ma = list(dict.fromkeys(int(x) for x in re.findall(r"\d{1,2}", t) if int(x) >= 1))
        if not ma:
            continue
        pg, _ = CG.cau_trong_hoi_thoai((msgs or [])[dau_phien(msgs):])
        try:
            bang = CG.bang_goi_gia(kb_page, pg) if kb_page is not None else {}
        except Exception:
            bang = {}
        khop = [(g, bang[g]) for g in bang if sum(g) == len(ma)]
        return {"ma": ma, "loi": t[:60], "cau": cau.strip()[:120], "goi": khop[0] if len(khop) == 1 else None,
                "bang": bang}
    return None


def dong_chon_mau(mm):
    """Khối nhắc cho prompt: con số khách đáp là MÃ MÀU — nhắc lại màu, không hỏi số lượng."""
    ma = ", ".join(str(x) for x in mm["ma"])
    n = len(mm["ma"])
    ra = (f'🎨 KHÁCH ĐANG CHỌN MÀU: phía page vừa hỏi "{mm["cau"]}" và khách đáp "{mm["loi"]}" = MÃ MÀU số {ma} '
          f'({n} màu). ⛔ Các con số này KHÔNG phải số lượng, số hiệu gói, ngày giao hay giá — CẤM hỏi "3 thỏi hay 6 thỏi", '
          'CẤM hỏi lại khách chọn màu nào. Nhắc lại ĐÚNG các mã màu khách chọn.')
    if mm.get("goi"):
        (a, b), v = mm["goi"]
        gia = "/".join(f"{x:g}" for x in sorted(v))
        ra += (f' {n} màu = đúng gói MUA {a} TẶNG {b} (khách nhận {a + b}, giá {gia}) → xác nhận gói này + giá, còn thiếu '
               'tên / SĐT / địa chỉ thì xin luôn trong cùng tin.')
    elif len(mm.get("bang") or {}) >= 2:
        goi = " · ".join(f"mua {a} tặng {b} → nhận {a + b}, giá {'/'.join(f'{x:g}' for x in sorted(v))}"
                         for (a, b), v in sorted(mm["bang"].items()))
        ra += f' Số màu không khớp đúng gói nào ({goi}) → ghi nhận màu rồi hỏi khách lấy gói nào, nêu đủ gói kèm giá.'
    else:
        ra += " Còn thiếu tên / SĐT / địa chỉ thì xin luôn trong cùng tin."
    return ra


def dong_mo_ho_goi(mm):
    """Khối nhắc cho prompt: liệt kê đủ gói (số nhận + giá) và bắt hỏi lại đúng một câu."""
    goi = " · ".join(f"mua {a} tặng {b} → khách nhận {a + b}, giá {'/'.join(f'{x:g}' for x in sorted(v))}"
                     for (a, b), v in sorted(mm["bang"].items()))
    return ('⚠️ SỐ LƯỢNG KHÁCH NÓI ĐANG MƠ HỒ: khách nói "' + mm["loi"] + '" — tức muốn nhận '
            f'{mm["so"]} sản phẩm, mà page này CHỈ bán theo gói: {goi}. KHÔNG gói nào cho đúng '
            f'{mm["so"]} sản phẩm, và con số khách nói CÓ THỂ là số muốn nhận CHỨ KHÔNG PHẢI số hiệu gói. '
            'ÁP LUẬT SỐ LƯỢNG MƠ HỒ: ⛔ CẤM tự chọn gói, CẤM chốt / báo giá của MỘT gói, CẤM lên đơn. '
            'Hỏi lại ĐÚNG MỘT câu ngắn bằng tiếng khách, nêu ĐỦ các gói kèm số sản phẩm nhận được và giá '
            'từng gói để khách chọn; xin tên / SĐT / địa chỉ ở lượt SAU, khi khách đã chọn gói.')


# KHÁCH NÓI ĐỢI LƯƠNG / CHƯA CÓ TIỀN — chủ shop chốt 2026-09-14 (ca Violy De Lazo, Solid Big
# Infinity Ring UAE: khách "ok i wait my salary mam", AI đáp "I'll keep the promo for you… which one
# should I reserve?" → khách đi, không có đơn. *"tôi muốn ra đơn luôn cơ mà, như này bạn phải thuyết
# phục cho thông tin đơn hàng để giao vào ngày nhận lương chứ"*).
# Luật: vẫn RA ĐƠN NGAY trong lượt, hẹn giao đúng ngày khách có tiền (COD: hôm nay không trả gì).
# Bộ dò này chỉ bắt câu khách nói về lương/tiền + câu hẹn ngày (nếu có) để:
#   (1) nhắc model ngay trong khối hồ sơ — đi đúng luật ĐỢI LƯƠNG trong luat_model.md;
#   (2) chép nguyên lời khách vào note đơn (tao_don_moi / bo_sung_don_cu) cho sale giao đúng ngày.
DOI_LUONG = re.compile(
    # "salery / sallary / salry" (25/09, ca Eni Habibty) — lương gõ sai
    r"\b(salary|sal{1,2}(?:a|e|o)?r{1,2}(?:y|i|ie|ey)|sahod|sweldo|suweldo|payday|pay\s*day|gaji|no money|no cash|don'?t have money"
    r"|dont have money|walang pera|wala pa(?:ng)? pera|end of (?:the )?month|next month"
    r"|after (?:my )?salary|when i (?:get|have) (?:paid|money))\b"
    # thiếu tiền nói kiểu khác (14/09 tối, ca Teresa / Rena) — cũng đi luật ĐỢI LƯƠNG: ra đơn, giao lúc có tiền
    r"|\bkulang(?:\s+\w+){0,2}\s+(?:pera|budget|money)\b|\bnot enough (?:money|cash|budget)\b"
    r"|\bw(?:a)?la(?:ng)?\s+(?:pa\s*)?(?:pong?\s+|ng\s+)?(?:pera|budget)\b|\bno budget\b"
    r"|\blaman ng (?:account|wallet|bank|gcash)\b|\bonly have \d+"
    r"|راتب|معاش|مافي فلوس|ما عندي فلوس|آخر الشهر|الشهر الجاي", re.I | re.U)
# Câu có NGÀY hẹn — cố ý KHÔNG bắt số trơn ("1 set", SĐT): phải có st/nd/rd/th, tên tháng,
# dd/mm, "on the 25", thứ trong tuần, tomorrow/bukas, next week/month, end of month…
_THANG = r"(?:jan|feb|mar|apr|may|jun|jul|aug|sep|sept|oct|nov|dec)[a-z]*\.?"
NGAY_HEN = re.compile(
    r"\b(\d{1,2}(?:st|nd|rd|th)\b|\d{1,2}\s*(?:of\s*)?" + _THANG + r"\b|" + _THANG + r"\s*\d{1,2}\b"
    # dd-mm KHÔNG bắt số thứ tự / chuỗi số (25/09, ca Noena: "I want no.1-5-6-7" = chọn màu số 1, 5, 6, 7 → đọc thành ngày 1)
    r"|(?<![\d/.-])(?<!no\.\s)(?<!no\s)(?<!#)\d{1,2}[/.-]\d{1,2}(?:[/.-](?:19|20)?\d{2})?(?![/.-]?\d)\b"
    r"|(?<![\d/.-])(?:19|20)\d{2}[/.-]\d{1,2}[/.-]\d{1,2}(?![/.-]?\d)\b|on\s+(?:the\s+)?\d{1,2}\b|sa\s+(?:a-)?\d{1,2}\b"
    r"|tomorrow|bukas|tonight|mon|monday|tue|tuesday|wed|wednesday|thu|thursday|fri|friday"
    r"|sat|saturday|sun|sunday|next\s+(?:week|month|monday|tuesday|wednesday|thursday|friday|saturday|sunday)"
    r"|end of (?:the )?month|this\s+(?:week|weekend|friday|saturday|sunday)|weekend"
    r"|after\s+\d+\s+days?|in\s+\d+\s+days?|sa\s+(?:linggo|lunes|martes|miyerkules|huwebes|biyernes|sabado)"
    # "date4 / date 4 / date4sis / petsa 4 / ika-4" (25/09, ca Eni Habibty) — ngày 1-31, chữ dính sau số vẫn tính
    r"|date\s*(?:3[01]|[12]\d|0?[1-9])(?!\d)[a-z]{0,6}|petsa\s*(?:3[01]|[12]\d|0?[1-9])(?!\d)|ika-?\s*(?:3[01]|[12]\d|0?[1-9])(?!\d)"
    r"|بكرة|بكره|غدا|الاسبوع الجاي|يوم\s+\d{1,2})\b", re.I | re.U)


# KHÁCH NÓI "ĐÃ MUA TỪ MÌNH" MÀ POS KHÔNG CÓ ĐƠN — chủ shop 2026-09-14, ca Juliet Delrosario
# (Golden Buddha Blessings UAE): khách "Maam. Nkbili npo ako sa inyo maam" (tôi đã mua từ bà rồi),
# POS không có đơn nào tên/hội thoại/SĐT của khách, mà AI đáp "Narinig ko na may Golden Buddha ka
# na pala! Maswerte ka…" rồi 2 tin sau còn hướng dẫn "đặt tượng CỦA BẠN ở hướng đông". *"khách này
# đã mua từ cửa hàng đâu, phải hỏi xem khách có nhầm bên nào không, chứ chưa có lịch sử mua hàng
# từ cửa hàng chúng tôi cơ mà"*. Page tâm linh / trang sức có hàng chục page na ná nhau, khách
# nhầm shop là chuyện thường. Bộ dò này chỉ bắt CÂU KHẲNG ĐỊNH ĐÃ MUA (quá khứ), không bắt "I
# want to order". Việc "POS không có đơn" thì vòng chạy đã bảo đảm: tin chỉ tới model sau cửa
# `da_mua_o_page` (khách có đơn là AI im hẳn), nên hễ dò trúng là chắc chắn POS trống.
NOI_DA_MUA = re.compile(
    r"\b(i\s+(already\s+)?(bought|purchased|ordered|got|received)\s+(it|one|this|mine|from\s+you|"
    r"my|the|a|already)\b|already\s+(bought|purchased|ordered|have\s+(it|one|this)|got\s+(it|one|mine))\b|"
    r"i\s+have\s+(it|one|this|mine)\s+already|received\s+(it|mine|my\s+order)|"
    r"my\s+(order|parcel|item)\s+(arrived|came|was\s+delivered)|"
    r"(nakabili|nkbili|nkabili|nabili|bumili|umorder|nag[\s-]?order|nakaorder|nkaorder|nakuha|nkuha|"
    r"natanggap|ntanggap)\s+(na\s+|npo\s+|po\s+)*(ako|ko|kami|namin)\b|"
    r"(meron|mayroon|may)\s+(na\s+|npo\s+|po\s+)*(ako|akong|kami)\b|(ako|ko)\s+na\s+(po\s+)?(nito|niyan|nyan)\b|"
    r"sa\s+inyo\s+(ko|ako)\s+(nakabili|nkbili|bumili|umorder|nag[\s-]?order)|"
    r"اشتريت|طلبت\s+من(كم|ك)|وصلني|وصلتني|عندي\s+واحد)", re.I | re.U)


# KHÔNG PHẢI "ĐÃ MUA" dù trúng NOI_DA_MUA — chủ shop 19/09, ca Amboy Medina (Japan Herb Lab KSA):
# khách "Ok inshallah i will message u if i received my salary" → "i received my" trúng nhánh tiếng
# Anh → AI đáp "không thấy đơn nào của bạn, chắc mua nhầm shop khác?" với khách ĐANG ĐỢI LƯƠNG để
# mua. Bỏ qua khi: (1) câu ĐIỀU KIỆN/hẹn ("if/once/until/pag/kapag/kung/لو/إذا … received") hoặc
# chưa xảy ra ("how to received it", "when will i received it"),
# (2) thứ nhận được là TIỀN hoặc TIN ("received my salary", "natanggap ko na sahod", "وصلني الراتب",
# "i got the message"). Chỉ bỏ ĐÚNG chỗ trúng đó — câu khác trong tin vẫn xét.
_DA_MUA_DIEU_KIEN = re.compile(
    r"(?:\b(?:if|once|until|till|unless|as\s+soon\s+as|pag|kapag|pagka|kung|lpag|لو|إذا|اذا)"
    r"\s+(?:\S+\s+){0,2}"
    r"|\b(?:to|will|can|could|would|should|shall|gonna|wanna|can['’]?t|cannot|won['’]?t|wont|couldn['’]?t)"
    r"\s+(?:i\s+)?)$", re.I | re.U)
_DA_MUA_KHONG_PHAI_HANG = re.compile(
    r"\s*(?:(?:na|ng|yung|ung|ang|the|my|your|a|ko|po|already)\s+){0,3}"
    r"(?:salary|sahod|sweldo|suweldo|money|pay|payment|paycheck|allowance|pension|bonus|cash|pera|"
    r"message|msg|reply|answer|question|info|information|notification|notif|"
    r"price|photo|picture|pics?|"
    r"راتب|الراتب|راتبي|معاش|المعاش|فلوس|الفلوس|رسالة|الرسالة|رسالتك|رقم|الرقم|رقمك|سعر|السعر|صورة|صور|معلومات"
    r"|وتس|واتس)\b", re.I | re.U)


# Cùng ngày, ca محمد جعفر (Al Shifa Denture Saudi): page xin ảnh răng, khách "بس عندي واحد ضرس جوا" (tôi còn MỘT
# CÁI RĂNG HÀM bên trong) → "عندي واحد" trúng → AI hỏi "bạn mua ở page khác à?"; khách "لا لا ماقد اشتريت"
# (không, tôi CHƯA mua) → "اشتريت" lại trúng. Nên: nhánh "tôi CÓ …" (عندي واحد / meron akong / may ako) chỉ
# tính khi KHÔNG kèm danh từ khác ("meron po akong tanong" = tôi có câu hỏi) — trừ khi có "na" (= rồi); và
# "اشتريت/طلبت" đứng sau chữ phủ định (ما / ماقد / لم / ابد) là CHƯA mua.
_DA_MUA_CO = re.compile(r"(?:عندي|meron|mayroon|may)\b", re.I | re.U)
_DA_MUA_CO_DUOI = re.compile(
    r"\s*(?:$|[^\w\s]|(?:منه|منها|منكم|منك|من|قبل|already|nito|niyan|nyan|ganito|ganyan|ito|yan|yun|isa"
    r"|din|rin|po)\b)", re.I | re.U)
_DA_MUA_AR_PHU_DINH = re.compile(r"(?:^|\s)(?:ما|ماقد|ما\s+قد|لم|ابد|أبد|ابدا|أبداً|ابداً)\s*$", re.U)


def _la_noi_da_mua(t):
    for m in NOI_DA_MUA.finditer(t):
        if _DA_MUA_DIEU_KIEN.search(t[:m.start()]) or _DA_MUA_KHONG_PHAI_HANG.match(t, m.end()):
            continue
        g = m.group(0)
        if (_DA_MUA_CO.match(g) and not re.search(r"\bna\b", g, re.I)
                and not _DA_MUA_CO_DUOI.match(t, m.end())):
            continue
        if re.match(r"اشتريت|طلبت", g) and _DA_MUA_AR_PHU_DINH.search(t[:m.start()]):
            continue
        return True
    return False


def khach_noi_da_mua(msgs, so_tin=3):
    """Khách có KHẲNG ĐỊNH đã mua hàng của mình không? Trả câu khách nói (≤120 ký tự) hoặc None.

    Chỉ xét `so_tin` tin gần nhất của khách: câu "nakabili na ako" từ tuần trước mà hôm nay khách
    đang hỏi giá thì không nên kéo lại.
    """
    khach = [lam_sach(m.get("text") or "") for m in (msgs or []) if m.get("boi") == "khach"]
    for t in reversed(khach[-so_tin:]):
        if _la_noi_da_mua(t):
            return t[:120]
    return None


# KHÁCH KHIẾU NẠI / ĐÒI HOÀN TIỀN CHO HÀNG HỌ NÓI ĐÃ NHẬN — chủ shop 2026-09-20, ca Jen Emperio
# (Al Shifa Denture UAE): khách vừa bấm quảng cáo đã chửi "U ned.to back my money", "U deliver me fake
# teeth", "Plastic", "That 100 aed.u ned to back with me". POS KHÔNG có đơn nào, hội thoại KHÔNG có thẻ
# "Đã gửi" — mà model vẫn treo "sale kiểm tra đơn và xử lý". *"báo bạn mua nhầm bên rồi, chúng tôi chưa
# có lịch sử mua hàng nào từ bạn"*. Khác `khach_noi_da_mua`: ở đây khách KHÔNG nói "tôi đã mua", họ
# buộc tội page đã giao hàng / đòi lại tiền — câu nào cũng ngầm định có đơn.
#
# ⚠️ Bộ dò này CHỈ là bộ lọc rẻ. Phán "không có lịch sử mua hàng" phải do POS + thẻ quyết (vòng chạy),
# vì nói sai với khách ĐÃ mua thì mất khách hẳn. Đo 2.221 hội thoại / 10.958 tin khách thật 6 nước
# (kho /root/thu_da_mua/tin_khach.jsonl): trúng 13 hội thoại, 11 trong số đó POS CÓ đơn thật (vẫn treo
# cho sale như cũ), 1 có thẻ "Đã gửi" (AI im từ đầu vòng), chỉ 1 ca giống Jen là AI được nói. Bản nới
# hơn (không bắt buộc chữ chê) trúng 24 nhưng 8 ca là khách MỚI hỏi giao hàng ("Monday you deliver to
# me", "how many medical you send to me") — bỏ.
_KN_TIEN = r"(?:money|cash|payment|amount|pera|bayad|فلوس|فلوسي|مبلغ|مبلغي|نقود)"
# Chữ CHÊ CHẮC — đứng sau "you send/give/deliver" thì hiện tại (tiếng Anh bồi) vẫn là chê.
# "used for/to …" là hỏi cách dùng ("this cream is used for?"), không phải "hàng đã qua sử dụng".
_KN_XAU_MANH = (r"(?:wrong|fake|plastic|broken|damaged|used(?!\s+(?:for|to|as|in|on|with|by|daily|every|"
                r"everyday|at|when|before|after|once|twice)\b)|expired|not\s+the\s+same|"
                r"peke|sira|mali|luma|مقلد|تقليد|مكسور|خربان|غلط|بلاستيك)")
# Chữ KHÁC / THÊM — chủ shop 21/09, ca Lanie Antonio Jacinto (Mario Jewelry UAE): khách MỚI "Can you send
# me another design" khớp "you send me another" → bị coi là "page giao nhầm mẫu" → AI 2 lần nhắn "không có
# lịch sử mua hàng, chắc bạn nhầm shop". "another design / different color" gần như luôn là XIN XEM MẪU.
# Chỉ tính là chê khi: động từ GIAO/NHẬN (delivered, shipped, I received, dineliver/pinadala/binigay niyo),
# hoặc "you send/sent me another ONE / ITEM …" (vật cụ thể — ca Sam Mon Kuwait "I order one u send me
# another one") mà không phải câu nhờ/hỏi (xem _kn_khop_that).
_KN_XAU_YEU = r"(?:another\s+one|another|different|iba)"
_KN_XAU = r"(?:" + _KN_XAU_MANH + r"|" + _KN_XAU_YEU + r")"
_KN_VAT = (r"(?:one|item|items|iteam|product|products|thing|things|order|parcel|package|set|ring|necklace|"
           r"earrings?|bracelet|teeth|denture|dentures|cream|soap|oil|watch)")
# Thứ page "gửi sai" mà KHÔNG phải hàng: giá, số, ảnh, link… ("you sent me the wrong price").
_KN_KHONG_PHAI_HANG = (r"(?!\s+(?:price|prices|number|no|num|photo|photos|picture|pictures|pic|pics|video|"
                       r"videos|vid|link|address|info|information|message|msg|details|amount|quote|total|"
                       r"name|account|website|page|location)\b)")
_KN_HANG = (r"(?:item|items|product|products|order|parcel|package|teeth|denture|dentures|cream|soap|ring|bracelet|"
            r"set|tablet|capsule|oil|watch|design|size|color|colour)")
# Đòi lại TIỀN ĐÃ TRẢ — luôn phải có chữ "back / refund / ibalik / ارجع", nên "I already give my money
# to my friend" (ca Angel Hope, Hally Skincare KSA) không tính.
KN_DOI_TIEN = re.compile(
    r"(?:\bmy\s+" + _KN_TIEN + r"\s+back\b"
    r"|\bback\s+my\s+" + _KN_TIEN + r"\b"
    r"|\b(?:give|send|return|pay|bring|get)\s+(?:me\s+)?back\s+(?:my|the)\s+" + _KN_TIEN + r"\b"
    r"|\breturn\s+(?:my|the)\s+" + _KN_TIEN + r"\b"
    r"|\brefund\s+(?:me|my|the|it)\b"
    r"|\b(?:i|we)\s+(?:want|need|demand|require)\s+(?:a\s+|my\s+|the\s+)?refund\b"
    r"|\b(?:ibalik|balikan|isauli)\s+(?:niyo|nyo|ninyo|mo|nio|po)?\s*(?:ang\s+|yung\s+|ung\s+)?(?:pera|bayad)\b"
    r"|\bpera\s+ko\b[^.?!\n]{0,24}\b(?:ibalik|balik|isauli)\b"
    r"|(?:ارجع|أرجع|رجعوا|ردوا|رد|ارجاع|إرجاع|استرجاع|استرداد)\s*(?:لي\s*)?(?:ال)?(?:فلوس|مبلغ|نقود|فلوسي|مبلغي)"
    r"|(?:فلوسي|مبلغي|نقودي)\s*(?:ارجع|أرجع|رجعوا|ردوا|رد))", re.I | re.U)
# Khách nói PAGE ĐÃ GIAO / hàng ĐÃ NHẬN và CHÊ. Bắt buộc có chữ chê (_KN_XAU) — "you deliver to me on
# September 25?" hay "Monday you deliver to me" là khách MỚI hẹn giao, không phải khiếu nại.
_KN_TOI = r"(?:me\s+|us\s+|to\s+me\s+|sakin\s+|saakin\s+)?(?:a\s+|an\s+|the\s+|my\s+|one\s+)?"
_KN_BAN = r"\b(?:you|u|yu|kayo|niyo)\s+(?:already\s+)?"
_KN_TL_GIAO = r"(?:pinadala|binigay|dinala|dineliver|ni-?deliver|ibinigay)\s+(?:niyo|nyo|ninyo|mo)\b"
KN_DA_GIAO_LOI = re.compile(
    "(?:"
    + _KN_BAN + r"(?:deliver|delivered|sent|send|gave|give|shipped|ship)\s+" + _KN_TOI + _KN_XAU_MANH + r"\b"
    + _KN_KHONG_PHAI_HANG
    + r"|" + _KN_BAN + r"(?:delivered|shipped)\s+" + _KN_TOI + _KN_XAU_YEU + r"\b" + _KN_KHONG_PHAI_HANG
    + r"|" + _KN_BAN + r"(?:deliver|sent|send|gave|give|ship)\s+" + _KN_TOI + _KN_XAU_YEU + r"\s+" + _KN_VAT + r"\b"
    + r"|\b(?:i|we)\s+(?:already\s+)?(?:received|recieved|got|paid\s+for)\b[^.?!\n]{0,40}?\b(?:is|was|are|were)?\s*"
    + _KN_XAU_MANH + r"\b" + _KN_KHONG_PHAI_HANG
    + r"|\b(?:i|we)\s+(?:already\s+)?(?:received|recieved)\b[^.?!\n]{0,40}?\b(?:is|was|are|were)?\s*"
    + _KN_XAU_YEU + r"\b" + _KN_KHONG_PHAI_HANG
    + r"|\b(?:the|my|this)\s+" + _KN_HANG + r"\b[^.?!\n]{0,30}?\b(?:i\s+)?(?:received|recieved|got)\b[^.?!\n]{0,20}?"
    + _KN_XAU_MANH + r"\b"
    + r"|\b(?:the|my|this)\s+" + _KN_HANG + r"\b[^.?!\n]{0,30}?\b(?:i|we)\s+(?:received|recieved|got)\b"
    + r"[^.?!\n]{0,20}?" + _KN_XAU_YEU + r"\b"
    + r"|\b(?:the|my|this)\s+" + _KN_HANG + r"\b[^.?!\n]{0,24}?\b(?:is|was|are|were|looks?|seems?)\s+(?:like\s+)?"
    + _KN_XAU_MANH + r"\b"
    + r"|\b(?:the|my|this)\s+" + _KN_HANG + r"\b[^.?!\n]{0,24}?\b(?:was|were)\s+" + _KN_XAU_YEU + r"\b"
    + r"|\b" + _KN_TL_GIAO + r"[^.?!\n]{0,50}?" + _KN_XAU + r"\b"
    + r"|" + _KN_XAU + r"\b[^.?!\n]{0,50}?\b" + _KN_TL_GIAO
    + r"|(?:وصلني|وصلتني|استلمت|جاني|ارسلتوا|أرسلتوا|وصلتوني)[^.?!\n]{0,30}?" + _KN_XAU
    + r"|" + _KN_XAU + r"[^.?!\n]{0,30}?(?:وصلني|وصلتني|استلمت|جاني|ارسلتوا|أرسلتوا|وصلتوني)"
    + ")", re.I | re.U)
# NHỜ / HỎI chứ không phải kể tội: "Can you send me another design" (ca Lanie), "do you send fake?",
# "you send fake or original?", "u send me another one pls". Soi đúng mệnh đề chứa chỗ khớp; có
# "why/bakit/ليش" đứng trước = hỏi vặn, vẫn là kể tội.
_KN_NHO_HOI = re.compile(r"\b(?:can|could|would|will|do|does|pls|plz|please|kindly|pwede|paki|hope|sana)"
                         r"\s*(?:po\s+)?(?:ba\s+)?$", re.I | re.U)
_KN_HOI_VAN = re.compile(r"\b(?:why|bakit|how\s+come)\b|ليش|لماذا|ليه", re.I | re.U)
_KN_LICH_SU = re.compile(r"\b(?:pls|plz|please|thanks|thank\s*you|ty)\b", re.I | re.U)
_KN_QUA_KHU = re.compile(r"\b(?:delivered|sent|gave|shipped|received|recieved|got|paid|was|were|did|pinadala|"
                         r"binigay|dinala|dineliver|ni-?deliver|ibinigay)\b|وصلني|وصلتني|استلمت|جاني|ارسلتوا|"
                         r"أرسلتوا|وصلتوني", re.I | re.U)


def _kn_khop_that(t):
    """Chỗ khớp KN_DA_GIAO_LOI đầu tiên KHÔNG nằm trong câu nhờ/hỏi; không có → None.

    Đo 21/09 trên kho 10.958 tin khách thật 6 nước (/root/thu_da_mua/tin_khach.jsonl): trúng y hệt bản
    cũ (30 tin / 13 hội thoại, không bỏ không thêm ca nào); 43 câu mẫu tự đặt kiểu khách xin/hỏi mẫu:
    bản cũ bắt nhầm 28, bản này 0 (script /root/thu_kn_design/do.py).
    """
    for m in KN_DA_GIAO_LOI.finditer(t):
        truoc = re.split(r"[.?!\n,;]", t[max(0, m.start() - 40):m.start()])[-1]
        if _KN_HOI_VAN.search(truoc):
            return m
        if _KN_NHO_HOI.search(truoc):
            continue                        # "Can you send me …" — nhờ, không phải kể tội
        cuoi = re.search(r"[.?!\n]", t[m.end():])
        if (cuoi and cuoi.group(0) == "?"
                and not _KN_QUA_KHU.search(m.group(0) + " " + truoc)):
            continue                        # "you send fake or original?" — hỏi trước khi mua
        if not re.search(_KN_XAU_MANH, m.group(0), re.I | re.U):
            duoi = re.split(r"[,;.?!\n]", t[m.end():])[0]
            if _KN_LICH_SU.search(duoi):
                continue                    # "u send me another one pls" — xin thêm mẫu
        return m
    return None


# Câu ĐIỀU KIỆN / CHƯA XẢY RA = hỏi chính sách trước khi mua (luat/31_hoan_tien.md lo), không phải khiếu nại.
_KN_DIEU_KIEN = re.compile(r"\b(?:if|once|unless|in\s+case|suppose|pag|kapag|kung|sakali|لو|إذا|اذا)\b", re.I | re.U)
_KN_TUONG_LAI = re.compile(
    r"\b(?:will|shall|going\s+to|gonna|planning|plan\s+to|before\s+i\s+(?:buy|order|pay)|"
    r"want\s+to\s+(?:buy|order)|next\s+(?:week|month|time))\b", re.I | re.U)


# KHÁCH NHẮC "ĐƠN CỦA TÔI" MÀ PAGE NÀY CHƯA BÁN GÌ — chủ shop 2026-09-23, ca Mariel Tupas (Madam Mystic Fengshui
# Expert TW): khách "Ma am gd mrning sa 27 kupo makukuha yong order ko sa inyo" (ngày 27 em nhận hàng) rồi "I order
# already but this coming 27 is my day off" — tức muốn ĐẶT dây chuyền của page, nhận vào ngày nghỉ 27. Không regex nào
# bắt, model tự đọc "yong order ko" thành đơn cũ → tra_loi_treo "Is this about an order you already placed? … name and
# phone number you used when you ordered?" + ghi chú "Khách hỏi đơn cũ (đơn ngày 27)". *"khách đã mua hàng đâu? bạn rep
# gì đây"*, *"page này đâu phải bán tượng phật"* (đơn #491 của khách là tượng Phật ở page khác). Bộ dò chỉ để BÁO model
# (goi_soan) + bắt soạn lại (_soan_viec); vòng chạy tra POS trước — page này có đơn thật thì không đụng. Câu khách
# KHẲNG ĐỊNH đã mua ("nakabili na ako", "I already bought") vẫn đi luật 32A (khach_noi_da_mua), không qua đây.
NHAC_DON_MINH = re.compile(
    r"\bmy\s+orders?\b|\bthe\s+order\s+i\b|\bi\s+(?:already\s+)?order(?:ed)?\b|\border(?:ed)?\s+already\b"
    r"|\borders?\s+(?:ko|namin|natin)\b|\b(?:yung|yong|yun|ung|un|ang)\s+order\b"
    r"|\bnag-?order\s+(?:na\s+)?(?:po\s+)?(?:ako|ko|kami)\b|\bnakapag-?order\b"
    r"|طلبي|طلبيتي|我的訂單|我的订单|我訂的|我订的", re.I | re.U)
# Chỉ nhận câu nói về đơn SẮP đặt / sắp nhận (ngày hẹn, ngày nghỉ, lương, "will get"…) và KHÔNG mang dấu đơn đã đi
# (where / cancel / track / received / not yet / wala pa / ordered…) — đo 23/09 trên 50.251 câu khách: "my order" trơn
# phần lớn là khách hỏi đơn đang giao ("where is my order", "cancel my order", "10 days wala pa").
NHAC_DON_DA_DI = re.compile(
    r"\b(?:where|wher|wheres|wer|cancel\w*|cans?el\w*|track\w*|still|refund\w*|paid|wrong|return\w*|rec[ie]{2}v\w*"
    r"|nareceive\w*|have\s+(?:place|placed|order)|had\s+order|move\s+my\s+order|already\s+(?:sept|oct|nov|\d)"
    r"|natanggap|dumating|arriv\w*|delivered|ordered|placed|fake|scam|complain\w*|ibalik|wala\s+pa|hindi\s+pa|di\s+pa"
    r"|not\s+(?:yet|coming|come|receiv\w*|deliver\w*)|send\s+(?:me\s+)?back)\b", re.I)
NHAC_DON_TUONG_LAI = re.compile(
    r"day\s*-?\s*off|rest\s*day|\boff\s+(?:ko|day)\b|pahinga|makukuha|kukunin|\bwill\s+(?:get|pick|receive|order|take)\b"
    r"|\border\s+na\s+(?:po\s+)?(?:ako|ko)\b|\border\s+already\b|\bcan\s+i\s+order\b|\bcoming\s+\d{1,2}\b", re.I)
# Lý do / ghi chú model viết khi nó coi là đơn cũ; câu AI hỏi ngược "đơn bạn đã đặt / SĐT lúc đặt".
LY_DO_DON_CU = re.compile(r"đơn\s*cũ|đơn\s*đã\s*đặt|kiểm\s*tra\s*(?:lại\s*)?đơn|tra\s*(?:lại\s*)?đơn|mục\s*7\.4"
                          r"|old\s*order|existing\s*order|previous\s*order", re.I)
HOI_DON_DA_DAT = re.compile(
    r"already\s+placed|order\s+you\s+(?:already\s+)?(?:placed|made)|when\s+you\s+(?:placed\s+|made\s+)(?:the\s+|your\s+)?order"
    r"|when\s+you\s+ordered|you\s+used\s+(?:when|for|to)|your\s+previous\s+order|nag-?order\s+na\s+po\s+ba\s+kayo"
    r"|ginamit\s+(?:niyo|ninyo|mo)\s+(?:sa|nung|noong)", re.I)


def khach_nhac_don_minh(msgs):
    """Câu khách nhắc "đơn của tôi" SẮP đặt / sắp nhận (order ko / yung order / my order / I order already… + ngày hẹn /
    ngày nghỉ / lương) trong 2 tin khách gần nhất, hoặc None. Câu mang dấu đơn đã đi (where / cancel / received…) và câu
    khẳng định đã mua (khach_noi_da_mua — luật 32A) để cửa khác lo."""
    if khach_noi_da_mua(msgs):
        return None
    khach = [lam_sach(m.get("text") or "") for m in (msgs or []) if m.get("boi") == "khach"]
    for t in reversed(khach[-2:]):
        if (NHAC_DON_MINH.search(t) and not NHAC_DON_DA_DI.search(t)
                and (NGAY_HEN.search(t) or DOI_LUONG.search(t) or NHAC_DON_TUONG_LAI.search(t))):
            return t[:120]
    return None


def khach_khieu_nai_don(msgs, so_tin=10):
    """Khách đang khiếu nại / đòi hoàn tiền cho hàng họ nói ĐÃ nhận? Trả câu khách nói hoặc None.

    Cửa sổ là các tin khách TRONG PHIÊN NÀY (sau lần bấm quảng cáo gần nhất), tối đa `so_tin` tin —
    ca Jen: câu "back my money" nằm ở tin khách thứ 2/6, lấy 3 tin cuối như `khach_noi_da_mua` là mù.
    """
    msgs = msgs or []
    dau = 0
    for i, m in enumerate(msgs):
        if m.get("boi") == "hethong" and _MO_PHIEN_MOI.search(m.get("text") or ""):
            dau = i
    khach = [lam_sach(m.get("text") or "") for m in msgs[dau:] if m.get("boi") == "khach"]
    for t in reversed(khach[-so_tin:]):
        if not t or _KN_DIEU_KIEN.search(t) or _KN_TUONG_LAI.search(t):
            continue
        if KN_DOI_TIEN.search(t) or _kn_khop_that(t):
            return t[:120]
    return None


# Câu AI HỨA ĐỀN BÙ cho cái đơn không tồn tại — cấm tuyệt đối ở ca trên (shop không có gì để xử).
KN_HUA_DEN_BU = re.compile(
    r"\b(?:we|i|our team)\s*(?:'ll|will|can|shall|are\s+going\s+to)\s+(?:gladly\s+|surely\s+|definitely\s+)?"
    r"(?:refund|replace|resend|re-?send|reship|return\s+your\s+" + _KN_TIEN + r"|check\s+(?:your|the)\s+order|"
    r"look\s+into\s+(?:your|the)\s+order|process\s+(?:your\s+)?(?:refund|return)|send\s+(?:you\s+)?"
    r"(?:a\s+|another\s+)?(?:new|replacement|correct))\b"
    r"|\b(?:sorry|apolog\w+)\b[^.?!\n]{0,40}?\b(?:wrong|damaged|broken|fake|delivery|delivered|order|parcel|"
    r"experience|inconvenience)\b"
    r"|\byour\s+(?:refund|replacement)\b|\bfull\s+refund\b"
    r"|\b(?:ibabalik|isasauli)\s+(?:namin|po)\b|\bpapalitan\s+namin\b"
    r"|سنقوم\s*(?:بـ)?(?:إرجاع|ارجاع|استرجاع)|سنرجع\s*(?:لك)?\s*(?:ال)?(?:فلوس|مبلغ)", re.I | re.U)
# …và câu ĐÚNG luật: nói rõ bên mình KHÔNG có đơn / khách có thể nhầm shop.
KN_BAO_KHONG_CO_DON = re.compile(
    r"\b(?:no|not|don'?t|do\s+not|can'?t|cannot|couldn'?t|didn'?t|unable\s+to)\b[^.?!\n]{0,40}?"
    r"\b(?:order|orders|purchase|record|records|history|transaction|bought|buy)\b"
    r"|\b(?:another|different|other|iba(?:ng)?|ibang)\s+(?:page|shop|store|seller|tindahan)\b"
    r"|\bwala\b[^.?!\n]{0,30}?\b(?:order|record|bili|binili|nabili)\b"
    r"|\bhindi\b[^.?!\n]{0,30}?\b(?:makita|nakita|mahanap)\b[^.?!\n]{0,20}?\b(?:order|record|bili)\b"
    r"|لا\s*يوجد\s*(?:أي\s*)?(?:طلب|طلبات|سجل)|ما\s*(?:عندنا|لدينا)\s*(?:أي\s*)?(?:طلب|طلبات|سجل)"
    r"|لم\s*نجد\s*(?:أي\s*)?(?:طلب|طلبات|سجل)|(?:صفحة|متجر)\s*(?:ثانية|أخرى|اخرى|ثاني|آخر|اخر)", re.I | re.U)


# LỜI ĐỢI LƯƠNG CŨ KHÔNG KÉO SANG PHIÊN MỚI — chủ shop 14/09 tối, ca Landa Militar (Kuwait Amoura
# Gold): khách nói "I'm waiting my salary" từ 23/07, tới 14/09 bấm lại quảng cáo hỏi "How much", AI
# đáp nguyên bài "giao đúng ngày lương, bạn nhận lương ngày nào?" mà không báo giá. *"khách hỏi 1
# đường, rep 1 nẻo vậy"*. Gốc: bộ dò quét toàn bộ lịch sử không giới hạn thời gian.
# Chỉ tính tin khách: sau lần bấm quảng cáo gần nhất, trong LUONG_HIEU_LUC_GIAY tính từ tin khách
# mới nhất, và nằm trong LUONG_SO_TIN tin khách cuối.
LUONG_HIEU_LUC_GIAY = 3 * 86400
LUONG_SO_TIN = 3
_MO_PHIEN_MOI = re.compile(r"đã trả lời một quảng cáo|replied to (?:an|your) ad", re.I | re.U)


def _moc_giay(luc):
    from datetime import datetime, timezone
    try:
        t = datetime.fromisoformat(str(luc).replace("Z", "+00:00"))
        return (t if t.tzinfo else t.replace(tzinfo=timezone.utc)).timestamp()
    except Exception:
        return None


# PHIÊN MỚI = khách bấm quảng cáo lại sau ≥ PHIEN_IM_GIAY im lặng — chủ shop 21/09, ca Najo Oiretuel · She
# Jewelry UAE (*"page này đã sửa kịch bản, bạn fix lại nhé"*): khách nhắn page hồi 19/06–06/07 (quảng cáo VÒNG
# TAY, page báo "89 AED – 1 Bracelet / 139 AED – 2 Bracelets"), 21/09 bấm quảng cáo NHẪN mới hỏi "How much?" →
# AI: "89 AED for 1 bracelet, or 139 AED for 2 bracelets". Kịch bản nhẫn đã về máy 21 GIÂY trước đó — lỗi ở khối
# "GIÁ PAGE ĐÃ TỰ BÁO" lục cả lịch sử, nhặt bảng vòng tay 3 tháng trước và dặn "bảng mới nhất thắng cả kịch bản";
# bản ghi đưa model cũng còn nguyên tin sale báo giá vòng tay. Đo 1.345 hội thoại 72 giờ (6 nước): 45 hội
# thoại mang bảng giá phiên cũ có con số KHÔNG có trong kịch bản hiện tại (Cloves Tea 2 set 169 — nay 159;
# Hair Repair KSA báo AED; Veloura còn là cái ví; Oman Gold "199 OMR"…). Ngưỡng 6 giờ: khách bấm lại quảng
# cáo trong vài giờ vẫn là một lần mua (đo: bấm lại < 6 giờ không có ca nào mang giá ngoài kịch bản).
PHIEN_IM_GIAY = 6 * 3600


def dau_phien(msgs):
    """Vị trí tin đầu của PHIÊN hiện tại trong msgs — 0 = cả đoạn là một phiên.

    Mốc = tin hệ thống "đã trả lời một quảng cáo" mà trước cụm tin của lần bấm đó (ad_click rỗng, câu chào
    tự động — cách mốc ≤ 120 giây) hội thoại đã im ≥ PHIEN_IM_GIAY. Phiên bắt đầu từ chính cụm tin ấy.
    """
    msgs = msgs or []
    dau = 0
    for i, m in enumerate(msgs):
        if m.get("boi") != "hethong" or not _MO_PHIEN_MOI.search(m.get("text") or ""):
            continue
        t0 = _moc_giay(m.get("luc"))
        if t0 is None:
            continue
        j = i - 1
        while j >= 0 and msgs[j].get("boi") == "hethong" and t0 - (_moc_giay(msgs[j].get("luc")) or t0) <= 120:
            j -= 1
        tj = _moc_giay(msgs[j].get("luc")) if j >= 0 else None
        if tj is not None and t0 - tj >= PHIEN_IM_GIAY:
            dau = j + 1
    return dau


def _tin_khach_con_hieu_luc(msgs):
    """Tin khách (đã làm sạch) còn tính cho luật đợi lương — bỏ tin phiên cũ / quá cũ."""
    msgs = msgs or []
    dau = 0
    for i, m in enumerate(msgs):
        if m.get("boi") == "hethong" and _MO_PHIEN_MOI.search(m.get("text") or ""):
            dau = i
    kh = [m for m in msgs[dau:] if m.get("boi") == "khach"][-LUONG_SO_TIN:]
    moi = _moc_giay(kh[-1].get("luc")) if kh else None
    if moi is not None:
        kh = [m for m in kh if (_moc_giay(m.get("luc")) or moi) >= moi - LUONG_HIEU_LUC_GIAY]
    return [lam_sach(m.get("text") or "") for m in kh]


def _mo_ta_ngay_hen(hen):
    """Đoạn nhắc ngày hẹn cho khối ĐỢI LƯƠNG: có ngày thì ghi RÕ ("date4sis" = ngày 4) + cấm hỏi lại (25/09, ca Eni Habibty — AI
    hỏi lại 2 lần vì chỉ được dặn 'khách đã nêu ngày trong câu đó')."""
    if not hen or not hen[1]:
        return " — khách CHƯA nói ngày nào"
    m = NGAY_HEN.search(hen[1])
    doan = m.group(0) if m else hen[1][:40]
    so = re.search(r"\d{1,2}", doan)
    ro = ("ngày " + str(int(so.group(0)))) if so and not re.search(_THANG, doan, re.I) else doan
    return (' — NGÀY KHÁCH ĐÃ HẸN: "' + doan + '" (= ' + ro + '; khách nói: "' + hen[1][:80] + '"). ⛔ KHÔNG hỏi lại ngày lương / '
            'ngày giao — xác nhận giao ĐÚNG ' + ro + ', chỉ xin phần CÒN THIẾU')


def hen_giao_theo_luong(msgs):
    """Khách có nói đợi lương / chưa có tiền không?

    Trả (câu khách nói về lương, câu hẹn ngày — "" nếu khách chưa nói ngày) hoặc None.
    Quét tin khách từ MỚI về CŨ, lấy lần gần nhất; ngày hẹn tìm trong chính câu đó rồi các tin
    khách SAU đó (khách hay nói "wait my salary" rồi lượt sau mới nói "on the 25th").
    Chỉ xét tin còn hiệu lực (_tin_khach_con_hieu_luc) — lời đợi lương 2 tháng trước không tính.
    """
    khach = _tin_khach_con_hieu_luc(msgs)
    for pos in range(len(khach) - 1, -1, -1):
        t = khach[pos]
        if not DOI_LUONG.search(t):
            continue
        ngay = next((u for u in khach[pos:] if NGAY_HEN.search(u)), "")
        if not ngay and pos > 0 and NGAY_HEN.search(khach[pos - 1]):
            ngay = khach[pos - 1]                     # "deliver at october 5" rồi "After salary" (25/09, ca Noena)
        return t[:120], ngay[:120]
    return None


def dong_hen_giao(msgs, mkey=None, pid=None):
    """Dòng ghi vào note đơn khi khách hẹn giao ngày lương; None nếu khách không nói gì như thế."""
    hen = hen_giao_theo_luong(msgs)
    qh = khach_hen_qua_han(msgs, mkey=mkey, pid=pid)
    canh_bao = (f" · ⚠️ QUÁ HẠN GIỮ ĐƠN {CG.so_thang_giu_don(mkey)} THÁNG (khách nói ≈{qh[1]:%d/%m/%Y}, "
                f"hạn {CG.han_giu_don(mkey=mkey):%d/%m/%Y})"
                f" — sale gọi chốt ngày trong hạn hoặc hủy") if qh else ""
    if not hen:
        return (f'KHÁCH HẸN GIAO: "{qh[0]}"' + canh_bao) if qh else None
    cau, ngay = hen
    return (f'HẸN GIAO NGÀY LƯƠNG — khách nói: "{cau}"'
            + (f' · ngày hẹn: "{ngay}"' if ngay and ngay != cau
               else (' (câu này có ngày)' if ngay else ' · CHƯA rõ ngày — sale hỏi khách'))
            + (canh_bao or " → giao đúng ngày đó, gọi xác nhận trước khi giao"))


# HẠN GIỮ ĐƠN 1 THÁNG — chủ shop 2026-09-14, ca Jessica Dongon (Meco Kuwait): khách "February po sir"
# (đợi lương tháng 2 năm sau), AI "I-schedule ko na po ang delivery sa February 24" và lên đơn.
# *"như vậy tôi lấy đâu ra đơn hàng … bảo khách chỉ nhận giữ đơn hàng trong vòng 1 tháng kể từ ngày
# chốt đơn, ví dụ đến hết tháng 10"*. Hạn và bộ đọc ngày ở chan_gui (CG.han_giu_don / CG.ngay_qua_han).
# Chỉ xét câu khách nói TRONG NGỮ CẢNH hẹn giao: đang nói lương/tiền, hoặc nhắc giao/nhận, hoặc page
# vừa hỏi ngày — "I bought it in March" không phải hẹn giao.
_NGU_CANH_HEN = re.compile(
    r"\b(deliver\w*|receive|send|ship\w*|schedule|date|when|kailan|petsa|hatid|padala|dating|tanggap\w*|"
    r"sweldo|suweldo|sahod|salary|payday|paid|money|pera|cash|book)\b|توصيل|توصل|متى|موعد|تاريخ|راتب|送|到貨|薪",
    re.I | re.U)
# Tin PAGE đứng trước chỉ tính là ngữ cảnh hẹn khi page HỎI NGÀY/lương — "Para ma-book ko na po ang order"
# hay "COD cash on delivery" có trong gần như mọi tin page (ca Aiza 14/09: "book" → "month of feb" thành hẹn).
_PAGE_HOI_NGAY = re.compile(
    r"\b(when|kailan|date|petsa|schedule\w*|i-?schedule|what\s+day|which\s+day|araw|sweldo|suweldo|sahod|"
    r"salary|payday)\b|متى|موعد|تاريخ|راتب|哪天|幾號|几号|何時", re.I | re.U)
# Tháng là TÊN HÀNG: page bán bộ đá/trang sức tháng sinh ("18K Saudi Gold Birthstone Set", "January Garnet
# Birthstone Set"). Ca Aiza "Available po month of feb", ca Saudi #74162 "2 set mam September and July available".
_THANG_LA_HANG = re.compile(
    r"\b(birth\w*|stones?|sets?|designs?|avail\w*|stocks?|pendants?|necklaces?|rings?|bracelets?|earrings?|"
    r"zodiac|colou?rs?|kulay|month\s+of)\b", re.I)
_PAGE_BAN_THANG_SINH = re.compile(r"birth\s*-?\s*(stone|month)|zodiac|\bmonth\s+of\s+(jan|feb|mar|apr|may|jun|jul|"
                                  r"aug|sep|oct|nov|dec)", re.I)
# "jan" trơn không kèm ngày là Tagalog "dyan" (ở đó): "pic jan", "Jan dito po Ako philippines" — đo 14/09
_JAN_TAGALOG = re.compile(r"(?<!\d)(?<!\d\s)\bjan\b(?!\s*\d)(?!uary)", re.I)

# ══ PAGE BÁN THEO THÁNG SINH: TÊN THÁNG KHÁCH NÓI LÀ TÊN BỘ, KHÔNG PHẢI NGÀY HẸN (chủ shop 22/09) ══════════════
# Ca Fe Cavan Cavan · Kuwait Amoura Gold 14:43 VN: khách chọn đá cho 6 bộ — "August march april and may ok" — AI đáp
# "Sorry Fe, we can only hold the order and the promo price until October 31 … the 15th or the 30th?". Chủ shop:
# *"khách chọn tháng sinh mà sao bạn lại rep hẹn"*. Gốc: tin page ngay trước là câu GIỮ ƯU ĐÃI (CAU_GIU_UU_DAI)
# "…and you can choose your delivery date" — chữ "date" làm _PAGE_HOI_NGAY tưởng page vừa HỎI NGÀY, cửa miễn "page
# bán tháng sinh" (14/09) tắt, "August" thành ngày hẹn 08/2027. Sổ việc 14→22/09 ở 14 page có ảnh tháng: 33 tin AI
# nhắc hạn giữ đơn, ít nhất 16 tin là khách đang CHỌN THÁNG — Jhenjhen · Oman Gold "Ok I choose April and
# February", Crisarlene · Oman Gold "October dec", Elias · Amoura "May salary coming October 31 … month birthday
# January", Rassel · Veloura "April po ok itong end og sept ko ipa deliver po", Perlita · Veloura "…sa salary day.
# August and May".
# Ở page bán theo tháng sinh, TỪNG tên tháng khách gõ được xét riêng (_ngay_hen_page_thang_sinh):
#   1. sát chữ hàng / sinh / đá / màu / ảnh / giá (±2 chữ, không đếm chữ đệm po/na/lang…; bộ _NGU_CANH_THANG của
#      đường ảnh đúng tháng) → TÊN BỘ;
#   2. nằm trong DANH SÁCH tháng ("October dec", "April and February", "August and May") → TÊN BỘ;
#   3. có chữ giao / lương / trả tiền / thời hạn sát bên (±4 chữ không đệm, cùng câu), "sa <tháng> pa" → NGÀY HẸN;
#      chữ MUA (order/buy/bibili/kunin) chỉ tính khi tháng có giới từ thời gian ("order ON January", "bibili ako SA
#      December", "December PA") — "I want to order January" (Oman Gold, kho 19/09) là đặt BỘ tháng 1;
#   4. câu có chữ hàng ở chỗ khác (_THANG_LA_HANG, cửa cũ 14/09) → TÊN BỘ;
#   5. page vừa HỎI NGÀY bằng câu hỏi thật và trong câu không tháng nào gắn chữ giao → NGÀY HẸN ("When do you want
#      it?" → "February");
#   6. còn lại → TÊN BỘ (như cửa miễn cũ).
# "Page vừa HỎI NGÀY" ở page này = một CÂU CÓ DẤU HỎI chứa chữ hỏi ngày/lương. Câu mời "you can choose your delivery
# date" và câu COD "pay when you receive" không có dấu hỏi — đo 1.850 tin AI gửi ở 14 page: mọi câu hỏi ngày/lương
# thật ("When do you get your salary?", "Kailan po ang sahod ninyo?", "Which day works for you?") đều có "?".
# Page KHÔNG bán theo tháng sinh: giữ nguyên luật cũ (ở đó "February" sau câu mời chọn ngày đúng là ngày giao).
_KHONG_HOI_NGAY = re.compile(
    r"\bwhen\s+(?:you|it|they|your\s+\w+|the\s+\w+)\s+(?:\w+\s+)?(?:receive|get|arrive|deliver)\w*", re.I)
_RANG_BUOC_NGAY = re.compile(
    r"(?:deliver\w*|ship\w*|arriv\w*|dumating|darating|padala|ipadala|hatid|ihatid|receiv\w*|matanggap|tanggap\w*"
    r"|sahod|sahud|sahuran|sweldo|suweldo|swelduhan|salary|payday|pay|paid|payment|bayad|magbabayad|babayaran"
    r"|schedul\w*|i-?schedule|reserv\w*|until|till|untill|hanggang|pagdating|katapusan|before|after|bago|next"
    r"|توصيل|نوصل|يوصل|راتب|الراتب|موعد|تاريخ)", re.I | re.U)
_MUA_HANG = re.compile(r"(?:o?order\w*|bibili|bumili|makakabili|mabibili|buy|purchase|kukunin|kunin|kuha|makuha)", re.I)
_GIOI_TU_LUC = {"in", "on", "by", "sa", "this", "come", "pag", "pagdating", "ngayong", "until", "till", "before",
                "after", "bago", "hanggang", "next"}
_TU_CHI_MON = {"yung", "ang", "ung", "yong", "iyong", "kay", "the"}       # "yung sa December" = cái của tháng 12
_NOI_DS_THANG = {"and", "at", "or", "o", "&", ",", "/", "po", "saka", "tsaka", "also", "then"}
_SAU_MAY_DS = {None, "ok", "okay", "po", "lang", "only", "month", "months", "birthstone", "birthstones", "set", "sets",
               "stone", "stones", "and", "at", "or", ",", "&", "/", "pls", "please"}
_NAM_SINH_SAU = re.compile(r"\s*,?\s*(?:19\d\d|200\d|201\d)(?!\d)")


# Page BÁN THEO THÁNG SINH theo KỊCH BẢN: kịch bản có chữ birthstone / birth month, hoặc có ảnh nhãn tháng cho ≥ 6
# tháng (Kuwait Amoura Gold, Oman Gold Lucky, Glamora, Veloura, BirthStone USUS, Stone Jewelry Saudi - Taiwan). Hội thoại
# mà sale chỉ gửi mẫu giá / mẫu xin thông tin (không có chữ "birthstone") thì bộ dò theo tin không nhận ra — ca "January i
# want" → "Send me the january" (Amoura, kho hội thoại cũ) vẫn bị coi là hẹn tháng 1/2027. Page chỉ có 1-2 ảnh tháng lạc
# (ChunHo, Jode, Master ng Kapalaran…) KHÔNG tính — ở Jode "Sa October 12 pa ang salary" là ngày lương thật.
_KB_THANG = {}                                   # mkey -> (mtime kich_ban.json, kịch bản, {pid: bool})


def page_ban_theo_thang_sinh(mkey, pid):
    """Page này bán theo tháng sinh không (theo kịch bản, đệm theo mtime). Lỗi đọc → False (rơi về bộ dò theo tin)."""
    if not (mkey and pid):
        return False
    try:
        f = os.path.join(SCRIPT_DIR, "state", mkey, "kich_ban.json")
        mt = os.path.getmtime(f)
        cu = _KB_THANG.get(mkey)
        if not cu or cu[0] != mt:
            cu = (mt, qht.load_json(f, {}), {})
            _KB_THANG[mkey] = cu
        pid = str(pid)
        if pid not in cu[2]:
            v = cu[1].get(pid) or {}
            cu[2][pid] = bool(_PAGE_BAN_THANG_SINH.search(json.dumps(v.get("mau") or [], ensure_ascii=False))
                              or len(_anh_theo_thang_page(v, mkey, pid)) >= 6)
        return cu[2][pid]
    except Exception:
        return False


def _bo_ngay_sinh(t):
    """Xoá ngày có NĂM SINH đi kèm ("November 17,1979", "June 11 1983") — ngày sinh, không bao giờ là ngày hẹn giao.
    Ca Leticia · Mang Mulat Sa (kho 19/09): page tử vi hỏi ngày sinh, bộ đọc ngày coi "November 17" là 17/11 năm nay
    (năm 19xx không được _NAM đọc) → quá hạn giữ đơn. Mọi page."""
    t = str(t or "")
    ra = list(t)
    for mo in CG._THANG_RE.finditer(t):
        if _NAM_SINH_SAU.match(t, mo.end()):
            ra[mo.start():mo.end()] = " " * (mo.end() - mo.start())
    return "".join(ra)


def _thang_sat_chu_sinh(t):
    """Khách gõ TÊN THÁNG sát chữ sinh / đá / màu (±2 chữ): "I want color December", "month birthday January"."""
    tok = re.findall(r"[^\W\d_]+", qht.norm(t or ""))
    for k, w in enumerate(tok):
        if w in ("may", "mayo", "jan", "jun", "mar") or not (_la_ten_thang(w) or w in _THANG_AR):
            continue
        if _NGU_CANH_SINH.search(" ".join(tok[max(0, k - 2):k + 3])):
            return True
    return False


def _page_hoi_ngay_that(truoc):
    """Tin page đứng trước có CÂU HỎI ngày / lương thật không — câu có dấu hỏi chứa chữ hỏi ngày (bỏ cụm COD
    "pay when you receive"). Chỉ dùng cho page bán theo tháng sinh."""
    for c in re.split(r"(?<=[.!?؟？。])\s+|\n+", truoc or ""):
        if re.search(r"[?؟？]", c) and _PAGE_HOI_NGAY.search(_KHONG_HOI_NGAY.sub(" ", c)):
            return True
    return False


def _ngay_hen_page_thang_sinh(t, hom_nay=None, hoi_that=False):
    """Page bán theo tháng sinh: các NGÀY HẸN thật trong câu khách — tên tháng là tên BỘ thì bỏ (xem khối trên).

    Trả (danh sách date, có tháng nào gắn chữ giao / lương / thời hạn không)."""
    hn = hom_nay or date.today()
    t = str(t or "")
    tj = _JAN_TAGALOG.sub(lambda mo: " " * len(mo.group(0)), t)          # giữ nguyên vị trí từng chữ
    tok = [(mo.group(0).lower(), mo.start()) for mo in re.finditer(r"[^\W\d_]+(?:['’][^\W\d_]+)?|\d+|[,&/]", t)]
    ngat = [mo.end() for mo in re.finditer(r"[.!?؟？。](?=\s)", t)]

    def _cau(k):
        return sum(1 for x in ngat if x <= tok[k][1])

    def _la_thang_tok(k, cho_may=True):
        if not 0 <= k < len(tok):
            return False
        w = tok[k][0]
        if w == "may":                               # "may" trơn = có thể / Tagalog "có" — chỉ tính trong danh sách
            if not cho_may:
                return False
            sau = tok[k + 1][0] if k + 1 < len(tok) else None
            return sau in _SAU_MAY_DS or _la_thang_tok(k + 1, cho_may=False)
        return bool(_la_ten_thang(w)) or w in ("jan", "jun", "mar") or w in _THANG_AR

    def _cua_so(idx, n, lo, hi):
        # chỉ số đầu / cuối của cửa sổ gồm n chữ KHÔNG phải chữ đệm (_TU_DEM) mỗi bên, trong cùng câu —
        # "December pa po ako bibili": động từ đứng cuối sau mấy chữ đệm
        a = b = idx
        dem = 0
        while a > lo and dem < n:
            a -= 1
            dem += tok[a][0] not in _TU_DEM
        dem = 0
        while b < hi and dem < n:
            b += 1
            dem += tok[b][0] not in _TU_DEM
        return a, b

    nam = CG._NAM.search(t)
    nam = int(nam.group(1)) if nam else None
    co_hang = bool(_THANG_LA_HANG.search(t))
    nhac = []                                        # [(vị trí chữ tháng, tháng, ngày)]
    for mo in CG._THANG_RE.finditer(tj):
        th = next(int(k[1:].split("_")[0]) for k, v in mo.groupdict().items() if v and k[0] in "abc")
        ng = mo.group("d1") or mo.group("d2") or mo.group("d3")
        idx = next((k for k in range(len(tok)) if mo.start() <= tok[k][1] < mo.end()
                    and not tok[k][0].isdigit() and tok[k][0] not in ("st", "nd", "rd", "th", "of", "ng", "de")), None)
        if idx is not None:
            nhac.append((idx, th, int(ng) if ng else None))
    loai = {}
    for idx, th, ng in nhac:
        c = _cau(idx)
        cung = [k for k in range(len(tok)) if _cau(k) == c]
        lo, hi = cung[0], cung[-1]
        a2, b2 = _cua_so(idx, 2, lo, hi)
        if _NGU_CANH_THANG.search(" ".join(w for w, _ in tok[a2:b2 + 1])):
            loai[idx] = "hang"
            continue
        if any(j != idx and _la_thang_tok(j) and all(tok[x][0] in _NOI_DS_THANG for x in range(min(j, idx) + 1, max(j, idx)))
               for j in range(max(0, idx - 3), min(len(tok), idx + 4))):
            loai[idx] = "hang"
            continue
        a4, b4 = _cua_so(idx, 4, lo, hi)
        quanh = [tok[x][0] for x in range(a4, b4 + 1) if x != idx]
        t1 = tok[idx - 1][0] if idx > lo else ""
        t2 = tok[idx - 2][0] if idx - 1 > lo else ""
        s1 = tok[idx + 1][0] if idx < hi else ""
        co_luc = (t1 in _GIOI_TU_LUC and not (t1 == "sa" and t2 in _TU_CHI_MON)) or s1 == "pa"
        if (any(_RANG_BUOC_NGAY.fullmatch(w) for w in quanh) or (t1 == "sa" and s1 == "pa")
                or (co_luc and any(_MUA_HANG.fullmatch(w) for w in quanh))):
            loai[idx] = "hen"
            continue
        loai[idx] = "hang" if co_hang else "?"
    co_rang_buoc = "hen" in loai.values()
    ra = []
    for idx, th, ng in nhac:
        lo_ = loai.get(idx)
        if lo_ == "hen" or (lo_ == "?" and hoi_that and not co_rang_buoc):
            y = nam or (hn.year + 1 if th < hn.month else hn.year)
            v = CG._ngay_hop_le(y, th, ng or 1)
            if v:
                ra.append(v)
    # Ngày KHÔNG viết bằng tên tháng (dd/mm/yyyy, "next year", "after 3 months", 十月) — đọc như cũ trên câu đã xoá tên tháng
    trong = list(tj)
    for mo in CG._THANG_RE.finditer(tj):
        trong[mo.start():mo.end()] = " " * (mo.end() - mo.start())
    ra += CG.ngay_trong_cau("".join(trong), hn)
    return ra, co_rang_buoc


def khach_hen_qua_han(msgs, hom_nay=None, so_tin=4, mkey=None, pid=None):
    """Khách có hẹn giao / đợi tới một ngày QUÁ hạn giữ đơn không?

    Trả (câu khách nói ≤120 ký tự, ngày date đọc được) hoặc None. Quét `so_tin` tin khách gần nhất từ
    MỚI về CŨ: gặp tin có ngày TRONG hạn trước (khách đã đổi ý "ok October 30") thì thôi, không kéo lại.
    """
    msgs = msgs or []
    co_luong = any(m.get("boi") == "khach" and DOI_LUONG.search(lam_sach(m.get("text") or "")) for m in msgs)
    ban_thang_sinh = any(m.get("boi") != "khach" and _PAGE_BAN_THANG_SINH.search(m.get("text") or "") for m in msgs)
    # 22/09: page không nói "birthstone" trong hội thoại mà KHÁCH gõ tên tháng sát chữ sinh / đá / màu ("I want color
    # December" — Veloura, kho 19/09) thì hội thoại cũng là chuyện bộ theo tháng sinh. Đo ~3.000 hội thoại cũ: bật thêm
    # 11, cả 11 ở page bán theo tháng sinh (Amoura 8, Jode 2, Veloura 1), 0 ở page khác.
    ban_thang_sinh = (ban_thang_sinh or page_ban_theo_thang_sinh(mkey, pid)
                      or any(m.get("boi") == "khach" and _thang_sat_chu_sinh(m.get("text") or "") for m in msgs))
    dem = 0
    for i in range(len(msgs) - 1, -1, -1):
        m = msgs[i]
        if m.get("boi") != "khach":
            continue
        dem += 1
        if dem > so_tin:
            break
        t = lam_sach(m.get("text") or "")
        tn = _bo_ngay_sinh(t)               # ngày có năm sinh đi kèm là NGÀY SINH, không phải ngày hẹn (22/09)
        ds = CG.ngay_trong_cau(_JAN_TAGALOG.sub(" ", tn), hom_nay)
        if not ds:
            continue
        truoc = next((lam_sach(x.get("text") or "") for x in reversed(msgs[:i]) if x.get("boi") != "khach"), "")
        tu_noi_giao = _NGU_CANH_HEN.search(t)
        page_hoi_ngay = _PAGE_HOI_NGAY.search(truoc)
        if ban_thang_sinh:
            # Page bán theo tháng sinh (chủ shop 22/09, ca Fe Cavan): xét TỪNG tên tháng — tên BỘ thì bỏ, chỉ còn
            # ngày hẹn thật; "page hỏi ngày" phải là câu hỏi thật (xem _ngay_hen_page_thang_sinh).
            hoi_that = _page_hoi_ngay_that(truoc)
            ds_that, rang_buoc = _ngay_hen_page_thang_sinh(tn, hom_nay, hoi_that)
            if not ds_that or not (rang_buoc or co_luong or tu_noi_giao or hoi_that):
                continue
            muon = max(ds_that)
            return (t[:120], muon) if muon > CG.han_giu_don(hom_nay, mkey) else None
        # Tháng là tên hàng (bộ đá tháng sinh) — khách không tự nói giao/lương trong câu thì bỏ qua
        if not tu_noi_giao and (_THANG_LA_HANG.search(t) or (ban_thang_sinh and not page_hoi_ngay)):
            continue
        if not (co_luong or tu_noi_giao or page_hoi_ngay):
            continue
        qh = CG.ngay_qua_han(_JAN_TAGALOG.sub(" ", tn), hom_nay, mkey)
        return (t[:120], qh) if qh else None
    return None


def dong_han_giu_don(msgs, hom_nay=None, mkey=None, pid=None):
    """Khối nhắc model khi khách hẹn quá hạn giữ đơn; None nếu không có."""
    qh = khach_hen_qua_han(msgs, hom_nay, mkey=mkey, pid=pid)
    if not qh:
        return None
    han = CG.han_giu_don(hom_nay, mkey)
    _st = CG.so_thang_giu_don(mkey)
    han_en = f"{han:%B} {han.day}"
    return (f'⛔ KHÁCH HẸN NGÀY QUÁ HẠN GIỮ ĐƠN: "{qh[0]}" (≈ {qh[1]:%d/%m/%Y}). Hôm nay {(hom_nay or date.today()):%d/%m/%Y}; '
            f"shop CHỈ giữ đơn trong vòng {_st} tháng từ ngày chốt — hạn chót giao: {han:%d/%m/%Y} ({han_en}). "
            f"KHÔNG nhận ngày đó, KHÔNG 'schedule/book/deliver on' ngày đó, KHÔNG lên lịch giao sau {han_en}. "
            f"Áp luật HẠN GIỮ ĐƠN: nói rõ (đúng tiếng khách, nhẹ nhàng) đơn và giá khuyến mãi chỉ giữ được tới "
            f"{han_en}; COD hôm nay không trả gì; mời khách chọn một ngày giao TRƯỚC {han_en} (vd. ngày lương "
            f"gần nhất 15 hoặc 30) + xin phần còn thiếu. Níu đủ {LUOT_NIU} lượt; sau lượt {LUOT_NIU} khách vẫn chỉ nhận sau "
            f"{han_en} → 'treo', ghi_chu 'khách chỉ nhận hàng {qh[1]:%m/%Y} — quá hạn giữ đơn {_st} tháng, sale quyết'.")


# THỜI GIAN GIAO — chủ shop 14/09 tối, ca Wahida (Kreain Nature PH in Uae): khách "Ok yuo can deliver tomorrow",
# AI "I can arrange delivery for tomorrow". *"b phải dựa vào thời gian giao hàng để rep khách chứ"*. Số ngày ở
# CG.thoi_gian_giao (chủ shop chốt 23/09: Saudi 3-7, Đài/Mỹ theo khoảng GIAO HÀNG trong kịch bản page, còn lại 2-5;
# KHÔNG đọc tin hội thoại nữa — ca Hanah "7–10 days pa lang may changes na"). Khối nhắc chỉ chèn khi
# khách đang nói chuyện giao/ngày (đỡ tiền prompt); luật cứng hua_giao_som ở vòng soạn + cổng chặn là rào.
_KHACH_NOI_GIAO = re.compile(
    r"\b(deliver\w*|ship\w*|arriv\w*|receive|tomorrow|tmrw|today|tonight|bukas|ngayon|kailan|when|how\s+long|"
    r"how\s+many\s+days|days?|araw|date|schedule|rush|urgent|asap)\b|توصيل|متى|بكرة|بكره|غدا|اليوم|كم يوم|"
    r"明天|今天|幾天|几天|到貨|送", re.I | re.U)


def dong_thoi_gian_giao(msgs, mkey, kb_page, so_tin=3):
    """Khối nhắc số ngày giao khi khách đang hỏi/hẹn giao; None nếu khách không nhắc gì tới giao/ngày."""
    kh = [lam_sach(m.get("text") or "") for m in (msgs or []) if m.get("boi") == "khach"][-so_tin:]
    if not any(_KHACH_NOI_GIAO.search(t) for t in kh):
        return None
    cau_page = [m.get("text") or "" for m in (msgs or []) if m.get("boi") in ("botcake", "nguoi")
                and "AI SALE" not in (m.get("text") or "")]
    lo, hi, nguon = CG.thoi_gian_giao(mkey, kb_page, cau_page)
    hn = date.today()
    som = date.fromordinal(hn.toordinal() + lo)
    return (f"🚚 THỜI GIAN GIAO HÀNG: {lo}-{hi} ngày kể từ khi chốt đơn, không tính cuối tuần/ngày lễ ({nguon}). "
            f"Hôm nay {hn:%d/%m} → sớm nhất khoảng {som:%B} {som.day}. ⛔ KHÔNG nhận / KHÔNG hứa giao hôm nay, "
            f"ngày mai, hay ngày nào trước {som:%B} {som.day} — kể cả khi khách đòi. Khách muốn nhận sớm → nói nhẹ "
            f"nhàng hàng mất {lo}-{hi} ngày, đặt ngay hôm nay là nhận sớm nhất, rồi xin phần còn thiếu. Khách hẹn "
            f"ngày muộn hơn (vẫn trong hạn giữ đơn) thì nhận bình thường.")


# Tin hệ thống Facebook khi khách bấm quảng cáo: "Hi Krishel! How can we help you?" / "... đã trả lời một quảng
# cáo" — Facebook tự chèn, page CHƯA hỏi gì. Ca Krishel 14/09 tối: khách "hm" ngay sau câu này bị coi là "đáp cụt
# sau câu hỏi của page" → AI chào giá. Chủ shop: *"sao khách này b lại rep"*.
CHAO_TU_DONG_FB = re.compile(
    r"^hi\b[^!?]{0,60}[!,.]?\s*how can we help you\??$|đã trả lời một quảng cáo|replied to an ad", re.I)
# Tiếng ậm ừ — không trả lời câu nào, không từ chối gì: "hm", "hmmm", "uhm", "ah", "oh", "haha".
# Nút bấm của quảng cáo / Messenger — khách chưa nói gì (ca Rosalie "Start!" 14/09 tối): để sale/Botcake chào.
NUT_QUANG_CAO = re.compile(r"^\W*(get\s*started|bắt\s*đầu|start|menu|learn\s*more|send\s*message)\W*$", re.I)
TIN_AM_U = re.compile(r"^\W*(h+m+|u+h*m+|m+|a+h+|o+h+|e+h+|ha(?:ha)+|he(?:he)+|hi(?:hi)+|huh|k+)\W*$", re.I)
# TIN MẪU TỪ QUẢNG CÁO — chủ shop 14/09/2026: *"các từ howmuch, start, hmm,... từ bài quảng cáo bạn cứ treo lên
# để sale rep, b k phải rep"*. Khách bấm nút/câu gợi ý của quảng cáo, chưa nói gì riêng → không gọi model.
# Đo sổ chi phí 14/09 (8 nước): 188/852 lượt gọi model (~$1.11/$5.11) là đúng loại tin này. Chỉ khớp TRỌN
# câu (được thêm lời chào đầu + po/maam/sir cuối): "How much are the dentures?", "how much for 2 sets",
# "Magkano necklace", "how much delivery to abu dhabi" có nội dung riêng → AI vẫn trả lời như cũ.
TIN_MAU_QC = re.compile(
    r"^\W*(?:(?:hi+|hello+|hey+|salam|اهلين|اهلا|مرحبا|السلام\s*عليكم)\W+)?(?:"
    r"how\s*much|howmuch|how\s*mch|hw\s*much|hm+|h\.m|hmm+|how\s*much\s*(?:is\s*)?(?:it|this|the\s*price)"
    r"|how\s*much\s*(?:price|in\s+\w+(?:\s+\w+)?|saudi\s*riyals?|riyals?|dirhams?|aed|sar|kwd|qar|omr|bhd|usd|dollars?)"
    r"|price|prices|prce|prces|pric|prics|prise|prize|pirc|pirce|prcie|the\s*price|what(?:'?s|\s*is)\s*the\s*price"
    r"|(?:hm|how\s*much|magkano|mgkno|mgkano)\s*(?:po\s*)?(?:ang\s*)?(?:set|this|dis|it|nito|ito|ganyan)"
    r"|mag\s*ka+n[ou]|mag\s*kno|mg\s*ka?n[ou]|mgkno|pila|presyo|" + _MAGKANO_GO_SAI + r""
    r"|start|get\s*started|menu|get\s*offers?|info|details?|more\s*info|more\s*details?|tell\s*me\s*more"
    r"|(?:can\s*i\s*get|i\s*want|send\s*me)\s*more\s*(?:info|information|details?)"
    r"|(?:is\s*(?:this|it)\s*)?(?:still\s*)?available|i'?m\s*interested|interested|i\s*am\s*interested"
    r"|كم|بكم|كم\s*السعر|كم\s*سعره|السعر|سعر|سعره|كام|ممكن\s*تفاصيل|تفاصيل|দাম\s*কত|多少錢|多少|價格|价格|قیمت|قيمت"
    r")(?:\W+(?:po+h?|yan|iyan|yn|yung|ito|nito|dis|this|that|it|maam|ma'?am|mam|sir|dear|madam|please|pls|plz|bro|sis))*\W*$", re.I | re.U)


def page_vua_hoi(msgs, i):
    """Tin page (bot/sale/AI) gần nhất TRƯỚC tin khách thứ i có phải câu hỏi/câu chốt không.

    Chỉ tính câu page nói trong vòng 6 GIỜ trước tin khách. Ca Rosalie Opiana 14/09 tối (Kreain UAE): khách bấm
    "Start!" ở quảng cáo mới, hàm cũ lục ngược tới câu Botcake 26/07 "Do you have any other questions?" → coi là
    "đáp cụt sau câu hỏi của page" → AI rep. Chủ shop: *"để sale rep, b k phải rep, 'start' mà"*."""
    luc_kh = _giay_tu(msgs[i].get("luc")) if 0 <= i < len(msgs) else None
    for m in reversed(msgs[:i]):
        if m["boi"] == "khach":
            continue
        if luc_kh is not None and _giay_tu(m.get("luc")) - luc_kh > 6 * 3600:
            return False
        t = lam_sach(m.get("text") or "")
        if not t or (m["boi"] == "hethong" and CHAO_TU_DONG_FB.search(t)):
            continue
        return ("?" in t) or bool(re.search(
            r"\b(would you|do you|can i|may i|ready|order now|reserve|reservation|which|pwede|gusto|ba kayo|po ba)\b",
            t, re.I))
    return False


# 17/09: khách hỏi CÁCH ĐẶT HÀNG — "How to order", "paano po mag order", "how to buy". Chỉ 3 từ
# nên `_tin_co_noi_dung` cũ (ngưỡng ≥4 từ) trả False → rơi vào nhánh "Botcake rep gì cũng đủ" →
# AI im. Đo 17/09: 11 lượt "How to order" không được rep lần nào (Kreain Nature Aura Saudi,
# Clear Sight Optical Oman).
# + Urdu / Ả Rập (24/09, ca Mohammad Ejaz: "اس کے لینے کا طریقہ کار تو بتائیں" = cho biết cách lấy/mua nó). "طریقہ" trơn KHÔNG tính —
# "استعمال کا طریقہ" là cách DÙNG.
CACH_DAT = re.compile(r"\b(?:how|paano|pano|papaano)\b[^.!?]{0,20}\b(?:order|buy|avail|bili|bumili)\b"
                      r"|(?:لینے|لینا|منگوانے|منگوانا|خریدنے|خریدنا|آرڈر|ارڈر)\s*(?:کا|کے|کی)?\s*طریق"
                      r"|[آا]رڈر\s*کیسے|کیسے\s*(?:منگوا|خرید|[آا]رڈر|لے\s*سکت|ملے\s*گا)"
                      r"|كيف\s*(?:[أا]طلب|[أا]شتري|احصل\s*عليه)|طريقة\s*الطلب", re.I | re.U)


def _tin_co_noi_dung(t):
    """Tin khách có điều gì cần đáp RIÊNG không (câu hỏi, từ chối/chê, hỏi giá, số, câu dài)?
    Không có -> Botcake rep gì cũng đủ, AI khỏi đọc lại. Chỉ dùng ở nhánh Botcake ĐÃ rep."""
    t = str(t or "")
    if "?" in t or "؟" in t:
        return True
    if (_CAM_DO.search(t) or _cam_do_go_sai(t)) and not _khieu_nai_don_cu(t):
        return True                                  # CAM_DO_1CHU_2609: "Pawnable" — hỏi cầm đồ, Botcake chào chung không đủ
    if TU_CHOI.search(t) or HOI_GIA.search(t) or re.search(r"\bsorr?y\b", t, re.I):
        return True                                  # "Sorry 😐" sau lời chào hàng = từ chối mềm
    if re.search(r"\d{3,}", t):                       # SĐT / địa chỉ / số lượng
        return True
    # 17/09: ý định mua nói ngắn ("I need one", "Reserve this offer", "Order po ako", "I need it")
    # và câu hỏi cách đặt hàng đều dưới 4 từ nên trượt ngưỡng dưới. MUON_MUA đã bắt sẵn các cụm
    # này từ 14/09 (ca Remy), chỉ là hàm này chưa gọi tới. Thử trên 2.878 tin thật ngày 17/09:
    # thêm đúng 22 tin, không tin nào oan.
    if MUON_MUA.search(t) or CACH_DAT.search(t):
        return True
    if CG.ten_tieng_tron(t):
        return True                                  # khách xin đổi tiếng — Botcake rep tiếng cũ là chưa đủ
    if XIN_FEEDBACK.search(t):
        return True                                  # khách xin feedback — phải gửi ảnh, không bỏ qua
    return len(re.findall(r"\w+", t, re.U)) >= 4


# ĐỒNG Ý NGẮN — chủ shop 19/09, ca Cynthia Gabitan (Glamora Jewelry, Saudi): AI tư vấn "Garnet is your January
# birthstone… free shipping and cash on delivery" (không có câu hỏi), khách "OK" → tin 1 chữ → vo_nghia → treo;
# 4,5 phút sau sale Nguyễn Duyên phải tự gõ "Please add your delivery address and phone number". *"sao k rep tiếp"*.
# Khách xuôi theo lời tư vấn = lúc chốt, không phải tin rỗng. KHÔNG tính: "ok thanks" (từ chối mềm, nhánh níu),
# emoji/sticker trơn, "k"/"hm" (TIN_AM_U).
DONG_Y_NGAN = re.compile(
    r"^\W*(?:ok+(?:ay|ey|ie|i)?|oky|okey|kay|oo+|opo|oh?\s*sige|sige|yes+|yeah|yup|yep|ya|yah|yea|sure|alright"
    r"|all\s*right|fine|noted|got\s*it|tamam|تمام|طيب|ماشي|اوكي|أوكي|اوك|حسنا|نعم|ايوه|ايوا|أيوه|اكيد)"
    r"(?:\W+(?:po|dear|maam|ma'?am|mam|sir|madam|sis|bro|na|then|ok+|yes))*\W*$", re.I | re.U)

# Câu page nói chuyện ĐƠN ĐÃ CHỐT / GIAO HÀNG — khách "ok" sau câu này là đáp lễ, không phải lúc chốt.
DA_CHOT_DON = re.compile(
    r"\b(?:order|booking)\b[^.!?]{0,40}\b(?:confirmed|placed|created|received|booked|processed|registered)\b"
    r"|\byour\s+order\s+(?:is|number|no\b|#)|shipping\s+company|delivery\s+(?:team|service|staff|man)"
    r"|re-?deliver|تم\s+تأكيد|طلبك", re.I | re.U)


# OK_NHAC_2609 (chủ shop 26/09, ca Nirmala Tamang · Lapad Jewelry KSA in UAE — chọn "nhắc ngay 1 lần"): khách "Ok" sau câu AI xin
# SĐT + địa chỉ mà không gửi gì. Đo 3 ngày: 273 lần bị treo/im, chỉ 34% khách tự gửi SĐT trong 3 giờ.
OK_NHAC = "khách đáp đồng ý sau câu AI xin thông tin mà chưa gửi"


def khach_ok_sau_xin_tt(msgs, i=None):
    """Tin khách thứ i (mặc định: cuối) là ĐỒNG Ý NGẮN ngay sau câu AI XIN SĐT / địa chỉ (≤6h), khách chưa đưa SĐT, và từ tin có
    nội dung gần nhất của khách page mới xin thông tin ĐÚNG 1 lần → trả chữ khách, không thì None (nhắc 1 lần, không nhắc lần hai)."""
    msgs = msgs or []
    if i is None:
        i = next((k for k in range(len(msgs) - 1, -1, -1) if msgs[k].get("boi") == "khach"), None)
    if i is None or not (0 <= i < len(msgs)):
        return None
    j = i
    while j > 0 and msgs[j - 1].get("boi") in ("khach", "hethong"):
        j -= 1
    chuoi = [lam_sach(m.get("text") or "").strip() for m in msgs[j:i + 1] if m.get("boi") == "khach"]
    if not chuoi or not any(chuoi) or not all(not t or DONG_Y_NGAN.match(t) for t in chuoi):
        return None
    truoc = next((m for m in reversed(msgs[:j]) if m.get("boi") not in ("khach", "hethong")
                  and lam_sach(m.get("text") or "").strip()), None)
    if not truoc or truoc.get("boi") != "ai":
        return None
    luc_kh = _giay_tu(msgs[i].get("luc"))
    if luc_kh is not None and _giay_tu(truoc.get("luc")) - luc_kh > 6 * 3600:
        return None
    tt = lam_sach(truoc.get("text") or "")
    if not XIN_THONG_TIN.search(tt) or HOI_KET.search(tt) or DA_CHOT_DON.search(tt) or re.search(DON_CU, tt.lower()):
        return None
    if any(re.search(r"\d{7,}", re.sub(r"[\s\-]", "", m.get("text") or "")) for m in msgs[:i + 1] if m.get("boi") == "khach"):
        return None
    if any(m.get("boi") == "hethong" and re.search(r"\bspam\b|thư mục spam", m.get("text") or "", re.I)
           for m in msgs[max(0, i - 3):]):
        return None
    # nhắc 1 lần: đếm câu xin thông tin của page từ tin khách CÓ NỘI DUNG gần nhất (không phải ok/yes/rỗng)
    k = j - 1
    while k >= 0 and not (msgs[k].get("boi") == "khach" and lam_sach(msgs[k].get("text") or "").strip()
                          and not DONG_Y_NGAN.match(lam_sach(msgs[k].get("text") or "").strip())):
        k -= 1
    so_lan_xin = sum(1 for m in msgs[k + 1:j] if m.get("boi") in ("ai", "botcake", "nguoi")
                     and XIN_THONG_TIN.search(lam_sach(m.get("text") or "")))
    if so_lan_xin >= 2:
        return None
    return chuoi[-1] or next(t for t in chuoi if t)


def khach_dong_y_ngan(msgs, i=None):
    """Tin khách thứ i (mặc định: tin khách cuối) là lời ĐỒNG Ý NGẮN sau LỜI TƯ VẤN của page → trả chữ khách, không thì None.

    Đo 24 giờ 19/09 (173 page có token, 6 nước): 162 tin "ok/yes" một chữ bị treo, nhưng phần lớn KHÔNG phải lúc
    chốt — khách "Ok" sau câu SALE báo đơn/giao hàng ("Your order is 109 SAR… 2-5 days", "We will notify the
    shipping company…") hoặc khách rác "Oky" trong thư mục spam. Hỏi gói + xin địa chỉ ở đó là hỏng. Nên chỉ tính khi:
    câu page gần nhất (≤6 giờ) do AI hoặc Botcake nói (luồng bán; câu của sale thì sale tự theo), KHÔNG phải câu kết
    (HOI_KET — "ok" là chào), KHÔNG phải câu đã xin thông tin (khách "ok" = sắp gửi), KHÔNG nói chuyện đơn/giao hàng
    (DON_CU / DA_CHOT_DON), khách CHƯA đưa SĐT, hội thoại không bị Facebook đẩy vào spam."""
    msgs = msgs or []
    if i is None:
        i = next((k for k in range(len(msgs) - 1, -1, -1) if msgs[k].get("boi") == "khach"), None)
    if i is None or not (0 <= i < len(msgs)):
        return None
    t = lam_sach(msgs[i].get("text") or "").strip()
    if not t or not DONG_Y_NGAN.match(t):
        return None
    luc_kh = _giay_tu(msgs[i].get("luc"))
    truoc = None
    for m in reversed(msgs[:i]):
        if m.get("boi") in ("khach", "hethong"):
            continue
        if not lam_sach(m.get("text") or "").strip():
            continue                               # ảnh trơn của page — xét câu chữ trước nó
        truoc = m
        break
    if not truoc or truoc.get("boi") not in ("ai", "botcake") or (
            luc_kh is not None and _giay_tu(truoc.get("luc")) - luc_kh > 6 * 3600):
        return None
    tt = lam_sach(truoc.get("text") or "")
    if (HOI_KET.search(tt) or XIN_THONG_TIN.search(tt) or DA_CHOT_DON.search(tt)
            or re.search(DON_CU, tt.lower())):
        return None
    if any(m.get("boi") == "hethong" and re.search(r"\bspam\b|thư mục spam", m.get("text") or "", re.I)
           for m in msgs[max(0, i - 3):]):
        return None
    if any(re.search(r"\d{7,}", re.sub(r"[\s\-]", "", m.get("text") or ""))
           for m in msgs[:i + 1] if m.get("boi") == "khach"):
        return None
    return t


# 22/09 (chủ shop, ca Sheila Balacanta Ledesma · Healthy Figure PH in Saudi — *"sao cái này bạn rep lâu vậy"*): AI xin
# "contact number and complete address in Jeddah", 31 giây sau khách gửi MỖI SĐT "0586410525" → 1 chữ nên vo_nghia →
# TREO "không có gì để trả lời". AI lên đơn nháp #76214 nhưng KHÔNG xin địa chỉ; 4,5 phút sau page tự gõ "Please provide
# your address" thì AI mới đọc lại. Cùng tin SĐT trơn mà câu page trước là câu HỎI ("?", "may i…") thì `page_vua_hoi`
# cho qua (7 ngày Saudi 168 lượt, câu rep đúng kiểu "Noted your number 😊 Just need your complete address…"); câu page là
# lời DẶN ("Please send…") thì treo (7 ngày: Saudi 91, UAE 28 lượt — 80 lượt AI không rep lần nào, sale phải tự vào).
# SĐT / link Google Maps khách gửi là THÔNG TIN GIAO HÀNG: AI ghi nhận + xin phần còn thiếu, không treo. Câu page ngay
# trước nói chuyện ĐƠN ĐÃ CHỐT / giao hàng thì vẫn treo như cũ (mục 7.4).
MAPS_LINK = re.compile(r"maps\.app\.goo\.gl|goo\.gl/maps|google\.[a-z.]{2,8}/maps|maps\.google\.", re.I)
_SO_AR_SDT = str.maketrans("٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹", "01234567890123456789")
# Sale đang lo đơn ĐANG ĐI ĐƯỜNG — chỉ lấy mấy cụm chắc chắn là sau khi chốt. Cố ý KHÔNG dùng nguyên _SALE_XU_DON: mẫu
# xin thông tin của sale ("…for RESERVING: ✔️Delivery date: ✔️Your full name ✔️Contact number…", "To confirm your
# order…") dính "delivery date"/"your order" → giữ treo oan (đo 22/09: ca Sheila Chirii · Al Shifa Denture Saudi).
_DON_DANG_DI = re.compile(r"\bout\s+for\s+delivery\b|\btransit\b|\bwaiting\s+for\s+your\s+confirmation\b"
                          r"|\bstaff\s+contacted\b|\bkeep\s+your\s+phone\b|\bre-?schedul|شحنة|المندوب", re.I | re.U)


def khach_gui_sdt_vi_tri(chuoi):
    """Chuỗi tin khách chưa được đáp có SĐT (≥7 chữ số liền sau khi bỏ cách/gạch/chấm/ngoặc) hoặc link Google Maps."""
    for m in chuoi or []:
        t = lam_sach(m.get("text") or "").translate(_SO_AR_SDT)
        if re.search(r"\d{7,}", re.sub(r"[\s\-\.\(\)]", "", t)) or MAPS_LINK.search(t):
            return True
    return False


def page_noi_don_da_chot(msgs, j):
    """Câu chữ gần nhất phía page TRƯỚC tin khách thứ j có nói chuyện đơn đã chốt / giao hàng (mục 7.4) không.

    Câu AI/Botcake: chỉ tính lời báo đơn đã xác nhận (DA_CHOT_DON) — câu chào hàng có "courier will call you" /
    "delivery address" vẫn là lúc đang chốt. Câu SALE: tính thêm DON_CU + _DON_DANG_DI (sale xin số để giao đơn cũ)."""
    for m in reversed((msgs or [])[:max(0, j)]):
        if m.get("boi") not in ("botcake", "nguoi", "ai"):
            continue
        t = lam_sach(m.get("text") or "")
        if not t:
            continue
        if DA_CHOT_DON.search(t):
            return True
        return m.get("boi") == "nguoi" and bool(re.search(DON_CU, t.lower()) or _DON_DANG_DI.search(t))
    return False


# ── KHÁCH CHỈ CHÀO GIỮA CHỪNG (chủ shop 23/09: *"giống sale trang đang làm"*) ──
# Ca Joy Manduljao · Nature's Daily Care in Saudi: 22/09 AI đã hỏi tuổi + triệu chứng; sáng 23/09 khách bấm lại quảng cáo
# rồi nhắn "good morning Po madam" → vo_nghia → TREO, sale Trang tự gửi "helooo Joy Manduljao" rồi chép lại câu hỏi tuổi/
# triệu chứng. Chuỗi tin khách CHỈ là lời chào (± emoji/sticker) mà page ĐÃ từng nói chuyện thật với khách (tin AI / sale /
# Botcake có chữ) → AI làm như sale: chào lại bằng tên + hỏi tiếp câu page đang dở. Khách mới tinh (chưa có tin page nào
# ngoài câu chào tự động) vẫn như cũ; chuyện đơn đã chốt / đang giao (mục 7.4) vẫn treo cho sale.
CHAO_GIUA_CHUNG = "khách chỉ chào giữa lúc đang nói chuyện"


def _kh_chi_chao(ds_chu):
    """Các tin khách (chữ) toàn lời chào ngắn ± emoji/sticker, có ít nhất 1 lời chào → lời chào đầu tiên; không thì None."""
    chu = [lam_sach(x or "").strip() for x in (ds_chu or [])]
    chu = [t for t in chu if t]
    la_chao = lambda t: bool(re.match(CHAO, t.lower())) and len(t.split()) <= 5
    if not chu or not all(la_chao(t) or _chi_ky_hieu(t) for t in chu):
        return None
    return next((t for t in chu if la_chao(t)), None)


def khach_chao_giua_chung(msgs, dau, chuoi):
    """Lời chào nếu chuỗi tin khách chưa được đáp (`chuoi`, bắt đầu ở vị trí `dau`) CHỈ là lời chào, page đã từng nói
    chuyện với khách, và không đứng sau chuyện đơn đã chốt / giao hàng; không thì None."""
    chao = _kh_chi_chao([m.get("text") for m in (chuoi or [])])
    if not chao:
        return None
    if not any(m.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(m.get("text") or "").strip()
               for m in (msgs or [])[:max(0, dau)]):
        return None
    if page_noi_don_da_chot(msgs, dau):
        return None
    # Sale đang lo đơn / giao hàng trong 3 tin page gần nhất (đo kho cũ: "hi sir" sau câu sale "I checked the delivery
    # system…" — Zhiyang Herbal Care Qatar) → chuyện đơn cũ là việc của sale (mục 7.4), vẫn treo như cũ.
    _gan_ = [m for m in (msgs or [])[:max(0, dau)]
             if m.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(m.get("text") or "").strip()][-3:]
    if any(m.get("boi") == "nguoi" and _SALE_XU_DON.search(lam_sach(m.get("text") or "")) for m in _gan_):
        return None
    return chao


def cau_page_dang_do(msgs):
    """Câu hỏi gần nhất PHÍA PAGE (AI / sale / Botcake) — để khách chỉ chào thì hỏi tiếp đúng câu đó, kể cả khi nó nằm ở
    phiên cũ mà prompt đã lược (dau_phien). Bỏ câu chào mời chung kiểu 'How can we help you?'."""
    for m in reversed(msgs or []):
        if m.get("boi") not in ("ai", "nguoi", "botcake"):
            continue
        t = lam_sach(m.get("text") or "").strip()
        if t and re.search(r"[?؟？]", t) and not re.search(
                r"how can (?:we|i) help|can (?:we|i) help you|what would you like to know|anything else", t, re.I):
            # chỉ lấy CÂU HỎI (25/09, ca Emie Casarino: trả cả tin → AI chép lại lời xin lỗi "earrings only come with the set")
            _hoi = [c.strip() for c in re.split(r"(?<=[.!?؟？])\s+|\n+", t) if re.search(r"[?؟？]", c)]
            return " ".join(_hoi[-2:]) if _hoi else t
    return ""


# CÂU AI VỪA NÓI "PAGE KHÔNG CÓ REVIEW / BẰNG CHỨNG" (28/09, ca রঙিন কালো পৃথিবী · Hally Skincare PH in
# Saudi). Khách đòi review công khai, page không có; AI trả lời xong khách đòi nữa → model chỉ biết lặp lại
# đúng câu đó → cổng nhan_lap chặn → AI im. Nhận ra câu này thì lượt soạn lại được đưa cổng KHÁC (COD).
_KHONG_CO_BANG_CHUNG = re.compile(
    r"\b(?:don[\u2019']?t|do\s+not|dont|can[\u2019']?t|cannot|havent|haven[\u2019']?t|no)\b[^.!?\n]{0,40}"
    r"\b(?:public\s+|online\s+|customer\s+)?(?:reviews?|feedbacks?|testimonials?|proofs?|comments?)\b"
    r"|\bwala\b[^.!?\n]{0,30}\b(?:review|feedback|patunay|patotoo)\b"
    r"|\bhindi\b[^.!?\n]{0,30}\b(?:review|feedback|patunay)\b"
    r"|لا\s*(?:يوجد|توجد)[^.!?\n]{0,25}(?:تقييم|مراجع|دليل)", re.I | re.U)


# ── KHÁCH HỎI LẠI "CÁI GÌ?" (28/09, ca Fennish Mucaa Kaku · Glamora Jewelry Saudi: "Wat") ──
# Khách bấm "Order now", Botcake đòi tên/SĐT/địa chỉ, khách đáp "Wat" → 1 chữ nên vo_nghia → TREO.
# Đây KHÔNG phải tin trơ như "👍" hay sticker: khách đang KHÔNG HIỂU page vừa hỏi gì, và đang đứng
# ở bước đặt hàng. Việc của sale là nói lại cho gọn rồi hỏi lại, nên là việc của AI.
HOI_GI_VAY = "khách hỏi lại 'cái gì?'"

# NGUYÊN tin chỉ một tiếng "cái gì?" — không bắt câu dài (câu dài là câu hỏi thật, cửa khác lo).
_HOI_GI_VAY = re.compile(r"^(?:wh?[ae]?t+|wht|wt|wat+|huh+|sorry\s*\?+|pardon|come\s+again|"
                         r"an[o0](?:\s+(?:po|ba|yan|ito|iyan|yun))?|anong(?:\s+po)?|"
                         r"ap[ao](?:\s+(?:sih|itu|maksudnya))?|kya(?:\s+(?:hai|hua))?|"
                         r"ماذا|شنو|وش|ايش|شو)"
                         r"[\s!.?،؟]*$", re.I | re.U)


def khach_hoi_gi_vay(msgs, dau, chuoi):
    """Chữ khách gõ nếu chuỗi tin chưa được đáp (`chuoi`, bắt đầu ở vị trí `dau`) CHỈ là một tiếng
    "cái gì?" và page đã từng nói chuyện với khách; không thì None. Cùng bộ rào với
    `khach_chao_giua_chung`: đơn đã chốt / sale đang xử đơn thì vẫn để yên cho sale (mục 7.4)."""
    chu = [lam_sach(m.get("text") or "").strip() for m in (chuoi or [])]
    chu = [t for t in chu if t]
    if not chu or not all(_HOI_GI_VAY.match(t) or _chi_ky_hieu(t) for t in chu):
        return None
    hoi = next((t for t in chu if _HOI_GI_VAY.match(t)), None)
    if not hoi:
        return None
    # Page/Botcake phải đã nói gì đó — "what" ngay đầu hội thoại (chỉ mới có câu chào tự động của
    # hệ thống) là khách hỏi vu vơ, vẫn treo cho sale như cũ.
    if not any(m.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(m.get("text") or "").strip()
               for m in (msgs or [])[:max(0, dau)]):
        return None
    if page_noi_don_da_chot(msgs, dau):
        return None
    _gan_ = [m for m in (msgs or [])[:max(0, dau)]
             if m.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(m.get("text") or "").strip()][-3:]
    if any(m.get("boi") == "nguoi" and _SALE_XU_DON.search(lam_sach(m.get("text") or "")) for m in _gan_):
        return None
    return hoi


# CHON_PTTT_1CHU_2909 (ca Gia Khánh Cát · Madam Mystic Fengshui Expert USA 29/09): page hỏi "which payment method…
# Check / Cash App / Venmo / Zelle / PayPal", khách đáp "Check" 1 chữ → vo_nghia → TREO, AI không gửi mẫu /CHECK_ và không chốt.
# Tên phương thức ngay sau danh sách phương thức của page là CÂU TRẢ LỜI — cho vào vòng soạn, khối 9b lo gửi mẫu + chốt.
CHON_PTTT_NGAN = "khách chọn phương thức thanh toán bằng 1 chữ"


def khach_chon_pttt_ngan(msgs, dau, chuoi):
    """Tên phương thức khách chọn nếu chuỗi tin chưa đáp CHỈ là tên phương thức (± emoji) và trong 3 tin page gần nhất
    trước chuỗi có tin liệt kê ≥3 phương thức (AI / sale / Botcake đều tính); không thì None."""
    ten = None
    for m in (chuoi or []):
        t = lam_sach(m.get("text") or "").strip()
        if not t or _chi_ky_hieu(t):
            continue
        g = _pttt_trong_cau(t)
        if not g or len(t.split()) > 4:
            return None
        ten = ten or g[0]
    if not ten:
        return None
    _gan_ = [m for m in (msgs or [])[:max(0, dau)]
             if m.get("boi") in ("ai", "nguoi", "botcake") and lam_sach(m.get("text") or "").strip()][-3:]
    if not any(len({re.sub(r"\W", "", x.lower()) for x in R_PTTT_KHACH.findall(lam_sach(m.get("text") or ""))}) >= 3
               for m in _gan_):
        return None
    return ten


