#   · chưa rõ nước → AI "nha" xử và hỏi nước trước khi báo giá (đúng bước "Where are you currently living?" của page);
#   · AI đang xử thấy khách ở nước khác trong "nuoc" (khách nói tên nước/thành phố, SĐT mã nước, mẫu giá sale/AI vừa
#     gửi) → ghi sổ chủ rồi buông; AI nước kia nhận ở vòng dò kế. AI nước kia không chạy → giữ lại, luật cũ (treo);
#   · model chỉ thấy mẫu của ĐÚNG nước AI đang chạy + mẫu chung (tram_loc_kb) — hết cảnh ghép "Buy 1 Get 1 — 89 SAR" của
#     vòng tay với "Buy 2 Get 2 — 159 SAR" của dầu Batana (ca Akhlak Ahmad · Yuki Store 24/09 09:36 VN);
#   · chưa rõ nước thì KHÔNG lên nháp (nháp nằm nhầm shop); daemon quet_khong_tag cũng bỏ hội thoại chưa về nước nó.
_F_TRAM_CHU = os.path.join(SCRIPT_DIR, "state", "chung", "tram_landing_chu.json")
_TRAM_CFG = {"luc": 0.0, "cfg": {}}            # cấu hình page trạm, đọc lại ≤ 30s
_TRAM_SO = {"luc": 0.0, "d": {}}               # sổ chủ hội thoại, đọc lại ≤ 3s
_TRAM_SONG = {}                                # nước -> (lúc hỏi, AI nước đó đang chạy?)
_TRAM_LINK = {}                                # mkey -> (lúc, {link landing: nước}) học từ chủ đề các page trạm
# Nước của một mẫu theo TÊN CHỦ ĐỀ ("256 - Saudi", "242 uae", "confirm Kuwait", "235- Qatar").
_TRAM_CD_NUOC = (("saudi", r"saudi|\bksa\b"), ("uae", r"\buae\b|emirat"), ("qatar", r"qatar"), ("kuwait", r"kuwait"),
                 ("oman", r"\boman\b"), ("bahrain", r"bahrain"))
# Tiền tệ / câu giao hàng trong chữ mẫu hoặc tin page ("89 AED", "SAR 109", "Delivery in Saudi Arabia", "📍 Emirate:").
_TRAM_TIEN = (("saudi", r"\bsar\b|ريال\s*سعودي|delivery\s+in\s+saudi"),
              ("uae", r"\baed\b|درهم|delivery\s+in\s+(?:the\s+)?uae"),
              ("qatar", r"\bqar\b|ريال\s*قطري|delivery\s+in\s+qatar"),
              ("kuwait", r"\bkwd\b|دينار\s*كويتي|delivery\s+in\s+kuwait"),
              ("oman", r"\bomr\b|ريال\s*عماني|delivery\s+in\s+oman"),
              ("bahrain", r"\bbhd\b|دينار\s*بحريني|delivery\s+in\s+bahrain"),
              ("philippines", r"₱|(?<![a-z])php\b"), ("usa", r"(?<![a-z])\$\s*\d"), ("taiwan", r"nt\$|\btwd\b"))
_TRAM_TEN_VN = {"saudi": "Saudi", "uae": "UAE", "qatar": "Qatar", "kuwait": "Kuwait", "oman": "Oman", "bahrain": "Bahrain"}


def tram_cau_hinh():
    """{pid: {"nha": mkey, "nuoc": [mkey…], "ten": …}} — khoá "tram_landing" của page_gan_them.json."""
    now = time.time()
    if now - _TRAM_CFG["luc"] < 30:
        return _TRAM_CFG["cfg"]
    cfg = {}
    try:
        d = json.load(open(os.path.join(SCRIPT_DIR, "state", "chung", "page_gan_them.json"), encoding="utf-8"))
        for pid, v in (d.get("tram_landing") or {}).items():
            if isinstance(v, dict) and v.get("nha"):
                nuoc = [str(x) for x in (v.get("nuoc") or []) if x]
                if str(v["nha"]) not in nuoc:
                    nuoc.insert(0, str(v["nha"]))
                cfg[str(pid)] = {"nha": str(v["nha"]), "nuoc": nuoc, "ten": v.get("ten") or ""}
    except Exception:                                    # noqa: BLE001 — file đang ghi dở: giữ bản cũ
        cfg = _TRAM_CFG["cfg"]
    _TRAM_CFG.update(luc=now, cfg=cfg)
    return cfg


def tram_la(pid):
    try:
        return str(pid or "") in tram_cau_hinh()
    except Exception:                                    # noqa: BLE001
        return False


def tram_chu(cid):
    """Nước đang GIỮ hội thoại này theo sổ chủ; None = chưa AI nào nhận (AI nhà xử)."""
    now = time.time()
    if now - _TRAM_SO["luc"] > 3:
        try:
            _TRAM_SO["d"] = json.load(open(_F_TRAM_CHU, encoding="utf-8")) or {}
        except Exception:                                # noqa: BLE001 — chưa có file / đang ghi: giữ bản cũ
            pass
        _TRAM_SO["luc"] = now
    v = _TRAM_SO["d"].get(str(cid))
    return v.get("nuoc") if isinstance(v, dict) else None


def tram_ghi_chu(cid, nuoc, vi, boi):
    """Ghi nước giữ hội thoại — khoá file (6 AI + daemon cùng đọc), đọc-sửa-ghi, bỏ mục quá 14 ngày."""
    import fcntl
    os.makedirs(os.path.dirname(_F_TRAM_CHU), exist_ok=True)
    with open(_F_TRAM_CHU + ".lock", "a", encoding="utf-8") as lk:
        fcntl.flock(lk, fcntl.LOCK_EX)
        try:
            d = json.load(open(_F_TRAM_CHU, encoding="utf-8")) or {}
        except Exception:                                # noqa: BLE001
            d = {}
        now = time.time()
        d = {k: v for k, v in d.items() if isinstance(v, dict) and now - float(v.get("luc") or 0) < 14 * 86400}
        d[str(cid)] = {"nuoc": nuoc, "luc": now, "vi": str(vi or "")[:160], "boi": boi}
        tmp = f"{_F_TRAM_CHU}.{os.getpid()}.tmp"
        with open(tmp, "w", encoding="utf-8") as g:
            json.dump(d, g, ensure_ascii=False)
        os.replace(tmp, _F_TRAM_CHU)
    _TRAM_SO.update(luc=time.time(), d=d)


def _tram_ai_song(k):
    """AI nước k có đang chạy không (systemctl is-active, nhớ 60s). Không hỏi được → coi như KHÔNG chạy:
    thà AI nhà giữ lại rồi treo cho sale còn hơn giao cho một AI đã tắt (khách bị bỏ im)."""
    now = time.time()
    v = _TRAM_SONG.get(k)
    if v and now - v[0] < 60:
        return v[1]
    unit = "aisale-chat" if k == "uae" else f"aisale-chat-{k}"
    try:
        import subprocess
        r = subprocess.run(["systemctl", "is-active", unit], capture_output=True, text=True, timeout=5)
        ok = r.stdout.strip() == "active"
    except Exception:                                    # noqa: BLE001
        ok = False
    _TRAM_SONG[k] = (now, ok)
    return ok


def tram_bo_qua(pid, cid, mkey):
    """AI <mkey> KHÔNG đụng hội thoại này: page trạm mà hội thoại thuộc AI nước khác, hoặc chưa ai nhận mà mình không
    phải AI nhà. AI nhà nhận lại hội thoại của một AI nước đã tắt (khách không bị bỏ im)."""
    try:
        cfg = tram_cau_hinh().get(str(pid))
        if not cfg:
            return False
        chu = tram_chu(cid)
        if not chu or chu == mkey:
            return bool(chu != mkey and cfg["nha"] != mkey)
        return not (cfg["nha"] == mkey and not _tram_ai_song(chu))
    except Exception:                                    # noqa: BLE001 — cửa hỏng thì đi đường cũ
        return False


_TRAM_DA_NHAN = set()                          # (cid, lúc giao) mình đã nhận — mỗi lần giao xét lại MỘT lần


def tram_moi_nhan(cid, mkey):
    """Hội thoại vừa được AI nước KHÁC giao cho mình (sổ chủ ghi nước mình, người ghi là nước khác) → True đúng MỘT lần:
    vòng dò phải xét lại dù danh sách chưa đổi (lúc AI kia buông, khách không nhắn gì thêm)."""
    try:
        if tram_chu(cid) != mkey:
            return False
        v = _TRAM_SO["d"].get(str(cid)) or {}
        if v.get("boi") == mkey:
            return False
        k = (str(cid), v.get("luc"))
        if k in _TRAM_DA_NHAN:
            return False
        _TRAM_DA_NHAN.add(k)
        return True
    except Exception:                                    # noqa: BLE001
        return False


def _tram_nuoc_cau(t):
    """Nước trạm (Vịnh) khách nhắc trong câu — đúng MỘT nước; tên hàng ("Saudi gold") và người nhà ở đó thì bỏ."""
    t = _TEN_HANG_NUOC.sub(" ", lam_sach(t or ""))
    if not t.strip() or _NGUOI_KHAC_O.search(t):
        return None
    ra = {k for k in _TRAM_TEN_VN
          if (NUOC_TP.get(k) and re.search(NUOC_TP[k], t, re.I | re.U))
          or (TEN_NUOC_BAN_DIA.get(k) and re.search(TEN_NUOC_BAN_DIA[k], t, re.I | re.U))}
    return ra.pop() if len(ra) == 1 else None


def _tram_nuoc_sdt(t):
    """Nước theo SĐT khách gõ: mã nước (+971/966/974/965/968/973) hoặc đầu số chỉ một nước có (053/057/059 Saudi, 052 UAE).
    05x còn lại dùng chung Saudi–UAE, số 8 chữ số dùng chung Qatar–Kuwait–Oman–Bahrain → không kết luận."""
    for m in HS.R_SDT_CHUNG.finditer(HS.so_latin(t or "")):
        so = re.sub(r"[\s.\-()]", "", m.group(1))
        tho = re.sub(r"^(?:\+|00)", "", so)
        for k, ma, n in (("uae", "971", 9), ("saudi", "966", 9), ("qatar", "974", 8), ("kuwait", "965", 8),
                         ("oman", "968", 8), ("bahrain", "973", 8)):
            if tho.startswith(ma) and len(tho) - len(ma) in (n, n + 1) and (so != tho or len(tho) >= 11):
                return k
        if re.fullmatch(r"05[379]\d{7}", tho):
            return "saudi"
        if re.fullmatch(r"052\d{7}", tho):
            return "uae"
    return None


def _tram_nuoc_chu(t):
    """Nước theo tiền tệ / câu giao hàng trong một đoạn chữ của page — đúng MỘT nước."""
    ra = {k for k, rx in _TRAM_TIEN if re.search(rx, t or "", re.I | re.U)}
    return ra.pop() if len(ra) == 1 else None


def tram_nuoc_khach(msgs, pid=None, cid=None):
    """(nước, căn cứ) của khách ở page trạm; (None, "") nếu chưa rõ.
    Ưu tiên: lời khách MỚI NHẤT nhắc tên nước/thành phố > tiền tệ khách gõ > SĐT khách gõ > mẫu giá SALE/AI đã gửi (Botcake không tính:
    bot bắn mẫu cho mọi khách, không biết khách ở đâu)."""
    khach = [m for m in (msgs or []) if m.get("boi") == "khach" and (m.get("text") or "").strip()]
    for m in reversed(khach[-8:]):
        k = _tram_nuoc_cau(m["text"])
        if k:
            return k, f'khách nói "{m["text"][:60]}"'
    ng = nguon_khach(cid) if cid else None      # NGUON_KHACH_2409 — mã landing / nút tư vấn mang sẵn nước
    if ng and ng.get("nuoc") in _TRAM_TEN_VN and ng.get("loai") in ("landing", "tuvan"):
        return ng["nuoc"], f'khách vào từ landing {_TRAM_TEN_VN[ng["nuoc"]]} ({str(ng.get("sp") or "")[:40]})'
    for m in reversed(khach[-8:]):
        k = _tram_nuoc_chu(m["text"])
        if k in _TRAM_TEN_VN:
            return k, f'khách nói tiền {_TRAM_TEN_VN[k]}: "{m["text"][:50]}"'
    for m in reversed(khach[-12:]):
        k = _tram_nuoc_sdt(m["text"])
        if k:
            return k, f"SĐT khách gõ là số {_TRAM_TEN_VN.get(k, k)}"
    ng_qc_ = nguon_khach(cid) if cid else None       # SP_KHACH_2509 — bài QC khách bấm ghi giá tiền nước nào
    if ng_qc_ and ng_qc_.get("loai") == "qc" and ng_qc_.get("noi_dung"):
        k = _tram_nuoc_chu(ng_qc_["noi_dung"])
        if k in _TRAM_TEN_VN:
            return k, f"bài quảng cáo khách bấm ghi giá / giao theo {_TRAM_TEN_VN[k]}"
    for m in reversed([x for x in (msgs or []) if x.get("boi") in ("ai", "nguoi") and (x.get("text") or "").strip()][-10:]):
        k = _tram_nuoc_chu(m["text"])
        if k in _TRAM_TEN_VN:
            return k, f'page đã báo giá/giao theo {_TRAM_TEN_VN[k]}: "{m["text"][:50]}"'
    return None, ""


def _tram_chu_mau(m):
    return " ".join(m.get("tin") or []) if isinstance(m.get("tin"), list) else str(m.get("tin") or "")


def _tram_links(t):
    return set(re.findall(r"https?://[^\s{}<>\"']+", t or ""))


def _tram_nuoc_mau(m, ten_cd, link_nuoc):
    """Nước của MỘT mẫu: tên chủ đề > link landing đã biết nước (học từ chủ đề page trạm khác) > tiền tệ trong chữ.
    None = mẫu chung (chào, xin thông tin, WhatsApp, hỏi nước…)."""
    ra = {k for k, rx in _TRAM_CD_NUOC if re.search(rx, ten_cd or "", re.I)}
    if len(ra) == 1:
        return ra.pop()
    chu = _tram_chu_mau(m)
    ln = {link_nuoc[x] for x in _tram_links(chu) if x in link_nuoc}
    if len(ln) == 1:
        return ln.pop()
    return _tram_nuoc_chu(chu)


def _tram_link_nuoc(mkey):
    """{link landing: nước} học từ các page trạm có chủ đề ghi tên nước (Guzela không có chủ đề → mượn)."""
    v = _TRAM_LINK.get(mkey)
    if v and time.time() - v[0] < 300:
        return v[1]
    ra, xung = {}, set()
    for p, cfg in tram_cau_hinh().items():
        kb = None
        try:
            kb = _kb_page(mkey, p) or _kb_page(cfg["nha"], p)
        except BaseException:                            # noqa: BLE001 — nap_kich_ban sys.exit khi thiếu file
            kb = None
        cd = {str(x.get("id")): x.get("ten") or "" for x in ((kb or {}).get("chu_de") or []) if isinstance(x, dict)}
        for m in (kb or {}).get("mau") or []:
            ten = cd.get(str(m.get("chu_de_id")), "")
            nuoc = {k for k, rx in _TRAM_CD_NUOC if re.search(rx, ten, re.I)}
            if len(nuoc) != 1:
                continue
            k = nuoc.pop()
            for ln in _tram_links(_tram_chu_mau(m)):
                if ra.get(ln, k) != k:
                    xung.add(ln)
                ra[ln] = k
    ra = {k: v for k, v in ra.items() if k not in xung}
    _TRAM_LINK[mkey] = (time.time(), ra)
    return ra


def tram_loc_kb(kb, pid, mkey):
    """Kịch bản page trạm chỉ còn mẫu của nước <mkey> + mẫu chung. Thiếu kịch bản ở nước mình → mượn bản nước nhà.
    Lọc hỏng → trả nguyên kịch bản (đường cũ)."""
    try:
        return _tram_loc_kb(kb, pid, mkey)
    except Exception as e:                               # noqa: BLE001
        print(f"  ⚠️  trạm landing: lọc kịch bản hỏng ({e!r}) — dùng nguyên kịch bản", flush=True)
        return kb


def _tram_loc_kb(kb, pid, mkey):
    cfg = tram_cau_hinh().get(str(pid)) or {}
    if not (kb or {}).get("mau") and cfg.get("nha") and cfg["nha"] != mkey:
        try:
            kb = nap_kich_ban(cfg["nha"], pid)
        except BaseException:                            # noqa: BLE001
            kb = None
    if not (kb or {}).get("mau"):
        return kb
    cd = {str(x.get("id")): x.get("ten") or "" for x in (kb.get("chu_de") or []) if isinstance(x, dict)}
    ln = _tram_link_nuoc(mkey)
    giu = [m for m in kb["mau"] if _tram_nuoc_mau(m, cd.get(str(m.get("chu_de_id")), ""), ln) in (None, mkey)]
    return dict(kb, mau=giu, tram_bo=len(kb["mau"]) - len(giu))


def tram_chi_mau_chung(kb):
    """Chưa rõ khách ở nước nào (AI nhà xử): chỉ đưa model MẪU CHUNG — không mẫu giá, không link nước nào. Đo 24/09 với
    model thật: có mẫu SAR là model báo giá SAR luôn dù được dặn hỏi nước trước. Hỏng → trả nguyên."""
    try:
        if not (kb or {}).get("mau"):
            return kb
        cd = {str(x.get("id")): x.get("ten") or "" for x in (kb.get("chu_de") or []) if isinstance(x, dict)}
        ln = {}
        for v in _TRAM_LINK.values():
            ln.update(v[1])
        giu = [m for m in kb["mau"] if _tram_nuoc_mau(m, cd.get(str(m.get("chu_de_id")), ""), ln) is None
               and not CG.tien_trong(CG.bo_chu_toan(_tram_chu_mau(m)))]
        return dict(kb, mau=giu, tram_chung=True) if giu else kb
    except Exception:                                    # noqa: BLE001
        return kb


_TRAM_TU_CHUNG = {"thank", "thanks", "your", "interest", "with", "this", "that", "from", "ours", "free", "shipping",
                  "offer", "limited", "only", "best", "value", "special", "clearance", "sale", "just", "days", "hair",
                  "daily", "every", "more", "look", "order", "form", "each", "into", "have", "will", "near"}


def _tram_tu_sp(chu):
    """Từ khoá TÊN SẢN PHẨM của một mẫu giá = dòng đầu (tiêu đề) — chữ ≥4, bỏ chữ chung."""
    dong = next((x for x in (chu or "").splitlines() if re.search(r"[A-Za-z]{4,}", x)), "")
    return {w for w in re.findall(r"[a-z]{4,}", lam_sach(dong).lower()) if w not in _TRAM_TU_CHUNG}


def _tram_cung_tu(a, b):
    """TRAM_DON_2709 — cùng MỘT chữ: bằng nhau, hoặc chữ ngắn (≥4, hoặc thêm đúng 's') là đầu chữ dài và dài hơn ≤3 ký tự
    (lift/lifting, glass/glasses, bag/bags). "face" KHÔNG khớp "facelift" (ca Lalaine 26/09)."""
    if a == b:
        return True
    n, d = sorted((a, b), key=len)
    return (len(n) >= 4 or d == n + "s") and d.startswith(n) and len(d) - len(n) <= 3


def tram_kiem_gia(tin, msgs, kb, pid, mkey, cid=None):
    """Cổng giá ở page trạm. None = cho qua; ("hoi_nuoc", câu) = chưa rõ nước mà AI nhà báo giá → thay bằng câu hỏi nước
    của page; ("treo", lý do) = giá không nằm trọn trong MỘT mẫu giá (ghép gói SP khác — ca Akhlak 24/09: 89 SAR vòng tay
    + 159 SAR Batana) hoặc là giá của mẫu SP mà cả hội thoại lẫn câu AI không nhắc tới (ca "eye cream" lấy giá dầu nở
    ngực, thử model 24/09)."""
    so = set(CG.tien_trong(CG.bo_chu_toan(tin or "")))
    if not so:
        return None
    cfg = tram_cau_hinh().get(str(pid)) or {}
    nuoc, _ = tram_nuoc_khach(msgs, pid, cid)
    if not nuoc and cfg.get("nha") == mkey:
        cau = next((t for m in (kb or {}).get("mau") or [] for t in (m.get("tin") or [])
                    if "currently living" in (t or "").lower()), None)
        return "hoi_nuoc", (cau or "Where are you currently living? 😊\n- Qatar\n- UAE\n- Kuwait\n- Saudi")
    ung = [c for c in (_tram_chu_mau(m) for m in (kb or {}).get("mau") or [])
           if so <= set(CG.tien_trong(CG.bo_chu_toan(c)))]
    if not ung:
        return "treo", f"AI báo giá {sorted(so)} không nằm trọn trong mẫu giá nào của page (ghép gói SP khác / tự đặt giá)"
    ctx = lam_sach((tin or "") + " " + " ".join(m.get("text") or "" for m in (msgs or [])[-12:])).lower()
    ng_ = nguon_khach(cid) if cid else None      # NGUON_KHACH_2409 — SP khách đến từ landing / nút tư vấn / QC
    if ng_:
        ctx += " " + lam_sach(str(ng_.get("sp") or "") + " " + str(ng_.get("tieu_de") or "") + " "
                            + str(ng_.get("noi_dung") or "")).lower()      # SP_KHACH_2509 — + chữ bài QC
        ma_ng_ = set(re.findall(r"(?<!\d)\d{3}(?!\d)", str(ng_.get("sp") or "") + " " + str(ng_.get("ma_sp") or "")))
        cd_ = {str(x.get("id")): str(x.get("ten") or "") for x in ((kb or {}).get("chu_de") or []) if isinstance(x, dict)}
        for m_ in (kb or {}).get("mau") or []:
            if (ma_ng_ & set(re.findall(r"(?<!\d)\d{3}(?!\d)", cd_.get(str(m_.get("chu_de_id")), "")))
                    and so <= set(CG.tien_trong(CG.bo_chu_toan(_tram_chu_mau(m_))))):
                return None
    tu_ctx_ = set(re.findall(r"[a-z]{3,}", ctx))     # TRAM_DON_2709 — khớp NGUYÊN CHỮ, không khớp khúc chữ
    for c in ung:
        kw = _tram_tu_sp(c)
        if not kw or any(_tram_cung_tu(w, x) for w in kw for x in tu_ctx_):
            return None
    ten = next((x.strip() for x in ung[0].splitlines() if x.strip()), "")[:60]
    return "treo", f"AI báo giá của mẫu «{ten}» mà khách/AI không nói tới sản phẩm đó"


def dong_tram_landing(rec):
    """Khối dặn model ở page trạm landing (đưa vào khoi_ho_so của goi_soan). Hỏng → chuỗi rỗng."""
    try:
        return _dong_tram_landing(rec)
    except Exception:                                    # noqa: BLE001
        return ""


def _dong_tram_landing(rec):
    mkey = rec.get("thi_truong")
    ten = _TRAM_TEN_VN.get(mkey, str(mkey).upper())
    nuoc, vi = tram_nuoc_khach(rec.get("msgs"), rec.get("pid"), rec.get("conv"))
    if nuoc == mkey:
        dau = f"Khách đang ở {ten} ({vi}) → chỉ tư vấn / báo giá theo mẫu {ten} dưới đây."
    else:
        dau = (f"CHƯA RÕ khách ở nước nào. Page bán cho Saudi / UAE / Qatar / Kuwait, mỗi nước giá khác nhau. Khách hỏi giá "
               f"hoặc muốn đặt mà chưa nói nước → hỏi nước TRƯỚC, đúng câu mẫu \"Where are you currently living? 😊 Qatar / "
               f"UAE / Kuwait / Saudi\" (dịch sang tiếng khách), CHƯA báo giá, CHƯA xin SĐT/địa chỉ. Khách đã nói rõ ở {ten} "
               f"thì mới dùng mẫu {ten} dưới đây.")
    loc = (f"Kịch bản đưa bạn ĐÃ LỌC chỉ còn mẫu {ten} + mẫu chung." if nuoc == mkey else
           "Kịch bản đưa bạn chỉ còn MẪU CHUNG (chưa có mẫu giá nào) vì chưa rõ khách ở nước nào.")
    _ds_sp_ = tram_ds_sp(rec.get("pid"), mkey)      # SP_KHACH_2509 — SP page có mẫu (mọi nước, không giá)
    _ds_sp_dong = ("SẢN PHẨM PAGE NÀY CÓ MẪU (mọi nước; mã: tên): " + " · ".join(_ds_sp_) + "\n") if _ds_sp_ else ""
    return ("🧭 PAGE TRẠM LANDING — page này gom NHIỀU sản phẩm cho khách ở NHIỀU nước; khách thường vừa xem / vừa đặt trên "
            f"landing rồi bấm sang Messenger. {loc} {dau}\n"
            f"{_ds_sp_dong}"
            "1. Khách CHƯA gửi ảnh, CHƯA nói tên sản phẩm, CHƯA vào từ quảng cáo / landing có sản phẩm → hỏi tên sản phẩm "
            "hoặc xin ảnh. Khách ĐÃ gửi ảnh sản phẩm (dòng [ẢNH KHÁCH GỬI …]) / đã nói tên / 📍 NGUỒN KHÁCH có sản phẩm → "
            "CẤM hỏi lại 'sản phẩm nào / gửi ảnh': gọi đúng tên sản phẩm đó rồi làm tiếp.\n"
            "2. Giá / gói / số lượng CHỈ lấy NGUYÊN từ mẫu của ĐÚNG sản phẩm khách hỏi. CẤM ghép gói hay giá của sản phẩm "
            "khác, cấm tự đặt giá, cấm đổi tiền tệ.\n"
            "3. Sản phẩm khách hỏi không có mẫu giá mà có link landing → gửi đúng câu mẫu kèm link đó. Sản phẩm KHÔNG có "
            "trong danh sách SẢN PHẨM PAGE NÀY CÓ MẪU (vd khách gửi ảnh món khác) → hanh_dong \"tra_loi_treo\": 1-2 câu "
            "gọi đúng tên sản phẩm khách gửi (chưa rõ nước thì hỏi thêm khách đang ở nước nào), KHÔNG báo giá, KHÔNG hứa "
            "kiểm tra rồi báo lại; ghi_chu \"MKT bổ sung kịch bản mã <mã SP; không biết thì ?> để tư vấn khách — "
            "SP khách hỏi: <tên> (" + ten + ")\". CẤM nói shop không bán / không có món đó (khách thấy nó trên "   # SP_KHACH_2509C
            "quảng cáo của mình).\n"
            "4. Khách vừa đặt trên landing (tin page \"Thank you for your order\", khách nói đã đặt / đã điền form) → đơn "
            "ĐÃ CÓ: cảm ơn, trả lời đúng câu khách hỏi (thời gian giao theo mẫu confirm), KHÔNG xin lại thông tin, KHÔNG "
            "chốt đơn mới, KHÔNG nói đơn đã gửi / đang trên đường (chưa biết trạng thái). Khách muốn đổi / thêm / hủy → "
            "hanh_dong \"treo\" cho sale.")


# ══ SẢN PHẨM KHÁCH ĐANG HỎI — thẻ quảng cáo + ảnh khách + danh sách SP page trạm (SP_KHACH_2509) ══════════════════════
# Chủ shop 25/09: (1) ảnh Josephine Lanaza · Cosmetics YukiSmart *"như này là bạn biết khách muốn tư vấn sản phẩm nào rồi phải k"*
# — Pancake gửi THẺ QUẢNG CÁO ở tin đầu: tin page rỗng "<div></div>" + đính kèm {"type": "ad_click", "ad_id", "post_attachments":
# [{"description": <nguyên văn bài QC>, "url": <ảnh>}]}; AI chỉ thấy tin rỗng. (2) ảnh Mamath Luffi · Guzela 01:38 VN *"khách gửi
# ảnh sp rồi mà"* — máy ĐÃ đọc ảnh ("Facebook screenshot showing an Aliceva white perfume toothpaste ad…") nhưng khách chưa nói nước
# → model chỉ thấy mẫu chung (có câu chào "Which product… send me the product name or a photo") → hỏi lại SP. Kem Aliceva KHÔNG có
# trong kịch bản Guzela. Vá: đọc chữ thẻ QC vào nguồn khách; lời dặn trạm kèm DANH SÁCH SP page có (mọi nước, không giá) + luật
# "khách đã cho SP thì không hỏi lại; SP ngoài danh sách → tra_loi_treo"; cổng máy bắt câu hỏi lại SP → sửa nhẹ, hỏng thì treo.
_R_HOI_LAI_SP = re.compile(
    r"which (?:product|item|one are you)|what (?:product|item)|product name|name of the product"
    r"|send (?:me |us )?(?:a |the )?(?:photo|picture|pic|screenshot|product name)|photo of the product"
    r"|(?:anong|aling|ano pong|anu pong) (?:produkto|product|item)", re.I | re.U)
_ANH_SP = re.compile(
    r"\bads?\b|advert|product|bottle|jar|tube|cream|serum|\boil\b|perfume|toothpaste|soap|\bgel\b|lotion|spray|bracelet"
    r"|necklace|\bring\b|earring|glasses|wallet|charm|patch|brush|\bbag\b|package|\bbox\b|supplement|capsule|shop now|buy now"
    r"|% ?off|\bprice\b|packaging|pouch", re.I)
_TRAM_DS_SP = {}                               # (nước nhà, pid) -> (lúc, [dòng "mã: tên"])


def the_qc_tu_tin(res):
    """Chữ bài quảng cáo từ THẺ QC trong gói tin (tin page đính kèm type ad_click / post_attachments). None nếu không có."""
    for m in sorted((res or {}).get("messages") or [], key=lambda m: m.get("inserted_at") or ""):
        for a in m.get("attachments") or []:
            if not isinstance(a, dict) or not (a.get("post_attachments") or a.get("type") == "ad_click"):
                continue
            pa = [x for x in (a.get("post_attachments") or []) if isinstance(x, dict)]
            # SP_KHACH_2509B — thẻ BÌNH LUẬN (khách bình luận bài, Botcake nhắn riêng; ca Fatma RF · Cozy Home 25/09 "Really"
            # dưới bài nhẫn 251): NỘI DUNG BÀI nằm ở `name`, post_attachments chỉ có tiêu đề video; câu khách ở `comment.content`.
            chu = " ".join([str(a.get("name") or "")]
                           + [str(x.get("description") or x.get("title") or x.get("name") or "") for x in pa])
            chu = lam_sach(unicodedata.normalize("NFKC", chu))
            bl_ = a.get("comment") if isinstance(a.get("comment"), dict) else {}
            if chu:
                return {"ad_id": str(a.get("ad_id") or ""), "noi_dung": chu[:600], "luc": m.get("inserted_at"),
                        "anh": next((x.get("url") for x in pa if x.get("url")), None),
                        "binh_luan": lam_sach(unicodedata.normalize("NFKC", str(bl_.get("content") or "")))[:200]}
    return None


def _tram_ten_tieu_de(chu):
    """Tên SP từ dòng tiêu đề mẫu giá ("👓 COLOR CHANGING … GLASSES", "Hi! ❤️ Thank you for your interest in our Face Lifting Brush.")."""
    dong = next((x for x in (chu or "").splitlines() if re.search(r"[A-Za-z]{4,}", x)), "")
    dong = unicodedata.normalize("NFKC", dong)
    dong = re.sub(r"(?i)^\W*(?:hi|hello)\b\W*", "", dong)
    dong = re.sub(r"(?i)thank you for your interest in (?:our )?", "", dong)
    dong = re.sub(r"[^\w\s&'’/-]", " ", dong)
    return re.sub(r"\s+", " ", dong).strip(" .-")[:70]


def _tram_ten_slug(ln):
    """Tên SP từ link landing: …/xn--gods-word-scripture-bracelet-s-wy8r → "god’s word scripture bracelet"."""
    slug = str(ln or "").rstrip("/}").split("/")[-1]
    if slug.startswith("xn--"):
        try:
            slug = slug[4:].encode("ascii").decode("punycode")
        except Exception:                                # noqa: BLE001
            slug = slug[4:]
    for _ in range(3):
        slug = re.sub(r"(?i)(?:-(?:s|q|\d)|uaemay|saudimay|kuwaitmay|qatarmay|may|v\d+)$", "", slug)
    return re.sub(r"[-_]+", " ", slug).strip()


def tram_ds_sp(pid, mkey=None):
    """["mã: tên / tên", …] các SẢN PHẨM page trạm có mẫu (mọi nước, KHÔNG giá) — kịch bản nước nhà, nhớ 5 phút. Hỏng → []."""
    try:
        cfg = tram_cau_hinh().get(str(pid)) or {}
        nha = cfg.get("nha") or mkey
        k = (nha, str(pid))
        v = _TRAM_DS_SP.get(k)
        if v and time.time() - v[0] < 300:
            return v[1]
        kb = _kb_page(nha, pid) or (_kb_page(mkey, pid) if mkey else None)
        cd = {str(x.get("id")): str(x.get("ten") or "") for x in ((kb or {}).get("chu_de") or []) if isinstance(x, dict)}
        theo_ma, rieng = {}, []
        for m in (kb or {}).get("mau") or []:
            chu = _tram_chu_mau(m)
            nuoc_ = _tram_nuoc_chu(chu)
            if nuoc_ and nuoc_ not in _TRAM_TEN_VN:
                continue                                 # mẫu giá nước shop không bán (₱ cũ của Guzela)
            if CG.tien_trong(CG.bo_chu_toan(chu)):
                ten = _tram_ten_tieu_de(chu)
            else:
                lk = sorted(_tram_links(chu))
                ten = _tram_ten_slug(lk[0]) if lk else ""
            if len(re.sub(r"\W", "", ten)) < 4:
                continue
            ma = (re.findall(r"(?<!\d)(\d{3})(?!\d)", cd.get(str(m.get("chu_de_id")), "")) or [""])[0]
            ds = theo_ma.setdefault(ma, []) if ma else rieng
            if ten.lower() not in [x.lower() for x in ds]:
                ds.append(ten)
        ra = [f"{ma}: {' / '.join(ts)}" for ma, ts in sorted(theo_ma.items())] + rieng
        _TRAM_DS_SP[k] = (time.time(), ra)
        return ra
    except Exception:                                    # noqa: BLE001
        return []


def tram_sp_khach_da_cho(msgs, cid=None):
    """Khách đã cho biết SẢN PHẨM chưa: ảnh khách gửi mà máy đọc ra hàng hoá / quảng cáo · thẻ QC có chữ · mã landing có SP.
    Trả câu mô tả (tiếng Anh, đưa thẳng vào lệnh sửa nhẹ) hoặc None."""
    for m in reversed([x for x in (msgs or []) if x.get("boi") == "khach"][-6:]):
        if m.get("mo_ta") and _ANH_SP.search(m["mo_ta"]):
            return "their photo shows: " + m["mo_ta"][:220]
    ng = nguon_khach(cid) if cid else None
    if ng and ng.get("loai") == "qc" and ng.get("noi_dung"):
        return "they came from this ad: " + ng["noi_dung"][:220]
    if ng and ng.get("loai") in ("landing", "tuvan") and ng.get("sp"):
        return "they came from the landing page of: " + str(ng["sp"])[:120]
    return None


# ══ SP CHƯA CÓ KỊCH BẢN → "MKT bổ sung kịch bản mã …" (SP_KHACH_2509C) ═══════════════════════════════════════════════
# Chủ shop 25/09 (sau ca Fatma RF · Cozy Home — khách hỏi mã 251, không page trạm nào có mẫu 251): *"cái nào k có kịch bản,
# bạn note là MKT bổ sung kịch bản mã ... để tư vấn khách"*. Page trạm: AI giao sale vì SP khách hỏi KHÔNG có mẫu (luật 3 khối
# trạm, cổng giá, cổng hỏi lại SP) → ghi chú MỞ ĐẦU đúng câu "MKT bổ sung kịch bản mã <mã> để tư vấn khách". Mã tra trong catalog
# POS (state/<nước>/catalog.json, mã = số đầu tên SP, dùng chung các shop): mã nguồn khách (nút tư vấn / landing / tên QC) > mã
# model ghi > tên SP khớp chữ (ghi chú model + ảnh khách > bài QC / landing > lời khách). Không chắc → "mã ?" + tên SP khách
# hỏi. SP ĐÃ có mẫu ở nước khách (AI ghép giá / nói sai) → giữ ghi chú cũ, không bắt MKT làm việc thừa.
CAU_MKT = "MKT bổ sung kịch bản mã {ma} để tư vấn khách"
_R_THIEU_KB = re.compile(
    r"chưa có (?:mẫu|giá|kịch bản)|kịch bản(?: page)? (?:chưa|không) có|không có (?:trong )?(?:mẫu|kịch bản|danh sách)"
    r"|thiếu (?:mẫu|kịch bản)(?! thì)|ngoài (?:danh sách|kịch bản)|MKT bổ sung", re.I | re.U)
_R_MA_MKT = re.compile(r"(?i)\bmã\s*(?:sp\s*)?(\d{3})(?!\d)")
_TU_BO_SP = {"the", "and", "for", "with", "you", "your", "our", "this", "that", "from", "new", "pro", "plus", "pcs", "set",
             "item", "product", "free", "gift", "combo", "pack", "box", "size", "type", "style", "color", "colour", "version"}
_CATALOG_TRAM = {}                             # nước -> (lúc, [(mã, tên, {từ})])


def _tu_sp(chu):
    """Từ tên SP để so khớp: chữ Latin ≥3 (chữ đậm unicode đã chuẩn hoá), bỏ đuôi số nhiều, bỏ chữ chung."""
    ra = set()
    for w in re.findall(r"[a-z]{3,}", unicodedata.normalize("NFKC", CG.bo_chu_toan(chu or "")).lower()):
        if len(w) > 4 and w.endswith("s") and not w.endswith("ss"):
            w = w[:-1]
        if w not in _TU_BO_SP:
            ra.add(w)
    return ra


def _catalog_nuoc(nuoc):
    v = _CATALOG_TRAM.get(nuoc)
    if v and time.time() - v[0] < 1800:
        return v[1]
    ra = []
    try:
        d = json.load(open(os.path.join(SCRIPT_DIR, "state", nuoc, "catalog.json"), encoding="utf-8"))
        for sp in d.get("san_pham") or []:
            ma = str(sp.get("ma") or "").strip()
            ten = re.sub(r"^\s*\d{3}\s*[-–.:]\s*", "", str(sp.get("ten") or "")).strip()
            tu = _tu_sp(ten)
            if re.fullmatch(r"\d{3}", ma) and tu:
                ra.append((ma, ten, tu))
    except Exception:                                    # noqa: BLE001 — thiếu file / hỏng → nước đó coi như trống
        ra = []
    _CATALOG_TRAM[nuoc] = (time.time(), ra)
    return ra


def _catalog_tram(uu_tien):
    """Catalog gộp các nước (nước ưu tiên đứng trước; trùng mã giữ bản đứng trước)."""
    ds, co = [], set()
    for n in list(uu_tien) + ["saudi", "uae", "qatar", "kuwait", "oman", "bahrain"]:
        for x in _catalog_nuoc(n) if n else []:
            if x[0] not in co:
                co.add(x[0])
                ds.append(x)
    return ds


def tram_khop_sp(chu, cat):
    """(mã, tên) SP catalog khớp đoạn chữ — trọng số từ = 1/số SP chứa từ đó, điểm = phần khớp × tỉ lệ phủ tên. SP điểm cao
    nhất phải: ≥2 từ khớp (tên chỉ 1 từ thì từ đó phải hiếm), phủ ≥60% tên, hơn SP tên khác ≥1.3 lần. Không chắc → None
    (vd "Lucky Turtle Wallet Charm": 133 Feng Shui Lucky Charm và 246 Golden Turtle Wealth Charm sát nhau → None, không đoán)."""
    tu = _tu_sp(chu)
    if not tu or not cat:
        return None
    df = {}
    for _, _, t in cat:
        for w in t:
            df[w] = df.get(w, 0) + 1
    ung = []
    for ma, ten, t in cat:
        khop = t & tu
        if len(khop) < 2 and not (len(t) == 1 and khop and df[next(iter(khop))] == 1):
            continue
        w = sum(1 / df[x] for x in khop)
        tong = sum(1 / df[x] for x in t)
        ung.append((w * w / tong, w / tong, ma, ten, t))
    if not ung:
        return None
    ung.sort(key=lambda x: -x[0])
    dau = ung[0]
    nhi = next((u for u in ung[1:] if u[4] != dau[4]), None)
    if dau[1] < 0.6 or (nhi and dau[0] < 1.3 * nhi[0]):
        return None
    return dau[2], dau[3]


def tram_ma_sp(msgs, cid, pid, mkey, ghi_chu="", nuoc=None):
    """(mã, tên SP catalog) khách đang hỏi ở page trạm; (None, tên gợi ý hoặc "") nếu không chắc."""
    cfg = tram_cau_hinh().get(str(pid)) or {}
    cat = _catalog_tram([nuoc, mkey, cfg.get("nha")])
    theo_ma = {x[0]: x[1] for x in cat}
    ng = (nguon_khach(cid) if cid else None) or {}
    for ma in ([m.group(1) for m in [re.match(r"\s*(\d{3})(?!\d)", str(ng.get("sp") or ""))] if m]
               + [str(ng.get("ma_sp") or "")] + _R_MA_MKT.findall(ghi_chu or "")):
        if ma in theo_ma:
            return ma, theo_ma[ma]
    m = re.search(r"(?i)(?:SP khách hỏi|khách hỏi SP)\s*:?\s*«?([^—(«»\n]{3,60})", ghi_chu or "")
    ten_gc = m.group(1).strip(" .,;:-") if m else ""
    tu_gc = _tu_sp(ten_gc)
    if len(tu_gc) >= 2:                                  # tên model ghi ngắn ("reading glasses") → SP DUY NHẤT chứa đủ các từ đó
        chua = {frozenset(x[2]): x for x in cat if tu_gc <= x[2]}
        if len(chua) == 1:
            x = next(iter(chua.values()))
            return x[0], x[1]
    khach = [m for m in (msgs or []) if m.get("boi") == "khach"][-8:]
    anh = " ".join(m["mo_ta"] for m in khach[-3:] if m.get("mo_ta"))
    nguon = " ".join(str(ng.get(k) or "") for k in ("sp", "tieu_de", "noi_dung", "binh_luan"))
    loi = " ".join(m.get("text") or "" for m in khach)
    tang = [ghi_chu + " " + anh, nguon, loi]
    for i in range(1, len(tang) + 1):
        kq = tram_khop_sp(" ".join(tang[:i]), cat)
        if kq:
            return kq
    return None, (ten_gc or (anh or nguon).strip()[:70])


def tram_nuoc_co_mau(pid, mkey, ma, ten):
    """Tập nước có mẫu (giá / link landing) cho SP này trong kịch bản page trạm; None trong tập = mẫu không rõ nước (dùng được
    ở mọi nước). Khớp theo mã trong tên chủ đề hoặc tên SP ở tiêu đề / link mẫu."""
    cfg = tram_cau_hinh().get(str(pid)) or {}
    tu_sp = _tu_sp(ten)
    ra = set()
    ln = _tram_link_nuoc(mkey)
    for k in dict.fromkeys([cfg.get("nha"), mkey]):
        try:
            kb = _kb_page(k, pid) if k else None
        except BaseException:                            # noqa: BLE001 — nap_kich_ban sys.exit khi thiếu file
            kb = None
        cd = {str(x.get("id")): str(x.get("ten") or "") for x in ((kb or {}).get("chu_de") or []) if isinstance(x, dict)}
        for m in (kb or {}).get("mau") or []:
            chu = _tram_chu_mau(m)
            ten_cd = cd.get(str(m.get("chu_de_id")), "")
            co_gia = bool(CG.tien_trong(CG.bo_chu_toan(chu)))
            lk = sorted(_tram_links(chu))
            if not co_gia and not lk:
                continue                                 # mẫu chung (chào, xin thông tin…)
            if ma and ma in re.findall(r"(?<!\d)(\d{3})(?!\d)", ten_cd):
                ra.add(_tram_nuoc_mau(m, ten_cd, ln))
                continue
            tu_m = _tu_sp(_tram_ten_tieu_de(chu) if co_gia else " ".join(_tram_ten_slug(x) for x in lk))
            khop = tu_sp & tu_m
            if tu_sp and len(khop) >= min(2, len(tu_sp)) and len(khop) >= 0.6 * len(tu_sp):
                ra.add(_tram_nuoc_mau(m, ten_cd, ln))
    return ra


def tram_ghi_chu_mkt(qd, msgs, cid, pid, mkey):
    """Ghi chú mới "MKT bổ sung kịch bản mã … để tư vấn khách — …" khi AI giao sale vì SP khách hỏi chưa có mẫu ở page trạm.
    None = giữ ghi chú cũ (không phải ca thiếu kịch bản / SP đã có mẫu ở nước khách / cổng máy mà không ra được mã)."""
    if not qd or qd.get("hanh_dong") not in ("treo", "tra_loi_treo") or not tram_la(pid):
        return None
    gc = str(qd.get("ghi_chu") or "")
    chu = gc + " " + str(qd.get("ly_do") or "")
    cong = gc.startswith("Page trạm landing:")           # ghi chú của cổng giá / cổng hỏi lại SP (máy)
    if not cong and not _R_THIEU_KB.search(chu):
        return None
    nuoc, _ = tram_nuoc_khach(msgs, pid, cid)
    ma, ten = tram_ma_sp(msgs, cid, pid, mkey, chu, nuoc)
    if cong and not ma:
        return None
    co = tram_nuoc_co_mau(pid, mkey, ma, ten) if (ma or ten) else set()
    if (nuoc and (nuoc in co or None in co)) or (not nuoc and co):
        return None
    ten_n = _TRAM_TEN_VN.get(nuoc, "") if nuoc else ""
    co_n = sorted(_TRAM_TEN_VN.get(x, x) for x in co if x)
    them = [f"SP «{ten[:70]}»" if ten else "SP khách hỏi chưa rõ tên — xem ảnh / tin khách",
            f"khách ở {ten_n}" if ten_n else "chưa rõ khách ở nước nào"]
    if co_n:
        them.append(f"page mới có mẫu {', '.join(co_n)}")
    return CAU_MKT.format(ma=ma or "?") + " — " + ", ".join(them) + ". Sale tư vấn khách trong lúc chờ."


def _page_gan_them(mkey):
    """19/09 (chủ shop: "rõ ràng tôi bảo theo đơn vị tiền tệ mà gắn rồi còn gì"): page còn gói nhưng thuộc shop POS
    RIÊNG (không có trong markets.json) → gắn vào thị trường theo tiền tệ page báo giá (AED→uae, NT$/TWD→taiwan…).
    Nguồn: state/chung/page_gan_them.json {tt: {pid: ghi chú}}. Đọc lại mỗi lần gọi → sửa file không cần restart
    (vòng dò tra lại danh sách page 10 phút/lần). Hỏng/thiếu file → không gắn thêm gì."""
    try:
        d = json.load(open(os.path.join(SCRIPT_DIR, "state", "chung", "page_gan_them.json"), encoding="utf-8"))
        # TRAM_LANDING_2409: + page trạm landing có nước này trong "nuoc" (mỗi hội thoại vẫn chỉ 1 AI xử — tram_bo_qua)
        return ({str(p) for p in (d.get(mkey) or {})}
                | {str(p) for p, v in (d.get("tram_landing") or {}).items()
                   if isinstance(v, dict) and mkey in [v.get("nha")] + list(v.get("nuoc") or [])})
    except Exception:                                    # noqa: BLE001
        return set()


def _page_gan_noi_khac(mkey):
    """23/09 (chủ shop: "giá bán thị trường nào tư vấn theo thị trường đó" — ca Gold Avenue Taiwan: page nằm trong shop
    POS Mỹ nhưng kịch bản báo 1290/1790 TWD): page đã được gắn cho thị trường KHÁC trong page_gan_them.json thì
    thị trường của shop POS phải BỎ nó ra, không thì hai AI cùng rep (AI Mỹ nói giá đô + xác nhận nhà + cọc $50
    với khách Đài). Cùng file với _page_gan_them, đọc lại mỗi lần gọi; hỏng/thiếu file → không bỏ gì."""
    try:
        d = json.load(open(os.path.join(SCRIPT_DIR, "state", "chung", "page_gan_them.json"), encoding="utf-8"))
        return {str(p) for k, o in d.items() if k != mkey and isinstance(o, dict) for p in o}
    except Exception:                                    # noqa: BLE001
        return set()


def _hop_page_shop(mkey, ids):
    """Tập page AI <mkey> trông = page của shop POS − page đã gắn cho nước khác (theo tiền tệ) + page gắn thêm cho nước này."""
    return (set(ids) - _page_gan_noi_khac(mkey)) | _page_gan_them(mkey)


_SHOP_NHO = {}     # mkey -> (lúc nhớ, tập page id của shop POS) — 23/09, xem _pages_cua_shop


def _pages_cua_shop(mkey):
    """Tập page id THUỘC ĐÚNG shop POS của thị trường này. None = không tra được.

    Vì sao cần: `state/<tt>/page_tokens.json` KHÔNG bảo đảm chỉ chứa page của thị trường đó.
    Đo thật 2026-09-05: shop Bulgaria không có page nào, nhưng setup vẫn cấp token cho 159 page
    của Kuwait/Qatar/UAE/Đài Loan rồi ghi vào state/bulgaria/. Nếu AI chạy trên đó, khách Kuwait
    sẽ được báo giá EUR của Bulgaria và đơn rơi vào shop Bulgaria — đúng thứ mục 3 của luật cấm.
    Nên trước mỗi vòng, hỏi thẳng POS xem shop này thật sự có page nào.
    """
    try:
        mk = json.load(open(os.path.join(SCRIPT_DIR, "markets.json"), encoding="utf-8"))[mkey]
    except Exception:                                    # noqa: BLE001
        return None
    # 23/09 (lượt 3 ca Abul Shalim): khởi động lại khỏi đứng đợi POS (5-9s/lần, gọi 2 lần liền lúc khởi động).
    # Gọi lại trong 60s → dùng lại. Lần ĐẦU của tiến trình mà bản lưu ≤ AI_DS_PAGE_DIA (900s) → dùng bản lưu;
    # lần tra lại 10 phút sau hỏi POS như cũ.
    _nho_ = _SHOP_NHO.get(mkey)
    if _nho_ and time.time() - _nho_[0] < 60:
        return _hop_page_shop(mkey, _nho_[1])
    if _nho_ is None:
        try:
            _d_ = json.load(open(os.path.join(SCRIPT_DIR, "state", mkey, "pages_cua_shop.json"), encoding="utf-8"))
            if time.time() - float(_d_.get("luc") or 0) < _so_env("AI_DS_PAGE_DIA", 900) and _d_.get("ids"):
                _SHOP_NHO[mkey] = (time.time(), set(_d_["ids"]))
                return _hop_page_shop(mkey, _d_["ids"])
        except Exception:                                # noqa: BLE001
            pass
    u = "https://pos.pages.fm/api/v1/shops?" + urllib.parse.urlencode(
        {"api_key": mk.get("api_key", "")})
    try:
        with urllib.request.urlopen(u, timeout=40) as r:
            res = json.loads(r.read().decode() or "{}")
    except Exception as e:                               # noqa: BLE001
        try:                                             # 19/09: dùng bản lưu gần nhất ≤24 giờ
            d = json.load(open(os.path.join(SCRIPT_DIR, "state", mkey, "pages_cua_shop.json"), encoding="utf-8"))
            if time.time() - float(d.get("luc") or 0) < 86400 and d.get("ids"):
                print(f"  ⚠️  không tra được danh sách page của shop {mkey} ({e}) — dùng bản lưu "
                      f"{(time.time() - float(d['luc'])) / 60:.0f} phút trước", flush=True)
                return _hop_page_shop(mkey, d["ids"])
        except Exception:                                # noqa: BLE001
            pass
        print(f"  ⚠️  không tra được danh sách page của shop {mkey} ({e}) — BỎ QUA bước lọc,"
              f" hãy tự kiểm tên page in ra bên dưới có đúng thị trường không")
        return None
    for sh in res.get("shops") or []:
        if str(sh.get("id")) == str(mk.get("shop_id")):
            _ids = {str(x.get("id")) for x in (sh.get("pages") or []) if x.get("id")}
            if _ids:
                try:
                    _f = os.path.join(SCRIPT_DIR, "state", mkey, "pages_cua_shop.json")
                    with open(f"{_f}.{os.getpid()}.tmp", "w", encoding="utf-8") as g:
                        json.dump({"luc": time.time(), "ids": sorted(_ids)}, g)
                    os.replace(f"{_f}.{os.getpid()}.tmp", _f)
                except Exception:                        # noqa: BLE001
                    pass
            _SHOP_NHO[mkey] = (time.time(), set(_ids))
            return _hop_page_shop(mkey, _ids)
    return _page_gan_them(mkey)


_CON_GOI = {"luc": 0.0, "bang": None}


def _con_goi_that(p):
    """Page còn gói VÀ tài khoản AI dùng được. 19/09 đo 478 page: 50 page has_active_subscription=true
    nhưng có deactivation_days_left (3/6/7 ngày) — hỏi hội thoại cả 50 đều trả mã 121 "Không tìm thấy gói
    cước". Chỉ tính page KHÔNG đếm ngược: ra 170 page, khớp chủ shop "hơn 170 page hoạt động ở pan"."""
    return bool(p.get("has_active_subscription")) and p.get("deactivation_days_left") is None


_DS_PAGE_TK = {"luc": 0.0, "ds": None}


def _giu_page_vang_tam(ps, f):
    """24/09 (ca Md Midul · Waheed Zaman — Nature's Daily Care in Saudi): 16:29 VN pages.fm trả THIẾU 37 page đang chạy (còn gói,
    đủ quyền; 17 phút sau hỏi lại thì đủ) → AI bỏ trông 37 page ~17 phút, khách nhắn không ai rep. Page hết gói thật vẫn NẰM trong
    danh sách (has_active_subscription False / đếm ngược), không biến mất — nên page CÒN GÓI ở bản trước mà bản mới vắng thì giữ
    bản cũ thêm AI_DS_PAGE_GIU_VANG giây (mặc định 1800) tính từ lần ĐẦU vắng (mốc lưu chung trong file), rồi mới bỏ. 0 = tắt.
    Trả (danh sách đã bù, {pid: lúc bắt đầu vắng})."""
    giu = _so_env("AI_DS_PAGE_GIU_VANG", 1800)
    if giu <= 0:
        return ps, {}
    truoc, vang = None, {}
    try:
        _d_ = json.load(open(f, encoding="utf-8"))
        if time.time() - float(_d_.get("luc") or 0) < 3600:
            truoc, vang = _d_.get("pages"), dict(_d_.get("vang") or {})
    except Exception:                                    # noqa: BLE001
        pass
    if not truoc:
        truoc = _DS_PAGE_TK["ds"] or []
    co = {str(p.get("id")) for p in ps if isinstance(p, dict)}
    now = time.time()
    bu, bo, vang_moi = [], [], {}
    for p in truoc:
        if not isinstance(p, dict) or str(p.get("id")) in co or not _con_goi_that(p):
            continue
        pid = str(p.get("id"))
        try:
            tu = float(vang.get(pid) or now)
        except (TypeError, ValueError):
            tu = now
        if now - tu < giu:
            bu.append(p)
            vang_moi[pid] = tu
        else:
            bo.append(p)
    if bu:
        lau = max(now - t for t in vang_moi.values()) / 60
        print(f"  ⚠️  Pancake trả THIẾU {len(bu)} page còn gói so với bản trước — giữ tạm (vắng lâu nhất {lau:.0f}/"
              f"{giu / 60:.0f} phút): " + " · ".join((p.get("name") or str(p.get("id")))[:26] for p in bu[:6])
              + (f" … +{len(bu) - 6}" if len(bu) > 6 else ""), flush=True)
    if bo:
        print(f"  ⏸  {len(bo)} page vắng khỏi danh sách Pancake đủ {giu / 60:.0f} phút → bỏ: "
              + " · ".join((p.get("name") or str(p.get("id")))[:26] for p in bo[:6]), flush=True)
    return list(ps) + bu, vang_moi


def _ds_page_tai_khoan():
    """Danh sách page tài khoản AI thấy trên Pancake (pages.fm/api/v1/pages) — nguồn chung cho bảng còn gói
    (`_bang_con_goi`) và page chạy kênh tài khoản (`_pages_khong_quyen`).

    19/09 (ca Boyet Salamat Torres · ClearVision Eye Care Saudi): service khởi động lại 14:53 VN đúng lúc lệnh
    này hỏng → 12 page không token vắng khỏi danh sách AI trông ~10 phút; khách nhắn 14:49-14:58 không ai rep.
    Nay: thử 3 lần; hỏng hết thì dùng bản tốt gần nhất — bộ nhớ, rồi file lưu ≤24 giờ. None = chưa từng có bản nào."""
    tok_user = env().get("PANCAKE_USER_TOKEN", "")
    if not tok_user:
        return None
    if _DS_PAGE_TK["ds"] is not None and time.time() - _DS_PAGE_TK["luc"] < 60:
        return _DS_PAGE_TK["ds"]           # _bang_con_goi + _pages_khong_quyen gọi liền nhau → 1 lần hỏi
    f = os.path.join(SCRIPT_DIR, "state", "chung", "ds_page_tai_khoan.json")
    # 23/09 (lượt 3 ca Abul Shalim): lần ĐẦU của tiến trình (vừa khởi động lại) mà bản lưu chung ≤ AI_DS_PAGE_DIA (900s)
    # → dùng luôn, khỏi tải 9,4 MB. Đo 23/09: tải 1 mình 7-224s; 7 nước khởi động cùng lúc → 6/7 bị 429 → Saudi/Kuwait/
    # Oman mù ~2 phút sau restart 14:02:10 CEST (khách chờ 191-218s). Lần làm mới 10 phút sau hỏi mạng như cũ.
    if _DS_PAGE_TK["ds"] is None:
        try:
            _d_ = json.load(open(f, encoding="utf-8"))
            if time.time() - float(_d_.get("luc") or 0) < _so_env("AI_DS_PAGE_DIA", 900) and _d_.get("pages"):
                _DS_PAGE_TK.update(luc=time.time(), ds=_d_["pages"])
                return _d_["pages"]
        except Exception:                                # noqa: BLE001
            pass
    loi = None
    for lan in range(3):
        res, err = _get("https://pages.fm/api/v1/pages", {"access_token": tok_user}, thu_lai=3)
        ps = None if (err or not res) else (res.get("pages") or (res.get("categorized") or {}).get("activated"))
        if ps:
            try:                                         # 24/09: bản hụt (page còn gói biến mất) → giữ tạm bản cũ
                ps, _vang_ = _giu_page_vang_tam(ps, f)
            except Exception as e:                       # noqa: BLE001 — hỏng thì dùng bản vừa hỏi như cũ
                print(f"  ⚠ giữ page vắng tạm lỗi: {e}", flush=True)
                _vang_ = {}
            _DS_PAGE_TK.update(luc=time.time(), ds=ps)
            try:
                tam = f"{f}.{os.getpid()}.tmp"
                with open(tam, "w", encoding="utf-8") as g:
                    json.dump({"luc": time.time(), "pages": ps, "vang": _vang_}, g, ensure_ascii=False)
                os.replace(tam, f)
            except Exception:                            # noqa: BLE001 — lưu hỏng không chặn vòng
                pass
            return ps
        loi = err or "API trả rỗng"
        if lan < 2:
            time.sleep(1 + 2 * lan)
    if _DS_PAGE_TK["ds"] is not None:
        print(f"  ⚠️  hỏi danh sách page Pancake hỏng ({loi}) — dùng bản trong bộ nhớ", flush=True)
        return _DS_PAGE_TK["ds"]
    try:
        d = json.load(open(f, encoding="utf-8"))
        tuoi = time.time() - float(d.get("luc") or 0)
        if tuoi < 86400 and d.get("pages"):
            print(f"  ⚠️  hỏi danh sách page Pancake hỏng ({loi}) — dùng bản lưu {tuoi / 60:.0f} phút trước", flush=True)
            _DS_PAGE_TK["ds"] = d["pages"]          # luc giữ 0 → lần gọi sau vẫn hỏi lại mạng
            return d["pages"]
    except Exception:                                    # noqa: BLE001
        pass
    print(f"  🚨 hỏi danh sách page Pancake hỏng ({loi}) và không có bản lưu — page chạy kênh tài khoản vắng mặt", flush=True)
    return None


def _bang_con_goi():
    """{pid: còn gói cước?} theo danh sách page của tài khoản AI trên Pancake; nhớ 10 phút.
    Hỏi hỏng → bảng cũ (hoặc None = không lọc gì, giữ như trước)."""
    if _CON_GOI["bang"] is not None and time.time() - _CON_GOI["luc"] < 600:
        return _CON_GOI["bang"]
    tok_user = env().get("PANCAKE_USER_TOKEN", "")
    if not tok_user:
        return None
    ps = _ds_page_tai_khoan() or []
    if not ps:
        return _CON_GOI["bang"]
    _CON_GOI.update(luc=time.time(), bang={str(p["id"]): _con_goi_that(p) for p in ps})
    return _CON_GOI["bang"]


_TU_GAN_LUC = os.path.join(SCRIPT_DIR, "state", "chung", "tu_gan_luc.txt")


def _tu_gan_page_moi(nghi=1800):
    """Page MỚI còn gói mà thuộc shop POS riêng → tự gắn vào thị trường theo tiền tệ báo giá, để AI
    tự kéo kịch bản và chat khách mới. Chủ shop 20/09: *"page mới lên là bạn chủ động tự học kịch bản
    để mà chát các khách mới đó nhé"* — trước bản này `state/chung/page_gan_them.json` phải sửa TAY,
    page mới ngoài 12 shop thị trường thì AI không thấy, không kéo kịch bản, không một dòng log.

    Luật gắn + số đo hai chiều nằm trong `tu_gan_page_ngoai.py`. 6 service thị trường cùng gọi hàm
    này nên chặn bằng mốc giờ CHUNG `state/chung/tu_gan_luc.txt`: 30 phút một lượt, ai tới trước thì
    làm. Hỏng gì cũng chỉ in ra — không được giết vòng dò."""
    try:
        luc = float((open(_TU_GAN_LUC, encoding="utf-8").read() or "0").strip() or 0)
    except Exception:                                    # noqa: BLE001
        luc = 0.0
    if time.time() - luc < nghi:
        return
    try:
        tam = f"{_TU_GAN_LUC}.{os.getpid()}.tmp"
        with open(tam, "w", encoding="utf-8") as g:
            g.write(str(time.time()))
        os.replace(tam, _TU_GAN_LUC)
        import tu_gan_page_ngoai as TG
        TG.quet(that=True, in_ra=print)
    except Exception as e:                               # noqa: BLE001
        print(f"  ⚠ tự gắn page mới ngoài shop lỗi: {e}")


def _pages_cua_thi_truong(mkey, page_loc=None):
    d = os.path.join(SCRIPT_DIR, "state", mkey)
    f = os.path.join(d, "page_tokens.json")
    if not os.path.exists(f):
        sys.exit(f"❌ Thị trường {mkey!r} chưa setup. Chạy: python3 auto_len_don.py setup {mkey}")
    tok = json.load(open(f, encoding="utf-8"))
    ds = [(p, st) for p, st in tok.items() if st.get("token")]
    thuoc = _pages_cua_shop(mkey)
    if thuoc is not None:
        ngoai = [x for x in ds if x[0] not in thuoc]
        ds = [x for x in ds if x[0] in thuoc]
        if ngoai:
            print(f"  🚨 BỎ QUA {len(ngoai)} page KHÔNG thuộc shop {mkey} — chúng nằm nhầm "
                  f"trong state/{mkey}/page_tokens.json:")
            print("     " + " · ".join((x[1].get("name") or x[0])[:26] for x in ngoai[:5])
                  + (f" … +{len(ngoai)-5}" if len(ngoai) > 5 else ""))
            print(f"     Chạy trên chúng là bán giá {mkey} cho khách nước khác — mục 3 của luật cấm.")
    # 18/09 — CHỈ TRÔNG PAGE CÒN GÓI CƯỚC (chủ shop: "hiện tại tôi đang có 168 page hoạt động ở pan, chỉ cần
    # xử lý các page tôi đang hoạt động"). page_tokens.json còn giữ token cũ của page hết gói: AI dò 304 page mà
    # chỉ 167 còn gói — 137 page chết vẫn bị hỏi Pancake mỗi 6s. Nguồn: danh sách page của tài khoản AI
    # (has_active_subscription). Page không có trong danh sách cũng bỏ. Hỏi hỏng thì KHÔNG lọc.
    _goi = _bang_con_goi()
    if _goi is not None:
        _bo = [x for x in ds if not _goi.get(str(x[0]))]
        if _bo:
            ds = [x for x in ds if _goi.get(str(x[0]))]
            print(f"  ⏸  bỏ {len(_bo)} page hết gói cước / không còn trên Pancake — còn {len(ds)} page có token (page chạy bằng tài khoản tính riêng bên dưới)")
    # 20/09 — TOKEN CHẾT thì bỏ token, để page rơi xuống kênh tài khoản ("token chết → chạy bằng
    # kênh tài khoản"). Trước đó page có `token_hong` vẫn nằm trong ds với token chết: mỗi lượt chỉ
    # ra "✖ KHÔNG lấy được hội thoại: token hỏng" rồi thôi, mà `_pages_khong_quyen` cũng không thêm
    # vào được vì page đã có mặt trong ds → page mù hẳn. Đo 20/09: 4 page còn gói kẹt kiểu này
    # (Fire Dragon Alaga PH in Saudi có khách chờ 83 phút, Uniform Skin UAE, Mang Mulat Kuwait,
    # Madam Jane Feng Shui Expert Qatar). Daemon lên đơn tự xoá dấu `token_hong` khi đọc lại được
    # bằng token page, nên page tự quay về đường cũ — không cần ai gỡ tay.
    if gui_qua_user_bat():
        _chet = [x for x in ds if (x[1] or {}).get("token_hong")]
        if _chet:
            ds = [x for x in ds if not (x[1] or {}).get("token_hong")]
            print(f"  🔁 {len(_chet)} page token page đã chết → chuyển sang kênh tài khoản: "
                  + " · ".join((st.get("name") or p)[:26] for p, st in _chet[:6])
                  + (" …" if len(_chet) > 6 else ""))
    if gui_qua_user_bat():
        # Page thuộc shop, còn gói, tài khoản AI thấy nhưng KHÔNG có token page → chạy bằng tài khoản.
        co = {str(p) for p, _ in ds}
        them = [(pid, {"name": ten, "token": TOKEN_USER, "khong_quyen": True, "role": role})
                for pid, ten, role in _pages_khong_quyen(mkey) if pid not in co]
        if them:
            ds += them
            print(f"  👤 {len(them)} page không có token page → AI chạy bằng tài khoản Pancake: "
                  + " · ".join(st["name"][:26] for _, st in them[:6]) + (" …" if len(them) > 6 else ""))
    if page_loc:
        ds = [x for x in ds if str(x[0]) == str(page_loc)]
    return ds


# ─────────── Page AI KHÔNG CÓ QUYỀN → ghi chú cho chủ shop (14/09/2026) ───────────
#
# Chủ shop: *"page nào bạn không gửi được tin nhắn cho, không có quyền, thì note ghi chú cho tôi
# là AI SALE k có quyền ở page này"*. Đó là page thuộc shop, còn gói cước, tài khoản Pancake của AI
# nhìn thấy nhưng KHÔNG có token page dùng được (Biên tập viên thì không sinh được token — quyền
# này lấy từ Facebook, xem quyen-admin-page-theo-facebook). Đọc hội thoại + ghi chú thì Biên tập
# viên vẫn làm được, qua API nội bộ pancake.vn với PANCAKE_USER_TOKEN. Mỗi hội thoại ghi ĐÚNG 1 lần,
# chỉ hội thoại khách nhắn sau mốc bật chức năng. Tin nhắn cho khách VẪN đi Public API (chủ shop dặn).
GC_KHONG_QUYEN = "AI SALE không có quyền ở page này"


def _f_khong_quyen(mkey):
    return os.path.join(SCRIPT_DIR, "state", mkey, "khong_quyen.json")


def _pages_khong_quyen(mkey):
    """[(pid, tên, role)] page thuộc shop, còn gói, tài khoản AI thấy, nhưng không có token page sống."""
    tok_user = env().get("PANCAKE_USER_TOKEN", "")
    thuoc = _pages_cua_shop(mkey)
    if not tok_user or not thuoc:
        return []
    f = os.path.join(SCRIPT_DIR, "state", mkey, "page_tokens.json")
    tok = json.load(open(f, encoding="utf-8")) if os.path.exists(f) else {}
    co = {p for p, st in tok.items() if isinstance(st, dict) and st.get("token") and not st.get("token_hong")}
    ps = _ds_page_tai_khoan()
    if not ps:
        return []
    return [(str(p["id"]), p.get("name") or str(p["id"]), p.get("role_in_page"))
            for p in ps if str(p["id"]) in thuoc and str(p["id"]) not in co and _con_goi_that(p)]


def ghi_chu_page_khong_quyen(mkey, that=False, in_ra=False):
    if gui_qua_user_bat():
        if in_ra:
            print("  👤 kênh tài khoản đang BẬT → AI tự trả lời ở page không token, không ghi chú 'không có quyền'.")
        return 0
    tok_user = env().get("PANCAKE_USER_TOKEN", "")
    f = _f_khong_quyen(mkey)
    try:
        st = json.load(open(f, encoding="utf-8"))
    except Exception:                                    # noqa: BLE001
        st = {}
    moc = st.get("moc") or (time.time() - 3600)          # lần đầu: chỉ nhìn lại 1 giờ
    da = dict(st.get("da_ghi") or {})
    pages = _pages_khong_quyen(mkey)
    ghi = 0
    for pid, ten, role in pages:
        res, err = _get(f"https://pancake.vn/api/v1/pages/{pid}/conversations",
                        {"access_token": tok_user, "current_count": 0, "type": "INBOX", "mode": "OR"})
        if err or not res:
            if in_ra:
                print(f"  ✖ {ten[:40]}: không đọc được hội thoại ({err})")
            continue
        for c in res.get("conversations") or []:
            cid = str(c.get("id"))
            luc = c.get("last_customer_interactive_at")
            if not luc or cid in da:
                continue
            if time.time() - _giay_tu(luc) < moc:      # khách nhắn TRƯỚC mốc → không đào lại lịch sử
                continue
            cust = ((c.get("customers") or [{}])[0] or {}).get("id")
            if not cust:
                continue
            khach = (c.get("from") or {}).get("name", "?")
            if role == "EDIT_PROFILE":
                ten_ai = (env().get("AI_TEN_TAI_KHOAN") or "AI LEADER").split(",")[0].strip()
                text = (f"{GC_KHONG_QUYEN} — tài khoản Pancake của AI ({ten_ai}) chỉ là Biên tập "
                        f"viên nên không gửi tin được. Nâng lên Quản trị viên trên page Facebook thì AI tự trả lời.")
            else:
                text = f"{GC_KHONG_QUYEN} — AI chưa có token page (thiếu quyền Admin hoặc hết gói cước)."
            if that:
                r2, e2 = _post(f"https://pancake.vn/api/v1/pages/{pid}/customers/{cust}/notes",
                               {"access_token": tok_user},
                               {"message": text, "conversation_id": cid, "images": "[]", "links": "[]"})
                if e2 or not r2:
                    if in_ra:
                        print(f"  ✖ {ten[:40]} / {khach}: ghi chú hỏng ({e2})")
                    continue
                da[cid] = int(time.time())
            ghi += 1
            if in_ra:
                print(f"  📝 {ten[:40]} / {khach} — {'đã ghi' if that else 'SẼ ghi'}: {GC_KHONG_QUYEN}")
            time.sleep(0.2)
    if that:
        os.makedirs(os.path.dirname(f), exist_ok=True)
        json.dump({"moc": moc, "da_ghi": da, "cap_nhat": int(time.time())},
                  open(f, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    if in_ra or ghi:
        print(f"  📝 page AI không có quyền: {len(pages)} page · ghi chú {'mới' if that else 'sẽ ghi'} {ghi}"
              + ("" if that else " (THỬ, chưa ghi gì)"))
    return ghi


def cmd_loc(mkey, so=30):
    """Chỉ ĐỌC: xem AI sẽ vào cuộc ở những hội thoại nào (mục 0b)."""
    pages = _pages_cua_thi_truong(mkey)
    print(f"\n🔎 Thử soi {so} hội thoại/page trên {len(pages)} page — KHÔNG gửi gì\n")
    nhan = {"tra_loi": "AI TRẢ LỜI (Botcake im)",
            "xet":     "XÉT LẠI (Botcake đã rep — trúng hay lạc?)",
            "im":      "IM (sale thật đang xử)",
            "treo":    "TREO cho sale"}
    dem = {k: 0 for k in nhan}
    da_xem = hong = 0
    for pid, st in pages:
        if da_xem >= 6:
            break
        convs, err = hoi_thoai_gan_day(pid, st["token"], so=so, gio=72)
        if err:
            hong += 1                      # token hỏng -> bỏ qua page này (mục 11)
            continue
        if not convs:
            continue          # page không có khách trong 72h — bỏ qua, tìm page khác
        da_xem += 1
        print(f"  ── {st.get('name','?')[:44]} ({len(convs)} hội thoại)")
        for c in convs:
            msgs, _, e = tin_cua_hoi_thoai(pid, c["id"], st["token"])
            if e:
                continue
            quyet, ly_do = ai_co_vao_cuoc(msgs)
            dem[quyet] += 1
            khach = [m for m in msgs if m["boi"] == "khach"]
            cuoi = (khach[-1]["text"] if khach else "") or "(ảnh/sticker)"
            print(f"     [{quyet:7s}] {cuoi[:52]!r:56s} ← {ly_do}")
            time.sleep(0.1)
        time.sleep(0.1)
    t = sum(dem.values()) or 1
    print("")
    for k, v in dem.items():
        print(f"  {nhan[k]:46s} {v:4d} ({100*v/t:.0f}%)")
    if hong:
        print(f"\n  ⚠ Bỏ qua {hong} page token hỏng. Xem chi tiết: python3 ai_sale.py token {mkey}")


def cmd_soi(mkey, ten):
    """Soi 1 hội thoại: in toàn bộ tin + AI sẽ làm gì."""
    dau = {"khach": "👤 khách", "botcake": "🤖 Botcake", "nguoi": "🧑‍💼 sale", "ai": "🤖 AI", "hethong": "⚙️ hệ thống"}
    for pid, st in _pages_cua_thi_truong(mkey):
        convs, err = hoi_thoai_gan_day(pid, st["token"], so=60, gio=24 * 14)
        if err:
            continue
        for c in convs:
            nm = ((c.get("customers") or [{}])[0].get("name") or "")
            if ten.lower() not in nm.lower():
                continue
            msgs, cus_id, e = tin_cua_hoi_thoai(pid, c["id"], st["token"])
            print(f"\n═══ [{st.get('name')}] {nm} — conv {c['id']} (khách {cus_id}) ═══")
            for m in msgs:
                print(f"  {dau.get(m['boi'], m['boi']):12s} {m['text'][:96]}"
                      f"{'  [ẢNH: ' + m['mo_ta'] + ']' if m.get('mo_ta') else ''}"
                      f"{'  [có ảnh/file]' if m['co_dinh_kem'] and not m.get('mo_ta') else ''}")
            quyet, ly_do = ai_co_vao_cuoc(msgs)
            viec = {
                "tra_loi": "AI TRẢ LỜI theo kịch bản, xong đánh dấu CHƯA ĐỌC",
                "xet":     "ĐỌC LẠI tin Botcake: trúng câu khách hỏi thì IM, lạc đề mới trả lời lại",
                "im":      "AI KHÔNG làm gì",
                "treo":    "TREO: đánh dấu chưa đọc + ghi chú nội bộ cụ thể (mục 7)",
            }[quyet]
            print(f"\n  → Quyết định: **{quyet}** ({ly_do})")
            print(f"  → {viec}")
            return
    print(f"Không thấy hội thoại nào của {ten!r} trong 14 ngày.")


def cmd_token(mkey):
    """Đếm page token còn sống / đã hỏng (mục 11), và ghi dấu vào state.

    Ghi dấu để 'setup --force-token --hong' cấp lại token đúng những page này — và để
    lệnh 'bao-cao' thôi đếm chúng vào "page chạy được".
    """
    qht.set_state_dir(os.path.join(SCRIPT_DIR, "state", mkey))
    pages = _pages_cua_thi_truong(mkey)
    song, hong, doi_dau = [], [], False
    for pid, st in pages:
        _, err = hoi_thoai_gan_day(pid, st["token"], so=1, gio=1)
        (hong if err else song).append((st.get("name", "?"), err))
        doi_dau = qht.danh_dau_token(st, err) or doi_dau
    if doi_dau:
        qht.luu_dau_token(dict(pages))
    print(f"\n🔑 {mkey}: {len(song)} page token SỐNG / {len(hong)} page token HỎNG "
          f"(tổng {len(pages)} page có lưu token)\n")
    for ten, err in hong:
        print(f"  ✖ {ten[:44]:46s} {err}")
    if hong:
        print(f"\n  → Lấy token mới cho các page trên: "
              f"python3 auto_len_don.py setup {mkey} --force-token --hong")
        print("  → Không lấy lại thì AI bỏ qua các page này, chỉ xử page còn token.")


# ─────────── Gửi ẢNH cho khách (mục 9b) ───────────
# Kiểm chứng bằng openapi.yaml chính thức 2026-09-03:
#   POST /pages/{page_id}/upload_contents  (multipart, trường `file`) -> {"id": ..., "attachment_type": "PHOTO"}
#   rồi gửi tin với content_ids: [id].
# ⚠️ `message` và `content_ids` LOẠI TRỪ NHAU — gửi cả hai thì API trả lỗi 500.
#    Nên ảnh và lời nhắn phải là HAI tin riêng.

def _tai_anh_len(page_id, token, duong_dan):
    """Trả (content_id, lỗi)."""
    import uuid
    ranh = "----pancake" + uuid.uuid4().hex
    ten = os.path.basename(duong_dan)
    try:
        with open(duong_dan, "rb") as f:
            anh = f.read()
    except Exception as e:
        return None, f"không đọc được file ảnh: {e}"
    body = (f"--{ranh}\r\nContent-Disposition: form-data; name=\"file\"; filename=\"{ten}\"\r\n"
            f"Content-Type: image/jpeg\r\n\r\n").encode() + anh + f"\r\n--{ranh}--\r\n".encode()
    u = (f"{BASE_V1}/pages/{page_id}/upload_contents?"
         + urllib.parse.urlencode({"page_access_token": token}))
    req = urllib.request.Request(u, data=body, method="POST",
                                 headers={"Content-Type": f"multipart/form-data; boundary={ranh}"})
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            res = json.loads(r.read().decode() or "{}")
    except Exception as e:
        return None, str(e)
    loi = loi_token(res)
    if loi or not res.get("id"):
        return None, loi or f"API không trả id: {str(res)[:120]}"
    return res["id"], None


def _tai_anh_len_bytes(page_id, token, anh, ten="anh.jpg"):
    """Như _tai_anh_len nhưng nhận sẵn bytes — dùng cho ảnh tải từ URL của mẫu."""
    import uuid
    ranh = "----pancake" + uuid.uuid4().hex
